import type { ParsedHymnInput } from './importHinario.ts';

const RAW_HYMNS_CATALOG = "{\"hinario\":[{\"number\":\"1\",\"collection_type\":\"Hinário\",\"title\":\"Ó Deus de Amor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó Deus de amor, vimos nós Te adorar.\\nVós, ó nações, rendei louvor!\\nÉs Tu, Senhor, o poderoso Vencedor;\\nÉs Criador e Rei sem-par.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por Teu poder nos criaste, Senhor,\\nDeste-nos vida e perfeição;\\nE ao desviar-nos de Teu plano de amor,\\nVeio, em Jesus, a salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Teu é o poder e o louvor, nosso Deus;\\nTeu, nosso amor, fervor também.\\nQual rocha firme a verdade ficará,\\nDeus eternal, Senhor. Amém.\"}]},{\"number\":\"2\",\"collection_type\":\"Hinário\",\"title\":\"Ó, Adorai o Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, adorai o Senhor na beleza\\nDa santidade, da glória e poder;\\nVinde e prostrai-vos à Sua grandeza;\\nEle é o princípio, e sempre há de ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vinde a Seus pés, Ele é caridade,\\nGrande e piedoso, tardio em furor;\\nVinde adorá-Lo por Sua bondade,\\nPela grandeza do Seu santo amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele criou o Universo e a Terra;\\nVinde e adorai-O com fé e oração;\\nLímpida fonte de bênçãos encerra,\\nFonte de graça e de redenção.\"}]},{\"number\":\"3\",\"collection_type\":\"Hinário\",\"title\":\"O Deus Eterno Reina\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Deus eterno reina no monte de Sião.\\nChegai-vos ante o trono Seu em santa adoração.\\nTrazei, humildemente, o vosso coração\\nAo Deus eterno e Rei dos reis, Senhor da redenção.\"},{\"section_type\":\"Estrofe\",\"content\":\"O Deus eterno reina no monte de Sião.\\nOs astros na amplidão sem fim, sustenta com a mão.\\nA Ele seja a honra, a glória e o poder,\\nE ascendam os louvores mil ao mais sublime Ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"O Deus eterno reina no monte de Sião.\\nEntrai no santo templo Seu, buscai o Seu perdão.\\nBuscando Sua face, a paz encontrareis;\\nE reine para sempre, enfim, o eterno Rei dos reis.\"}]},{\"number\":\"4\",\"collection_type\":\"Hinário\",\"title\":\"Louvor ao Trino Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó anjos e homens, dai a Deus louvores,\\nPois Sua graça dá aos pecadores.\\nÓ firmamento, Céus, e mar e Terra,\\nSim, dai louvor a Deus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vós, ó remidos, dai louvor a Cristo,\\nTal sacrifício, oh! jamais foi visto!\\nA Sua morte Seu amor revela,\\nSim, adorai Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quão insondável é o amor divino!\\nO Santo Espírito ilumina o mundo;\\nÉ tão sublime, luz ao peregrino,\\nLuz que ao Céu conduz!\"}]},{\"number\":\"5\",\"collection_type\":\"Hinário\",\"title\":\"Supremo Criador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Supremo Criador, do bem és manancial;\\nCom Tua graça e Teu amor livraste-me do mal:\\nCom Tua graça e Teu amor livraste-me do mal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Feitura Tua sou; de Ti a vida vem;\\nO Teu maravilhoso amor me ampara e me sustém;\\nO Teu maravilhoso amor me ampara e me sustém.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que sempre Teu poder impere, Ó Deus, aqui;\\nE fia-me sempre ser fiel me unindo, Ó Deus, a ti;\\nE faz-me sempre ser fiel me unindo, ó Deus, a Ti.\"}]},{\"number\":\"6\",\"collection_type\":\"Hinário\",\"title\":\"Por Belezas Naturais\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Por belezas naturais, pelo azul do lindo céu,\\nPor encantos imortais, ó Senhor, ao trono Teu\\nSe erguerá, e com fervor, Nossa voz em Teu louvor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por amigos e irmãos, pela luz do puro amor,\\nPor poderem nossas mãos trabalhar em Teu favor,\\nSe erguerá, também, Senhor, Nossa voz em Teu louvor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por Jesus, o Salvador, que por nós morreu na cruz,\\nPelo Espírito de amor que à verdade nos conduz,\\nSe erguerá, também, Senhor, Nossa voz em Teu louvor.\"}]},{\"number\":\"7\",\"collection_type\":\"Hinário\",\"title\":\"Sejas Louvado\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sejas Louvado, Rei Criador da natura!\\nLouva, minha alma, louva com zelo e ternura!\\nLouva ao Senhor pelo insondável amor,\\nCálido amor que perdura!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sejas Louvado, Tu que o Universo conduzes!\\nSob Tuas asas, paz e conforto produzes!\\nHaja louvor pelo Teu dom redentor,\\nPríncipe eterno das luzes!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sejas Louvado, pelo cuidado paterno!\\nsobre a verdade ergues Teu reino superno!\\nTeu, o louvor seja somente, Senhor,\\nPor Teu amor sempiterno!\"}]},{\"number\":\"8\",\"collection_type\":\"Hinário\",\"title\":\"A Ti Rendemos Glórias\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A Ti rendemos glórias, Ó Rei e Redentor,\\nA quem crianças rendem, também, o seu louvor.\\nSenhor, nos inclinamos aos Teus sagrados pés,\\nE a Ti nós adoramos, pois Deus eterno és.\"},{\"section_type\":\"Estrofe\",\"content\":\"A voz dos anjos santos, em sons transcendentais,\\nAqui na Terra ecoa na voz dos vis mortais.\\nSó Tu, ó Deus bondoso, és o Pastor fiel,\\nO Rei dos reis vindouro, Senhor de Israel.\"},{\"section_type\":\"Estrofe\",\"content\":\"Louvor Te deram antes da cruz e da paixão;\\nE nós também cantamos o dom da salvação,\\nPois Teu, Senhor, é o reino, a glória e o poder,\\nE a Ti, pra sempre, os salvos, mui gratos hão de ser.\"}]},{\"number\":\"9\",\"collection_type\":\"Hinário\",\"title\":\"Prece ao Trino Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó grande e eterno Deus! Ouve nos lá dos Céus;\\nEis a oração: Vem, Pai, presente estar,\\nVem, Teu poder nos dar,\\nCom Tua voz falar Ao coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó encarnado Deus, Sim, te adoramos nós,\\nBom Redentor; Vem nos purificar,\\nVem nos santificar;\\nDá-nos a Tua paz E o Teu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem, Consolador, Com tua voz falar\\nAo coração; E vem em nós morar,\\nConsolação nos dar,\\nTambém nos confirmar Na redenção.\"}]},{\"number\":\"10\",\"collection_type\":\"Hinário\",\"title\":\"Louvemos o Rei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Louvemos o Rei, glorioso Senhor\\nOh, vamos cantar de Seu infindo amor!\\nEscudo seguro é Seu grande poder,\\nE sempre Seus filhos está a defender.\"},{\"section_type\":\"Estrofe\",\"content\":\"Falemos de Deus, da graça sem-par,\\nDo grande Senhor do Céu, da Terra e mar,\\nQue forma a chuva, o vento e a luz.\\nA forte tormenta o Seu poder traduz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantemos do Seu cuidado por nós,\\nE demos ao Pai louvor em alta voz,\\nLouvemos, louvemos ao bom Criador,\\nAmigo sincero, fiel e Redentor.\"}]},{\"number\":\"11\",\"collection_type\":\"Hinário\",\"title\":\"Ao Deus de Abraão Louvai\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao Deus de Abraão louvai, supremo Criador,\\nEterno Deus, bondoso Pai e Rei Senhor.\\nO grande Deus EU SOU, Céu, Terra e mar formou,\\nMeu ser também dará louvor ao Deus de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao Deus de Abraão louvai, Eterno Benfeitor.\\nO povo Seu um dia vai ao lar de amor.\\nO mundo vil deixei, seu gozo e seu prazer,\\nE filho então de Deus serei até morrer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao Deus de Abraão louvai; os anjos dão louvor,\\nE vós também louvores daí ao Deus de amor.\\nAo Deus de Abraão e meu, no além irei louvar.\\nEternamente eu louvarei ao Deus sem-par.\"}]},{\"number\":\"12\",\"collection_type\":\"Hinário\",\"title\":\"Vinde, Povo do Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vinde povo do Senhor, adorai-o com louvor\\nAo Deus trino exaltai: a Jesus, a Deus, o Pai,\\nE ao Espírito de luz que em bondade nos conduz.\\nVinde, povo do Senhor, adorai o Deus de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Observemos com fervor este dia do Senhor,\\nPois as bênçãos lá do Céu, aos fiéis as prometeu.\\nAtentai à Sua voz com amor falar a nós.\\nVinde, povo do Senhor, exaltai o Criador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando a igreja se tornar triunfante, lá no lar,\\nNossas lutas findarão, e virá a redenção.\\nMal e dor ficando atrás, reinará amor e paz.\\nVinde, povo do Senhor, aclamai o Redentor.\"}]},{\"number\":\"13\",\"collection_type\":\"Hinário\",\"title\":\"Louvamos-Te, ó Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Louvamos-Te, ó Deus, pelo dom de Jesus,\\nQue por nós, pecadores, foi morto na cruz.\"},{\"section_type\":\"Coro\",\"content\":\"Aleluia! Toda a glória\\nTe rendemos sem fim.\\nAleluia! Tua graça\\nImploramos. Amém.\"},{\"section_type\":\"Estrofe\",\"content\":\"Louvamos-Te, ó Deus, pelo Espírito, luz\\nQue nos tira das trevas e a Cristo conduz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem nos encher de celeste fervor,\\nDe esperança e bondade, de fé, zelo e amor.\"}]},{\"number\":\"14\",\"collection_type\":\"Hinário\",\"title\":\"Jubilosos Te Adoramos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jubilosos te adoramos, Deus da glória, Deus do amor.\\nNosso coração transborda em louvor a Ti, Senhor.\\nRompe as nuvens da tristeza, do pecado e do temor.\\nDoador da eterna graça, enche-nos de Teu amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tuas obras anunciam Teu poder e resplendor.\\nCéus e Terra cantam hinos em louvor a Ti, Senhor.\\nVales, montes e campinas, lindos prados, verde mar,\\nAves, fontes cristalinas, todos querem te adorar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aleluia, aleluia, a Jesus o Redentor!\\nAleluia eternamente em louvor a Ti, Senhor\\nAo Consolador dai glória, pois conforto e vida traz.\\nAleluia ao Pai eterno, Deus da graça, Deus da paz!\"}]},{\"number\":\"15\",\"collection_type\":\"Hinário\",\"title\":\"Vós, Criaturas do Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vós, criaturas do Senhor,\\nOh, elevai a Deus louvor!\\nOh, louvai-O! Aleluia!\\nTu, Sol dourado a refulgir;\\nTu, Lua em prata a reluzir!\\nOh, louvai-O! Oh, louvai-O!\\nAleluia! Aleluia! Aleluia!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Terra e Céu, a Deus honrai;\\nPreito de amor e graças dai!\\nOh, louvai-O! Aleluia!\\nFlores, erguei-vos em canção\\nAo grande Deus da criação!\\nOh, louvai-O! Oh, louvai-O!\\nAleluia! Aleluia! Aleluia!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vós, homens sábios e de bem,\\nDai ao Senhor louvor também!\\nOh, louvai-O! Aleluia!\\nDai glória ao Filho, glória ao Pai,\\nE ao Santo Espírito louvai!\\nOh, louvai-O! Oh, louvai-O!\\nAleluia! Aleluia! Aleluia!\"}]},{\"number\":\"16\",\"collection_type\":\"Hinário\",\"title\":\"A Deus Demos Glória\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A Deus demos glória com grande fervor,\\nSeu Filho bendito por nós todos deu.\\nA graça concede ao mais vil pecador,\\nAbrindo-lhe a porta de entrada no Céu.\"},{\"section_type\":\"Coro\",\"content\":\"Exultai! Exultai! Vinde todos louvar\\nA Jesus Salvador; a Jesus Redentor.\\nA Deus demos glória, por quanto do Céu,\\nSeu Filho bendito por nós todos deu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! graça real! Foi assim que Jesus,\\nMorrendo, Seu sangue por nós derramou!\\nHerança nos Céus, com os santos em luz,\\nComprou-nos Jesus, pois o preço pagou.\"},{\"section_type\":\"Estrofe\",\"content\":\"A crer nos convida tal prova de amor,\\nNos merecimentos do Filho de Deus.\\nE quem, pois, confia no seu Salvador,\\nVai vê-Lo sentado na glória do Céu.\"}]},{\"number\":\"17\",\"collection_type\":\"Hinário\",\"title\":\"Nós Te Adoramos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nós Te adoramos, Deus infinito,\\nE a Teu Filho, Rei, Salvador;\\nTeu nome eterno é sempre bendito;\\nTeu Espírito traz-nos amor.\\nGlória rendemos, honra, louvor,\\nE adoração a Ti, ó Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Éramos presos pelo pecado,\\nTu nos livraste dessa prisão;\\nE por Teu Filho imaculado,\\nOfertaste-nos a salvação.\\nGlória rendemos, honra, louvor,\\nE adoração a Ti, Redentor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu nos convences dos vis pecados,\\nE da justiça, luzes nos dás,\\nE à verdade somos guiados,\\nÓ Espírito Santo de paz.\\nGlória rendemos, honra, louvor,\\nE adoração, ó consolador!\"}]},{\"number\":\"18\",\"collection_type\":\"Hinário\",\"title\":\"Santo! Santo! Santo!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Santo! Santo! Santo! Deus onipotente!\\nCedo de manhã cantaremos Teu louvor.\\nSanto! Santo! Santo! Deus Jeová triúno!\\nÉs Deus excelso, nosso Criador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Santo! Santo! Santo! Nós, os pecadores,\\nNão podemos ver Tua glória sem tremor.\\nTu somente és santo, justo e compassivo,\\nPuro e perfeito, nosso Redentor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Santo! Santo! Santo! Deus onipotente!\\nTua criação manifesta o Teu amor.\\nAntes de criares todo o Céu e a Terra,\\nEras e sempre hás de ser, Senhor.\"}]},{\"number\":\"19\",\"collection_type\":\"Hinário\",\"title\":\"Ao Coro dos Arcanjos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao coro dos arcanjos eu uno meu louvor,\\nE adoro humildemente o grande Criador.\\nEnquanto os passarinhos voando pelo ar\\nEntoam seus louvores, eu ergo meu cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se às vezes sou tentado a ouvir a voz do mal,\\nEscuto, então, dos anjos, o coro divinal.\\nEu canto em voz mais alta que a voz do tentador,\\nE nesse mesmo instante renovo meu vigor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nas horas de tristeza, nas lutas e na dor,\\nNos dias de saudade do eterno lar de amor,\\nEu ouço a natureza, feliz, rejubilar,\\nE sinto da harmonia a paz me confortar.\"}]},{\"number\":\"20\",\"collection_type\":\"Hinário\",\"title\":\"A Ti, Toda Glória\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A Ti, toda glória e louvores rendemos,\\nSenhor do Universo e Deus, Criador!\\nReunidos, rogamos as Tuas santas bênçãos,\\nE graças ofertamos por Teu grande amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó fonte perene de bênçãos constantes,\\nFruindo Tua graça queremos viver;\\nSustém-nos os passos, pois, são mui vacilantes;\\nSomente pela fé nós podemos vencer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Louvores rendemos por Tua bondade.\\nTeu Filho querido nos deste, na cruz;\\nSua morte nos trouxe perdão e eternidade,\\nE abriu-nos os portais para o reino de luz.\"}]},{\"number\":\"21\",\"collection_type\":\"Hinário\",\"title\":\"Vigiar e Orar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem de manhã, embora o céu sereno\\nPareça um dia calmo anunciar,\\nVigia e ora; o coração pequeno\\nUm temporal pode abrigar.\"},{\"section_type\":\"Coro\",\"content\":\"Bem de manhã, e sem cessar;\\nVigiar sim, e orar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao meio-dia, quando os sons da Terra\\nAbafam mais de Deus a voz de amor,\\nRecorre à oração, evita a guerra,\\nE goza paz com o Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao fim do dia, após os teus lidares,\\nRelembra as bênçãos do celeste amor,\\nE conta a Deus prazeres e pesares,\\nDeixando em Suas mãos a dor.\"},{\"section_type\":\"Estrofe\",\"content\":\"E sem cessar, vigia a cada instante,\\nQue o inimigo ataca sem parar;\\nSó com Jesus, em comunhão constante,\\nPode o mortal ao Céu chegar\"}]},{\"number\":\"22\",\"collection_type\":\"Hinário\",\"title\":\"Bem de Manhã\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem de manhã, sereno surge o dia;\\nJá aves mil entoam seu louvor.\\nLuz vem encher o mundo de alegria.\\nBem de manhã, contigo estou, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem de manhã, alegre, a natureza\\nDá seu louvor ao Deus da criação.\\nSó, com fervor, eu busco mais pureza;\\nEu venho a Ti, ó Deus, em oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pai, quando enfim a luz fugir do mundo,\\nJá quando o céu escuro e negro for,\\nVem conceder, em Teu amor profundo,\\nLuz, proteção, descanso em Ti, Senhor.\"}]},{\"number\":\"23\",\"collection_type\":\"Hinário\",\"title\":\"De Manhã Bem Cedo Busco\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"De manhã bem cedo busco,\\nDe Jesus, a direção,\\nPra seguir sempre Seus passos,\\nNo conforto ou na aflição.\"},{\"section_type\":\"Coro\",\"content\":\"Ele me ama, Ele me ama,\\nCristo me ama, bem o sei.\\nTenho a prova no Calvário;\\nPara sempre ama-lo-ei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu, embora pequenino,\\nObedeço ao Seu mandar.\\nSigo a estrada que Ele mostra,\\nSem temer nem hesitar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele é forte, me protege,\\nE me guarda de pecar.\\nSe tentado corro a Ele,\\nQue me livra sem tardar.\"}]},{\"number\":\"24\",\"collection_type\":\"Hinário\",\"title\":\"Desponta o Sol\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Desponta o Sol, e eu venho a Ti,\\nSenhor dos altos Céus;\\nOuvir-me-ás a voz aqui,\\nA voz dos rogos meus?\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem cedo, ó Pai, irás me ouvir,\\nSim, desde o arrebol;\\nCom Tua mão me conduzir;\\nAté o pôr-do-sol.\"},{\"section_type\":\"Estrofe\",\"content\":\"E quando enfim voltar Jesus,\\nCom glória e resplendor;\\nQue eu possa então, brilhando em luz,\\nSubir ao lar de amor.\"}]},{\"number\":\"25\",\"collection_type\":\"Hinário\",\"title\":\"Bendito Seja Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Na luz da alvorada,\\nMinh'alma acorda e brada:\\nBendito seja Deus!\\nE quando o dia aquece,\\nEu canto em minha prece:\\nBendito seja Deus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Então a vil fraqueza\\nTransforma-se em firmeza:\\nBendito seja Deus!\\nNo meio da agonia,\\nDeus manda-me alegria:\\nBendito seja Deus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantai, com alegria,\\nA doce melodia:\\nBendito seja Deus!\\nA quem minh'alma adora,\\nDizei, nações, agora:\\nBendito seja Deus!\"},{\"section_type\":\"Estrofe\",\"content\":\"E seja o nosso canto\\nSincero, puro e santo:\\nBendito seja Deus!\\nCantai, ó cristandade,\\nPor toda a eternidade:\\nBendito seja Deus!\"}]},{\"number\":\"26\",\"collection_type\":\"Hinário\",\"title\":\"Luzes da Aurora\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Luzes da aurora faze brilhar,\\nÓ Pai, agora, ao despertar;\\nSim, bem cedinho, faze luzir,\\nHoje, o caminho meu a seguir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cresça Teu brilho, luz divinal,\\nSobre meu trilho, longe do mal;\\nEu me humilho ante Teus pés,\\nPois sou Teu filho; meu Deus Tu és.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dia após dia, dá-me, Senhor,\\nMais alegria e mais fervor;\\nFelicidade na retidão,\\nE santidade de coração.\"}]},{\"number\":\"27\",\"collection_type\":\"Hinário\",\"title\":\"Perto do Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Desce o Sol atrás dos montes,\\nE a tarde já chegou.\\nCalma e quieta vem a noite,\\nMais um dia terminou;\\nJá se foi com sua luta,\\nLogo a negra noite vem,\\nMas é doce a lembrança:\\nPerto está o lar de além.\"},{\"section_type\":\"Coro\",\"content\":\"Perto do lar, perto do lar,\\nPerto, sim, do lar dos Céus!\\nDesse tão lindo lar\\nCom fontes de cristal,\\nDo país do eterno Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mui cansado o peregrino\\nQuer do dia ao fim chegar;\\nDo labor, que é tão penoso,\\nOutra vez vai descansar.\\nTal a vida, neste mundo,\\nQue havemos de passar,\\nMas as sombras nos relembram:\\nPerto está o eterno lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais um dia na viagem\\nPara a casa paternal;\\nJá mais perto está o rio\\nDo país celestial.\\nA cidade já refulge,\\nVislumbramos seu fulgor;\\nCada vez mais perto estamos\\nDo glorioso lar de amor.\"}]},{\"number\":\"28\",\"collection_type\":\"Hinário\",\"title\":\"Morre o Dia\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Morre o dia, põe-se o Sol;\\nDesce à Terra, na amplidão,\\nSuave calma, doce paz;\\nVem, medita em oração,\\nEm oração\"},{\"section_type\":\"Coro\",\"content\":\"Santo, santo, santo és, nosso Deus!\\nToda a Terra e altos Céus\\nDão-Te graças e louvor,\\nA Ti, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando as sombras sobrevêm,\\nCobre-nos com Tua mão.\\nTu, que lá no Céu estás,\\nVem ao nosso coração,\\nAo coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando a noite a nós vier,\\nE chegar a escuridão,\\nQue em Tua graça, ó Deus,\\nHaja, enfim, ressurreição,\\nRessurreição.\"}]},{\"number\":\"29\",\"collection_type\":\"Hinário\",\"title\":\"Já o Dia Longe Vai\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Já o dia longe vai;\\nCom negror a noite cai.\\nLivre, agora, do labor,\\nVenho a Ti, meu. bom Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu, que a todos vês dos Céus,\\nVés também os erros meus,\\nMas às faltas contra a lei,\\nDá perdão, bondoso Rei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minha noite triste cai,\\nLonge a luz do Sol se vai.\\nQuero, pois, em Ti, meu Deus,\\nRepousar dos fardos meus.\"}]},{\"number\":\"30\",\"collection_type\":\"Hinário\",\"title\":\"Hora Feliz do Pôr-do-Sol\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Hora feliz do pôr-do-sol,\\nHora de paz e comunhão,\\nHora de luz celestial,\\nHora de fé e de oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bênçãos de paz, de amor e luz,\\nPara os fiéis vem dar Senhor.\\nVimos a Ti com gratidão,\\nPara cantar em Teu louvor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! Como é bom aqui sentir\\nTeu divinal e eterno amor!\\nDá-nos, ó Deus, o Teu perdão,\\nGraça e poder, ó bom Senhor!\"}]},{\"number\":\"31\",\"collection_type\":\"Hinário\",\"title\":\"Sublime Amor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sublime amor, o amor de Deus,\\nQue lira não traduzirá!\\nMaior que o mar, maior que o céu,\\nJamais alguém compreenderá!\\nAo pecador em aflição,\\nSeu Filho, Deus entregou;\\nAo sofredor deu Ele a mão,\\nE as culpas lhe perdoou.\"},{\"section_type\":\"Coro\",\"content\":\"Sublime amor, o amor de Deus!\\nOh! Maravilha sem-par!\\nPôr esse amor, eternamente,\\nA Deus iremos louvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se em tinta o mar se transformasse,\\nE em papel o céu também,\\nE a pena ágil deslizasse,\\nDizendo o que esse amor contém,\\nDaria fim ao grande mar,\\nAo esse amor descrever,\\nE o céu seria mui pequeno\\nPra tal relato conter.\"},{\"section_type\":\"Estrofe\",\"content\":\"Excelso amor; o amor de Deus,\\nQue nos remiu da perdição!\\nEm gratidão proclamaremos\\nTão grande amor e salvação.\\nE quando enfim no lar dos Céus,\\nEm gozo e glória eternal,\\nPra sempre ali desfrutaremos\\nDo grande amor divinal.\"}]},{\"number\":\"32\",\"collection_type\":\"Hinário\",\"title\":\"Deus é nosso Pai Amado\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jamais teu coração se turbe,\\nNem nele haja algum temor;\\nPois Deus, do Céu, de ti bem cuida;\\nOh, confia em teu Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"Deus é nosso Pai amado,\\nQue das aves zela bem;\\nDá ao lírio tanta glória!\\nSim, te atenderá também.\"},{\"section_type\":\"Estrofe\",\"content\":\"O fardo pode ser pesado,\\nGrande a cruz a conduzir;\\nLevando a Cristo teu cuidado,\\nVais com Ele o repartir.\"},{\"section_type\":\"Estrofe\",\"content\":\"No céu, se negras nuvens pairam,\\nDando a ti perturbação,\\nOh, busca em Cristo novo alento;\\nNEle há consolação.\"}]},{\"number\":\"33\",\"collection_type\":\"Hinário\",\"title\":\"Castelo Forte\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Castelo forte é nosso Deus, refúgio e fortaleza.\\nCom Seu poder defende os Seus, e os livra com presteza.\\nCom fúria pertinaz, nos segue Satanás,\\nCom artimanhas tais e astúcias tão cruéis\\nQue iguais não há na Terra.\"},{\"section_type\":\"Estrofe\",\"content\":\"A nossa força nada faz, estamos, sim, perdidos;\\nMas nosso Deus socorro traz, e somos protegidos.\\nSabeis quem é Jesus, o que venceu na cruz?\\nSenhor dos altos Céus, e, sendo o próprio Deus,\\nTriunfa na batalha.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se nos quisessem devorar, demônios não contados,\\nNão nos iriam assustar, nem somos derrotados.\\nO grande acusador dos servos do Senhor,\\nJá condenado está; vencido cairá\\nPor uma só palavra.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, que a palavra vencerá, sabemos com certeza;\\nE nada nos assustará, com Cristo por defesa.\\nSe temos de deixar parentes, bens e lar,\\nEmbora a vida vá, por nós Jesus está\\nE dar-nos-á Seu reino.\"}]},{\"number\":\"34\",\"collection_type\":\"Hinário\",\"title\":\"Quão Grande És Tu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Senhor meu Deus, quando eu, maravilhado,\\nFico a pensar nas obras de Tuas mãos,\\nEstrelas mil a cintilar no espaço,\\nDe Teu poder, em manifestação,\"},{\"section_type\":\"Coro\",\"content\":\"Então minh'alma canta a Ti, Senhor:\\nQuão grande és Tu! Quão grande és Tu!\\nEntão minh'alma canta a Ti, Senhor:\\nQuão grande és Tu! Quão grande és Tu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se ao calminhar por campos e florestas,\\nEscuto as aves belas a cantar;\\nSe estendo o olhar do alto da montanha\\nE a fonte além eu ouço a murmurar,\"},{\"section_type\":\"Estrofe\",\"content\":\"Se penso, então, que sem poupar Teu Filho,\\nO enviaste pra morrer por mim,\\nLevando à cruz os meus pecados todos,\\nPara eu viver eternamente assim,\"},{\"section_type\":\"Estrofe\",\"content\":\"E ao vir Jesus em resplendor e glória,\\nPara levar-me ao lar dos filhos Seus,\\nProstrar-me-ei em gratidão infinda,\\nE exclamarei: Quão grande és Tu, meu Deus!\"}]},{\"number\":\"35\",\"collection_type\":\"Hinário\",\"title\":\"Tu És Fiel, Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tu és fiel, Senhor, ó Deus eterno!\\nTeus filhos sabem que não falharás!\\nNunca mudaste, Tu nunca falhaste;\\nTal como eras, sim, sempre serás.\"},{\"section_type\":\"Coro\",\"content\":\"Tu és fiel, Senhor! Tu és fiel, Senhor!\\nDias após dia Tuas bênçãos nos dás.\\nTua mercê nos sustenta e nos guarda;\\nSim, para sempre, ó Deus, fiel serás.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nuvens no azul do céu, Sol refulgente,\\nMontes e vales, campinas em flor,\\nTudo criaste na terra e nos ares,\\nE todos louvam-Te, fiel Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pleno perdão nos dás, que segurança!\\nSempre nos guias na senda do bem;\\nE no porvir, oh! Que doce esperança!\\nTu nos receberás no lar de além.\"}]},{\"number\":\"36\",\"collection_type\":\"Hinário\",\"title\":\"O Mundo é de Meus Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O mundo é de meu Deus, Senhor da criação.\\nE todo ser que vida tem O louva em gratidão.\\nO mundo é de meu Deus; conforta assim pensar.\\nDeus fez o Sol e o lindo céu, Deus fez a terra e O mar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O mundo é de meu Deus; as aves na amplidão,\\nO lírio branco e o arrebol provêm de Sua mão.\\nO mundo é de meu Deus, em tudo posso ver;\\nAté na brisa a sussurrar, percebo Seu poder\"},{\"section_type\":\"Estrofe\",\"content\":\"O mundo é de meu Deus, jamais olvidarei.\\nEm toda a vasta criação, somente Deus é Rei.\\nO mundo é de meu Deus; e o Salvador Jesus,\\nPara esta Terra resgatar, a vida deu na cruz.\"}]},{\"number\":\"37\",\"collection_type\":\"Hinário\",\"title\":\"Tudo Que Há em Terra e Mar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Coro\",\"content\":\"Tudo que há em terra e mar;\\nBelezas que há no céu;\\nTudo que o bom Deus criou\\nTraz honra ao nome Seu.\"},{\"section_type\":\"Estrofe\",\"content\":\"A linda flor se abrindo,\\nE o canto do pardal,\\nDe Deus o amor revelam,\\nCom graça divinal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Florestas e montanhas,\\nO rio a correr;\\nO pôr-de-sol tão lindo,\\nDeus fez com Seu poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deu olhos para vermos,\\nE lábios pra cantar;\\nO Seu amor infindo,\\nOh, vamos proclamar!\"}]},{\"number\":\"38\",\"collection_type\":\"Hinário\",\"title\":\"Encanto Sem Igual\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há encantos no sol pela tarde,\\nEncantos no lindo arrebol;\\nMas encanto de encantos será pra mim,\\nTer-me Deus amado assim.\"},{\"section_type\":\"Coro\",\"content\":\"Há encanto sem igual, encanto sem igual,\\nEm ter Deus me amado assim;\\nHá encanto sem igual, encanto sem igual,\\nEm ter Deus amor por mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Há encantos no céu, numa estrela,\\nNos vales e campos em flor;\\nMas encanto de encantos será pra mim,\\nEsse amor de Deus, sem fim.\"}]},{\"number\":\"39\",\"collection_type\":\"Hinário\",\"title\":\"O Céu Azul\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O céu azul na amplidão,\\nEstrelas mil em multidão,\\nA luz do céu e seu fulgor\\nProclamarão o Criador.\\nO Sol de luz, com seu calor,\\nLouvor dará ao seu Autor,\\nE sem falar, a resplender,\\nDirá de Deus e Seu poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao grande Deus, o som do mar,\\nA flor gentil, a voz do ar,\\nA doce paz da noite azul\\nAclamarão de norte a sul.\\nAssim dirão o céu e o mar,\\nDo Seu poder e amor sem par.\\nE vós, nações clamai também!\\nLouvai a Deus, Senhor! Amém.\"}]},{\"number\":\"40\",\"collection_type\":\"Hinário\",\"title\":\"Filhos do Pai Celeste\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus é nosso Pai celeste,\\nSomos sempre bem guardados;\\nNem às aves e às estrelas;\\nEle mostra tais cuidados.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus, com zelo, com ternura,\\nSeus filhinhos alimenta;\\nDo pecado Ele os livra\\nE em Seus braços os sustenta.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na tristeza ou na bonança,\\nNunca os filhos Deus olvida;\\nSeu desejo é guardá-los\\nPuros, santos para a vida.\"}]},{\"number\":\"41\",\"collection_type\":\"Hinário\",\"title\":\"Glória ao Rei Que Vos Nasceu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Já soou por todo o céu:\\n\\\"Glória ao Rei que vos nasceu!\\\"\\nGraça e paz Deus quer doar,\\nHomens vis, reconciliar.\\nVós nações, cantai louvor;\\nÓ, cantai de Deus o amor;\\nProclamai, pois, vós também,\\nQuem nasceu lá em Belém.\\nJá soou por todo o céu:\\n\\\"Glória ao Rei que vos nasceu!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Dêem louvor os anjos Seus,\\nCristo é o eterno Deus;\\nTerra e céu, e mar sabei\\nQue nasceu o grande Rei.\\nPara nós, no mundo, paz,\\nCristo lá do Céu nos traz.\\nAtravés de cruz e fel,\\nSer-nos-á \\\"Emanuel\\\".\\nJá soou por todo o céu:\\n\\\"Glória ao Rei que vos nasceu!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Proclamai o Rei da paz,\\nRei que a nós justiça traz;\\nVida e luz a todos dá\\nPobre Rei, em palha está!\\nGlória e Céu abandonou!\\nOh! sim, Deus o mundo amou!\\nCom amor nos dá perdão\\nE eternal ressurreição.\\nJá soou por todo o céu:\\n\\\"Glória ao Rei que vos nasceu!\\\"\"}]},{\"number\":\"42\",\"collection_type\":\"Hinário\",\"title\":\"Noite de Paz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tudo é paz! Tudo amor!\\nDormem todos em redor.\\nEm Belém Jesus nas ceu,\\nRei da paz, da Terra e Céu;\\nNosso Salvador é Jesus, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Glória a Deus! Glória a Deus!\\\"\\nCantam anjos lá nos Céus;\\nBoas novas de perdão,\\nGraça eterna, salvação.\\nProva desse amor, dá o Redentor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Rei da paz, Rei do amor,\\nÉ Jesus o Salvador.\\nVinde todos Lhe pedir\\nQue nos venha conduzir;\\nDeste mundo, a luz é o Senhor Jesus.\"}]},{\"number\":\"43\",\"collection_type\":\"Hinário\",\"title\":\"Soou em Meio à Noite Azul\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Soou em meio à noite azul, um hino divinal;\\nJamais com tal beleza assim, ouviu algum mortal.\\nDo Céu ao mundo, graça e paz! Excelso dom gentil!\\nDos anjos essa doce voz encheu o céu anil.\"},{\"section_type\":\"Estrofe\",\"content\":\"Enquanto os anjos inda estão cantando, com prazer,\\nLouvor por todo o céu sem fim ao mais sublime Ser,\\nEntão, suave e meiga voz, descendo como um véu,\\nCantou que já nasceu Jesus e uniu a Terra ao Céu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! quem nos dera sempre ouvir as vozes divinais!\\nSentir a paz do Céu de luz, país dos imortais!\\nLouvar a Cristo, o Rei dos reis, com anjos em canção!\\nNo lar possamos nós também cantar a salvação!\"}]},{\"number\":\"44\",\"collection_type\":\"Hinário\",\"title\":\"Natal! Feliz Natal!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Natal, feliz Natal! No céu de Belém,\\nUma luz que surgiu fez vibrar, lá no além,\\nA voz de querubins em sons divinais,\\nQue do Céu proclamou salvação aos mortais.\"},{\"section_type\":\"Coro\",\"content\":\"Natal, feliz natal!\\nNatal, Natal!\\nEis que nasceu\\nNosso Rei divinal!\"},{\"section_type\":\"Estrofe\",\"content\":\"A paz então reinou em, céu, terra e mar,\\nAo descer sobre o Rei uma luz tutelar;\\nA luz do Salvador brilhou mais e mais,\\nE guiou a Seus pés nobres reis orientais.\"},{\"section_type\":\"Estrofe\",\"content\":\"A luz que fez remar a paz divinal,\\nQue encheu todo o céu de fulgor sideral,\\nA luz que ainda está no céu a luzir,\\nVem também nossos pés a Jesus conduzir.\"}]},{\"number\":\"45\",\"collection_type\":\"Hinário\",\"title\":\"Nasce Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nasce Jesus, fonte de luz!\\nDescem os anjos cantando.\\nNasce Jesus, é nossa luz,\\nTrevas vem, pois, dissipando.\\nNasce Jesus, fonte de luz!\\nOh! glória a Deus nas alturas!\\nVede a redenção raiar, Cristo ao mundo vem!\\nSe, pois, bem-vindo! Firma Teu justo império!\\nHonras e glórias, anjos e homens dêem!\"},{\"section_type\":\"Coro\",\"content\":\"Nasce Jesus fonte de luz!\\nOh! glória a Deus nas alturas!\\nPaz na Terra, aos homens\\nA quem quer Ele bem.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus nos amou, Deus nos mandou\\nCristo, Seu Filho querido.\\nDeus nos amou, Deus encarnou.\\nVede o Menino nascido!\\nDeus nos amou! Deus nos salvou!\\nDigam-no todos os povos;\\nPodem salvação fruir, todos os que crêem!\\nReino bendito! Reino do amor divino!\\nEis que resgate, todos, por Cristo, têm!\"}]},{\"number\":\"46\",\"collection_type\":\"Hinário\",\"title\":\"Estrela de Luz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Estrela de luz um dia brilhou,\\nCom raro fulgor, e os magos guiou\\nAo pobre curral da humilde Belém,\\nAo meigo Jesus, a fonte do bem.\"},{\"section_type\":\"Coro\",\"content\":\"Brilhando inda está, brilhando inda está,\\nA estrela de luz, de raro fulgor\\nBrilhando inda está, brilhando inda está,\\nA estrela a indicar o Deus Salvador\"},{\"section_type\":\"Estrofe\",\"content\":\"Já por Balaáo, da estrela porvir,\\nOuviram falar, em terra oriental;\\nE logo que a vêem, a estão a seguir,\\nE vão encontrar Jesus, afinal.\"},{\"section_type\":\"Estrofe\",\"content\":\"A fim de encontrar e ter salvação,\\nHavemos também de a estrela seguir;\\nE achando a Jesus, felizes, então,\\nDo amor e da paz iremos fruir.\"}]},{\"number\":\"47\",\"collection_type\":\"Hinário\",\"title\":\"Belém, Bendita És\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Belém, bendita és entre as cidades de Judá;\\nEnquanto assim tu dormes, oh! que bênção Deus te dá!\\nEmbora obscura, brilha em ti a eterna luz,\\nA luz das esperanças que os mortais a Deus conduz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em ti já é nascido o Messias Redentor;\\nNo Céu os santos anjos cantam glórias, dão louvor.\\nÓ vós, estrelas d'alva, a nova anunciai;\\nA Deus erguei hosanas, e a nós a paz cantai!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem, Senhor e Mestre que nasceste em Belém;\\nVisita-nos e nasce em nosso coração também.\\nA voz dos anjos soa, a paz a proclamar.\\nJesus, agora mesmo vem, sim, vem em nós morar.\"}]},{\"number\":\"48\",\"collection_type\":\"Hinário\",\"title\":\"Ó, Vinde, Adoremos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Chegai-vos, ó crentes, vinde jubilosos\\nSigamos a estrela do céu de Belém!\\nEis que é nascido Cristo, Rei da glória!\"},{\"section_type\":\"Coro\",\"content\":\"Ó, vinde, adoremos!\\nÓ, vinde, adoremos!\\nÓ, vinde, adoremos o Rei Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó coros celestes, plenos de harmonia,\\nUnivos aos povos, cantai com fervor!\\nÓ, dai hosanas, glória nas alturas!\"},{\"section_type\":\"Estrofe\",\"content\":\"Com altos louvores, glória a Deus rendemos,\\nPor CRisto que ao mundo desceu lá do além!\\nOh! para sempre temos Deus conosco!\"}]},{\"number\":\"49\",\"collection_type\":\"Hinário\",\"title\":\"Surgem Anjos Proclamando\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Surgem anjos proclamando\\nPaz na Terra, e a Deus, louvor.\\nVão seus hinos ecoando\\nNas montanhas, ao redor.\"},{\"section_type\":\"Coro\",\"content\":\"Glória, glória a Deus nas alturas!\\nGlória, glória a Deus nas alturas!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vão-se alegres os pastores\\nVer o Infante celestial,\\nE acrescentam seus louvores\\nAo louvor angelical.\"},{\"section_type\":\"Estrofe\",\"content\":\"Berço rude, Lhe foi dado,\\nMas do Céu Lhe vem louvor.\\nEle é o Salvador amado,\\nBem merece o nosso amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Povos, tribos, celebrai-O!\\n\\\"Glória a Deus\\\", também dizei.\\nDe joelhos adorai-O;\\nEle é o Cristo, o grande Rei!\"}]},{\"number\":\"50\",\"collection_type\":\"Hinário\",\"title\":\"Num Berço de Palha\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Num berço de palha dormia Jesus,\\nO meigo Menino, coberto de luz,\\nNum rude presépio, à noite, em Belém,\\nEnquanto as estrelas brilhavam além.\"},{\"section_type\":\"Estrofe\",\"content\":\"Acorda o Menino o gado a mugir,\\nMas Ele não chora, Se põe a sorrir.\\nEu Te amo, Menino nascido em Belém;\\nÓ, guia meus pés no caminho do bem.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem perto de nós permanece, ó Senhor,\\nGuardando-nos sempre com Teu santo amor;\\nContigo queremos pra sempre ficar;\\nÓ, dá-nos entrada no Teu doce lar.\"}]},{\"number\":\"51\",\"collection_type\":\"Hinário\",\"title\":\"Clara Noite\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Clara noite, feliz e calma;\\nDoce paz já envolve o céu.\\nVibram vozes em nossa alma,\\nPois Jesus, nosso Rei, nasceu.\\nRompam as fontes da alegria,\\nPois já nasceu o Salvador.\\nRompam as fontes da alegria,\\nPois já nasceu o Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantam anjos no firmamento\\nUm louvor ao Menino Dues;\\nBrilha a estrela, por um momento,\\nA indicar o Senhor dos Céus.\\nTodos cantemos: \\\"Deus conosco,\\nNoite feliz, feliz Natal!\\\"\\nTodos cantemos: \\\"Deus conosco,\\nNoite feliz, feliz Natal!\\\"\"}]},{\"number\":\"52\",\"collection_type\":\"Hinário\",\"title\":\"Vestido, em Linho\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vestido em linho Jesus desceu,\\nTrazendo salvação;\\nDe mirra o bálsamo traz do Céu,\\nBeleza e perfeição.\"},{\"section_type\":\"Coro\",\"content\":\"Vindo ao mundo, deixou no Céu\\nPalácios de marfim;\\nGlória não quis; em dor morreu.\\nA cruz suportou por mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Trazendo em Si de aloés o odor,\\nA morte atroz sofreu;\\nProvou aqui amargura e dor;\\nAo mundo abriu o Céu\"},{\"section_type\":\"Estrofe\",\"content\":\"Olor de cássia as vestes têm:\\nSim, Ele ressurgiu;\\nE junto ao Pai Se assentou no além;\\nAo homem redimiu.\"}]},{\"number\":\"53\",\"collection_type\":\"Hinário\",\"title\":\"Conta-me a História de Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Conta-me a história de Cristo,\\nGrava-a em meu coração.\\nConta-me a história preciosa,\\nConta-me com emoção.\\nConta-me como Seus anjos\\nDeram-Lhe honra ao nascer:\\n\\\"Glória ao Senhor, paz na Terra\\\",\\nAo Céu fizeram ascender.\"},{\"section_type\":\"Coro\",\"content\":\"Conta-me a história de Cristo;\\nGrava-a em meu coração.\\nConta-me a história preciosa;\\nConta-me com emoção!\"},{\"section_type\":\"Estrofe\",\"content\":\"Conta-me a história de Cristo,\\nQuando na Cruz expirou.\\nConta-me como O choraram,\\nE como ressuscitou.\\nNessa história tão terna,\\nVejo o Seu grande amor.\\nQuero pra sempre servi-Lo;\\nÉ meu Senhor e Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Essa história bendita,\\nDeves contar com amor,\\nAo mundo todo falando,\\nDe Seu poder salvador.\\nHoje no Céu intercede,\\nEsse fiel Redentor;\\nVida eterna concede,\\nAos que aceitam Seu favor.\"}]},{\"number\":\"54\",\"collection_type\":\"Hinário\",\"title\":\"A Doce História\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Alegro-me em proclamar a história de Jesus,\\nQue veio lá da glória, morrer na amarga cruz!\\nSim, quero proclamá-la, pois ela satisfaz\\nAnseios de minh'alma, e enche-me de paz.\"},{\"section_type\":\"Coro\",\"content\":\"Oh! doce e bela história\\nDe Cristo, o Salvador!\\nDe Sua eterna graça,\\nDe Seu imenso amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Desejo sempre repetir a história desse amor;\\nQue trouxe nova vida. Oh! glória ao Salvador!\\nE Cristo ainda hoje, com terna compaixão\\nProcura pecadores e dá-lhes o perdão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, dessa história vou falar pra sempre, com fervor,\\nPois muitos inda vivem nas trevas e na dor.\\nE mesmo lá na glória, no bom e eterno lar,\\nTão linda e doce história eu hei de celebrar!\"}]},{\"number\":\"55\",\"collection_type\":\"Hinário\",\"title\":\"Cantarei a Linda História\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cantarei a linda história\\nDe Jesus, o Salvador\\nQue deixou Seu lar na glória\\nPra salvar o pecador.\"},{\"section_type\":\"Coro\",\"content\":\"Cantarei a linda história De Jesus e Seu amor;\\nCom fervor, na Sua glória, louvarei ao Salvador\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu andei, do lar, distante,\\nPrestes já a perecer,\\nMas Jesus, então, buscou-me\\nE salvou meu pobre ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Muitas vezes dias tristes\\nE aflições me sobrevêm,\\nMas Jesus depressa estende\\nSua mão que me sustém.\"}]},{\"number\":\"56\",\"collection_type\":\"Hinário\",\"title\":\"As Mãos do Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu vi essas mãos de meu Mestre,\\nQue pão deram à multidão,\\nChamando gentis criancinhas\\nE abençoando-as então.\"},{\"section_type\":\"Coro\",\"content\":\"Oh! belas mãos, as mãos do Senhor;\\nCrucificadas por ti!\\nMãos que serviram em santo labor;\\nMãos que inda velam por ti!\"},{\"section_type\":\"Estrofe\",\"content\":\"Aos pobres e fracos erguiam,\\nCuravam qualquer sofredor;\\nServiam choupanas humildes,\\nExemplificavam o amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, hoje a caminho à cidade,\\nDa qual é Deus Pai construtor,\\nEstão essas mãos a indicar-nos,\\nE estendem-se a ti, pecador.\"}]},{\"number\":\"57\",\"collection_type\":\"Hinário\",\"title\":\"Eu Quisera Andar com Cristo\",\"author\":\"Frederico Gerling Jr. (1925- )\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu quisera andar com Cristo,\\nSobre o mar da Galiléia;\\nAo Seu lado, pela Judéia,\\nPartilhar da celestial missão.\"},{\"section_type\":\"Coro\",\"content\":\"Com Cristo andar, com Cristo andar,\\nSentir em mim essa emoção;\\nBem sei, Senhor, que um dia a sentirei,\\nBem junto a Ti, Jesus, no eterno lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quisera andar com Cristo,\\nVer Suas santas mãos curando,\\nOs Seus lábios sempre pregando\\nDo infinito e divinal amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quisera andar com Cristo,\\nDe joelhos lá no horto,\\nImplorando de Deus conforto\\nPra Seu Filho suportar na cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quisera andar com Cristo,\\nQuando ao Céus subiu na nuvem;\\nEu quisera subir com Ele,\\nPra sempre tê-Lo junto a mim.\"}]},{\"number\":\"58\",\"collection_type\":\"Hinário\",\"title\":\"Conta-me a Velha História\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Conta-me a velha história, suave, com dulçor,\\nDe meu Jesus e Sua glória, de Cristo e Seu amor,\\nCom calma e com paciência, pois quero alcançar\\nA altura do mistério: que Deus nos pode amar.\"},{\"section_type\":\"Coro\",\"content\":\"Conta-me a velha história,\\nVelha e sublime história!\\nConta-me, pois, a história\\nDo meigo Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Fala-me com doçura do meigo Redentor,\\nDe Seu amor e Sua graqa, Pois, Sou um pecador,\\nSim, para o meu conforto, em tempos de aflição,\\nRepete a velha história de amor e salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se o brilho deste mundo toldar do Céu a luz,\\nRepete então a mesma história da graça de Jesus!\\nE quando, enfim, a glória do mundo além raiar,\\nOh, conta a mesma história: que veio aqui salvar.\"}]},{\"number\":\"59\",\"collection_type\":\"Hinário\",\"title\":\"'Stavas Lá?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"'Stavas lá, ao pregarem meu Jesus?\\n'Stavas lá, ao pregarem meu Jesus?\\nOh! nisto pensando, quanto tremo, tremo, tremo!\\n'Stavas lá, ao pregarem meu Jesus?\"},{\"section_type\":\"Estrofe\",\"content\":\"'Stavas lá, quando o Sol não quis brilhar?\\n'Stavas lá, quando o Sol não quis brilhar?\\nOh! nisto pensando, quanto tremo, tremo, tremo!\\n'Stavas lá, quando o Sol não quis brilhar?\"},{\"section_type\":\"Estrofe\",\"content\":\"'Stavas lá, quando Ele ressurgiu?\\n'Stavas lá, quando Ele ressurgiu?\\nOh! nisto pensando, quanto tremo, tremo, tremo!\\n'Stavas lá, quando Ele ressurgiu?\"}]},{\"number\":\"60\",\"collection_type\":\"Hinário\",\"title\":\"Foi por Você Também\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Foi por você também,\\nFoi por você também que Jesus Se entregou.\\nVejo os cravos a rasgar Suas mãs e pés sem-par!\\nFoi por você também que Jesus Se entregou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Foi por você também,\\nFoi por você também que o Mestre agonizou.\\nVejo o sangue de Jesus deslizando sobre a Cruz!\\nFoi por você também que o Mestre agonizou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Foi por você também,\\nFoi por você também que Jesus mostrou amor.\\nPadeceu sem merecer e sofreu até morrer!\\nFoi por você também que Jesus mostrou amor!\"}]},{\"number\":\"61\",\"collection_type\":\"Hinário\",\"title\":\"Ao Ver a Cruz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao ver a cruz, meu rude coração\\nFica em silêncio ante tanto horror!\\nPenso nos pregos sobre Suas mãos,\\nE como a sós morreu por ter-me amor!\"},{\"section_type\":\"Coro\",\"content\":\"Vejo o Calvário, o monte tão cruel!\\nAli, Jesus, pregado foi na cruz.\\nVejo o Calvário, o monte do amor!\\nA minha culpa ali Jesus pagou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aos olhos vêm as cenas tão cruéis,\\nE humildemente eu penso em Seu amor.\\nEntão minh'alma em muda contrição,\\nEterna graça rende ao Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao meditar nas dores que sofreu,\\nEu sinto mais amor por meu Jesus.\\nSe foi ali que Seu perdão me deu,\\nFeliz eu sou, e grato ao ver a cruz.\"}]},{\"number\":\"62\",\"collection_type\":\"Hinário\",\"title\":\"Monte do Calvário\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Lá, num monte além, eis a rude cruz,\\nOnde Alguém está em aflição.\\nÉ o me Senhor, que do Céu desceu,\\nPara conceder-me a salvação.\"},{\"section_type\":\"Coro\",\"content\":\"Monte, monte do Calvário,\\nOnde meu Jesus morreu por mim!\\nTriste, ei-Lo assim ferido;\\nSó, em agonia pereceu.\\nPuro, carregou meu fardo,\\nPara libertar-me do pecar.\\nEste foi o dia mais feliz:\\nPois morreu pra me salvar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá, num monte além, eis a multidão\\nA escarnecer do Salvador.\\nMas não foi em vão que Jesus desceu\\nPara resgatar o pecador.\"}]},{\"number\":\"63\",\"collection_type\":\"Hinário\",\"title\":\"Houve Alguém\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Houve Alguém que Se achando disposto a morrer\\nPor um vil pecador que sou eu,\\nNo caminho da cruz suportou o sofrer:\\nMeus pecados ali esqueceu.\"},{\"section_type\":\"Coro\",\"content\":\"Lá estão sobre a cruz,\\nLá estão sobre a cruz,\\nMeus pecados na cruz já estão.\\nCom que angústia Jesus\\nCaminhou para a cruz!\\nSanto que me deu salvação!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele é meigo comigo, paciente e leal,\\nPelo Seu grande amor salvo sou;\\nLiberdade me deu, gozo e paz perenal,\\nMinhas faltas na cruz já pregou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Grato sou a Jesus, Ele deu-me o perdão,\\nE com Ele feliz sempre sou.\\nEm meus lábios terei esta linda canção:\\n\\\"Meus pecados Jesus perdoou.\\\"\"}]},{\"number\":\"64\",\"collection_type\":\"Hinário\",\"title\":\"Cristo no Horto\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo entra no horto, a sós, e inclina-Se a orar.\\nTriste, ergue a Deus a voz; dispõe-Se a nos salvar.\\nQue angústia ao orar em dor!\\nEm sangue se torna o Seu suor!\\n\\\"Afasta este cálix Meu,\\nO Pai, se possível for!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Quanto sofrimento atroz provou o Salvador!\\nVede quanto amor por nós, divino e Santo amor!\\nAos ombros suportou a cruz,\\nPor nós Se dispôs à morte e à dor,\\nMas logo ressurgiu em luz,\\nTornando-Se vencedor!\"}]},{\"number\":\"65\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Fronte Ensangüentada!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! fronte ensangüentada, em sofrimento e dor!\\nCruel coroa fere Tua fronte, ó Salvador!\\nA turba escarnece de Tua condição,\\nE zomba destas dores, ferindo o coração!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sem luz estão Teus olhos; não brilham mais, assim;\\nPor que, Senhor, se apagam? Oh! sim, bem sei: por mim!\\nTão grandes sofrimentos os meus pecados vis\\nCausaram ao meu Mestre, que o Sol brilhar não quis.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, meu grande Amigo, morreste em meu lugar!\\nEm dor desfaleceste, a fim de me salvar!\\nPalavras não expressam a minha gratidão\\nPor Tua imensa graça, bendita redenção!\"}]},{\"number\":\"66\",\"collection_type\":\"Hinário\",\"title\":\"Na Senda do Calvário\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Seguia tristemente e só, ninguém a me observar;\\nCurvado ao fardo andava eu e quis desesperar;\\nQueixei-me então a Cristo, do mundo a me atrair,\\nE Sua voz suave pude ouvir:\\n\\\"Na senda do Calvário, Meus pés também cansei,\\nE sob a cruz pesada, sem forças Me prostrei;\\nCansado peregrino, a noite chega ao fim;\\nÓ, toma a cruz e segue junto a Mim.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Do esforço meu por Ti, Jesus, às vezes me gabei:\\nQuão grande sacrifício fiz, na senda estreita andei;\\nDeixei fortuna e fama a fim de Te seguir;\\nE Tua voz suave pude ouvir:\\n\\\"Deixei o trono e a glória, deixei do Céu a luz,\\nE Minhas mãos pregaram sobre uma rude cruz;\\nCom tua mão na Minha, sigamos, pois, assim;\\nÓ, toma a cruz e segue junto a Mim.\\\"\"}]},{\"number\":\"67\",\"collection_type\":\"Hinário\",\"title\":\"Desceu Lá do Céu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Desceu, lá do Céu, o bom Filho de Deus,\\npra ser teu e meu salvador.\\nDesprezou o penar para nos resgatar;\\nOh, sim, Ele é meu salvador!\"},{\"section_type\":\"Coro\",\"content\":\"Jesus a este mundo desceu,\\nPara ser Salvaldor de um qual eu. (de um qual eu.)\\nE o fardo cairá de quem turbado está,\\nRecorrendo a Jesus que morreu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não tinha um lugar para ali repousar;\\nOh! como sofreu meu Senhor!\\nLá no monte a orar, foi sozinho ficar;\\nOh, sim, Ele é meu salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sofrendo traição, a sentença Lhe dão;\\nÉ morto qual vil salteador;\\nMas em vendo eu a cruz, digo a Jesus:\\n\\\"Oh, sim, Tu és meu Salvador!\\\"\"}]},{\"number\":\"68\",\"collection_type\":\"Hinário\",\"title\":\"Quando no Calvário\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando no Calvário, contemplo o Salvador\\nEm grande agonia por mim vil pecador,\\nSinto-me cativo, e meu coração\\nQueda-se humilhado ante o excelso dom.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vendo aquelas gotas rútilas a rolar\\nDas feridas feitas a fim de me salvar,\\nPossa eu tal cena nunca esquecer,\\nMesmo em meio às lutas, quase a perecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Pai, Me abandonaste?\\\" Cristo então bradou.\\nCoração partido, a vida entregou;\\nMas o Filho amado não morreu em vão,\\nPois, Seu sacrifício deu-nos salvação.\"}]},{\"number\":\"69\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Já Ressuscitou\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo já ressuscitou! Aleluia!\\nSobre a morte triunfou! Aleluia!\\nTudo consumado está! Aleluia!\\nSalvação de graça dá! Aleluia!\"},{\"section_type\":\"Estrofe\",\"content\":\"Gratos hinos entoai! Aleluia!\\nAo Senhor Jesus honrai! Aleluia!\\nPois à morte quis baixar! Aleluia!\\nPecadores quis salvar! Aleluia!\"},{\"section_type\":\"Estrofe\",\"content\":\"Uma vez na cruz sofreu! Aleluia!\\nUma vez por nós morreu! Aleluia!\\nMas agora vivo está! Aleluia!\\nE pra sempre reinará! Aleluia!\"}]},{\"number\":\"70\",\"collection_type\":\"Hinário\",\"title\":\"Porque Ele vive\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus enviou Seu Filho amado\\nPara sofrer em meu lugar;\\nNa cruz morreu mas vivo agora está,\\nPois ressurgiu e para sempre viverá.\"},{\"section_type\":\"Coro\",\"content\":\"Porque Ele vive, posso crer no amanha;\\nPorque Ele vive, temor não há\\nEu sei que minha vida não será mais vã,\\nPois meu futuro em Suas mãos agora está.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quão grato é viver com Cristo,\\nE desfrutar Seu doce amor,\\nE certo estar de Sua proteção,\\nNos dias calmos ou nas horas de aflição.\"},{\"section_type\":\"Estrofe\",\"content\":\"E quando, enfim, chegar a hora\\nDe aqui cessar o meu viver,\\nNão temerei, pois Cristo vivo está,\\nE eu viverei, pois, vida nova me dará.\"}]},{\"number\":\"71\",\"collection_type\":\"Hinário\",\"title\":\"Saudai o Nome de Jesus (1)\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Saudai o nome de Jesus;\\nÓ anjos, vos prostrai,\\nÓ anjos, vos prostrai.\\nO Filho do glorioso Deus,\"},{\"section_type\":\"Coro\",\"content\":\"Com glória, glória, glória,\\nGlória, com glória coroai!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó escolhida geração\\nDo bom e eterno Pai,\\nDo bom e eterno Pai,\\nO grande Autor da salvação,\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó perdoados por Jesus,\\nAlegres adorai,\\nAlegres adorai;\\nO Deus de paz, o Deus de luz,\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó raças, tribos e nações,\\nAo Rei divino honrai,\\nAo Rei divino honrai!\\nA quem quebrou os vis grilhões,\"}]},{\"number\":\"72\",\"collection_type\":\"Hinário\",\"title\":\"Saudai o Nome de Jesus (2)\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Saudai o nome de Jesus;\\nÓ anjos, vos prostrai.\\nO Filho do glorioso Deus,\\nCom glória coroai!\\nO Filho do glorioso Deus,\\nCom glória coroai!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó escolhida geração\\nDo bom e eterno Pai,\\nO grande Autor da salvação,\\nCom glória coroai!\\nO grande Autor da salvação,\\nCom glória coroai!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó perdoados por Jesus,\\nAlegres adorai;\\nO Deus de paz, o Deus de luz,\\nCom glória coroai!\\nO Deus de paz, o Deus de luz,\\nCom glória coroai!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó raças, tribos e naçóes,\\nAo Rei divino honrai;\\nA quem quebrou os vis grilhões,\\nCom glória coroai!\\nA quem quebrou os vis grilhões,\\nCom glória coroai!\"}]},{\"number\":\"73\",\"collection_type\":\"Hinário\",\"title\":\"Rei dos Reis\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Rei dos reis! Deus, criador do Céu!\\nHonra e glória ao Deus infinito em poder!\\nTerra e Céu, cantai ao grande Rei!\\nDeus criador, Deus redentor, Deus, Rei dos reis!\"},{\"section_type\":\"Estrofe\",\"content\":\"Adorai, glorificai o nome de Cristo!\\nExaltai, magnificai Jesus, o Senhor!\\nTerra e Céu, cantai louvor a Deus! Bis\\nEle morreu! Ele venceu! É Rei dos reis!\"}]},{\"number\":\"74\",\"collection_type\":\"Hinário\",\"title\":\"Sempre vencendo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sempre vencendo, mui vitorioso,\\nCristo Jesus, o Senhor!\\nChefe bendito, Chefe glorioso,\\nEm tudo é vencedor.\\nEi-Lo supremo, guiando\\nCom Seu poder e valor!\\nTodos avante, ó crentes,\\nTodos seguindo ao Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"Não é dos fortes a vitória,\\nNem dos que correm melhor\\nMas dos fiéis e sinceros,\\nComo nos diz o Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre vencendo, mui vitorioso,\\nCristo Jesus, o Senhor!\\nEis Suas hostes inumeráveis,\\nSeu refulgente esplendor!\\nCristo, que é nosso Monarca,\\nÉ Salvador, Deus e Pai;\\nSempre nos ama, nos guarda,\\nSempre conosco Ele vai.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre vencendo, mui vitorioso,\\nCristo Jesus, o Senhor!\\nReis e monarcas, príncipes fortes\\nBuscam também Seu favor.\\nHumildemente Te peço\\nQue me permitas lutar,\\nSó ao Teu lado, seguro,\\nTé minha vida findar.\"}]},{\"number\":\"75\",\"collection_type\":\"Hinário\",\"title\":\"Jesus Conquista\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Donde vêm estes guerreiros\\nRevestidos de luz?\\nEles vêm de reais domínios,\\nGuiados por Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Conquista, ó Crito! Conquista já, ó Rei!\\nCom glória grandeza, poder celestial!\\nConquista, ó Cristo! Conquista já, ó Rei!\\nDomina sobre terra e céus, Ó Rei universal!\"},{\"section_type\":\"Estrofe\",\"content\":\"Aclamai, cantai, ó crentes,\\nRedimidos sereis.\\nVem o fim das vossas lutas,\\nSim, vem o Rei dos reis.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já se finda a escura noite,\\nEis que o dia já vem.\\nCristo lá no Céu Se apressa,\\nE os anjos Seus também.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem depressa, ó dia alegre!\\nEu suspiro por ti.\\nJá pressinto a glória eterna\\nQue perto me sorri.\"}]},{\"number\":\"76\",\"collection_type\":\"Hinário\",\"title\":\"Louvai a Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, louvai-O: Cristo, o bom Mestre divino!\\nPra salvar-nos, a Sua vida deu.\\nGraça e força hoje aos contritos outorga,\\nPois Seu sangue por todos nós verteu.\\nSim, louvai-O; seja pra sempre honrado!\\nPor Seus filhos, um mediador será.\"},{\"section_type\":\"Coro\",\"content\":\"Exaltai-O pelas excelsas grandezas\\nDesta graça que hoje aos perdidos dá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, louvai-O: Cristo, o bom Mestre divino!\\nBons conselhos dá Ele ao pecador.\\nDai ao mundo dádivas maravilhosas,\\nConcedidas por esse Salvador.\\nIde, todos, servos fiéis de Cristo,\\nEle nunca vos abandonará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, louvai-O: Cristo, o bom Mestre divino!\\nEntre os povos, Seu grande amor cantai.\\nCristo volta com os milhares de anjos;\\nLogo ao mundo esta mensagem dai.\\nQual pastor bom cuida do seu rebanho,\\nCristo os salvos sempre conduzirá.\"}]},{\"number\":\"77\",\"collection_type\":\"Hinário\",\"title\":\"É Jesus o Salvador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Escutai a voz de Deus: é Jesus o Salvador!\\nÓ, clamai, vós filhos Seus: é Jesus o Salvador.\\nProclamai com grande ardor salvação ao pecador,\\nPois Jesus aqui morreu para ser o Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Abraçai o excelso dom: é Jesus o Salvador!\\nPela cruz vos dá perdão: é Jesus o Salvador\\nMultidóes, ó, exultai; Seu amor considerai!\\nAnjos Seus também clamai: é Jesus o Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó fiéis, a voz erguei: é Jesus o Salvador!\\nVós, nações, louvor rendei: é Jesus o Salvador!\\nSalvação de graça dá, e perdão ao pecador!\\nGlórias mil a Deus Jeová, pois Jesus é o Salvador!\"}]},{\"number\":\"78\",\"collection_type\":\"Hinário\",\"title\":\"Coroai-O Rei dos Reis\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eis que Chefe tão glorioso\\nÉ Jesus, o bom Senhor,\\nQue lutou mui vitorioso\\nPara ser o salvador!\"},{\"section_type\":\"Coro\",\"content\":\"Coroai-O, vós, remidos,\\nCoroai-O Rei dos reis!\\nCoroai-O, vós, remidos,\\nCoroai-O Rei dos reis!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vinde, todos, coroá-Lo:\\nNosso salvador capaz!\\nNo poder entronizá-Lo\\nPríncipe da nossa paz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Escutai o grande aplauso!\\nTriunfou o bom Jesus!\\nEle toma, já, Seu reino,\\nCoroado Rei na luz!\"}]},{\"number\":\"79\",\"collection_type\":\"Hinário\",\"title\":\"Glória ao Salvador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Veio Jesus a este mundo vil,\\nPara nos libertar;\\nFoi rejeitado por gente hostil;\\nVeio pra nos salvar.\\nGlória e poder no Céu deixou,\\nIngratidão no mundo achou,\\nTudo Ele fez, pois nos amou,\\nPara nos resgatar.\"},{\"section_type\":\"Coro\",\"content\":\"Glória, glória, demos ao Salvador!\\nGlória, glória, por Seu tão grande amor!\\nGlória, glória! Temos a paz com Deus!\\nGlória, glória, vamos cantar nos Céus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Nosso castigo Jesus levou,\\nPara nos libertar;\\nTudo na cruz Ele consumou;\\nVeio pra nos salvar.\\nQuem entre nós já compreendeu\\nTodas as dores que sofreu,\\nA condição em que morreu,\\nPara nos resgatar?!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo morreu numa cruz de dor,\\nPara nos libertar;\\nE agora chama-nos com amor;\\nVeio pra nos salvar\\nVamos a Cristo em contrição,\\nTendo certeza do perdão,\\nPois Ele estende a Sua mão\\nPara nos resgatar.\"}]},{\"number\":\"80\",\"collection_type\":\"Hinário\",\"title\":\"Há Tais Cantos Lá no Céu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há tais cantos lá no Céu,\\nQue aqui ninguém jamais ouviu!\\nSempre os anjos cantam glórias\\nAo Cordeiro do Senhor.\\nHarpas sempre em harmonia,\\nSempre a voz em claros tons.\\nQuem nos dera ser assim,\\nServindo ao Rei e Salvador!\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Santo! Santo!\\\"\\nÉ o canto de anjos bons.\\nEu hei de um dia unir\\nA voz a tais aclamações!\\nMas quando eu lhes contar a história\\nDesta redenção: Mudez!\\nNão podem compreender\\nTão grande salvação!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mesmo que eu não seja um anjo,\\nLá no Céu hei de cantar.\\nVou unir-me ao grande coro\\nDos remidos do Senhor\\nLouvarei meu salvador\\nQue sobre a cruz por mim morreu,\\nQue pagou as minhas culpas\\nE libertação me deu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Esse canto de vitória,\\nSim, os anjos ouvirão.\\nÉ qual voz de muitas águas,\\nVoz de grande multidão.\\nO Universo inteiro pára,\\nEm espanto e admiração,\\nAnte o canto dos remidos\\nAo Senhor da redenção!\"}]},{\"number\":\"81\",\"collection_type\":\"Hinário\",\"title\":\"Louvores ao Meu Rei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, vinde crentes e entoai louvores a Jesus,\\nQue para nossa salvação foi morto numa cruz.\\nSeu sangue derramou, de tudo me lavou,\\nMais alvo do que a neve me tornou.\"},{\"section_type\":\"Coro\",\"content\":\"O sangue de Jesus me lavou, me lavou!\\nO sangue de Jesus me lavou, me lavou!\\nAlegre cantarei louvores a meu Rei,\\nA meu Senhor Jesus que me salvou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Conosco vinde vos unir na guerra contra o mal,\\nE com o nosso Salvador em marcha triunfal;\\nA todos proclamar a graça e seu poder;\\nSeu sangue derramou pra nos salvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O grande Autor da salvação é Cristo, o Salvador,\\nO Rei dos reis, o Redentor, Jesus, o bom Senhor;\\nPois tudo vencerá, vitória nos dará,\\nÀ glória, salvos, nos conduzirá.\"}]},{\"number\":\"82\",\"collection_type\":\"Hinário\",\"title\":\"Aleluia, Glória a Cristo!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Aleluia! Glória a Cristo!\\nGlória ao Rei e Vencedor!\\nAleluia! Exaltemos\\nSeu poder e grande amor!\"},{\"section_type\":\"Coro\",\"content\":\"Honras demos ao fiel Senhor,\\nGlorioso Deus, capaz.\\nCristo deu na cruz a vida;\\nGlória ao príncipe da paz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, cantemos co'alegria,\\nPois do Céu desceu Jesus!\\nAleluia! Adoremos,\\nCom fervor, ao Rei da luz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Toda graça vem do alto\\nPra salvar o pecador!\\nAleluia! Glória a Cristo!\\nGlória ao Rei e Salvador!\"}]},{\"number\":\"83\",\"collection_type\":\"Hinário\",\"title\":\"Glórias ao Rei de Amor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Glórias ao Rei de amor, ao Rei, Senhor Jesus!\\nO Seu divino e santo amor provou ali na cruz.\\nA Cristo, o Redentor, darei louvor sem fim,\\nLouvor ao santo Rei de amor, que a vida deu por mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Glórias ao Rei da luz, do bem o manancial!\\nLouvor ao nobre Rei da luz, ao dom celestial.\\nSenhor da Terra e mar, da luz que ao Céu conduz,\\nLouvor ao nobre Rei da luz, ao Rei que a Deus traduz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Glórias ao Rei da paz, ao Rei, Senhor e Deus!\\nLouvor ao grande Rei da paz, ao Rei dos altos Céus;\\nO Rei, por Teu favor, ali irei morar,\\nGozar a eterna e doce paz, a paz do eterno lar.\"}]},{\"number\":\"84\",\"collection_type\":\"Hinário\",\"title\":\"O Cântico dos Salvos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! que canto que, soando,\\nEnche os ares de dulçor!\\nSão os salvos entoando\\nGraças mil ao Redentor!\"},{\"section_type\":\"Coro\",\"content\":\"Ouve as vozes de vitória,\\nEm caminho para a glória,\\nProclamando a doce história\\nDe Jesus e Seu amor!\\nProclamando a doce história\\nDe Jesus e Seu amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus excelso! Resgatou-nos\\nE nos deu libertação!\\nCom poder Ele salvou-nos\\nDa eterna perdição!\"},{\"section_type\":\"Estrofe\",\"content\":\"Graça infinda! Deus aceita\\nOs rebeldes, com favor!\\nPois jamais Cristo rejeita\\nO contrito pecador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Aceitai, pois, sem limite,\\nA divina compaixão!\\nDeus estende Seu convite,\\nAbraçai a salvação!\"}]},{\"number\":\"85\",\"collection_type\":\"Hinário\",\"title\":\"Lindo És, Meu Mestre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Lindo és, meu Mestre,\\nRei do Céu, da Terra!\\nÓ Homem-Deus, Senhor Jesus!\\nTeu é o reino, é Tua a honra,\\nÉs minha glória e minha luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Flores do campo, como sois tão lindas!\\nSois o fúlgor de prados mil!\\nMais belo é Cristo, mais puro e lindo;\\nÉ sempre meigo, bom, gentil.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lua brilhante! Sol, tão resplendente!\\nQuão divinal é vossa luz!\\nMas há um brilho mais fulgurante:\\nO brilho do Senhor Jesus.\"}]},{\"number\":\"86\",\"collection_type\":\"Hinário\",\"title\":\"Ó, Alegrai-vos, Filhos de Sião\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, alegrai-vos filhos de Siáo!\\nEis que vem raiando vossa redenção.\\nHonras e louvores dai ao Rei do Céu,\\nPois a própria morte, Ele já venceu!\"},{\"section_type\":\"Coro\",\"content\":\"Ó, alegrai-vos, filhos de Sião!\\nEis que vem raiando vossa redenção!\"},{\"section_type\":\"Estrofe\",\"content\":\"Glória ao nome santo de Jesus,\\nQue ressuscitando, triunfou em luz.\\nAnjos poderosos, cheios de esplendor,\\nDeram glória a Cristo, o Conquistador!\\n3 Ó Rei eterno, nosso grande Deus!\\nJá venceste a morte, já estás nos Céus.\\nMais que vencedores, faze-nos também,\\nE Te louvaremos lá no lar de além!\"}]},{\"number\":\"87\",\"collection_type\":\"Hinário\",\"title\":\"O Meu Pastor é o Bom Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O meu Pastor é o bom Jesus,\\nJamais me deixará.\\nÀs águas calmas me conduz,\\nE me protegerá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus minh'aima quer nutrir,\\nEm pastos de amor;\\nE meu caminho dirigir,\\nPor onde quer que for.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com Seu cajado e Seu bordão\\nJesus me guardará;\\nE quando em vale de aflição,\\nConsolo me dará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com óleo puro vem me ungir;\\nNão mais terei temor.\\nE para sempre habitarei\\nNa casa do Senhor.\"}]},{\"number\":\"88\",\"collection_type\":\"Hinário\",\"title\":\"Achei um Grande Amigo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Achei um grande Amigo, Jesus, o Salvador;\\nContarei quão grandes coisas fez por mim.\\nEstando eu perdido, indigno pecador,\\nResgatou-me e agora eu sirvo a Ele enfim.\\nE em Seu amor imenso, por mim morreu na cruz,\\nE o perdão dos meus pecados outorgou.\\nAssim me regozijo, vivendo em Sua luz;\\nAleluia! Jesus Cristo me salvou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Por este grande Amigo, desejo aqui viver,\\nE com Ele sempre estar em comunhão;\\nServi-Lo fielmente, seguindo Seu querer;\\nVou a Cristo consagrar meu coração.\\nSe o mundo me persegue, se tenho tentação,\\nCom Jesus em minha vida, vencerei;\\nE a cada dia Cristo conduz-me pela mão,\\nE na Sua graça sempre confiarei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já vem chegando o dia, a Bíblia assim o diz,\\nEm que Cristo a este mundo voltará;\\nMomento mui alegre! Que dia tão feliz!\\nSim, que dia esplendoroso então será!\\nE assim com Ele sempre no Céu habitarei,\\nJá liberto do pecado e da dor;\\nE lá, constantemente, Seu rosto então verei,\\nE estarei pra sempre junto ao Salvador.\"}]},{\"number\":\"89\",\"collection_type\":\"Hinário\",\"title\":\"Meu Redentor, Meu Amigo e Irmão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Redentor, meu Amigo e Irmão,\\nÉs o meu Mestre divino!\\nDe Ti me vêm bênçãos em profusão;\\nJesus, tudo és para mim!\"},{\"section_type\":\"Coro\",\"content\":\"Tenho saudades de Ti, meu Jesus!\\nRaie depressa Teu dia de luz!\\nJuntos no lar sempre morar!\\nOh! que saudades que anseios!\"},{\"section_type\":\"Estrofe\",\"content\":\"Nada no mundo me pode afastar\\nNunca, do Mestre divino!\\nTenho o desejo de sempre cantar;\\nJesus, tudo és para mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais do que o mar é profundo esse amor\\nDe Cristo, o Mestre divino!\\nSinto enlevar-me tão grande favor;\\nJesus, tudo és para mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Podem amigos aqui me trair,\\nMas nunca o Mestre divino!\\nSeu grande amor não me deixa cair;\\nJesus, tudo és para mim!\"}]},{\"number\":\"90\",\"collection_type\":\"Hinário\",\"title\":\"A Voz de Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu ouvi mui doce a falar-me co'amor;\\nA divina voz de Jesus:\\n\\\"Ó querido filho. sou teu Salvador\\nDeixa as trevas, vem para a luz.\\\"\\nDesprezei o mundo e a Jesus me entreguei,\\nDei-Lhe todo o meu coração.\\nSó então a paz celestial desfrutei;\\nNEle eu encontrei salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Hoje Sua voz com ternura me diz:\\n\\\"Alcançaste pleno perdão.\\nDize a todos que Eu te tornei mui feliz,\\nE que ao mundo dou salvação.\\\"\\nConsagrado a Ele desejo anunciar\\nSeu incomparável amor.\\nPela Sua graça está pronto a aceitar,\\nAté o mais vil pecador\"},{\"section_type\":\"Estrofe\",\"content\":\"Tenho a mais ditosa esperança de ouvir\\nSua linda voz musical,\\nSalvo já na glória do eterno porvir,\\nLá na pátria celestial.\\nPara o eterno lar, afinal, partirei;\\nEste mundo não me seduz.\\nCom os santos anjos ali viverei,\\nSempre ouvindo a voz de Jesus.\"}]},{\"number\":\"91\",\"collection_type\":\"Hinário\",\"title\":\"Jesus é Melhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus é melhor, sim, que ouro e bens.\\nJesus é melhor do que tudo que tens;\\nMelhor que riquezas e posições;\\nMelhor muito mais do que milhões\"},{\"section_type\":\"Coro\",\"content\":\"Pode ser um rei com poder nas mãos,\\nMas do mal escravo, sim.\\nMil vezes prefiro o meu Jesus,\\nE servi-lo até o fim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus é melhor que qualquer valor;\\nAmigo leal, no prazer e na dor;\\nMelhor do que tudo, Ele é pra mim,\\nMelhor que qualquer amigo, enfim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus é mais puro que a linda flor;\\nJesus é o Sol da Justiça e do amor;\\nJesus é a fonte que satisfaz,\\nCaminho do bem, verdade e paz.\"}]},{\"number\":\"92\",\"collection_type\":\"Hinário\",\"title\":\"Eu Te Amo, Meu Mestre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu Te amo, meu Mestre, meu bom Salvador;\\nNão posso em palavras contar este amor.\\nEu Te amo deveras, pra sempre direi;\\nE pelos meus atos o confirmarei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que grande ventura, que glória, meu Deus,\\nSaber que em breve eu vou para os Céus!\\nDe longe diviso as glórias do além;\\nOh, como eu almejo fruílas também!\"},{\"section_type\":\"Estrofe\",\"content\":\"Teu nome eu exalto, ó Rei de Salém,\\nPois sempre Teus filhos nos braços susténs.\\nEu quero louvar-Te, cantar Teu amor.\\nEu Te amo, meu Mestre, meu bom Salvador.\"}]},{\"number\":\"93\",\"collection_type\":\"Hinário\",\"title\":\"Precioso é Jesus Para Mim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Precioso é Jesus, o meu Rei, Salvador;\\nA Ele somente darei meu louvor.\\nÉ fonte divina de força e vigor;\\nPreci oso é Jesus para mim.\"},{\"section_type\":\"Coro\",\"content\":\"Precioso é Jesus para mim,\\nPrecioso é Jesus para mim.\\nÉ meu Redentor meu fiel Protetor;\\nPrecioso é Jesus para mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus bate à porta do meu coração,\\nE espera paciente, quer dar-me o perdão.\\nQue Seu sacrificio não seja em vão;\\nPrecioso é Jesus para mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Preciosas promessas eu tenho do Rei;\\nCom Ele num lar perenal morarei;\\nNum reino de luz Sua face verei;\\nPrecioso é Jesus para mim.\"}]},{\"number\":\"94\",\"collection_type\":\"Hinário\",\"title\":\"Sou de Jesus Agora\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo tem fiel amizade,\\nNEle encontrarei real liberdade,\\nPois sobre a cruz minh'alma comprou,\\nDEle, por tanto, eu sou.\"},{\"section_type\":\"Coro\",\"content\":\"Sou de Jesus agora,\\nMeu é Jesus também;\\nMeu Ele é agora,\\nMeu para sempre. Amém.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo salvou-me; sinto em minha'alma\\nGrata esperança e a mais doce calma.\\nPra libertar-me o preço pagou,\\nDEle, portanto, eu sou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando perdido em dor e pecado,\\nCristo salvou-me, fui libertado.\\nVida eternal Jesus me outorgou,\\nDEle, portanto, eu sou.\"}]},{\"number\":\"95\",\"collection_type\":\"Hinário\",\"title\":\"Cristo é Tudo Para Mim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo é tudo para mim: viver, sonhar, cantar;\\nÉ minha força, meu bordão, sem Ele, que penar!\\nQuando em pesar a Ele vou, pois meu Jesus jamais falhou.\\nQuando em pesar, faz-me alegrar; Cristo é meu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é tudo para mim: Amigo em aflição.\\nEu dEle bênçãos vou buscar, e dá-me em profusão.\\nEnvia chuva, sol e luz, colheita farta, dons a flux;\\nSol, chuva e luz, bênçãos a flux, Cristo é meu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é tudo para mim; leal eu Lhe serei.\\nEle é amigo tão fiel! Jamais O negarei.\\nQuando ao Seu lado, alegre vou; em Sua mão seguro estou;\\nSó com Jesus tudo reluz; Cristo é meu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é tudo para mim; só Ele satisfaz.\\nA confiança nEle pus, não mais me falta paz.\\nTendo a Jesus comigo assim, minha alegria não tem fim:\\nVida eternal, livre do mal! Cristo é meu!\"}]},{\"number\":\"96\",\"collection_type\":\"Hinário\",\"title\":\"A Cristo Eu Amo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo Jesus é meu bom Salvador,\\nDesejo amá-Lo mais;\\nTodos os dias Ele é meu Pastor;\\nDesejo amá-Lo mais.\"},{\"section_type\":\"Coro\",\"content\":\"A Cristo eu amo; oh, quanto o amo!\\nNa cruz a vida Ele deu!\\nCom Seu sangue, Jesus me salvou, assim,\\nE em gratidão sou Seu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que alegria é servir a Jesus;\\nDesejo amá-Lo mais;\\nSempre com Ele, eu vivo na luz;\\nDesejo amá-Lo mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem cedo ao Céu Ele me levará,\\nDesejo amá-Lo mais;\\nEternamente Ele me guiará;\\nDesejo amá-Lo mais.\"}]},{\"number\":\"97\",\"collection_type\":\"Hinário\",\"title\":\"Meu Divino Protetor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu divino Protetor, quero em Ti me refugiar,\\nPois as ondas de terror ameaçam me tragar!\\nQuase estou a perecer! Dá-me a Tua proteção!\\nPois guardado em Teu poder, não receio o furacão!\"},{\"section_type\":\"Estrofe\",\"content\":\"És amparo, meu Jesus! Sem alento venho a Ti.\\nNão me deixes sem a luz que ilumina a senda aqui.\\nEu confio em Teu amor e na Tua compaixão;\\nÉs meu forte defensor; que me ampare Tua mão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Graça imensa em Ti se achou, para tudo perdoar;\\nSangue Teu se derramou, nele quero me lavar.\\nFonte és de todo bem; dá-me sempre de beber!\\nConfortar minh'alma vem; quero em Teu amor viver.\"}]},{\"number\":\"98\",\"collection_type\":\"Hinário\",\"title\":\"Por Que me Amou Assim?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Morte cruel padeceu meu Jesus;\\nPor que me amou assim?\\nEu merecera sofrer nessa cruz;\\nPor que me amou assim?\"},{\"section_type\":\"Coro\",\"content\":\"Por que me amou assim?\\nPor que me amou assim?\\nPor que sofreu meu Jesus por mim?\\nPor que me amou assim?!\"},{\"section_type\":\"Estrofe\",\"content\":\"Foi meu pecado que O crucificou;\\nPor que me amou assim?\\nPara salvar-me, que dor suportou!\\nPor que me amou assim?\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que agonia, que grande aflição!\\nPor que me amou assim?\\nHei de aceitar tão imenso perdão!\\nPor que me amou assim?\"}]},{\"number\":\"99\",\"collection_type\":\"Hinário\",\"title\":\"Noventa e Nove Ovelhas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Noventa e nove ovelhas há, seguras no curral,\\nMas uma longe se afastou do aprisco pastoral;\\nA errar nos montes de terror, distante do fiel Pastor,\\nDistante do fiel Pastor.\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Com tantas outras, bom Pastor, não Te contestarás?\\\"\\n\\\"A errante é Minha\\\", replicou, \\\"pertence-Me a fugaz.\\nVou ao deserto procurar a ovelha que ouço em dor balar,\\nA ovelha que ouço em dor balar.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Nenhum remido imaginou quão negra escuridão,\\nQuão fundas águas que passou, trazendo a salvação.\\nE quando foi pra socorrer, a errante estava a perecer,\\nA errante estava a perecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Por toda a estrada donde vens, que sangue enxergo ali?\\\"\\n\\\"Busquei a ovelha com dolor, o sangue Meu verti.\\\"\\n\\\"Ferida vejo a tua mão.\\\" \\\"A angústia encheu-Me o coração,\\nA angústia encheu-Me o coração.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Vêm de montanha aclamações! É a voz do bom Pastor!\\nRessoa em notas triunfais o salmo vencedor!\\nE os anjos cantam lá nos Céus: \\\"A errante já voltou a Deus,\\nA errante já voltou a Deus!\\\"\"}]},{\"number\":\"100\",\"collection_type\":\"Hinário\",\"title\":\"Há um Amigo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há um amigo que sabe dos ais que da alma se vão,\\nE no momento oportuno os torna em suave canção.\\nHá um amigo que sabe tuas tristezas e dor;\\nEle deseja mostrar-te o Seu inefável amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Há um amigo que sabe que o mal anda sempre ao redor;\\nSente também suas dores; das quedas te ergue co'amor.\\nQuando estás fraco e abatido, muito distante a vagar,\\nHá um amigo que aguarda do pródigo filho voltar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Há um amigo que te ama, se forte, se fraco tu estás.\\nNunca abandona um Seu filho nas mãos do inimigo voraz.\\nDe Sua vista, distante, nunca tu estás, meu irmão.\\nQual é Seu nome, perguntas? - Jesus, que nos dá salvação!\"}]},{\"number\":\"101\",\"collection_type\":\"Hinário\",\"title\":\"Não Há Nome Mais Amável\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Outro nome não existe\\nComo o nome de Jesus;\\nEle a glória é dos anjos,\\nDos cristãos fiéis, a luz.\"},{\"section_type\":\"Coro\",\"content\":\"Jesus! Jesus!\\nNão há nome mais amável!\\nJesus! Jesus!\\nNome santo e venerável.\"},{\"section_type\":\"Estrofe\",\"content\":\"Outro nome não existe,\\nQuando aflito o coração.\\nNele encontro segurança,\\nPaz, amor, consolação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre abrigo esta esperança,\\nQuando Cristo aqui voltar,\\nDe Lhe ver o lindo rosto\\nE de ouvi-Lo a me chamar.\"}]},{\"number\":\"102\",\"collection_type\":\"Hinário\",\"title\":\"Que Grande Amigo!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que grande Amigo é meu Jesus,\\nTão bom, leal eterno!\\nSem outro igual, é Seu poder,\\nE Seu amor superno.\\nPara esta ovelha sem vigor\\nOlhou com simpatia,\\nE Sua tão bondosa mão\\nServiu-me então de guia.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que grande Amigo é meu Jesus,\\nDe longe quis buscar-me!\\nDesceu do Céu, sofreu, morreu,\\nA fim de resgatar-me!\\nAs glórias mil do santo lar\\nRenovam meu alento,\\nPois breve irei ali obter\\nO Seu acolhimento.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que grande Amigo é meu Jesus,\\nMeu Guia tão prudente,\\nMeu Protetor tão ideal,\\nMeu Rei eternamente!\\nJesus é meu e dele eu sou\\nPor tempo, sim, eterno;\\nPois logo irei fruir no Céu\\nDo Seu favor paterno.\"}]},{\"number\":\"103\",\"collection_type\":\"Hinário\",\"title\":\"Nome Precioso\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Leva tu contigo o nome\\nDe Jesus, o Salvador,\\nEste nome dá consolo,\\nSeja no lugar que for.\"},{\"section_type\":\"Coro\",\"content\":\"Nome bom, doce à fé,\\nA esperança do porvir;\\nNome bom, doce à fé,\\nA esperança do porvir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Este nome, leva, sempre,\\nPara bem te defender.\\nEle é arma ao teu alcance,\\nQuando o mal te aparecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que nome tão precioso!\\nTraz conforto ao coração.\\nSendo Por Jesus aceito,\\nHás de ter o Seu perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nome Santo e venerável,\\nCristo, Príncipe da paz!\\nRei dos reis, Senhor eterno!\\nLá no Céu o aclamarás!\"}]},{\"number\":\"104\",\"collection_type\":\"Hinário\",\"title\":\"Jesus, Teu Nome Satisfaz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus, Teu nome satisfaz;\\nPor toda a Terra espalha paz;\\nPrazer infindo e vida traz,\\nJesus, Senhor amado!\"},{\"section_type\":\"Coro\",\"content\":\"Cristo, nome de valor!\\nCristo, forte Redentor!\\nCristo, sumo e bom Pastor,\\nLouvar-Te-ei pra sempre!\"},{\"section_type\":\"Estrofe\",\"content\":\"Com Teu poder, é Salvador,\\nAo coração tão sofredor\\nConcedes forças e vigor,\\nJesus, Senhor amado!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se fraco estou, em tentação,\\nPoder me vem de Tua mão\\nSe busco a Ti em oração,\\nJesus, Senhor amado!\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, Teu nome é sem igual,\\nTão meigo e bom, gentil, leal!\\nÉs meu Pastor celestial,\\nJesus, Senhor amado!\"}]},{\"number\":\"105\",\"collection_type\":\"Hinário\",\"title\":\"A Terna Voz do Salvador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A terna voz do Salvador\\nCom graça nos convida,\\nChamando-nos em Seu amor,\\nQuerendo dar-nos vida.\"},{\"section_type\":\"Coro\",\"content\":\"Nunca dos homens se ouvirá,\\nMesmo no Céu de amor e luz,\\nCom tanto ardor mais doce som,\\nQue o nome de Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Do cálice da amarga dor,\\nNão foi Jesus poupado,\\nA fim de dar ao pecador\\nPerdão do seu pecado.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por essa grande salvação,\\nRendei louvor ardente!\\nÉ digna de celebração,\\nAgora e eternamente!\"}]},{\"number\":\"106\",\"collection_type\":\"Hinário\",\"title\":\"Amigo Mui Precioso\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Amigo mui precioso eu tenho em meu Jesus;\\nEnvolve-me seu doce amor, meus pés no bem conduz.\\nSem Ele aqui não posso andar, até chegar ao Céu;\\nAssim andamos juntos: Jesus e eu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por vezes sou tentado nas lutas e na dor,\\nEntão Jesus me mostra a mão ferida por amor.\\nDe Seu amor a prova deu, por mim na cruz morreu;\\nE juntos nós andamos: Jesus e eu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu conto-Lhe tristezas, e todo o meu prazer;\\nEm Seu amor encontro a paz, e forças pra viver;\\nE enquanto sigo rumo ao lar, irei ao lado Seu,\\nPois juntos nós andamos: Jesus e eu.\"}]},{\"number\":\"107\",\"collection_type\":\"Hinário\",\"title\":\"Alegrias Vem Trazendo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Alegrias vem trazendo o eternal e santo amor,\\nLá do alto firmamento, para os crentes no Senhor;\\nVem e limpa nossa vida, e com meiga compaixão\\nPurifica, nós rogamos, o perverso coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem preside nossa vida, divinal e santo amor!\\nDá-nos forças nesta lida, té o nosso sol se pôr!\\nQue estejamos bem dispostos nosso sangue a entregar\\nPela causa da verdade; vida ou morte, mas lutar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao findarmos nossa luta, quando a luz do Céu romper,\\nPuros, santos e felizes que possamos todos ser.\\nVem, conduze nossos passos para o eterno lar de além,\\nOnde a Cristo louvaremos, para sempre e sempre. Amém.\"}]},{\"number\":\"108\",\"collection_type\":\"Hinário\",\"title\":\"Tudo Ele Fez por Mim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo Jesus veio um dia a Belém,\\nPara sofrer aflições e desdém.\\nVeio por causa do amor que me tem,\\nA procurar-me a mim!\\nA procurar-me a mim!\\nA procurar-me a mim!\\nVeio por causa do amor que me tem,\\nA procurar-me a mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo, por Seu sacrifício na cruz,\\nDeu-me alegria do reino de luz,\\nE no caminho do Céu me conduz;\\nTudo Ele fez por mim!\\nTudo Ele fez por mim!\\nTudo Ele fez por mim!\\nE no caminho do Céu me conduz;\\nTudo Ele fez por mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo te espera e chama por ti:\\nEle te diz: com amor te remi.\\nVem, pois Jesus já fez tanto por ti!\\nNão te demores mais!\\nNão te demores mais!\\nNão te demores mais!\\nVem, pois Jesus já fez tanto por ti!\\nNão te demores mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo, meu Mestre, de novo virá,\\nSim, com os anjos! Que glória será!\\nEu face a face verei a Jeová,\\nQuando me vier buscar!\\nQuando me vier buscar!\\nQuando me vier buscar!\\nEu face a face verei a Jeová,\\nQuando me vier buscar!\"}]},{\"number\":\"109\",\"collection_type\":\"Hinário\",\"title\":\"Jesus me Transformou\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pelo mal perdido andei, longe do meu Jesus,\\nSem amor, sem fé, sem Deus, a perecer sem luz;\\nMas Jesus então me viu, dando-me Sua mão,\\nE salvar-me conseguiu da perdição.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo me amou e me livrou;,\\nO Seu imenso amor me transformou.\\nFoi Seu poder, foi Seu querer,\\nSim, Cristo, meu Senhor, me transformou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minha vida, todo o ser, quero Lhe consagrar,\\nAo Seu lado, vou viver, o Seu amor cantar.\\nEsse amor levar, também, aos que perdidos são.\\nVenham todos já fluir a salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pecadores, vinde já, Cristo vos quer salvar,\\nSeu perdão, conforto e paz Ele vos pode dar.\\nSua luz e Seu amor sempre concederá;\\nVosso coração Jesus transformará.\"}]},{\"number\":\"110\",\"collection_type\":\"Hinário\",\"title\":\"Perfeita Paz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Senhor Jesus, eu Te amo mais\\nQue o mundo e seu prazer,\\nPois deste-me perfeita paz,\\nQue nunca irei perder.\"},{\"section_type\":\"Coro\",\"content\":\"Metade nunca se contou,\\nDo amor de Deus Jeová.\\nMetade nunca se contou,\\nDa paz que aos salvos dá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, de mim mais perto estás\\nQue amigos meus aqui.\\nOh! quanto à alma satisfaz\\nO só pensar em Ti!\"},{\"section_type\":\"Estrofe\",\"content\":\"E de prazer meu coração\\nEu sinto transbordar;\\nSem Ti comigo, os dias são\\nQuais noites sem luar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó meu Precioso Salvador,\\nQue gozo é caminhar\\nAqui, contigo, e sem temor,\\nTeu rosto contemplar!\"}]},{\"number\":\"111\",\"collection_type\":\"Hinário\",\"title\":\"Não Há Amigo Igual a Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não há amigo igual a Cristo!\\nNão, nenhum! Não, nenhum!\\nOutro não há que minh'alma salve!\\nNão, nenhum! Não, nenhum!\"},{\"section_type\":\"Coro\",\"content\":\"Cristo sabe das nossas lutas;\\nTé o fim nos irá guiar.\\nNão há amigo igual a Cristo!\\nNão, nenhum! Não, nenhum!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não há amigo tão nobre e santo!\\nNão, nenhum! Não, nenhum!\\nNão há também tão humilde e manso!\\nNão, nenhum! Não, nenhum!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não há momento em que me abandone!\\nNão, nenhum! Não, nenhum!\\nNão há desgosto que não suavize!\\nNão, nenhum! Não, nenhum!\"},{\"section_type\":\"Estrofe\",\"content\":\"Crente nenhum é desamparado!\\nNão, nenhum! Não, nenhum!\\nNão há aflito que é rejeitado!\\nNão, nenhum! Não, nenhum!\"}]},{\"number\":\"112\",\"collection_type\":\"Hinário\",\"title\":\"Ele Vive\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu sirvo a Cristo amado, que há muito ressurgiu.\\nEu sei que está presente, eu sei que me remiu.\\nAmor infindo eu sinto, por onde quer que eu vá,\\nE no momento extremo, bem perto está.\"},{\"section_type\":\"Coro\",\"content\":\"Jesus, Jesus me livra de pecar;\\nComigo está, comigo vai, não tenho mais pesar\\nJesus, Jesus quer dar-me a salvação,\\nE quer viver, reinar em mim, e em meu coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em tudo que me cerca só vejo Seu amor,\\nSe em lutas eu fraquejo, renova-me o vigor.\\nBem sei que O tenho à frente, bem sei que me conduz\\nAté a Sua volta, em glória e luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Alegra-te, ó crente, cantando com fervor\\nEternas aleluias a Cristo, Rei, Senhor.\\nAuxílio dos que buscam, refúgio dos que crêem,\\nÉ sempre nossa fonte de todo o bem.\"}]},{\"number\":\"113\",\"collection_type\":\"Hinário\",\"title\":\"Amor Glorioso\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Buscou-me com ternura Jesus, o bom Pastor.\\nAchou-me na miséria, salvou-me com amor.\\nNo Céu os anjos, em canção,\\nMostraram sua aprovação.\"},{\"section_type\":\"Coro\",\"content\":\"Oh! que amor glorioso!\\nPreço tão grandioso\\nQue Jesus por mim na cruz pagou!\\nGraça sem igual me resgatou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ferido, abandonado, Jesus me socorreu,\\nE segredou-me: \\\"Achei-te; de agora em diante és Meu\\\".\\nTão meiga voz jamais ouvi!\\nPrazer maior jamais senti!\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus mostrou-me as chagas que em meu lugar sofreu;\\nCoroa, mas de espinhos, a cruz que padeceu.\\nQue pôde em mim Jesus achar,\\nPra tais afrontas suportar?\"},{\"section_type\":\"Estrofe\",\"content\":\"Enquanto as horas passam, eu vivo em doce paz,\\nE aguardo o meu bom Mestre, que tão feliz me faz!\\nA mim Jesus virá buscar,\\nE então com Ele irei morar.\"}]},{\"number\":\"114\",\"collection_type\":\"Hinário\",\"title\":\"Meu Jesus é Cativante\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus é cativante, meigo, bom, leal, capaz.\\nUm sorriso confortante sempre aos lábios Ele traz.\\nQuando a alma é vacilante, em Jesus encontra paz.\"},{\"section_type\":\"Coro\",\"content\":\"Quanto O amo! Quanto O amo!\\nPois por mim morreu na cruz!\\nQuanto O amo! Quanto O amo!\\nQuanto amo a meu Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"A um mundo de pecado, por amor de mim desceu,\\nE por mim Se fez culpado: o Inocente Se fez réu.\\nO perdão dos meus pecados meu Jesus me concedeu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Muitas vezes fui indigno, mas Jesus não me deixou,\\nE comigo foi benigno, minhas faltas perdoou,\\nE das garras do maligno meu Jesus me libertou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus é meu amparo, minha paz e salvação.\\nQueres tu também amá-Lo, receber o Seu perdão?\\nOh, não deves rejeitá-Lo; abre-Lhe teu coração.\"}]},{\"number\":\"115\",\"collection_type\":\"Hinário\",\"title\":\"Foi Amor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Foi amor, quando Deus aqui\\nNeste mundo vil, homem Se tomou.\\nFoi amor, quando meu bom Deus\\nCarpinteiro foi, quando aqui andou!\\nFoi amor, quando veio meu Jesus,\\nPra me conceder nova vida e luz.\\nFoi amor, ao sofrer na cruz\\nPor mim, um pobre pecador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Foi amor, quando Deus desceu\\nPra cuidar de mim, qual um filho Seu.\\nFoi amor, ao morrer em dor\\nPor um pobre ser sem qualquer valor!\\nFoi amor, ao ressuscitar, enfim,\\nPra me conceder vida e paz sem fim.\\nFoi amor, ao sofrer na cruz\\nPor mim, um pobre pecador.\"}]},{\"number\":\"116\",\"collection_type\":\"Hinário\",\"title\":\"De um Nome Eu Sei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"De um nome eu sei, o nome de um Rei,\\nTrazido por anjos mil.\\nNos céus de Belém, cantaram, do além,\\nO nome de amor gentil.\"},{\"section_type\":\"Coro\",\"content\":\"O nome é Jesus, o Filho da luz,\\nO nosso Salvador.\\nO nome santo e doce é Jesus,\\nO nosso Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"De um nome eu sei, o nome de um Rei\\nQue a morte sofreu na cruz.\\nO mundo salvou, da morte o livrou,\\nE os homens a Deus conduz.\"},{\"section_type\":\"Estrofe\",\"content\":\"De um nome eu sei, o nome de um Rei\\nQue em breve regressará.\\nE quando voltar às glórias do lar,\\nConsigo levar-me-á.\"}]},{\"number\":\"117\",\"collection_type\":\"Hinário\",\"title\":\"Se Tu Buscares a Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se tu buscares a Jesus,\\nEncontrarás o Salvador;\\nA ti virá manhã de luz\\nE paz em Seu amor.\"},{\"section_type\":\"Coro\",\"content\":\"Se buscares conhecê-Lo,\\nOh, sim, amá-Lo-ás também!\\nManhã feliz despontará\\nPara ti no lar de além.\"},{\"section_type\":\"Estrofe\",\"content\":\"À luz do que Ele prometeu,\\nEm teu viver desfrutarás\\nO amor e as bênçãos lá do Céu,\\nDe Deus a doce paz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus compreende a tua dor,\\nE sempre quer teu bem-estar;\\nCrê, pois, que junto ao Salvador,\\nConforto hás de gozar.\"}]},{\"number\":\"118\",\"collection_type\":\"Hinário\",\"title\":\"Jesus, o Bom Amigo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus, o bom Amigo,\\nO nosso grande Deus,\\nPrepara-nos agora\\nMoradas lá nos Céus.\"},{\"section_type\":\"Coro\",\"content\":\"No lar feliz e eterno,\\nDe paz, amor e luz,\\nMorar também iremos,\\nCom nosso bom Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, o bom Amigo,\\nO nosso Benfeitor,\\nConcede a nós, Seus filhos,\\nMaravilhoso amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, o bom Amigo,\\nO nosso excelso Rei,\\nNos deu fiel promessa:\\n\\\"Em breve voltarei.\\\"\"}]},{\"number\":\"119\",\"collection_type\":\"Hinário\",\"title\":\"O Melhor Amigo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sei que o amigo melhor é Cristo;\\nSe a tormenta vem provar-me a fé,\\nPronto estende a Sua mão,\\nTranqüiliza o coração.\\nSim, o amigo melhor é Cristo.\"},{\"section_type\":\"Coro\",\"content\":\"Jesus é o melhor amigo,\\nJesus é o melhor amigo,\\nSim, repreende com dulçor,\\nE me anima com vigor.\\nSim, o amigo melhor é Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que amigo precioso é Cristo!\\nNele encontro amor, consolo e paz.\\nem Seu braço esperarei,\\nNenhum golpe temerei.\\nSim, o amigo melhor é Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se eu passar pelo vale escuro,\\nE chegar às águas do Jordão,\\nNão receio, pois Jesus,\\nSalvo, à pátria me conduz.\\nSim, o amigo melhor é Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na mansão eternal, eu, junto\\nCom os santos transformados já,\\nEste canto de louvor\\nEntoaremos ao Senhor:\\nSim, o amigo melhor é Cristo.\"}]},{\"number\":\"120\",\"collection_type\":\"Hinário\",\"title\":\"Amor Que por Amor Desceste\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Amor, que por amor desceste!\\nAmor, que por amor morreste!\\nAh, quanta dor não padeceste!\\nMinh'alma vieste resgatar\\nE meu amor ganhar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Amor, que com amor seguias\\nA mim, que sem amor, Tu vias!\\nOh! Quanto amor por mim sentias,\\nEterno Deus, Senhor Jesus,\\nSofrendo sobre a cruz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Amor, que tudo me perdoas!\\nAmor, que até mesmo abençoas\\nUm réu de quem Tu Te afeiçoas!\\nVencido, ó Salvador, por Ti,\\nTeu grande amor senti!\"},{\"section_type\":\"Estrofe\",\"content\":\"Amor sublime que perduras,\\nQue em Tua graça me seguras,\\nCercando a mim de mil venturas!\\nAceita agora, ó Salvador,\\nO meu humilde amor!\"}]},{\"number\":\"121\",\"collection_type\":\"Hinário\",\"title\":\"Divino Pastor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Divino Pastor, Jesus, meu Senhor,\\nSalvaste-me da perdição.\\nO mundo deixei, Tua paz eu busquei,\\nDe Ti recebi perdão.\\nTua luz brilha em meu caminho aqui;\\nEu quero viver sempre perto de Ti\\nTeus braços de amor me abres, Senhor,\\nDe Ti tenho proteção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Divino Pastor, Jesus, meu Senhor,\\nSofreste amargura por mim;\\nMorreste na cruz, ó meu bom Jesus,\\nMostrando-me amor, assim.\\nAgora, contrito e sem mais temor,\\nProcuro o aprisco do meu Salvador.\\nNão mais quero errar, não mais vaguear;\\nContigo estarei, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Divino Pastor, Jesus, meu Senhor,\\nTua voz amorável ouvi;\\nE todo o meu ser, também meu viver,\\nAgora eu consagro a Ti.\\nEnleva-me Teu insondável amor!\\nQuiseste salvar-me, a mim, pecador!\\nMui grato serei, a Ti servirei,\\nMeu Deus e meu Redentor.\"}]},{\"number\":\"122\",\"collection_type\":\"Hinário\",\"title\":\"O Que Penso de Meu Mestre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vou contar-vos o que penso de meu Mestre,\\nComo dEle recebi a luz e a paz;\\nEl' mudou-me, eu bem sei, completamente;\\nSó Jesus a minha alma satisfaz.\"},{\"section_type\":\"Coro\",\"content\":\"Sempre cuidará de mim, meu Mestre,\\nCom desvelo e compaixão sem fim!\\nNenhum outro tira a culpa do pecado.\\nOh! como Ele ama a mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Com a vida toda cheia de pecado,\\nNa miséria e com dor no coração\\nEl' me ergueu com braços fortes de ternura,\\nDeu-me vida, deu-me paz, consolação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cada dia Ele vem, com segurança,\\nMais e mais me revelar o Seu amor;\\nComo anelo compreender completamente\\nEsse dom tão divinal, restaurador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu maior desejo agora é honrá-Lo,\\nProclamar o que Ele fez pra me salvar;\\nE cantando esse amor inigualável,\\nQuero a Deus a minha vida consagrar.\"}]},{\"number\":\"123\",\"collection_type\":\"Hinário\",\"title\":\"O Amor de Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O amor de Jesus é tão puro e leal\\nQue aclara o meu viver.\\nO amor de Jesus me liberta do mal\\nE envolve meu pobre ser.\\nTão meigo e tão bom é Jesus!\\nEl' guia-me com Sua mão.\\nO amor de Jesus é qual fonte de luz:\\nTirou-me da escuridão.\"},{\"section_type\":\"Estrofe\",\"content\":\"O amor de Jesus é mais vasto que o mar;\\nSustém-me na provação\\nO amor de Jesus, qual fragrância da flor,\\nInunda meu coração.\\nSua paz dá-me calma e prazer,\\nEu sei que há um Céu para mim.\\nA Cristo Jesus minha vida darei,\\nPor Seu grande amor, sem fim.\"},{\"section_type\":\"Estrofe\",\"content\":\"O amor de Jesus minha vida refez\\nE deu-me de novo a paz.\\nAgora, feliz, quero sempre seguir\\nA senda que satisfaz.\\nServindo a Jesus, meu Senhor,\\nCom zelo e com devoção,\\nDesejo falar e cantar desse amor\\nQue luz traz ao coração.\"}]},{\"number\":\"124\",\"collection_type\":\"Hinário\",\"title\":\"Meu Nome em Suas Mãos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu caminho ponho em Suas mãos,\\nNelas deixo estar minha oração.\\nNestas santas mãos estão gravados\\nMeu nome e o teu, ó meu querido irmão.\"},{\"section_type\":\"Coro\",\"content\":\"Meu nome está nas mãos, nas mãos de meu Jesus;\\nFoi ali na cruz que o escreveu.\\nEsquecer-me não será possível:\\nTem sobre as mãos meu nome lá no Céu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Há um sinal em Suas mãos de luz,\\nQue no próprio Céu nos lembra a cruz.\\nMas também está meu pobre nome\\nEscrito ali nas mãos de meu Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Foi na dura cruz em que morreu,\\nQue tais cicatrizes recebeu.\\nMas ao ver as mãos assim sangrarem,\\nEl' viu também ali o meu nome\"}]},{\"number\":\"125\",\"collection_type\":\"Hinário\",\"title\":\"Por Jesus Desprezo o Mundo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Por Jesus desprezo o mundo,\\nPois o seu prazer é vão;\\nMas de Cristo, o amor profundo\\nNunca sofre alteração\"},{\"section_type\":\"Coro\",\"content\":\"Que amplidão, que profundeza\\nTem o amor de meu Jesus!\\nEste amor nos dá certeza\\nDe habitar na eterna luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por Jesus desprezo o mundo,\\nCristo é o amparo meu;\\nMesmo quando em rude luta,\\nTenho paz ao lado Seu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por Jesus desprezo o mundo,\\nPois por mim morreu na cruz;\\nMuito em breve eu hei de vê-lo\\nFace a face, em Sua luz.\"}]},{\"number\":\"126\",\"collection_type\":\"Hinário\",\"title\":\"Vigiai, Cristãos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vigiai, cristãos sinceros,\\nPois o fim está bem perto!\\nTende as lâmpadas acessas,\\nSempre prontos e despertos!\"},{\"section_type\":\"Coro\",\"content\":\"Eis que vem, sim, Cristo vem!\\nVem reinar em grande glória,\\nCom os santos em vitória!\\nEis que vem, sim, Cristo vem!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis que só Jesus promete\\nDar-nos paz, perdão e graça;\\nAceitai o Seu convite,\\nAvisai a toda raça!\"},{\"section_type\":\"Estrofe\",\"content\":\"Reinos e nações se abalam!\\nProclamai a todo o mundo\\nQue Jesus a vir Se apressa,\\nE que tem amor profundo!\"},{\"section_type\":\"Estrofe\",\"content\":\"Pecadores, vinde todos,\\nCristo ainda intercede!\\nVinde enquanto graça existe,\\nVinde enquanto Deus vos pede!\"}]},{\"number\":\"127\",\"collection_type\":\"Hinário\",\"title\":\"Quando Deus Fizer Chamada\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando Deus fizer chamada para os santos Seus reunir,\\nEstaremos lá perante o lindo mar;\\nQuando Cristo aqui descer e para a glória os conduzir,\\nQue feliz reunião teremos lá no lar!\"},{\"section_type\":\"Coro\",\"content\":\"Que prazer, que glória,\\nQuando Cristo, enfim, os salvos Seus buscar!\\nQue louvor! Vitória!\\nQue feliz reunião teremos lá no lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando o anjo do Senhor disser que tempo não há mais,\\nE a feliz eternidade começar,\\nE passados para sempre desta vida os tristes ais,\\nQue feliz reunião teremos lá no lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando as harpas ressoarem pela abóboda sem fim,\\nAnunciando então o ano jubilar,\\nQuando o hino da vitória nós cantarmos, em festim,\\nQue feliz reunião teremos lá no lar!\"}]},{\"number\":\"128\",\"collection_type\":\"Hinário\",\"title\":\"O Rei Vem Vindo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O mercado está vazio, o trabalho terminou.\\nNão há tráfego nas ruas, o barulho já cessou.\\nOs ceifadores lá no campo já deixaram seu labor.\\nEm suspense está a Terra, é a volta do Senhor!\"},{\"section_type\":\"Coro\",\"content\":\"O Rei vem vindo! O Rei vem vindo!\\nA trombeta está soando, os remidos a chamar.\\nO Rei vem vindo! O Rei vem vindo!\\nAleluia, Ele vem me buscar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis que se abrem sepulturas ante a ordem do Senhor;\\nOs remidos ressuscitam entre hosanas e louvor.\\nMas os maus, em desespero, em angústia e aflição,\\nJá se escondem pelas rochas, fogem da destruição!\"},{\"section_type\":\"Estrofe\",\"content\":\"Já os salvos vão subindo, ouço o coro angelical;\\nTodo o céu está se abrindo, há um brilho sem igual!\\nComo o som de muitas águas, ouvimos ecoar\\nAleluias ao Cordeiro. Nós já vamos para o lar!\"}]},{\"number\":\"129\",\"collection_type\":\"Hinário\",\"title\":\"Nenhum Vale Escuro\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nenhum vale escuro de luta e dor\\nNós teremos quando Jesus voltar;\\nNão mais sombras, quando Jesus voltar\\nPra dar-nos o galardão,\\nPra dar-nos o galardão,\\nPra dar-nos o galardão;\\nNão teremos sombras ao vir Jesus\\nPra dar-nos o galardão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, que lindo dia, manhã de luz!\\nTudo é alegria ao vir Jesus;\\nTudo é alegria ao vir Jesus\\nCom todos os anjos Seus,\\nCom todos os anjos Seus,\\nCom todos os anjos Seus;\\nTudo é alegria, ao vir Jesus\\nCom todos os anjos Seus.\"},{\"section_type\":\"Estrofe\",\"content\":\"A canção gloriosa de quem venceu,\\nCantaremos quando Jesus voltar;\\nCantaremos quando Jesus voltar,\\nUnidos no Seu amor;\\nUnidos no Seu amor,\\nUnidos no Seu amor;\\nCantaremos quando Jesus voltar,\\nUnidos no Seu amor.\"}]},{\"number\":\"130\",\"collection_type\":\"Hinário\",\"title\":\"O Rei Vindouro\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Rei vindouro perto está,\\nO mesmo que na cruz morreu.\\nAos justos Ele levará\\nConsigo para o Céu.\"},{\"section_type\":\"Coro\",\"content\":\"Perto está, perto está,\\nSim, às portas Ele já está;\\nVem depressa, vem depressa!\\nSim, o Rei já perto está.\"},{\"section_type\":\"Estrofe\",\"content\":\"Da Sua vinda vemos já\\nSinais por toda parte aqui,\\nE logo a alva eternal\\nVirá pra mim e ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"O nosso lar então será\\nA terra nova, perenal.\\nA morte lá não entrará,\\nPois tudo é imortal.\"}]},{\"number\":\"131\",\"collection_type\":\"Hinário\",\"title\":\"Triunfante Vem Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Triunfante, glorioso, com a corte angelical,\\nJesus Cristo volve ao mundo sobre nuvem triunfal!\\nAleluia! O Seu reino vem fundar!\\nAleluia! O Seu reino vem fundar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Em poder e majestade, vamos ver Jesus voltar.\\nMas os ímpios, criminosos, sim, Jesus virá julgar.\\nCom espanto, a Jesus verão chegar!\\nCom espanto, a Jesus verão chegar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Honra e glória, aleluia ao Senhor, supremo Rei!\\nCoroado, exaltado, vem guiar a Sua grei.\\nNo teu reino, vem, Senhor Jesus, reinar!\\nNo teu reino, vem, Senhor Jesus, reinar!\"}]},{\"number\":\"132\",\"collection_type\":\"Hinário\",\"title\":\"Quando o Rei Vier\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo nos chama ao real festim,\\nCom muito amor nos convida, sim.\\nOh! que será, pois, de ti e mim,\\nQuando o Rei vier?\"},{\"section_type\":\"Coro\",\"content\":\"Quando o Rei vier, irmão,\\nQuando o Rei vier!\\nOh! que será de ti e mim,\\nQuando o Rei vier?\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo morreu sobre a dura cruz,\\nPara levar este mundo à luz.\\nOs Seus fiéis para o Céu conduz,\\nQuando, enfim, vier.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os filhos Seus Ele acolherá,\\nCom trajes brancos os vestirá.\\nHora solene pra nós será,\\nQuando o Rei vier.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que terrível será, então,\\nPara os que não têm a salvação!\\nAmargamente eles chorarão,\\nQuando o Rei vier.\"}]},{\"number\":\"133\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Volta Brevemente\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo volta brevemente,\\nPara neste mundo ter,\\nEm lugar de sofrimento,\\nMajestade com poder.\\nEle volta, já em glória,\\nBrilha refulgente luz Desse dia tão querido\\nDos remidos de Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Sem tardar, eis que Cristo volta!\\nEle vem, para os Seus buscar.\\nEle vem na Sua glória.\\nCom poder irá reinar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo volta! Não mais lutas,\\nNão mais pranto, não mais dor,\\nNão mais sombra de pecado,\\nNão mais falta de vigor.\\nCristo busca Sua Igreja,\\nQue Ele ao Céu vai conduzir,\\nPara tê-la, enfim, consigo,\\nNo eternal, feliz porvir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo volta! Bem sabemos,\\nEle logo vai descer.\\nSim, podemos ter certeza\\nDe Seu lindo rosto ver;\\nPela Bíblia Cristo afirma,\\nE ela não irá falhar.\\nEis por que esperaremos\\nVer Jesus aqui voltar.\"}]},{\"number\":\"134\",\"collection_type\":\"Hinário\",\"title\":\"Breve Jesus Voltará\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Servos de Deus, a trombeta tocai:\\nBreve Jesus voltará!\\nA todo o mundo a mensagem levai:\\nBreve Jesus voltará!\"},{\"section_type\":\"Coro\",\"content\":\"Breve virá! Breve virá!\\nBreve Jesus voltará!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ide as nações e depressa anunciai:\\nBreve Jesus voltará!\\nGratos, alegres, as novas cantai:\\nBreve Jesus voltará!\"},{\"section_type\":\"Estrofe\",\"content\":\"Montes e vales, o som ecoai:\\nBreve Jesus voltará!\\nOndas do mar a canção entoai:\\nBreve Jesus voltará!\"},{\"section_type\":\"Estrofe\",\"content\":\"Guerras e fome nos dão a entender:\\nBreve Jesus voltará!\\nGraves sinais já nos fazem saber:\\nBreve Jesus voltará!\"}]},{\"number\":\"135\",\"collection_type\":\"Hinário\",\"title\":\"Guarda, Vê se Muito Falta\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Guarda, vê se muito falta para o dia alvorecer.\\nVai a noite ainda alta, ou já vem o amanhecer?\\nViajor, ó, sim, desperta ao romper do arrebol!\\nFica em pé e põe-te alerta, eia, pois, que surge o Sol!\"},{\"section_type\":\"Estrofe\",\"content\":\"Guarda, vê a luz nascente anunciando o jubileu;\\nAlça a voz, alegremente, faz vibrar o próprio céu.\\nLogo os justos falecidos, imortais ressurgirão,\\nAo soar aos seus ouvidos o clarim da redenção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Guarda, vê a terra linda, frutos, flores sem rival!\\nVê o Rei em glória infinda, vê o mar como um cristal!\\nOuve as harpas, que harmonia! Ouve as hostes a cantar!\\nPeregrino, que alegria! Vais em breve para o lar!\"}]},{\"number\":\"136\",\"collection_type\":\"Hinário\",\"title\":\"Cristão não Tarda a Voltar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sem mais demora Cristo virá,\\nEle afirmou-nos e não tardará.\\nOh! que alegria, que glória será,\\nQuando Jesus regressar!\"},{\"section_type\":\"Coro\",\"content\":\"Cristo não tarda, não tarda a voltar;\\nCristo não tarda a voltar!\\nOh! que alegria, que glória será,\\nQuando Jesus regressar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Breve da terra ressurgirão\\nNossos queridos que mortos estão,\\nPara subir à celeste mansão,\\nQuando Jesus regressar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Prontos estamos para esta paz?\\nPreso, encerrado será Satanás;\\nTudo que é vil deixaremos atrás,\\nQuando Jesus regressar.\"}]},{\"number\":\"137\",\"collection_type\":\"Hinário\",\"title\":\"Anunciai Pelas Montanhas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Coro\",\"content\":\"Anunciai pelas montanhas,\\nE proclamai por terra e mar;\\nAnunciai pelas montanhas\\nQue Cristo vai voltar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minha'lma, com Cristo,\\nJamais desanimou,\\nPorque Ele ajuda e guia,\\nE a senda me mostrou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Mestre divino,\\nConduz pela mão;\\nDe pão sacia a alma,\\nE escuta a oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"E nós, que O amamos,\\nDevemos proclamar\\nQue Cristo veio ao mundo,\\nE a todos quer salvar.\"}]},{\"number\":\"138\",\"collection_type\":\"Hinário\",\"title\":\"A Manhã de Luz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A manhã de luz já está raiando,\\nLogo o Rei virá;\\nE Seu povo, então, para o lar eterno\\nEle levará.\"},{\"section_type\":\"Coro\",\"content\":\"A manhã gloriosa está raiando,\\nBreve surgirá a luz!\\nA manhã gloriosa está raiando,\\nEis que vem Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Inda se ouve o som do evangelho eterno,\\nNão vos demoreis!\\nPois bem cedo vem, e com majestade,\\nCristo, o Rei dos reis.\"},{\"section_type\":\"Estrofe\",\"content\":\"Volverão à vida os queridos mortos,\\nEm exultação!\\nQue alegria infinda nos encontrarmos\\nNa eternal mansão!\"}]},{\"number\":\"139\",\"collection_type\":\"Hinário\",\"title\":\"Jesus à Terra Voltará\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus à Terra voltará\\nCom grande majestade,\\nE neste mundo exercerá\\nSuprema potestade.\"},{\"section_type\":\"Coro\",\"content\":\"Saudai o Rei celestial,\\nQue toma aqui poder real!\\nSaudai o Rei em Seu fulgor,\\nJesus, Deus santo e bom Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus dará justiça e paz,\\nFeliz fará Seu povo;\\nO Seu reinado gozo traz\\nAo mundo feito novo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os santos Seus lá fruirão\\nO Seu amor paterno;\\nOs príncipes e reis virão\\nServir ao Rei eterno.\"}]},{\"number\":\"140\",\"collection_type\":\"Hinário\",\"title\":\"Ó Vem! Emanuel!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem, ó, vem, Emanuel,\\nE salva o aflito Israel\\nQue chora o exílio em seu viver\\nAté Jesus aparecer.\"},{\"section_type\":\"Coro\",\"content\":\"Cantai! Cantai! Emanuel\\nVirá a vós, ó Israel!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sabedoria que é do além,\\nOrdena tudo aqui também!\\nO bom caminho, vem mostra;\\nE como nele sempre andar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Desejado das nações,\\nUnidos faze os corações.\\nDo mundo vem tirar o mal\\nE dar-lhe a paz celestial.\"}]},{\"number\":\"141\",\"collection_type\":\"Hinário\",\"title\":\"O Dia Não Sei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O dia não sei do regresso do Esposo,\\nPorém os sinais vêm encher-me de gozo,\\nPois presto virá esse evento glorioso,\\nMas o dia não sei.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo vem; vigiemos, oremos;\\nEle vem; Aleluia! Aleluia!\\nSobre nuvens virá,\\nCom os anjos da glória,\\nMas o dia não sei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os crentes verão, pela Santa Escritura,\\nQue não tardará nossa eterna ventura.\\nOlhemos, então, para a glória futura,\\nMas o dia não sei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Orar, vigiar, eis a necessidade;\\nBem firmes os pés na bendita verdade.\\nDescanso haverá na celeste cidade,\\nMas o dia não sei.\"}]},{\"number\":\"142\",\"collection_type\":\"Hinário\",\"title\":\"Bela Manhã\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bela manhã, manhã de alegria!\\nVem desfazer da noite a escuridão!\\nFoi-se o clamor, tristeza e agonia!\\nIrrompe o dia da salvação!\\nRejubilai, cantai em aleluias!\\nCantai, cantai, aleluias!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não mais temor, não mais tribulações!\\nLouvores enchem hoje os corações!\\nOh, festejai do dia a nova luz!\\nSaudai o Rei, saudai o Rei Jesus!\\nCantai, cantai, aleluias!\"}]},{\"number\":\"143\",\"collection_type\":\"Hinário\",\"title\":\"Será de Manhã?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Será de manhã, no começo do dia?\\nSerá quando a luz seu fulgor irradia,\\nQue Cristo há de vir com os anjos da glória,\\nReceber deste mundo os Seus?\"},{\"section_type\":\"Coro\",\"content\":\"Oh, Jesus, Salvador, Senhor!\\nQuando vamos cantar:\\nCristo volta, aleluia, aleluia, amém!\\nAleluia, amém?!\"},{\"section_type\":\"Estrofe\",\"content\":\"Será de manhã ou será pela tarde?\\nTambém pode ser que as trevas da noite\\nSe tornem na luz desse brilho de glória,\\nQuando Cristo os Seus receber.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! graça sem fim, quando a morte vencida,\\nE Cristo Jesus revestir-nos de vida,\\nE formos então habitar lá na glória,\\nNesse lar que Jesus preparou!\"}]},{\"number\":\"144\",\"collection_type\":\"Hinário\",\"title\":\"O Romper da Alva\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"'Stá perto o dia de Cristo vir,\\nEu ouço proclamar.\\nA alva já não tardará,\\nEis que vem muito próximo o alvorar.\"},{\"section_type\":\"Coro\",\"content\":\"Já não pode a alva demorar.\\nJá não pode a alva demorar.\\nA noite está a fugir,\\nO dia a entreluzir;\\nJá não pode a alva demorar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sinais preditos, da Lua e Sol,\\nEm terra, céu e mar,\\nProclamam o breve arrebol,\\nSim, da vinda de Cristo o aproximar.\"},{\"section_type\":\"Estrofe\",\"content\":\"É vinda a hora de despertar,\\nDeixando o orgulho vil.\\nFazendo sempre a luz brilhar,\\nConduzindo os perdidos ao redil.\"}]},{\"number\":\"145\",\"collection_type\":\"Hinário\",\"title\":\"Jesus Voltará\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus voltará, com poder voltará;\\nOs Seus levará para o Céu.\\nIremos com Ele pra sempre morar,\\nNum lar só de paz e de amor.\\nEstás pronto a ir e morar com Jesus,\\nO teu Salvador sem igual?\\nEstás pronto a ir e morar com Jesus,\\nA ir para o lar celestial?\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem pois! Que prazer é morar com Jesus,\\nNum lar onde há paz divinal!\\nNum lar onde a dor tão atroz, tão cruel,\\nJamais poderá penetrar!\\nOh, sim, vem morar, nesse lar, com Jesus;\\nFruir galardão celestial.\\nFeliz viverás com Jesus, teu Senhor,\\nO teu Salvador sem igual.\"}]},{\"number\":\"146\",\"collection_type\":\"Hinário\",\"title\":\"Maranata\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Maranata sempre é do cristão\\nA bendita, feliz esperança.\\nMaranata, a mensagem a dar\\nA um mundo que está em mudança.\\nMaranata é a fé\\nA inspirar o fiel cristão;\\nO regresso de Jesus amar,\\nAnunciar, apressar, aguardar.\\nMaranata, Maranata, maranata!\"}]},{\"number\":\"147\",\"collection_type\":\"Hinário\",\"title\":\"Nós O Veremos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nós O veremos retornando em glória;\\nContemplaremos o Rei Salvador.\\nCom muitos anjos nós O louvaremos,\\nCantando em coro, Hosana! Amém!\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós O veremos na manhã gloriosa;\\nContemplaremos o Seu resplendor.\\nEntoaremos hinos de vitória,\\nCantando em coro, Hosana! Amém!\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós O veremos em radiante brilho;\\nNosso louvor alçaremos ao Céu\\nCom santos anjos O exaltaremos,\\nCantando em coro, Hosana! Amém!\\nHosana! Amém!\"}]},{\"number\":\"148\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Vem\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo vem com grande majestade\\nSua obra terminar.\\nOh, louvai o Rei da eternidade\\nQue virá aqui reinar.\"},{\"section_type\":\"Coro\",\"content\":\"Rei da paz, sim, vem reinar\\nE vem levar-nos para o lar.\\nVem, Senhor Jesus, reinar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já se ouve o clarinar nos ares\\nDa trombeta angelical,\\nQue anuncia em todos os lugares\\nO chamado divinal.\"}]},{\"number\":\"149\",\"collection_type\":\"Hinário\",\"title\":\"Espero a Manhã Radiosa\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Espero a manhã radiosa,\\nO bendito alvorecer,\\nQuando as mágoas e tristezas\\nDesta vida eu esquecer\"},{\"section_type\":\"Coro\",\"content\":\"Eu espero mui ansioso,\\nMeu Jesus aqui voltar;\\nEu aguardo as boas-vindas\\nDe Jesus, na praia de outro mar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Espero já mui cansado\\nDos embates do viver,\\nMas quando isto for passado,\\nGalardão hei de receber.\"},{\"section_type\":\"Estrofe\",\"content\":\"Espero já mui ansioso\\nO celeste lar de amor;\\nQual um viajor saudoso,\\nQuero a vinda do Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Espero encontrar queridos\\nNa mansão celestial;\\nReceber do Mestre amado.\\nUm abraço fraternal.\"}]},{\"number\":\"150\",\"collection_type\":\"Hinário\",\"title\":\"Não Desistir\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dias há, bem sei, em que triste te sentes,\\nSem ter esperança e prazer,\\nMas existe Alguém que promete ajudar-te.\\nE forças à alma trazer.\"},{\"section_type\":\"Coro\",\"content\":\"Não desistir! Cristo vem logo!\\nBreve a aurora há de raiar!\\nNão desistir! Cristo vem logo!\\nNão desistir! Ele virá!\"},{\"section_type\":\"Estrofe\",\"content\":\"Este mundo, eu sei, já não vai muito longe,\\nE o mal vai breve findar.\\nMinha fé em Deus, sim, está bem firmada:\\nJesus logo vai regressar.\"}]},{\"number\":\"151\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Virá Outra Vez\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Novas alegres darei,\\nCantos de graça entoarei\\nAo proclamar com ardor:\\nCristo virá outra vez.\"},{\"section_type\":\"Coro\",\"content\":\"Breve virá! Breve virá!\\nPela noite pode ser,\\nOu no lindo alvorecer.\\nBreve virá! Breve virá!\\nOh! quão glorioso esse dia será!\\nCristo virá outra vez!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero a mensagem levar,\\nCom alegria e prazer;\\nA todos hei de dizer:\\nCristo virá outra vez.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sua presença trará\\nPaz e alegria sem-par;\\nSempre ao Seu lado andarei.\\nCristo virá outra vez.\"}]},{\"number\":\"152\",\"collection_type\":\"Hinário\",\"title\":\"Vencendo Vem Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Já refulge a glória eterna de Jesus o Rei dos Reis\\nBreve os reinos deste mundo ouvirão as Suas leis\\nOs finais da Sua vinda mais se mostram cada vez\\nVencendo vem Jesus\"},{\"section_type\":\"Coro\",\"content\":\"Glória, glória, aleluia\\nGlória, glória, aleluia\\nGlória, glória, aleluia\\nVencendo vem Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"O clarim que chama os crentes à batalha já soou\\nCristo à frente do Seu povo multidões já conquistou\\nO inimigo em retirada seu furor patenteou\\nVencendo vem Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"E por fim entronizado as nações há de julgar\\nTodos grandes e pequenos o Juiz hão de encarar\\nE os remidos triunfantes em fulgor hão de cantar\\nVencido tem Jesus\"}]},{\"number\":\"153\",\"collection_type\":\"Hinário\",\"title\":\"Já se Vêem os Sinais\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em terra e céus já se vêem os sinais\\nA nos mostrar que Jesus voltará.\\nVós, ó fiéis, sem vigor já estais?\\nEis que a redenção final já mui perto está.\"},{\"section_type\":\"Coro\",\"content\":\"Daí boas novas, sim, proclamai,\\nPois logo mais findará nossa dor.\\nVós, ó fiéis, com fervor sempre orai:\\n\\\"Ora vem, Senhor Jesus, ó, vem, Salvador!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"São os sinais, aos fiéis, predições,\\nDe que Jesus já não mais tardará;\\nEis, em furor já estão as nações,\\n\\\"Homens desmaiando de terror\\\", já os há.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, vamos nós novo ardor retomar,\\nPois Cristo vem e já não longe está!\\nSim, vamos já com Jesus habitar,\\nOnde amor, descanso e eterna paz haverá.\"}]},{\"number\":\"154\",\"collection_type\":\"Hinário\",\"title\":\"Ó, Vem, Espírito de Amor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem, Espírito de amor,\\nPoder celestial!\\nInspira-nos com santo ardor\\nDo vivo manancial;\\nDo vivo manancial.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eleva nosso coração\\nDo mundo mau e atroz;\\nE ao Teu amor e salvação\\nFiéis sejamos nós;\\nFiéis sejamos nós.\"},{\"section_type\":\"Estrofe\",\"content\":\"Concede fé à Tua grei,\\nE livra-nos do mal.\\nA nós ensina Tua lei,\\nDoutrina celestial;\\nDoutrina celestial.\"}]},{\"number\":\"155\",\"collection_type\":\"Hinário\",\"title\":\"Vive em Mim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vive, Santo Espírito,\\nNeste meu pobre ser!\\nFaz no meu coração a luz\\nDo Céu resplandecer.\"},{\"section_type\":\"Coro\",\"content\":\"Vive em mim, vive em mim,\\nSanto e bom Consolador.\\nLimpa do mal meu coraçáo,\\nReine nele só o amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Fala, Santo Espírito,\\nFala-me com poder;\\nPois para a redenção real\\nEu quero renascer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Santo, Santo Espírito,\\nEnche-me de fervor,\\nPara que eu ponha o meu viver\\nNas mãos do Salvador.\"}]},{\"number\":\"156\",\"collection_type\":\"Hinário\",\"title\":\"Vem, Espírito Divino\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem, Espírito divino,\\nAo meu pobre coração.\\nSê em mim presente sempre,\\nFaz em mim habitação.\"},{\"section_type\":\"Coro\",\"content\":\"Vem, ó, vem! Sim, vem já!\\nVem, ó, vem, Consolador\\nEnche-me com Tua presença,\\nE renova meu fervor\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sou fraco, muito fraco;\\nAos Teus pés eu venho assim.\\nÓ Espírito divino,\\nVem, ó, vem e habita em mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Limpa, salva, toma puro\\nEste rude coração.\\nVisto que és consolo e vida,\\nFaz em mim habitação.\"}]},{\"number\":\"157\",\"collection_type\":\"Hinário\",\"title\":\"O Santo Espírito Desceu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Santo Espírito desceu do Céu,\\nEm plenitude de poder,\\nE o Pentecoste fez brilhar a luz,\\nE multidões puderam crer.\\nFiéis em Cristo, sem qualquer temor,\\nSaíram todos a pregar,\\nE conseguiram, mesmo em luta e dor,\\nFinal vitória conquistar.\"},{\"section_type\":\"Coro\",\"content\":\"Ó Deus bendito, hoje, também,\\nVem conceder-nos Tua graça e Teu poder\\nEis nossa prece: Vem perto estar;\\nVem Tua Igreja aqui reavivar\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Só pela fé o justo vai viver\\\",\\nNa Bíblia vamos encontrar;\\nJesus portanto nos dará poder;\\nDevemos crer e confiar.\\nOs que esperam sempre no Senhor,\\nPaz e alegria hão de achar;\\nReceberão de Deus constante amor,\\nE graça pra testemunhar.\"}]},{\"number\":\"158\",\"collection_type\":\"Hinário\",\"title\":\"Suave Espírito\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há um suave espírito entre nós,\\nÉ do Espírito de Deus a doce voz.\\nVejo em cada rosto o resplendor\\nDa presença do Espírito do Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"Ó Santo Espírito, vindo do Céu,\\nFica conosco, enche-nos de fervor!\\nE por tais bênçãos rendemos-Te louvor;\\nE assim reavivados vamos todos ser\\nPor Teu poder e amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Há prazer em cada coração,\\nPois o Espírito desperta em nós o amor,\\nE nos faz viver em união,\\nAnimosos no serviço do Senhor.\"}]},{\"number\":\"159\",\"collection_type\":\"Hinário\",\"title\":\"Chuvas de Bênçãos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Chuvas de bênçãos teremos;\\nÉ a promessa de Deus.\\nTempos benditos veremos,\\nChuvas de bênçãos dos Céus.\"},{\"section_type\":\"Coro\",\"content\":\"Sim, chuvas de bênçãos,\\nChuvas de bênçãos dos Céus!\\nGotas somente nós temos;\\nChuvas rogamos a Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Chuvas de bênçãos teremos,\\nVida de paz e perdão.\\nOs pecadores indignos\\nGraça dos Céus obterão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Chuvas de bênçãos teremos;\\nManda-nos já, ó Senhor!\\nDá-nos agora o bom fruto\\nDesta promessa de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Chuvas de bênçãos teremos,\\nChuvas mandadas dos Céus;\\nBênçãos a todos os crentes,\\nBênçãos do nosso bom Deus.\"}]},{\"number\":\"160\",\"collection_type\":\"Hinário\",\"title\":\"Concede-nos o Espírito\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Concede-nos, ó Deus, o Espírito de amor,\\nE ao nosso coração, o Teu Consolador.\\nNo mundo atroz,\\nQue sempre o Santo Espírito esteja em nós.\"},{\"section_type\":\"Estrofe\",\"content\":\"Convença o mundo então, do juízo e do mal,\\nE da justiça, enfim, com graça divinal.\\nConcede, ó Deus,\\nQue andem na Verdade aqui os filhos Teus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Permite-nos aqui louvar a Deus, o Pai;\\nE ao Filho em alta voz, ó povos, glória dai.\\nLouvai também\\nO bom e Santo Espírito pra sempre. Amém.\"}]},{\"number\":\"161\",\"collection_type\":\"Hinário\",\"title\":\"Vem, Santo Espírito Agora\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem, Santo Espírito, agora,\\nVem, Te pedimos a orar;\\nVem com poder inspirar-nos,\\nSim, vem nos reavivar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem como água ao sedento,\\nTraz ao faminto o pão;\\nVem e sacia minh'alma,\\nFaz puro meu coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem como a brisa suave,\\nVem com o Teu resplendor;\\nDá-nos vigor e alegria,\\nEnche-nos com Teu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem, Espírito Santo,\\nBom, meigo Consolador;\\nVem mundar nossa vida\\nCom Teu sagrado fervor.\"}]},{\"number\":\"162\",\"collection_type\":\"Hinário\",\"title\":\"Que diz a Biblia?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"\\\"Que diz a Biblia, livro sagrado?\\\"\\nPara o fiel, eis a questão!\\nEnsinamentos de homens são falhos;\\nQue diz de Deus o livro, então?\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Que diz a Bíblia?\\\" Poucos dirão;\\n\\\"Que diz a Bíblia?\\\"\\nCumpre saber Seus mandamentos, guardem-nos todos,\\nBreve Jesus iremos ver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Poucos ponderam estes ensinos;\\nQuerem fugir de a lei guardar;\\nOutros pretendem, quanto ao descanso,\\nTer o poder de o revogar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao vir o Mestre, há de saudar-vos,\\nVós que pisais a Sua lei?\\nHá de Ele achar-vos justificados?\\nÓ, meditai e respondei!\"}]},{\"number\":\"163\",\"collection_type\":\"Hinário\",\"title\":\"Teu Livro é Qual Jardim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Teu livro é qual jardim, Senhor, de flores sen iguais.\\nBelezas mil encontro ali, promessas divinais.\\nA Bíblia qual tesouro é, de jóias de valor.\\nSomente as acha pela fé, o bom pesquisador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que a Bíblia santa eu possa amar, e encontrar paz assim;\\nE desse divinal farol, a luz resplenda em mim.\\nQue o livro santo possa ser espada sempre à mão,\\nQue vença o inimigo vil em toda tentação.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Bíblia mostra ao viajor o rumo a perseguir.\\nE mesmo se ele sofre em dor, o anima a prossegir.\\nUm dia quando enfim no lar, morarmos com Jesus,\\nMil graças hemos de cantar, ao dom de Sua luz.\"}]},{\"number\":\"164\",\"collection_type\":\"Hinário\",\"title\":\"Que Firme Alicerce!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que firme alicerce na Santa Escritura,\\nEncontram os crentes em lutas e dor!\\nGrandes promessas e com tal ternura,\\nQuem há que as daria, senão o Senhor?\\nQuem há que as daria, senão o Senhor?\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Se fores chamado a passar pelas águas\\nProfundas e bravas, de angústia e aflição,\\nCrê, pois contigo estarei nessas mágoas,\\nE em glória perene depois findarão,\\nEm glória perene depois findarão.\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Se tua vereda passar pela chama\\nDe fogos ardentes, não fujas à dor!\\nPalha, somente, no fogo se inflama;\\nO ouro, na chama, duplica o valor,\\nO ouro, na chama, duplica o valor.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"A todo que em Mim vem buscar o repouso,\\nConfiado no sangue do Filho de Deus,\\nEu lhe darei, sim, perdão, paz e gozo.\\nPor certo estará nas moradas dos Céus!\\nPor certo estará nas moradas dos Céus!\\\"\"}]},{\"number\":\"165\",\"collection_type\":\"Hinário\",\"title\":\"Dá-me a Bíblia\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dá-me a Biblia que eu tanto anelo,\\nPor seu caminho quero sempre andar;\\nSuas palavras são a doce nova\\nQue nosso Mestre veio anunciar\"},{\"section_type\":\"Coro\",\"content\":\"Dá-me a Biblia, livro tão precioso!\\nSanta doutrina, fonte é de luz.\\nSão seus ensinos um sublime gozo;\\nEles conduzem para o bom Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dá-me a Biblia, dela eu preciso,\\nPois do pecado há de me livrar;\\nSuas palavras têm poder e alento\\nQue minha alma podem renovar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dá-me a Biblia, que meu guia seja;\\nPor toda a vida, meu caminho e luz.\\nSeus bons ensinos sejam sempre o astro\\nQue me conduza para o pé da cruz\"}]},{\"number\":\"166\",\"collection_type\":\"Hinário\",\"title\":\"Novas de Amor e Vida\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, cantai, outra vez cantai, novas de amor e vida!\\nPois eu nelas encontro paz: novas de amor e vida!\\nBelas, sublimadas, puras, inspiradas:\"},{\"section_type\":\"Coro\",\"content\":\"Novas dos Céus! Bênçãos de Deus!\\nNovas de amor e vida!\\nNovas dos Céus! Bênçãos de Deus!\\nNovas de paz e luz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Jesus Cristo a todos dar novas de amor e vida!\\nDai ouvidos ao Seu chamar: novas de amor e vida!\\nSalva todo crente, salva livremente!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vós, ó crentes, a voz alçai: novas de amor e vida!\\nVós, ó anjos, também clamai: novas de amor e vida!\\nCristo, o Rei da glória, dá-nos a vitória!\"}]},{\"number\":\"167\",\"collection_type\":\"Hinário\",\"title\":\"Vem a Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem a Cristo, vem agora,\"},{\"section_type\":\"Coro\",\"content\":\"Vem, ó, vem, pecador!\\nVem, vem, confiantemente,\\nA Jesus, o Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo pode, sim, salvar-te,\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele almeja perdoar-te,\"},{\"section_type\":\"Estrofe\",\"content\":\"Tua entrega não rejeita,\"}]},{\"number\":\"168\",\"collection_type\":\"Hinário\",\"title\":\"A Última Hora\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao findar o labor desta vida,\\nQuando a morte ao teu lado chegar,\\nQue destino hás de ter, ó amigo?\\nQual será no futuro teu lar?\"},{\"section_type\":\"Coro\",\"content\":\"Meu amigo, hoje tu tens a escolha:\\nVida ou morte, qual vais aceitar?\\nAmanhã pode ser muito tarde, Hoje\\nCristo te quer libertar\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu procuras a paz neste mundo,\\nEm prazeres que passam em vão,\\nMas, na última hora da vida,\\nEles não mais te satisfarão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por acaso sorriste, ó amigo,\\nQuando ouviste falar de Jesus?\\nMas é só Ele o único meio\\nDe salvar, pela morte na cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com a alma manchada não podes\\nNunca ver o semblante de Deus;\\nSó os salvos, remidos por Cristo,\\nPoderão ter entrada nos Céus.\"}]},{\"number\":\"169\",\"collection_type\":\"Hinário\",\"title\":\"Deixa Entrar o Rei da Glória\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouve a voz, Jesus te chama!\\nVolve já, ó pecador!\\nOuve a voz de quem te ama:\\nÉ Jesus, teu Salvador.\"},{\"section_type\":\"Coro\",\"content\":\"Deixa entrar o Rei da glória;\\nAbre-Lhe o coração.\\nHás de ter final vitória;\\nVais obter a salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os prazeres do pecado\\nNão trarão conforto ou paz;\\nSó Jesus, o Mestre amado,\\nTua alma satisfaz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Hoje ainda graça existe\\nPara ti, ó pecador!\\nDeixa teu viver tão triste,\\nVem agora ao Salvador!\"}]},{\"number\":\"170\",\"collection_type\":\"Hinário\",\"title\":\"Só um Passo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mui terna e doce é do Mestre a voz,\\nChamando-me com amor:\\n\\\"De braços abertos te espero, vem!\\nÓ, vem ao teu Redentor!\\\"\"},{\"section_type\":\"Coro\",\"content\":\"Cristo me chama, me quer salvar;\\nÉ só um passo, é só confiar!\\nTodo o meu ser deponho no altar\\nAceita-me Tu, ó Cristo!\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Tu tens muitas culpas e débil fé\\\",\\nSugere-me o tentador.\\n\\\"Eu tudo já fiz\\\", uma voz me diz,\\n\\\"Confia em teu Salvador!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"O mundo é falso, perdido e mau;\\nPequeno e frágil sou,\\nMas Cristo com voz divinal me diz:\\n\\\"Meu filho, Eu forças dou!\\\"\"}]},{\"number\":\"171\",\"collection_type\":\"Hinário\",\"title\":\"Deixa Entrar o Rei da Glória\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouve a voz, Jesus te chama!\\nVolve já, ó pecador!\\nOuve a voz de quem te ama:\\nÉ Jesus, teu Salvador.\"},{\"section_type\":\"Coro\",\"content\":\"Deixa entrar o Rei da glória;\\nAbre-Lhe o coração.\\nHás de ter final vitória;\\nVais obter a salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os prazeres do pecado\\nNão trarão conforto ou paz;\\nSó Jesus, o Mestre amado,\\nTua alma satisfaz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Hoje ainda graça existe\\nPara ti, ó pecador!\\nDeixa teu viver tão triste,\\nVem agora ao Salvador!\"}]},{\"number\":\"172\",\"collection_type\":\"Hinário\",\"title\":\"Na Cruz Morri por Ti\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Na cruz morri por ti,\\nPor ti, ó pecador!\\nMeu sangue ali verti,\\nProvando amarga dor.\\nNa cruz a Minha vida pus,\\nDo Céu por isso vim.\\nDas trevas te chamei à luz;\\nQue fazes tu por Mim?\"},{\"section_type\":\"Estrofe\",\"content\":\"Em vão Eu não deixei\\nO trono lá na luz;\\nEm vão não permutei\\nA glória pela cruz.\\nPor ti deixei no Céu Meu lar,\\nFui peregrino aqui.\\nNão queiras, pois, desculpas dar;\\nQue fazes tu por Mim?\"},{\"section_type\":\"Estrofe\",\"content\":\"Imensa foi a dor,\\nA angústia que sofri!\\nNão pode haver maior!\\nA ela sucumbi.\\nMas mesmo a morte desprezei,\\nPra te salvar, assim;\\nPor ti a Minha vida dei;\\nQue fazes tu por Mim?\"}]},{\"number\":\"173\",\"collection_type\":\"Hinário\",\"title\":\"Jesus Está Esperando\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus quer entrar hoje em teu coração,\\nPor que não abres, então?\\nNão deixes que nada Lhe ocupe o lugar;\\nOh, que resposta vais dar?\"},{\"section_type\":\"Coro\",\"content\":\"Vezes sem conta esperado Ele tem,\\nE agora, eis que espera também,\\nA ver se Lhe queres a porta franquear.\\nOh, quanto almeja Ele entrar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se um passo tu deres pra teu Salvador,\\nEle te espera co'amor;\\nUnido a Jesus toda treva se esvai,\\nE Ele morar em ti vai.\"}]},{\"number\":\"174\",\"collection_type\":\"Hinário\",\"title\":\"Segue-Me\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Escuta a voz do meu Jesus:\\nSegue-Me, segue-Me, segue-Me.\\nGuiar-te-ei à eterna luz;\\nSegue-Me, segue-Me, segue-Me.\\nPor ti Eu toda a lei cumpri;\\nPor ti o amargo fel bebi;\\nPor ti a morte já sofri;\\nSegue-Me, segue-Me, segue-Me.\"},{\"section_type\":\"Estrofe\",\"content\":\"Liberto dos pecados teus,\\nSegue-Me, segue-Me, segue-Me.\\nGuiar-te-ei aos altos Céus;\\nSegue-Me, segue-Me, segue-Me.\\nOh, quantas vezes te chamei,\\nE tu quebraste a Minha lei;\\nMas fiador teu Eu fiquei;\\nSegue-Me, segue-Me, segue-Me.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Mim tu podes descansar;\\nSegue-Me, segue-Me, segue-Me.\\nVem teus cuidados Me entregar;\\nSegue-Me, segue-Me, segue-Me.\\nEu sou teu Deus, teu Salvador;\\nEu te amo muito, ó pecador;\\nÓ, deixa todo o teu temor;\\nSegue-Me, segue-Me, segue-Me.\"}]},{\"number\":\"175\",\"collection_type\":\"Hinário\",\"title\":\"Manso e Suave\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Manso e suave Jesus 'stá chamando;\\nChama por ti e por mim.\\nEis que Ele à porta espera velando;\\nVela por ti e por mim.\"},{\"section_type\":\"Coro\",\"content\":\"Vem já! Vem já!\\nAlma cansada, vem já!\\nManso e suave Jesus 'stá chamando;\\nChama: \\\"Ó, vem, pecador!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Pois que esperamos?\\nJesus convidando,\\nConvida a ti, sim, e a mim.\\nOh, não desprezes mercê que está dando,\\nSim, dando a ti, dando a mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Correm os dias, as horas se passam,\\nPassam por ti e por mim.\\nTranses de morte por fim nos esperam,\\n'Speram por ti e por mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! grande amor que Jesus nos tem dado!\\nTem dado a ti, dado a mim.\\nVeio salvar-nos do tão vil pecado;\\nVeio por ti e por mim.\"}]},{\"number\":\"176\",\"collection_type\":\"Hinário\",\"title\":\"À Tua Porta Cristo Está\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"À tua porta Cristo está; abre-Lhe!\\nSe Lhe abrires, entrará; abre-Lhe!\\nTeu pecado perdoará, luz e paz derramará;\\nNunca mais te deixará; abre-Lhe!\"},{\"section_type\":\"Estrofe\",\"content\":\"Abre, pois, teu coração; abre-Lhe!\\nDemorar não deves, não; abre-Lhe!\\nTeu amigo Ele há de ser; vai do mal te defender,\\nTé o fim te proteger; abre-Lhe!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não O faças esperar; abre-Lhe!\\nAfinal Se há de afastar; abre-Lhe!\\nOh! que dor depois terás, pois em vão tu clamarás,\\nE perdido te acharás; abre-Lhe!\"}]},{\"number\":\"177\",\"collection_type\":\"Hinário\",\"title\":\"Ó, Vem, Aflito Coração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem, aflito coração,\\nEm Cristo alívio encontrarás.\\nConsolo, paz e Seu perdão,\\nSim, dEle tu receberás.\"},{\"section_type\":\"Coro\",\"content\":\"Ó, vem sem demora ao Salvador!\\nPor que vacilar e ter temor?\\nÓ, vem! Vem já! Descanso te dará!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se estás ferido pela dor\\nQue vem da tua transgressão,\\nVem sem demora ao Salvador,\\nTerás alivio e salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se estás distante do Senhor,\\nE tens fraquezas a vencer,\\nO, vem, pois Ele, em Seu amor,\\nDará a graça do poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Cristo sem demora vem,\\nPois Ele almeja te valer,\\nE sempre quer buscar teu bem;\\nConfia nEle, em teu viver\"}]},{\"number\":\"178\",\"collection_type\":\"Hinário\",\"title\":\"Amor Sem Igual\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, não tens ouvido do amor sem igual,\\nDo amor que teu Deus tem por ti?\\nO amor que O levou a Seu Filho entregar,\\nPra os salvos levar para Si.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, crê! Sim, crê!\\nOh, crê! Sim, crê!\\nA graça de Deus te chama dos Céus.\\nOh, crê nesse amor sem igual!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não foram os grandes que Cristo chamou,\\nNem justos veio Ele salvar,\\nMas pobres e fracos, culpados e maus\\nMandou pelos servos buscar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O homem, porém, não podia chegar\\nÀ santa presença de Deus,\\nPorque os pecados de seu coração\\nVedavam-lhe a entrada nos Céus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mas pelo Seu sangue Jesus expiou\\nA culpa dos crentes, na cruz;\\nTirando o pecado, o caminho mostrou,\\nO qual para os Céus nos conduz.\"}]},{\"number\":\"179\",\"collection_type\":\"Hinário\",\"title\":\"Vinde a Mim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Convite bom e amável vos faz o Salvador;\\nQuer dar-vos Suas bênçãos e Seu sublime amor.\\nCom meiga voz, maviosa, Jesus vos chama, sim,\\nA todos vós, aflitos, e diz-vos: \\\"Vinde a Mim.\\\"\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Vinde, vinde a Mim! Vinde, vinde a Mim!\\nTristes, carregados, vinde, vinde a Mim!\\nVinde, vinde a Mim! Vinde, vinde a Mim!\\nFracos e cansados, vinde, vinde a Mim!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Por que viver tão longe do meigo e bom Jesus?\\nPor que vagar nas trevas, podendo andar na luz?\\nDa vida sem proveito, da culpa e da aflição,\\nCorramos para a senda da eterna salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se o denso véu da angústia trouxer tribulação,\\nOh, não temais, pois Cristo dará consolação.\\nE assim vereis, na vida, o alento que produz,\\nNo coração submisso, O \\\"Vinde\\\" de Jesus.\"}]},{\"number\":\"180\",\"collection_type\":\"Hinário\",\"title\":\"Foge Para o Monte\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Foge veloz para o monte,\\nÓ pecador, sem tardar\\nBusca perdão junto à fonte,\\nFonte que está a jorrar.\\nLá fruirás paz dos santos,\\nLá findarão os teus prantos.\\nOlha do Céu os encantos\\nE vem a Jesus sem tardar.\\nOh, vem a Jesus sem tardar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sente terror tua alma?\\nBuscas a paz, pecador?\\nHás de gozar doce calma\\nJunto do teu Salvador.\\nEle é gentil, bom e amável,\\nQuer só teu bem cada instante;\\nNão fiques, pois, vacilante,\\nOh, vem a Jesus sem tardar!\\nOh, vem a Jesus sem tardar!\"}]},{\"number\":\"181\",\"collection_type\":\"Hinário\",\"title\":\"Oh, Vinde à Fonte\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, vinde à fonte de sangue,\\nVinde, sim, vinde a Jesus!\\nPaz e perdão vos outorga;\\nVinde alcançá-los na cruz.\"},{\"section_type\":\"Coro\",\"content\":\"Vinde a Jesus! Vinde a Jesus!\\nNão demoreis; vinde já, vinde lá!\\nPaz e perdão vos outorga;\\nVinde alcançá-los na cruz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tais como sois vinde à fonte;\\nEle vos receberá.\\nTodos os vossos pecados,\\nCristo Jesus limpará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis a promessa do Mestre,\\nFeita a qualquer que aceitar:\\nVida na glória celeste,\\nJunto de Deus vai gozar.\"}]},{\"number\":\"182\",\"collection_type\":\"Hinário\",\"title\":\"Cristo te Chama\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo te chama com mui terno amor;\\nÓ pecador, vem atender!\\nDEle não fujas com fútil temor;\\nVem a Jesus te render!\"},{\"section_type\":\"Coro\",\"content\":\"Ó pecador eis o Senhor!\\nVem e atende com fé\\nA chamada de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo te chama pra vir descansar;\\nÓ pecador, vem atender!\\nTeu grande peso te quer minorar;\\nVem a Jesus te render!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo deseja, pois, te perdoar;\\nÓ pecador, vem atender!\\nTudo Ele fez para te resgatar;\\nVem a Jesus te render!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo de novo Se põe a chamar;\\nÓ pecador, vem atender!\\nCorre depressa, sim, vem te entregar;\\nNada te deve deter!\"}]},{\"number\":\"183\",\"collection_type\":\"Hinário\",\"title\":\"Dá Teu Coração a Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Queres o teu vil pecado vencer?\\nDá teu coração a Jesus.\\nQueres também Seu favor receber?\\nDá teu coração a Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Vem logo, sem hesitar\\nVem a Jesus te entregar!\\nOh, busca em Cristo o perdão,\\nE dá-Lhe teu coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em santidade desejas viver?\\nDá teu coração a Jesus.\\nQueres do Espírito Santo o poder?\\nDá teu coração a Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"A tempestade não quer acalmar?\\nDá teu coração a Jesus.\\nQueres as tuas paixões dominar?\\nDá teu coração a Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dentre os amigos alguém te traiu?\\nDá teu coração a Jesus.\\nBusca a amizade de quem te remiu;\\nDá teu coração a Jesus.\"}]},{\"number\":\"184\",\"collection_type\":\"Hinário\",\"title\":\"Deixa a Luz do Céu Entrar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tu anseias hoje a salvação fruir?\\nTens desejo de a escuridão banir?\\nAbre, pois, o coração de par em par!\\nDeixa a luz do Céu entrar!\"},{\"section_type\":\"Coro\",\"content\":\"Deixa a luz do Céu entrar!\\nDeixa a luz do Céu entrar!\\nAbre, pois, o coração de par em par!\\nDeixa a luz do Céu entrar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo, a luz celeste, quer morar em ti,\\nPara iluminar o teu caminho aqui!\\nSempre do pecado o coração limpar!\\nDeixa a luz do Céu entrar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que alegria andar no brilho dessa luz!\\nVida eterna e paz no coração produz!\\nOh, aceita agora o Salvador-Jesus!\\nDeixa a luz do Céu entrar!\"}]},{\"number\":\"185\",\"collection_type\":\"Hinário\",\"title\":\"Já Avaliaste o Preço?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quem rejeita o bom Deus 'stá um caminho a traçar,\\nQue abafar vai a voz do Senhor;\\nE se as glórias do mundo só queres buscar,\\nJá do preço calculaste o valor?\"},{\"section_type\":\"Coro\",\"content\":\"Se tua alma perderes, de que valerá\\nTer o mundo e seu esplendor?\\nE da senda que agora tu estás a trilhar\\nJá do preço calculaste o valor?\"},{\"section_type\":\"Estrofe\",\"content\":\"Vais trocar a esperança de vida eternal,\\nPor qualquer momentâneo fulgor?\\nDo prazer do pecado e seu brilho fatal,\\nJá do preço calculaste o valor?\"},{\"section_type\":\"Estrofe\",\"content\":\"E enquanto Sua graça inda franca estiver,\\nE encerrado não for seu favor,\\nTu não queres chegar ao teu Deus e dizer:\\n\\\"Já do preço calculei o valor\\\"?\"}]},{\"number\":\"186\",\"collection_type\":\"Hinário\",\"title\":\"Quem Ouvir as Novas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quem ouvir as novas, vá proclamar:\\nSalvação de graça, vinde desfrutar!\\nOh! que o mundo inteiro ouça anunciar:\\nTodo que quiser é vir!\"},{\"section_type\":\"Coro\",\"content\":\"Todo que quiser venha receber!\\nPossam todos essa boa nova ouvir.\\nÉ o Pai celeste quem convida assim:\\nTodo que quiser é vir!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quem quiser agora, venha aceitar;\\nEis a porta aberta, já podeis entrar;\\nÉ Jesus caminho para ao Céu chegar;\\nTodo que quiser é vir!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que fiel promessa tens, pecador!\\nQueres ter a vida? Vem ao Salvador!\\nEle a todos fala com mui terno amor:\\nTodo que quiser é vir!\"}]},{\"number\":\"187\",\"collection_type\":\"Hinário\",\"title\":\"Ouvi Jesus a me Dizer\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouvi Jesus a me dizer: \\\"Ó, vem, descansa em Mim;\\nE no Meu seio podes ter consolação sem fim.\\\"\\nEntão eu vim e Lhe entreguei meu triste coração.\\nAbrigo, paz, conforto achei; em Cristo achei perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ouvi Jesus a me dizen \\\"Da água viva Eu dou;\\nÓ vem, de graça vem beber, pois Eu a fonte sou.\\\"\\nEu vim a Cristo e me prostrei às águas e bebi;\\nJamais a sede sentirei, estando eu sempre aqui.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ouvi Jesus a me dizer: \\\"A luz do mundo Eu sou.\\nÓ, vem a Mim! A quem vier, a luz da vida Eu dou.\\\"\\nA Ele eu vim e nEle achei o Sol que brilha em mim.\\nE nessa luz eu sempre irei, até da vida o fim.\"}]},{\"number\":\"188\",\"collection_type\":\"Hinário\",\"title\":\"A Nós a Porta Franca Está\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A nós a porta franca está,\\nDa divinal morada,\\nE Cristo nos concederá\\nA triunfal entrada.\"},{\"section_type\":\"Coro\",\"content\":\"Oh! quanto amor Jesus sentiu,\\nPois Ele a porta já me abriu!\\nA mim, a mim,\\nA porta já me abriu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se queres tu também entrar,\\nA porta está aberta.\\nAli no Céu terás lugar\\nQue a ti Jesus oferta.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, vinde todos sem tardar;\\nSim, vinde sem demora.\\nO tempo próprio vai passar;\\nJesus vos chama agora.\"}]},{\"number\":\"189\",\"collection_type\":\"Hinário\",\"title\":\"Junto à Cruz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Na cruz onde Cristo morreu,\\nHá poder de abrigar e salvar;\\nAli meu Jesus, por amor, padeceu:\\nAmor tão imenso, mais vasto que o mar!\"},{\"section_type\":\"Coro\",\"content\":\"Junto à cruz há lugar pra ti,\\nJunto à cruz há lugar pra ti;\\nSalvou a milhões e ainda há lugar\\nJunto à cruz há lugar pra ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Milhões encontraram perdão,\\nDescobriram a paz divinal,\\nE Cristo inda espera pra dar salvação,\\nQuer dar-te esperança e vida eternal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sem Cristo não podes viver,\\nSem Jesus tu não podes andar;\\nVigor fruirás, vida plena hás de ter\\nSe em teu Salvador tu quiseres confiar.\"}]},{\"number\":\"190\",\"collection_type\":\"Hinário\",\"title\":\"Seu Maravilhoso Olhar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vivi tão longe do Senhor,\\nAssim eu quis andar,\\nAté que eu encontrei o amor\\nEm Seu bondoso olhar.\"},{\"section_type\":\"Coro\",\"content\":\"Seu maravilhoso olhar!\\nSeu maravilhoso olhar!\\nTransformou meu ser todo o meu viver\\nSeu maravilhoso olhar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Seu corpo vi na rude cruz,\\nSofrendo ali por mim,\\nE ouvi a voz do meu Jesus:\\n\\\"Por ti morri assim.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Em contrição então voltei\\nÀ fonte deste amor.\\nPerdão e paz em Cristo achei;\\nPertenço ao Salvador!\"}]},{\"number\":\"191\",\"collection_type\":\"Hinário\",\"title\":\"Quero Estar ao Pé da Cruz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quero estar ao pé da cruz,\\nDe onde rica fonte\\nCorre franca e salutar,\\nSobre o rude monte.\"},{\"section_type\":\"Coro\",\"content\":\"Sim, na cruz, sim, na cruz\\nSempre me glorio,\\nTé que ao fim vá descansar\\nSalvo, além do rio.\"},{\"section_type\":\"Estrofe\",\"content\":\"A tremer ao pé da cruz,\\nGraça eterna achou-me;\\nLá a Estrela da manhã\\nRaios Seus mandou-me.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre a cruz, Jesus meu Deus,\\nQueiras recordar-me;\\nDela, à sombra, ó Salvador,\\nQueiras abrigar-me.\"},{\"section_type\":\"Estrofe\",\"content\":\"Junto à cruz, ardendo em fé,\\nSem temor vigio,\\nPois ao lar paterno irei,\\nSalvo, além do rio.\"}]},{\"number\":\"192\",\"collection_type\":\"Hinário\",\"title\":\"Infinita Graça\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Conforme a Tua infinita graça,\\nÓ Pai, perdoa a minha transgressão.\\nFaz-me sentir o Teu amor infinito,\\nDá-me alegria em Tua salvação.\"},{\"section_type\":\"Coro\",\"content\":\"Mais uma vez eu sinto o meu pecado,\\nQue é contra Ti, ó Pai de amor.\\nConcede, ó Deus, a mim, misericórdia,\\nE entoarei a Ti o meu louvor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu coração entrego a Ti, contrito,\\nPerdão imploro, meu Senhor e Rei.\\nConforme a Tua infinita graça,\\nMisericórdia, sim, alcançarei.\"}]},{\"number\":\"193\",\"collection_type\":\"Hinário\",\"title\":\"Creio em Milagres\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em toda a criação de Deus\\nEu vejo o Seu poder;\\nE quem contempla a linda flor\\nMilagres pode ver.\"},{\"section_type\":\"Coro\",\"content\":\"Creio em milagres,\\nPois Cristo me salvou!\\nTão grandioso é o poder\\nQue assim me transformou!\\nMinh'alma escura se abriu\\nÀ luz do Salvador.\\nCreio em milagres,\\nPois tenho um Deus de amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"De Deus o amor, poder real,\\nMilagres fez em mim.\\nPerdão, felicidade, paz,\\nEu tenho agora, enfim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Divino Pai, em Seu poder\\nRenova o coração,\\nE num milagre de amor,\\nOpera a salvação.\"}]},{\"number\":\"194\",\"collection_type\":\"Hinário\",\"title\":\"Teus Pecados Brancos se Farão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pecador, teus pecados brancos, brancos se farão;\\nPecador, teus pecados brancos, brancos se farão!\\nSim, inda que sejam rubros, como lã serão;\\nMesmo que teus pecados sejam como escarlata,\\nBrancos, brancos se farão; como lã se tornarão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Pecador, Deus te chama, ouve já a voz dos Céus!\\nPecador, Deus te chama, ouve já a voz dos Céus!\\nEle é tão bom, tão amável, compassível é!\\nCom ardor te convida, com amor, sim, te abriga!\\nChega, pois, ao Salvador; ouve já a voz de amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Desfará tuas culpas, e lançá-las-á ao mar!\\nDesfará tuas culpas, e lançá-las-á ao mar!\\n\\\"Ó vinde a Mim, vós cansados!\\\" Diz Jesus, Senhor.\\nMau embora tu sejas, mau embora tu sejas,\\nSeu descanso te dará; e feliz te tornará!\"}]},{\"number\":\"195\",\"collection_type\":\"Hinário\",\"title\":\"Rocha Eterna\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Rocha eterna, meu Jesus, Tu morreste lá na cruz!\\nVem de Ti um sangue tal que me vem lavar do mal!\\nTraz as bênçãos do perdão: paz, conforto e salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nem trabalho, nem penar pode alguém aqui salvar,\\nMas só Tu, meu bom Jesus, podes dar-me a vida e luz.\\nPeço-Te perdão, Senhor, pois confio em teu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis que vem a morte atrás desta vida tão fugaz!\\nQuando ao lar do Céu subir, e Teu rosto em glória vir,\\nRocha eterna, que prazer eu terei de em Ti viver!\"}]},{\"number\":\"196\",\"collection_type\":\"Hinário\",\"title\":\"Em Deus Há Livre Perdão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Glória a Jesus, pois há livre perdão,\\nHá livre perdão, há livre perdão!\\nVem, pecador, aceitar este dom:\\nDe Deus um livre perdão!\\nÓ, vem agora em Deus confiar,\\nEm Deus confiar, em Deus confiar,\\nVida perene vais nEle encontrar,\\nDe Deus um livre perdão!\"},{\"section_type\":\"Coro\",\"content\":\"Cristo está pronto pra te perdoar,\\nPra te perdoar, pra te perdoar!\\nÓ pecador, por que não aceitar?\\nEm Deus há livre perdão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Longe de Cristo só podes sofrer,\\nSó podes sofrer, só podes sofrer,\\nMas em Jesus há supremo prazer,\\nEm Deus há livre perdão!\\nTrevas te cercam? Ó, vem para a luz,\\nÓ, vem para a luz, ó, vem para a luz;\\nPaz, força e vida terás em Jesus,\\nDe Deus um livre perdão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, há perdão para aquele que crer,\\nAquele que crer, aquele que crer!\\nE mesmo agora tu podes obter\\nDe Deus um livre perdão!\\nCristo te espera, sim, vem como estás,\\nSim, vem como estás, sim, vem como estás;\\nÓ, vem agora, pois receberás\\nDe Deus um livre perdão!\"}]},{\"number\":\"197\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Tocou-me\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Preso por imenso fardo\\nDe pecado e de amor,\\nFoi que Cristo, então, tocou-me,\\nE assim não sou mais tal pecador.\"},{\"section_type\":\"Coro\",\"content\":\"Tocou-me, sim, tocou-me.\\nOh! quanta paz no coração!\\nFui transformado e novo sou;\\nE hoje eu tenho salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Desde que encontrei meu Mestre,\\nSinto paz, prazer sem-par;\\nMeus louvores ergo a Cristo,\\nSeu nome a todos vou proclamar.\"}]},{\"number\":\"198\",\"collection_type\":\"Hinário\",\"title\":\"O Maior Milagre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Deus é onipotente Rei,\\nNão posso duvidar,\\nPois tantas maravilhas pôs\\nNo céu, em terra e mar!\"},{\"section_type\":\"Coro\",\"content\":\"Mas um maior milagre me comove o ser\\nTão insondável é, não posso compreender:\\nQue o meu eterno Deus, em Seu grande amor\\nA mim salvasse, pobre pecador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que em torno de meu Deus\\nHá glória sem igual;\\nE pelo Seu poder mantém\\nO espaço sideral!\"},{\"section_type\":\"Estrofe\",\"content\":\"A Bíblia fala desse Deus;\\nSupremo Criador,\\nA quem todo Universo vem\\nRender o seu louvor!\"}]},{\"number\":\"199\",\"collection_type\":\"Hinário\",\"title\":\"Olhai e Vivei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A mensagem do Senhor, Aleluia!\\nNos fala de perdão e amor.\\nCristo salva o pecador, Aleluia!\\nEle é nosso grande Redentor.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, olhai, e então vivei!\\nConfiai só em Jesus.\\nEle salva o pecador, Aleluia!\\nSim, por nós a vida deu na cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nossa culpa já levou, Aleluia!\\nSim, Cristo a carregou na cruz.\\nSua vida Ele entregou, Aleluia!\\nPara nos levar ao lar de luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sua graça nos legou, Aleluia!\\nE a vida eterna lá nos Céus.\\nConfiai só em Jesus, Aleluia!\\nConvertei-vos hoje mesmo a Deus.\"}]},{\"number\":\"200\",\"collection_type\":\"Hinário\",\"title\":\"Tens Vida em Olhar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tens vida em olhar para a cruz de amor;\\nDisse Jesus: \\\"Olhai pra Mim.\\\"\\nOuro e bens perdem seu valor\\nNa glória que vem dessa cruz, oh, sim.\"},{\"section_type\":\"Coro\",\"content\":\"Num olhar tens vida, sim,\\nNum olhar à cruz de amor;\\nBênçãos há e salvação,\\nNum olhar ao Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Amável sorriso em Seu rosto vi\\nQuando eu olhei a rude cruz;\\nTudo mudou ao prostrar-me ali,\\nPoder inundou-me e celeste luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Olhando pra cruz sempre confiarei\\nEm Seu poder, em Seu amor.\\nNunca vencido do mal serei,\\nPois tenho comigo meu Salvador.\"}]},{\"number\":\"201\",\"collection_type\":\"Hinário\",\"title\":\"Meu Cálice Transborda\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tão sedento, pelo mundo, eu procurava\\nMinh'alma, em vão, satisfazer;\\nEntão o Salvador falou-me;\\n\\\"Desta fonte eterna vem beber.\\\"\"},{\"section_type\":\"Coro\",\"content\":\"O meu cálice eu ergo a Ti, Senhor;\\nVem minh'alma sedenta saciar.\\nMinha vida anseia pelo Teu amor,\\nFaz meu ser dessa água transbordar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quanta gente está em busca dos prazeres\\nQue o mundo pode oferecer;\\nIgnoram a felicidade\\nQue em Cristo, de graça, podem ter.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó amigo, se as coisas desta Terra\\nSó trazem dor, desilusão,\\nEm Cristo há paz e alegria,\\nEle é fonte de vida e salvação.\"}]},{\"number\":\"202\",\"collection_type\":\"Hinário\",\"title\":\"Eis uma Fonte\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eis que uma fonte aberta está:\\nO sangue de Jesus.\\nQuem nela se lavar, à cruz,\\nSem manchas ficará.\\nSem manchas ficará,\\nSem manchas ficará;\\nQuem nela se lavar, à cruz,\\nSem manchas ficará.\"},{\"section_type\":\"Estrofe\",\"content\":\"O sangue do Cordeiro tem\\nPoder pra libertar\\nO pecador que a Cristo vem,\\nAo Salvador sem-par.\\nAo Salvador sem-par,\\nAo Salvador sem-par;\\nO pecador que a Cristo vem,\\nAo Salvador sem-par.\"},{\"section_type\":\"Estrofe\",\"content\":\"Desde que aceitei a salvação,\\nPor Cristo, meu Senhor,\\nTem sido a excelsa redenção\\nMeu tema e meu vigor.\\nMeu tema e meu vigor,\\nMeu tema e meu vigor;\\nTem sido a excelsa redenção\\nMeu tema e meu vigor.\"},{\"section_type\":\"Estrofe\",\"content\":\"E quando à eterna glória eu for,\\nMelhor eu cantarei;\\nA Cristo, Rei e Salvador,\\nPra sempre exaltarei.\\nPra sempre exaltarei,\\nPra sempre exaltarei;\\nA Cristo, Rei e Salvador\\nPra sempre exaltarei.\"}]},{\"number\":\"203\",\"collection_type\":\"Hinário\",\"title\":\"Ó Jesus, Habita em Mim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu pecado regatado\\nFoi na cruz, por Teu amor;\\nE da morte, triste sorte,\\nMe livraste, ó Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"Vem, inflama viva chama\\nDe fervor e fé sem fim!\\nEu Te adoro, sempre imploro:\\nÓ Jesus, habita em mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se hesitante, vacilante,\\nOuço a voz do tentador,\\nTu me guias, me auxilias\\nE me tornas vencedor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Redimida, só tem vida\\nA minh'alma em Teu amor.\\nCom apreço, reconheço\\nQuanto devo a Ti, Senhor!\"}]},{\"number\":\"204\",\"collection_type\":\"Hinário\",\"title\":\"Maravilhosa Graça\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Maravilhosa graça! Maior que o meu pecar!\\nComo poder cantá-la? Como hei de começar?!\\nTrouxe-me alívio à alma, e vivo em toda a calma,\\nPela maravilhosa graça de Jesus!\"},{\"section_type\":\"Coro\",\"content\":\"Graça! Quão maravilhosa graça!\\nComo o firmamento, é sem fim!\\nÉ maravilhosa, é tão grandiosa,\\nTão sublime e doce para mim!\\nÉ maior que a minha vida inútil,\\nMais profunda que o imenso mar.\\nA Cristo vamos, pois, louvores dar!\\nA Deus honrar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Maravilhosa graça! Traz vida perenal!\\nPor Cristo perdoado, vou à mansão real.\\nSei que hoje sou liberto, vivo de Deus bem perto,\\nPela maravilhosa graça de Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Maravilhosa graça! Quão ricas bênçãos traz!\\nPor ela Deus salvou-me, deu-me perdão e paz!\\nSalvo, sim, em verdade, por toda a eternidade,\\nPela maravilhosa graça de Jesus!\"}]},{\"number\":\"205\",\"collection_type\":\"Hinário\",\"title\":\"Alvo Mais que a Neve\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Seja bendito o Cordeiro\\nQue na cruz por nós padeceu!\\nSeja bendito Seu sangue\\nQue por nós pecadores verteu!\\nEis-nos no sangue lavados,\\nCom vestes que tão alvas são,\\nNós, pecadores redimidos,\\nQue de Deus recebemos perdão.\"},{\"section_type\":\"Coro\",\"content\":\"Alvo mais que a neve!\\nAlvo mais que a neve!\\nSim, nesse sangue lavado,\\nMais alvo que a neve serei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quão espinhosa a coroa\\nQue Jesus por nós suportou!\\nOh! quão profundas as chagas\\nQue nos provam o quanto Ele amou!\\nHá nessas chagas pureza\\nPara o mais torpe pecador!\\nPois que mais alvos que a neve\\nO Teu sangue nos torna, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se nós a Ti confessarmos,\\nE seguirmos na Tua luz,\\nTu não somente perdoas,\\nPurificas também, ó Jesus;\\nSim, e de todo o pecado!\\nQue maravilha desse amor!\\nPois que mais alvos que a neve\\nO Teu sangue nos torna, Senhor.\"}]},{\"number\":\"206\",\"collection_type\":\"Hinário\",\"title\":\"Seu Sangue Tem Poder\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"De teu pecado te queres livrar?\\nO sangue de Jesus dá o poder.\\nÉ teu querer do maligno escapar?\\nTerás no Seu sangue o poder.\"},{\"section_type\":\"Coro\",\"content\":\"Há poder, sim, força sem igual\\nSó no sangue de Jesus.\\nHá poder, sim, vem, ó pecador,\\nE aceita o dom de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não queres tu a vaidade afastar?\\nO sangue de Jesus dá o poder.\\nQueres as tuas paixões dominar?\\nTerás no Seu sangue o poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Teu coração queres purificar?\\nO sangue de Jesus dá o poder.\\nTodas as manchas te pode tirar;\\nSeu sangue tem este poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Queres entrar no serviço real?\\nO sangue de Jesus dá o poder.\\nQueres também ser um servo leal?\\nSeu sangue tem este poder.\"}]},{\"number\":\"207\",\"collection_type\":\"Hinário\",\"title\":\"Vida em Olhar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vida tens em olhar a Jesus, Salvador;\\nEle diz: \\\"Vida eterna te dou.\\\"\\nPois então, pecador, considera esse amor;\\nVê Jesus que na cruz expirou.\"},{\"section_type\":\"Coro\",\"content\":\"Vê, vê, viverás.\\nVida tens em olhar a Jesus, Salvador.\\nEle diz: \\\"Vida em Mim acharás.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Vida tens em olhar a Jesus, Salvador;\\nPois o Seu grande amor já provou.\\nCom Seu sangue na cruz, sucumbindo na dor,\\nTua falta também já pagou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vida tens em olhar a Jesus, Salvador;\\nJá por ti Ele tudo sofreu.\\nCom amor dá perdão ao maior transgressor.\\nVê Jesus que por ti padeceu.\"}]},{\"number\":\"208\",\"collection_type\":\"Hinário\",\"title\":\"Graça Excelsa\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, graça excelsa de Jesus!\\nPerdido, me encontrou!\\nEstando cego, me fez ver;\\nDa morte me livrou!\"},{\"section_type\":\"Estrofe\",\"content\":\"A graça libertou-me assim,\\nE meu temor levou.\\nOh! quão preciosa é para mim\\nA hora em que me achou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mil lutas, dores, tentações\\nCaíram sobre mim,\\nPorém, a graça me salvou!\\nFeliz eu sou, enfim!\"},{\"section_type\":\"Estrofe\",\"content\":\"E quando ao Céu em glória eu for,\\nAo lar de paz e luz,\\nPra sempre, então, eu cantarei\\nDa graça de Jesus!\"}]},{\"number\":\"209\",\"collection_type\":\"Hinário\",\"title\":\"Jesus me Remiu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus me remiu por Seu sangue!\\nEu hei de pra sempre cantar.\\nRemiu-me sem que o merecesse.\\nOh! graça suprema, sem-par!\"},{\"section_type\":\"Coro\",\"content\":\"Remiu, remiu,\\nNa cruz me remiu meu Jesus.\\nRemiu-me, remiu-me,\\nPor isso ando agora na luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Remido em Jesus por Sua graça,\\nNão posso exprimir o prazer!\\nA luz da divina presença\\nInunda constante meu ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em meu Redentor eu medito,\\nDe dia e de noite ao deitar;\\nDa graça tão maravilhosa\\nEu quero pra sempre cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que hei de ver, em Sua glória,\\nO Rei cuja lei é de amor,\\nPois sempre Ele guia meus passos,\\nE põe-me na boca o louvor.\"}]},{\"number\":\"210\",\"collection_type\":\"Hinário\",\"title\":\"Perdão, Poder e Paz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se nós quisermos gozo ter,\\nBusquemo-lo de Deus,\\nColhendo as bênçãos, com prazer,\\nQue em Seu amor nos deu.\"},{\"section_type\":\"Coro\",\"content\":\"Há perdão, poder e paz,\\nE graça e luz, e amor gentil\\nEm Cristo, a fonte de prazer.\\nA Ele demos glórias e honras mil!\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Sua graça tenho, sim,\\nPoder pra triunfar.\\nO Espírito divino em mim\\nMe livra de pecar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O Santo Espírito também\\nMe ajuda a conquistar\\nA alma que inda se detém\\nBem longe do seu lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Só é possível pela fé\\nTais bênçãos receber;\\nPor Cristo, o Pai concede, até\\nO reino àquel' que crer.\"}]},{\"number\":\"211\",\"collection_type\":\"Hinário\",\"title\":\"Rude Cruz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Rude cruz se erigiu! Dela o dia fugiu,\\nEm sinal de vergonha e de dor!\\nMas eu amo essa cruz, sobre a qual meu Jesus\\nDeu a vida por mim, pecador.\"},{\"section_type\":\"Coro\",\"content\":\"Sim, eu amo a mensagem da cruz;\\nTé morrer eu a vou proclamar.\\nLevarei eu também minha cruz,\\nTé por uma coroa trocar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Desde a glória dos Céus, o Cordeiro de Deus\\nAo Calvário humilhante baixou;\\nE essa cruz tem pra mim atrativos sem fim,\\nPois Jesus nela me regatou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nessa cruz padeceu, desprezado, morreu\\nMeu Jesus para dar-me o perdão.\\nEu me alegro na cruz, dela vem graça e luz\\nPara minha santificação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu aqui, com Jesus, a vergonha da cruz\\nQuero sempre levar e sofrer;\\nEle vem me buscar, e com Ele, no lar,\\nUma parte na glória hei de ter\"}]},{\"number\":\"212\",\"collection_type\":\"Hinário\",\"title\":\"Um Novo Nome Lá na Glória\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pecador eu era, sim, porém,\\nGraça eu encontrei em Jesus.\\nDeu-me prontamente Seu perdão,\\nDeu-me vida, paz e luz.\"},{\"section_type\":\"Coro\",\"content\":\"Há um novo nome lá na glória:\\nÉ o meu, sim, é o meu!\\nSantos anjos cantam essa história:\\nO pródigo volveu!\\nPois há um novo nome lá na glória:\\nÉ o meu, sim, é o meu!\\nPois que fui perdoado, sou ao Céu levado;\\nLá morar eu vou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Junto à cruz prostrei-me com temor,\\nAo sentir-me um vil pecador.\\nMas o Céu abriu-se e então eu vi\\nO meu nome escrito ali!\"},{\"section_type\":\"Estrofe\",\"content\":\"Glória, aleluia, salvo estou!\\nFoi Seu sangue que me livrou!\\nPela eterna graça, louvo a Deus!\\nPara o lar celeste vou!\"}]},{\"number\":\"213\",\"collection_type\":\"Hinário\",\"title\":\"Graça de Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Graça de Deus, infinito amor!\\nGraça do Céu, dom divinal!\\nPor Sua morte em amarga dor,\\nCristo me trouxe este amor real.\"},{\"section_type\":\"Coro\",\"content\":\"Graça, graça,\\nFonte de paz que Jesus me deu;\\nGraça, graça,\\nGraça maior que o pecado meu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Fardos me oprimem, de angústia e dor,\\nQuando me vêm ondas do mal,\\nMas pela graça do Salvador,\\nTenho poder para ser leal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quão insondável o amor de Deus!\\nTraz salvação ao pecador.\\nPor esta graça que vem dos Céus\\nSei que estarei com o meu Senhor.\"}]},{\"number\":\"214\",\"collection_type\":\"Hinário\",\"title\":\"Manancial de Toda Bênção\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Manancial de toda bênção,\\nVem o canto me inspirar!\\nDons de Deus que nunca cessam,\\nQuero em alto som louvar.\\nFaz brotar-me novo canto\\nDos remidos lá na luz;\\nE Teu servo, faze-o santo,\\nPra louvar-Te, ó Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Meus louvores dar eu quero,\\nPois Jesus me socorreu,\\nE por Sua graça espero\\nTransportar-me para o Céu.\\nEu, perdido, procurou-me,\\nLonge, longe, já sem luz;\\nMaculado, resgatou-me,\\nCom Seu sangue, meu Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cada dia, cada hora,\\nSou à graça devedor;\\nNão me lances nunca fora,\\nConfiarei em Teu amor.\\nEis minh'alma vacilante,\\nFaze-a firme em Teu amor;\\nFaz-me justo, bom, constante,\\nPara sempre, ó Senhor!\"}]},{\"number\":\"215\",\"collection_type\":\"Hinário\",\"title\":\"Remido\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Remido, eu vou proclamar,\\nRemido por preço real.\\nRemido por Cristo na morte,\\nEu tenho a paz eternal.\"},{\"section_type\":\"Coro\",\"content\":\"Remido! Remido\\nNo sangue do meu Salvador.\\nRemido pra sempre por Cristo\\nFui salvo por Seu santo amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Remido e feliz, com Jesus\\nEu vivo e posso cantar.\\nNa luz da presença de Cristo,\\nPra sempre eu vou caminhar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pensando no meu Redentor,\\nPensando, vou sempre orar.\\nVivendo, eu quero servi-Lo,\\nE um dia no Céu vou morar.\"}]},{\"number\":\"216\",\"collection_type\":\"Hinário\",\"title\":\"Eu Achei Junto à Cruz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu achei junto à cruz\\nLímpido manancial.\\nLimpo estou, por Jesus,\\nLivre de todo o mal.\"},{\"section_type\":\"Coro\",\"content\":\"Vem, Jesus, meu Senhor,\\nToma-me pela mão.\\nTenho paz, luz e amor,\\nSob Tua proteção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero andar com Jesus,\\nPor onde me levar,\\nPois eu sei, pela luz,\\nMeus passos quer guiar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sinto paz, doce paz,\\nMesmo que sofra a dor.\\nGrato sou, pois Jesus\\nGuarda-me em Seu amor.\"}]},{\"number\":\"217\",\"collection_type\":\"Hinário\",\"title\":\"Ando Sempre Alegre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Perdido eu na escuridão\\nFoi que Jesus me achou,\\nE com a luz do Seu amor\\nAs trevas dissipou.\"},{\"section_type\":\"Coro\",\"content\":\"Eu alegre vou na Sua luz,\\nPois agora Cristo me conduz.\\nDesde que me achou, da morte me livrou.\\nAndo sempre alegre, Cristo me salvou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Andando estou na luz de Deus,\\nQue doce comunhão!\\nProssigo sempre com vigor,\\nDeixando o mundo vão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá, face a face então verei\\nJesus, o Salvador,\\nO qual a Sua vida deu\\nPor mim, vil pecador.\"}]},{\"number\":\"218\",\"collection_type\":\"Hinário\",\"title\":\"A Paz de Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A paz de Deus no coração,\\nConsolo traz em aflição;\\nEm meio às tentações do mal\\nEu sinto um gozo divinal.\"},{\"section_type\":\"Coro\",\"content\":\"A doce paz de meu Jesus,\\nQue já morreu por mim na cruz,\\nPõe-me nos lábios a canção\\nDe Seu amor e salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"A doce voz do amor de Deus\\nA minha vida liga aos Céus;\\nSim, apesar da tentação,\\nEu tenho paz no coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nunca essa paz me vai faltar,\\nem minha alma há de habitar;\\nE quando eu for à pátria além,\\nEu hei de ouvir Sua voz também.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem de Jesus a voz ouvir,\\nEle deseja te remir.\\nCanções suaves lá dos Céus,\\nTu hás de ouvir do amor de Deus.\"}]},{\"number\":\"219\",\"collection_type\":\"Hinário\",\"title\":\"Sempre Alegre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Seja o coração alegre,\\nSempre a transbordar louvor,\\nPois o nosso Pai celeste\\nMostra-nos o Seu amor.\"},{\"section_type\":\"Coro\",\"content\":\"Sempre alegre, sempre alegre\\nÉ o viver do bom cristão;\\nOh! que regozijo pleno\\nBrota-lhe da salvação!\"},{\"section_type\":\"Estrofe\",\"content\":\"Temos proteção nas lutas,\\nDeus nos toma pela mão;\\nSua sempiterna graça\\nDá-nos forças na aflição.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre guiará os justos\\nCom amor, em Sua luz;\\nJuntos serviremos todos\\nAo amado e bom Jesus.\"}]},{\"number\":\"220\",\"collection_type\":\"Hinário\",\"title\":\"É Prazer Servir a Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"É prazer servir a Cristo\\nNesta vida terreal;\\nEnche a vida de louvores,\\nDe alegria divinal!\"},{\"section_type\":\"Coro\",\"content\":\"Há prazer na vida por Jesus,\\nE afasta o coração do mal.\\nCada instante é prazer\\nSob a mão do Seu poder;\\nNo viver com Cristo\\nHá prazer real.\"},{\"section_type\":\"Estrofe\",\"content\":\"É prazer servir a Cristo,\\nSobrepuja toda dor,\\nPois maiores sofrimentos\\nSuportou o Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"É prazer servir a Cristo,\\nAlegria perenal,\\nPois expulsa as trevas d'alma\\nCom a luz celestial.\"}]},{\"number\":\"221\",\"collection_type\":\"Hinário\",\"title\":\"Mui Triste Eu Andava\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mui triste eu andava sem gozo e sem paz,\\nMas eu hoje tenho prazer eficaz.\\nE constantemente bendigo a meu Deus,\\nE é claro o motivo: Já sou de Jesus!\"},{\"section_type\":\"Coro\",\"content\":\"Eu sou de Jesus, aleluia!\\nDe Cristo Jesus, meu Senhor!\\nEu quero falar, eu quero cantar\\nDo amor do meu Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cativo eu vivia nas garras do mal;\\nO mundo atirou-me no abismo fatal.\\nAgora, qual ave voando no céu,\\nSou livre e feliz, pois já cou de Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó alma cansada, por que lamentar?\\nEm Cristo tu achas tesouros sem-par,\\nInfida alegria, poder, salvação.\\nÓ, vem, vem a Cristo sem mais hesitar!\"}]},{\"number\":\"222\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Que Belo Hino Deus me Deu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu canto um hino inspirado\\nPor Jesus, meu Redentor;\\nJamais aqui soou com tal fervor\\nEste canto de amor.\"},{\"section_type\":\"Coro\",\"content\":\"Oh! que belo hino Deus me deu!\\nMe pôs no coração dulcíssima canção!\\nOh! que belo hino Deus me deu!\\nUm hino do divino amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu amo a Cristo que foi morto\\nSobre a cruz pra me salvar;\\nJesus um hino em meus lábios pôs,\\nPara a Deus melhor louvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando estiver eu lá na glória,\\nVendo os anjos a cantar,\\nUm belo hino vou cantar também,\\nLá no meu eterno lar!\"}]},{\"number\":\"223\",\"collection_type\":\"Hinário\",\"title\":\"Jesus Achou-me\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus um dia achou-me\\nMui longe do me lar,\\nPerdido já no mundo,\\nSem mais poder voltar.\\nNos braços Seus tomou-me,\\nPor Seu amor salvou-me,\\nE com dulçor levou-me\\nDe volta para o lar.\"},{\"section_type\":\"Coro\",\"content\":\"A presença de Jesus\\nDá-me paz, prazer e luz.\\nCada dia cresce, mais se enriquece\\nEsta vida com Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Andamos pelos montes\\nPra minha fé provar.\\nTão densas são as trevas!\\nNão posso caminhar!\\nNão há nenhum perigo\\nPois Cristo está comigo,\\nE este grande Amigo\\nConduz-me para o lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Passamos pelos vales,\\nQuão bom é relembrar!\\nDespertam as saudades\\nDo meu paterno lar.\\nOh, quão maravilhoso\\nSentir tão alto gozo:\\nO Amigo tão precioso\\nLevar-me vai ao lar.\"}]},{\"number\":\"224\",\"collection_type\":\"Hinário\",\"title\":\"Satisfeito Estou com Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Satisfeito estou com Cristo;\\nQuanto já não fez por mim!\\nPela fé, na cruz O avisto,\\nPara libertar-me assim.\"},{\"section_type\":\"Coro\",\"content\":\"Satisfeito estou, satisfeito estou,\\nSatisfeito estou com Cristo.\\nA pergunta então me vem,\\nAo pensar na cruz além:\\nTem Jesus, em mim, prazer também?\"},{\"section_type\":\"Estrofe\",\"content\":\"Que alegria eu tenho n'alma\\nAo seguir a meu Jesus!\\nHoje gozo plena calma,\\nTenho o coração em luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao chegar o fim terrestre,\\nE eu puder a Cristo ver,\\nQue alegria ouvir do Mestre:\\n\\\"Tenho em ti também prazer.\\\"\"}]},{\"number\":\"225\",\"collection_type\":\"Hinário\",\"title\":\"Se Tens Amor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quão alegre canta o ser quando tens amor;\\nDe Jesus virá prazer, quando tens amor;\\nTua dor logo se desfaz, uma bênção tu serás,\\nE alegria fruirás, se tens amor.\"},{\"section_type\":\"Coro\",\"content\":\"Se tens amor, se tens amor,\\nQuão alegre canta o ser\\nQuando tens amor;\\nSe tens amor, se tens amor,\\nPaz celeste aos outros levas\\nSe tens amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"A tristeza não persiste se tens amor;\\nFicam leves os teus fardos se tens amor;\\nBrilha intensa e radiante luz, que na senda te conduz;\\nOh, que bênçãos tens a flux, se tens amor!\"}]},{\"number\":\"226\",\"collection_type\":\"Hinário\",\"title\":\"É Manhã no Coração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Toda a escuridão da noite agora é sol:\\nÉ manhã no coração!\\nVivo hoje à luz de um rútilo arrebol:\\nÉ manhã no coração!\"},{\"section_type\":\"Coro\",\"content\":\"É manhã, sim, é manhã no coração!\\nPois Jesus as trevas todas dissipou.\\nDoces hinos cantarei,\\nPois Jesus hoje é meu Rei.\\nÉ manhã, sim, é manhã no coração!\"},{\"section_type\":\"Estrofe\",\"content\":\"Posso ouvir os passarinhos a cantar:\\nÉ manhã no coração!\\nMinha vida é qual um bonançoso mar:\\nÉ manhã no coração!\"},{\"section_type\":\"Estrofe\",\"content\":\"Com Jesus, eu tenho um paraíso em mim:\\nÉ manhã no coração!\\nMeus deveres com amor eu cumpro enfim:\\nÉ manhã no coração!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sou feliz pois encontrei meu Salvador:\\nÉ manhã no coração!\\nE com Ele hei de estar no lar de amor:\\nÉ manhã no coração!\"}]},{\"number\":\"227\",\"collection_type\":\"Hinário\",\"title\":\"Luz Bendita, Luz Gloriosa\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que bendita, que gloriosa luz,\\nA minh'alma vem encher!\\nMais intensa e bela que a do Sol:\\nVeio em mim Jesus viver!\"},{\"section_type\":\"Coro\",\"content\":\"Luz bendita, luz gloriosa\\nConcedida lá dos altos Céus!\\nSó o crente goza esta luz,\\nEsta Luz que vem de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre canta alegre seu louvor\\nQuem possui a luz dos Céus;\\nGoza afável e celeste paz,\\nDom gracioso só de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vida nova em santa retidão\\nTêm os crentes em Jesus.\\nQuem de perto segue o Salvador,\\nDEle tem poder e luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Esperança, vida e salvação\\nHás de ter, ó pecador,\\nAceitando Cristo, nossa luz,\\nEste dom do Deus de amor!\"}]},{\"number\":\"228\",\"collection_type\":\"Hinário\",\"title\":\"Eu Ouço um Cantar Divinal\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu ouço um cantar divinal,\\nUm coro sublime, ideal.\\nOuvi-lo é prazer sem igual:\\nÓ paz! És dom de meu Deus!\"},{\"section_type\":\"Coro\",\"content\":\"Paz, paz, paz, paz,\\nDom precioso dos Céus!\\nExcelsa e dulcíssima paz,\\nÉs dom do amor de meu Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por Cristo nos veio esta paz;\\nÉ bênção que nos satisfaz;\\nInfinda alegria nos traz\\nO excelso dom de meu Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Um dia, no belo porvir,\\nAo lar perenal vou subir,\\nE então hei de sempre fruir\\nA eterna paz de meu Deus.\"}]},{\"number\":\"229\",\"collection_type\":\"Hinário\",\"title\":\"Teu Coração em Paz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vindo sombras escuras nos caminhos teus,\\nOh, jamais desanimes, canta um hino a Deus.\\nCada nuvem escura um arco-íris traz,\\nQuando em teu coração reinar perfeita paz.\"},{\"section_type\":\"Coro\",\"content\":\"Se teu coração estiver em paz,\\nBem contente e alegre sempre te acharás;\\nSe teu coração estiver em paz,\\nVerás que um arco-íris,\\nCada nuvem traz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se o viver é de lutas, cheio de amargor,\\nMostra afeto aos aflitos, age em seu favor,\\nE de tudo o que sofres esquecer-te-ás;\\nFruirás doce calma se tiveres paz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem, após negra noite, a aurora matinal;\\nFica o céu mais brilhante após o temporal.\\nA esperança não percas, pois tu vencerás;\\nFugirão as tristezas, se tiveres paz.\"}]},{\"number\":\"230\",\"collection_type\":\"Hinário\",\"title\":\"Sou Feliz com Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se paz, a mais doce, me deres gozar,\\nSe dor a mais forte sofrer;\\nOh, seja o que for, Tu me fazes saber\\nQue feliz com Jesus hei de estar.\"},{\"section_type\":\"Coro\",\"content\":\"Sou feliz com Jesus!\\nSou feliz com Jesus,\\nMeu Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Embora me assalte o cruel Satanás,\\nE ataque com vis tentações,\\nOh, sim, certo estou, mesmo em tais provações,\\nEm Jesus acharei força e paz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, meu Senhor, ao morrer sobre a cruz\\nLivrou-me da culpa e do mal;\\nSalvou-me Jesus, oh, mercê sem igual!\\nSou feliz, e hoje vivo na luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"A vinda eu anseio do meu Salvador;\\nEm breve virá me buscar;\\nE então lá no Céu vou pra sempre morar,\\nCom remidos, na luz do Senhor.\"}]},{\"number\":\"231\",\"collection_type\":\"Hinário\",\"title\":\"Tenho um Hino em Meu Coração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tenho um hino em meu coração,\\nQue Jesus modula assim:\\n\\\"Ouve, Eu contigo estou na dor,\\nOu no riso até o fim.\\\"\"},{\"section_type\":\"Coro\",\"content\":\"A Jesus eu louvo,\\nPois feliz estou.\\nSigo então cantando\\nQuando aós Seus passos vou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Arruinada a minha vida foi,\\nDissipada em tristes ais,\\nMas Jesus as cordas consertou,\\nDesferiu sons divinais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sou feliz, oh, graça sem igual!\\nMui contente sempre estou,\\nPois Jesus me deu paz perenal;\\nEis porque louvores dou.\"}]},{\"number\":\"232\",\"collection_type\":\"Hinário\",\"title\":\"Cantarei ao Meus Salvador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mais do que tesouros é Cristo, meu bom Mestre;\\nEle é a luz do mundo, a Estrela da manhã.\\nEle é o Rei da glória, e no meu coração\\nContente vou cantando com muita gratidão.\"},{\"section_type\":\"Coro\",\"content\":\"Cantarei ao meu Salvador esta linda melodia,\\nPois eu tenho no coração plena paz e alegria.\\nCantarei ao meu Salvador, cantarei, sim, noite e dia.\\nAleluia! Aleluia! Feliz sempre cantarei!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo lebertou-me da pena do pecado,\\nE agora alegre eu canto, pois para o Céu irei.\\nEle me dá forças, Ele é o meu Protetor;\\nDou sempre glória a Ele, meu Mestre e meu Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Anjos não conhecem a linda melodia,\\nPois só mortais a entoam: os salvos por Jesus.\\nLivre, perdoado por Cristo e Seu amor,\\nMui vitoriosos eu vivo cantando em Seu louvor.\"}]},{\"number\":\"233\",\"collection_type\":\"Hinário\",\"title\":\"Com Cristo no Meu Coração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que mundança gloriosa em mim se operou,\\nCom Cristo no meu coração!\\nMinha alma alcançou luz que muito buscou,\\nCom Cristo no meu coração.\"},{\"section_type\":\"Coro\",\"content\":\"Com Cristo no meu coração,\\nCom Cristo no meu coração,\\nAlegria sem-par vem meu ser inundar,\\nCom Cristo no meu coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já deixei de vaguear pelas sendas do mal,\\nCom Cristo no meu coração;\\nE meus muitos pecados fui logo entregar,\\nCom Cristo no meu coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Té no vale da morte eu avisto uma luz,\\nCom Cristo no meu coração;\\nPois a santa cidade já perto reluz,\\nCom Cristo no meu coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nessa santa cidade pra sempre estarei,\\nCom Cristo no meu coração;\\nLá com grande alegria afinal entrarei,\\nCom Cristo no meu coração.\"}]},{\"number\":\"234\",\"collection_type\":\"Hinário\",\"title\":\"Oh, Dia Feliz!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Feliz o dia em que aceitei\\nDo meu Senhor a salvação.\\nA grande paz que eu alcancei\\nJamais deixou meu coração.\"},{\"section_type\":\"Coro\",\"content\":\"Que prazer eu senti\\nNo dia em que me converti!\\nSeguro estou no Salvador,\\nE tenho paz em Seu amor.\\nSou Feliz, tão feliz,\\nPois em Jesus me satisfiz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Exulta, pois, meu coração,\\nEm meu Jesus, supremo Deus,\\nPorque te deu a redenção,\\nTrazendo a ti perdão dos Céus.\"},{\"section_type\":\"Estrofe\",\"content\":\"O voto que eu então tomei,\\nMinh'alma, sim, o cumprirá.\\nE sem cessar eu renderei\\nLouvor que a Deus exaltará.\"}]},{\"number\":\"235\",\"collection_type\":\"Hinário\",\"title\":\"Hoje Sou Feliz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Perdido foi que Cristo me econtrou\\nNeste mundo vil;\\nSalvou-me, no Seu sangue me lavou.\\nHoje sou feliz!\"},{\"section_type\":\"Coro\",\"content\":\"Hoje sou feliz,\\nFoi-se o meu temor;\\nVou permanecer\\nJunto ao Salvador;\\nFoi-se a escuridão,\\nRaia a luz do Céu,\\nPois eu sei que sou do meu Senhor\\nE Ele é meu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se muitas tentações me sobrevêm,\\nPara Ele vou;\\nRecebo forças que do Céu me vêm\\nSe com Ele estou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se negra noite assustar-me vem,\\nSinto Seu amor.\\nAs trevas tornam-se em luz também,\\nCom meu Salvador!\"}]},{\"number\":\"236\",\"collection_type\":\"Hinário\",\"title\":\"Cantando Vou\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu coração a Cristo dei,\\nBanido é todo o mal;\\nAo pé da cruz eu me prostrei,\\nPois deu-me amor real.\"},{\"section_type\":\"Coro\",\"content\":\"Em meu viver cantando vou:\\nGlória ao Senhor! Glória ao Senhor!\\nEm meu viver cantando vou,\\nPois Cristo meu fardo levou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Perante o trono de meu Rei,\\nFiel promessa ouvi:\\n\\\"Meu forte braço te sustém.\\\"\\nDepus meu fardo ali.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pra sempre então eu viverei\\nCom Cristo, meu Senhor.\\nLouvores sempre cantarei,\\nPor Seu eterno amor!\"}]},{\"number\":\"237\",\"collection_type\":\"Hinário\",\"title\":\"Junto ao Bondoso Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que há perfeita paz\\nJunto ao bondoso Deus.\\nNão há temor nem obras más,\\nJunto ao bondoso Deus.\"},{\"section_type\":\"Coro\",\"content\":\"Jesus, Senhor, meu Mestre,\\nPão que desceu dos Céus,\\nSegura-me bem perto\\nDo coração de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que há conforto e luz\\nJunto ao bondoso Deus.\\nEncontro ali o meu Jesus,\\nJunto ao bondoso Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Encontro, sim, libertação,\\nJunto ao bondoso Deus;\\nE tenho paz e salvação,\\nJunto ao bondoso Deus.\"}]},{\"number\":\"238\",\"collection_type\":\"Hinário\",\"title\":\"Amor nos Faz Contentes\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Amor nos faz contentes,\\nAmor nos dá prazer.\\nE para a lei cumprirmos\\nO amor nos dá poder.\"},{\"section_type\":\"Coro\",\"content\":\"Deus é bom, Seus filhinhos somos.\\nDeus é bom, quer o nosso amor.\\nAmor nos faz contentes,\\nAmor nos dá prazer,\\nE para a lei cumprirmos\\nO amor nos dá poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"O mundo tem tristezas\\nE cheio está de dor.\\nDepressa, pois, busquemos\\nPerdidos ao Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"E quando, enfim, a vida\\nDe lutas se acabar,\\nNo Céu também iremos\\nAo nosso Deus louvar.\"}]},{\"number\":\"239\",\"collection_type\":\"Hinário\",\"title\":\"Exulta, Meu Coração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Exulta, meu coração,\\nNo dom que do Céu desceu,\\nPois Deus nos deu a salvação\\nPor Cristo que morreu!\"},{\"section_type\":\"Coro\",\"content\":\"Cantai! Cantai!\\nA Cristo louvores dai!\"},{\"section_type\":\"Estrofe\",\"content\":\"Do coro angelical,\\nPor terra e pelo Céu,\\nSoou um hino divinal,\\nDe Cristo que venceu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Exulta, meu coração!\\nVencido está o mal.\\nEis, rompe o dia da salvação,\\nE a paz é eternal.\"}]},{\"number\":\"240\",\"collection_type\":\"Hinário\",\"title\":\"Bendita Segurança\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que segurança! Sou de Jesus!\\nEu já desfruto bênçãos da luz!\\nSei que herdeiro sou de meu Deus;\\nEle me leva à glória dos Céus!\"},{\"section_type\":\"Coro\",\"content\":\"Canta, minh'alma! Canta ao Senhor!\\nRende-Lhe sempre honra e louvor!\\nCanta, minh'alma! Canta ao Senhor!\\nRende-Lhe sempre honra e louvor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sendo submisso sempre ao bem,\\nSinto os enlevos puros do além;\\nAnjos, descendo, trazem do alvor\\nEcos da graça, bênçãos do amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Semrpe vivendo em Seu grande amor,\\nMe regozijo em meu Salvador;\\nEsperançoso, vivo na luz;\\nQuanta bondade tem meu Jesus!\"}]},{\"number\":\"241\",\"collection_type\":\"Hinário\",\"title\":\"Cantarei de Jesus Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cantarei de Jesus Cristo,\\nQue na cruz por mim morreu;\\nO desprezo suportando,\\nSalvação me concedeu.\"},{\"section_type\":\"Coro\",\"content\":\"Cantarei que Jesus Cristo\\nCom amor me resgatou!\\nEle sobre a cruz foi morto;\\nMeus pecados perdoou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantarei de Jesus Cristo,\\nSua graça exaltarei;\\nEncontrou-me muito aflito,\\nE descanso nEle achei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantarei de Jesus Cristo,\\nE de como me encontrou,\\nE do mundo e do pecado\\nCom amor, me libertou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantarei no Céu, a Cristo,\\nBendirei Seu grande amor;\\nCom fervor, eternamente,\\nAo meu Rei darei louvor.\"}]},{\"number\":\"242\",\"collection_type\":\"Hinário\",\"title\":\"Ó Minh'Alma, a Deus Bendize\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó minh'alma, a Deus bendize\\nEm humilde adoração;\\nNada há mais que te escravize\\nNo pecado e escuridão!\\nÓ, louvai-O! Ó, louvai-O!\\nEle é o Rei da criação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pelo Seu favor e graça\\nQue outorgou a nossos pais,\\nE por tudo que Ele faça,\\nBendizei-O mais e mais!\\nÓ, louvai-O! Ó, louvai-O!\\nÉ fiel a nós mortais!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando estamos em perigo,\\nNosso Deus nos guardará;\\nEle as trevas e o inimigo\\nPara sempre abaterá!\\nÓ, louvai-O! Ó, louvai-O!\\nPelas bênçãos que Ele dá!\"},{\"section_type\":\"Estrofe\",\"content\":\"Anjos e homens reverentes,\\nAdorai-O com fervor;\\nLuz, estrelas, Sol fulgente\\nQue ao espaço dais fulgor,\\nÓ, louvai-O! Ó, louvai-O!\\nAo eterno Deus de amor!\"}]},{\"number\":\"243\",\"collection_type\":\"Hinário\",\"title\":\"Que Te Darei, Meu Mestre?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que Te darei, me Mestre,\\nMeu Rei e meu Senhor?\\nTenho tão pouco pra Te ofertar\\nMas é com mui grande amor.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo, Senhor bendito,\\nTudo fizeste a mim,\\nTu desceste lá do Céu,\\nDando ao pecado fim;\\nQue Te darei meu Mestre,\\nPor Teu imenso amor?\\nMeu coração e todo o meu ser,\\nTe entregarei, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que Te darei, meu Mestre,\\nPor Teu sublime amor?\\nTodos meus bens e tudo o que sou,\\nDeponho a Teus pés, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que Te darei, meu Mestre,\\nMeu grande Salvador?\\nCom gratidão e com devoção,\\nA Ti renderei louvor.\"}]},{\"number\":\"244\",\"collection_type\":\"Hinário\",\"title\":\"Conta as Bênçãos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se da vida as ondas procelosas são,\\nSe com desalento julgas tudo vão,\\nConta as muitas bênçãos, dize-as duma vez,\\nHás de ver, surpreso, quanto Deus já fez.\"},{\"section_type\":\"Coro\",\"content\":\"Conta as bênçãos, conta quantas são,\\nRecebidas da divina mão;\\nUma a uma, dize-as de uma vez;\\nHás de ver, surpreso, quanto Deus já fez.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tens acaso mágoas, triste é teu lidar?\\nÉ a cruz pesada que tens de levar?\\nConta as muitas bênçãos, não duvidarás,\\nE em canção alegre os dias passarás.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando vires outros com seu ouro e bens,\\nLembra que tesouros prometidos tens;\\nNunca os bens da Terra poderão comprar\\nA mansão celeste em que tu vais morar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Seja teu conflito fraco ou forte aqui,\\nNão te desanimes, cuida Deus de ti;\\nSeu divino auxílio, minorando o mal,\\nDar-te-á consolo sempre, até o final.\"}]},{\"number\":\"245\",\"collection_type\":\"Hinário\",\"title\":\"Gratidão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó Pai que estás no Céu,\\nVenho Te agradecer\\nPor Teu cuidado e amor\\nAo dirigir meu ser.\\nGraças a Ti Senhor.\\nMeus lábio em louvor\\nNão podem expressar\\nQuão grato sou a Ti.\"},{\"section_type\":\"Coro\",\"content\":\"Graças a Ti, Senhor!\\nPor Tua proteção\\nE bênçãos de Tua mão,\\nGraças a Ti, Senhor!\\nGraças a Ti, Senhor.\"}]},{\"number\":\"246\",\"collection_type\":\"Hinário\",\"title\":\"Vinde Vós, Fiéis, Cantar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vinde vós, fiéis, cantar o hino da vitória;\\nDeus dará ao povo Seu a eterna glória.\\nJubilai, Jesusalém, em acentos vivos!\\nAclamai de coração Cristo reditivo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Junto ao Pai no templo já Cristo intercede.\\nPelo que perdido está, Seu favor concede.\\nA justiça, por amor - Oh! excelsa graça!\\nSim, credita ao pecador, sem que nada faça.\"},{\"section_type\":\"Estrofe\",\"content\":\"Crentes, hoje, com fervor, vinde jubilosos,\\nPois em Cristo, certo, sois mais que vitoriosos.\\nGlória ao Filho, glória ao Pai, e ao Espírito Santo!\\nGraças mil, oh, glória dai, em um novo canto.\"}]},{\"number\":\"247\",\"collection_type\":\"Hinário\",\"title\":\"Graças\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Graças dou, sim, pela vida,\\nQue o bom Deus a mim legou;\\nGraças dou por meu futuro,\\nE por tudo o que passou;\\nPelas bênçãos derramadas,\\nPela dor e aflição;\\nPelo Seu cuidade infindo,\\nPela graça do perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Graças pelo azul celeste,\\nE por nuvens que há também;\\nPelas rosas do caminho\\nE os espinhos que elas têm;\\nPela aurora, pela noite,\\nPela estrela que brilhou;\\nPela prece respondida,\\nE a eperança que raiou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pela cruz e o sofrimento,\\nE eternal ressurreição;\\nPelo amor que é sem medida,\\nPela paz no coração;\\nPela lágriam vertida\\nE o consolo que é sem-par;\\nPelo dom da eterna vida,\\nSempre a Deus irei louvar.\"}]},{\"number\":\"248\",\"collection_type\":\"Hinário\",\"title\":\"Desde Que Eu Achei Perdão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu tenho um hino que me apraz cantar,\\nDesde que eu achei perdão;\\nDe Cristo, Amigo e Salvador sem-par,\\nDesde que eu achei perdão.\"},{\"section_type\":\"Coro\",\"content\":\"Desde que eu achei perdão,\\nDesde que eu achei perdão,\\nA Jesus eu louvarei.\\nDesde que eu achei perdão,\\nAo meu bom Jesus exaltarei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu tenho a Cristo que me satisfaz,\\nDesde que eu achei perdão;\\nCumprindo o Seu querer eu tenho paz,\\nDesde que eu achei perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu tenho alegria que é sem dim,\\nDesde que eu achei perdão;\\nPois Cristo o sangue derramou por mim,\\nDesde que eu achei perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu tenho lá no Céu um lindo lar,\\nDesde que eu achei perdão;\\nNo qual eternamente irei morar,\\nDesde que eu achei perdão.\"}]},{\"number\":\"249\",\"collection_type\":\"Hinário\",\"title\":\"Como Agradecer\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Como agradecer a Jesus o que fez por mim?\\nSem eu merecer vem provar o Seu amor sem fim.\\nAs vozes de um milhão de anjos não poderiam expressar\\nA gratidão que vibra em meu ser, por tudo devo a Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Deus seja a glória, a Deus seja a glória,\\nA Deus seja a glória, pelo que fez por mim!\\nCom Seu sangue lavou-me, Seu poder transformou-me,\\nA Deus seja a glória pelo que fez por mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero entregar, Senhor, a minha vida em Tuas mãos\\nE quero dar meu louvor pela Tua eterna salvação.\\nCom Seu sangue lavou-me, Seu poder transformou-me,\\nA Deus seja a glória pelo que fez por mim!\"}]},{\"number\":\"250\",\"collection_type\":\"Hinário\",\"title\":\"Cantarei de Meu Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cantarei de meu Jesus,\\nSeu amor leal, sem fim,\\nPois desceu dos altos Céus,\\nE na cruz morreu por mim.\"},{\"section_type\":\"Coro\",\"content\":\"Cantarei do meu Salvador,\\nSem cessar Lhe darei louvor,\\nPois morreu pra me salvar.\\nCantarei do Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Antes de eu poder chorar,\\nCristo já por mim pranteou.\\nAntes de eu poder orar,\\nNa angústia Ele orou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nada fiz por meu Senhor,\\nComo, pois, me pôde amar?\\nQuero, assim, em gratidão\\nMinha vida Lhe entregar.\"}]},{\"number\":\"251\",\"collection_type\":\"Hinário\",\"title\":\"Tem Fé em Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tem fé em Deus se a treva oculta o Sol;\\nTem fé em Deus se o dia está a findar.\\nTem fé em Deus, à noite ou no arrebol;\\nTem fé, amigo, em Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tem fé em Deus se o sonho se desfaz;\\nTem fé em Deus, não podes andar só.\\nTem fé em Deus, e busca dEle a paz;\\nTem fé, amigo, em Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tem fé em Deus se calma a vida vai;\\nTem fé em Deus se treme o coração.\\nTem fé em Deus que é teu bondoso Pai;\\nTem fé, amigo, em Deus.\"}]},{\"number\":\"252\",\"collection_type\":\"Hinário\",\"title\":\"Nunca Desanimes\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nunca, nunca desanimes\\nSe ao redor as trevas vêm!\\nUma estrela irá guiando;\\nCrê em Deus e faze o bem.\\nSe o caminho é penoso,\\nE seu fim é dor também,\\nBusca nEle luz e gozo,\\nCrê em Deus, crê em Deus,\\nCrê em Deus e faze o bem.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vês os ímpios desfrutando\\nDe mercês que não convêm?\\nQuer perdendo, quer ganhando,\\nCrê em Deus e faze o bem.\\nOs prazeres do pecado\\nMorte são e dor contêm.\\nDeixa o munod e o passado,\\nCrê em Deus, crê em Deus,\\nCrê em Deus e faze o bem.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nos momentos de tristeza\\nJunto a ti está Alguém.\\nQuer amar-te e dar consolo;\\nCrê em Deus e faze o bem.\\nE se queres ter entrada\\nLá no Céu, no lar de além,\\nVai com Cristo pela estrada;\\nCrê em Deus, crê em Deus,\\nCrê em Deus e faze o bem.\"}]},{\"number\":\"253\",\"collection_type\":\"Hinário\",\"title\":\"Minha Esperança\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em nada ponho minha fé\\nSenão na graça de Jesus,\\nNo sacrifício remidor,\\nNo sangue do bom Redentor.\"},{\"section_type\":\"Coro\",\"content\":\"A minha fé e o meu amor\\nEstão firmados no Senhor;\\nEstão firmados no Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se não Lhe posso a face ver,\\nEu mesmo assim não vou temer;\\nEm cada transe a suportar,\\nVou sempre nEle confiar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O Seu amor é mui leal,\\nAbriga-me no temporal;\\nAo vir cercar-me a tentação,\\nÉ Cristo minha salvação.\"}]},{\"number\":\"254\",\"collection_type\":\"Hinário\",\"title\":\"Não Consentir!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, não consintas tristezas\\nDentro do teu coração!\\nSempre confia em teu Mestre,\\nSegue-O sem hesitação!\"},{\"section_type\":\"Coro\",\"content\":\"Não consentir! Não consentir\\nQue qualquer dor ou tristeza\\nVenha apagar teu amor!\\nOh, não temer! Nunca ceder!\\nLembra-te sempre que Cristo\\nÉ teu fiel Protetor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se por acaso desgostos\\nVenham trazer-te temor,\\nNunca te esqueças de Cristo,\\nTeu divinal Protetor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deixa, pois, tua tristeza,\\nToda incerteza e o temor;\\nPaz e prazer para sempre\\nHás de fruir no Senhor.\"}]},{\"number\":\"255\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Eu Não Sei, Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! eu não sei, Senhor, porque Tu quererás\\nQue tanto eu sofra aqui pesares e aflição.\\nOh! eu não sei, Senhor, porque Tu quererás\\nQue eu sofra perdas se outra foi minha oração!\"},{\"section_type\":\"Coro\",\"content\":\"Mas isto eu sei: nunca eu Te deixarei,\\nTu sabes, Pai, melhor, na provação maior;\\nE sei também: se eu confiar em Ti,\\nBreve as trevas passam e oh! quão claro aqui!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! eu não sei, Senhor, porque Tu quererás,\\nQue eu ande neste vale escuro e tão hostil!\\nOh! eu não sei, Senhor, porque Tu quererás\\nQue venham nuvens negras no meu céu de anil!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! eu não sei, Senhor, porque Tu quererás\\nQue venham sobre mim tão duras tentações!\\nOh! eu não sei, Senhor, porque Tu quererás\\nQue eu sofra assim, na vida, amargas provações!\"}]},{\"number\":\"256\",\"collection_type\":\"Hinário\",\"title\":\"Ó Salvador, Creio em Ti\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mestre divino, Jesus, meu Senhor,\\nEu creio em Ti, sim, creio em Ti.\\nForça recebo, sustento e vigor;\\nÓ Salvador, creio em Ti.\"},{\"section_type\":\"Coro\",\"content\":\"Creio, creio,\\nCristo Jesus, creio em Ti!\\nGraça me dás, alegria e vigor;\\nÓ Salvador, creio em Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando me cercam as ondas do mar,\\nEu creio em Ti, sim, creio em Ti.\\nTenho prazer, alegria sem-par;\\nÓ Salvador, creio em Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Inda que as trevas encubram o céu,\\nEu creio em Ti, sim, creio em Ti.\\nFaz-me obediente, constante e fiel;\\nÓ Salvador, creio em Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo Jesus, meu Amigo leal,\\nEu creio em Ti, sim, creio em Ti.\\nÉs meu refúgio, defesa real;\\nÓ Salvador, creio em Ti.\"}]},{\"number\":\"257\",\"collection_type\":\"Hinário\",\"title\":\"Ó Minha'Alma, Espera\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó minh'alma, espera no teu Senhor!\\nTudo a Ele entrega, sem nenhum temor.\\nSempre avançar, não desanimar!\\nVem após as trevas lúcido alvorar.\\nNas tempestades ou grande dor,\\nHá de estar bem perto teu Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó minh'alma, espera no teu Senhor!\\nTudo a Ele entrega, sem nenhum temor.\\nSe o munod vil se mostrar hostil,\\nEis que tens ao lado Chefe varonil.\\nÓ Cristo eterno, meu Salvador,\\nSalva-me, sim, slava do tentador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó minh'alma, espera no teu Senhor!\\nTudo a Ele entrega, sem nenhum temor,\\nBem cedo ao lar vamos aportar,\\nOnde lutas, penas, tudo vai cessar.\\nAo fim das dores ou padecer,\\nVamos ter na vida prazer.\"}]},{\"number\":\"258\",\"collection_type\":\"Hinário\",\"title\":\"Fé dos Nossos Pais\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, como pulsa o coração,\\nQuando nos lembra a antiga fé\\nQue revelaram nossos pais,\\nAnte a dor e a morte até!\"},{\"section_type\":\"Coro\",\"content\":\"Bendita fé dos nossos pais,\\nInspira nossos ideais!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mesmo em prisões os nossos pais,\\nFirmes morriam sem pesar;\\nMerecem nossa imitação:\\nAntes morrer do que pecar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bendita fé dos nossos pais,\\nPossamos nós te ser fiéis;\\nSempre honrar e proclamar\\nCom devoção os teus lauréis.\"}]},{\"number\":\"259\",\"collection_type\":\"Hinário\",\"title\":\"Eu Sei em Quem Tenho Crido\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não sei porque de Deus o amor\\nA mim se revelou,\\nPor qual razão o Salvador\\nPra Si me resgatou.\"},{\"section_type\":\"Coro\",\"content\":\"Mas eu sei em quem tenho crido,\\nE estou bem certo que é poderoso,\\nPra guardar o meu tesouro\\nAté o fim chegar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não sei o que de mal ou bem\\nAqui enfrentarei;\\nSe maus ou áureos dias vêm,\\nSe lutas eu terei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não sei também o dia em que\\nVerei Jesus voltar;\\nSe de manhã, se à tarde vem\\nPra me levar ao lar.\"}]},{\"number\":\"260\",\"collection_type\":\"Hinário\",\"title\":\"Jesus Contemplará a Fé\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus promete grandes coisas conceder\\nA qualquer que peça, crendo que há de obter,\\nEsperando, sem jamais esmorecer;\\nCristo sua fé contemplará.\"},{\"section_type\":\"Coro\",\"content\":\"Sim, Jesus contemplará a fé,\\nPois o que Jesus promete, dá.\\nEle vê o coração e responde a petição;\\nCristo sua fé contemplará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus tem prometido a quem não duvidar,\\nDar-lhe as bênçãos que a Ele suplicar;\\nEle prometeu e não irá falhar.\\nCristo sua fé contemplará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus já grandes maravilhas operou\\nPor aquele que no Seu amor confiou;\\nNunca olvidou a quem a fé guardou.\\nCristo sua fé contemplará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, creiamos no que Deus nos prometeu,\\nPois desonra nunca trouxe ao nome Seu;\\nEle cumprirá promessas que nos deu;\\nCristo nossa fé contemplará.\"}]},{\"number\":\"261\",\"collection_type\":\"Hinário\",\"title\":\"Fé é a Vitória\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Soldados de Jesus Senhor, cristãos, ó, despertai!\\nDa noite já as trevas vêm, depressa batalhai!\\nE contra os inimigos vis saí a combater!\\nA nossa fé vitória é, ao mundo irá vencer.\"},{\"section_type\":\"Coro\",\"content\":\"Fé é a vitória,\\nSim, fé sempre tem poder.\\nFé é a vitória:\\nAo munod irá vencer\"},{\"section_type\":\"Estrofe\",\"content\":\"Sob a bandeira que pra nós é o santo amor de Deus,\\nTrilhemos o caminho aqui, que leva para os Céus.\\nOs santos crentes, pela fé, venceram Satanás.\\nA nossa fé vitória é, e a todos traz a paz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aquele que viver na fé, justiça alcançará;\\nUm nome novo há de ter, perdão receberá.\\nAssim, bem firmes, pela fé, unidos em amor,\\nNós venceremos com poder que vem do Salvador.\"}]},{\"number\":\"262\",\"collection_type\":\"Hinário\",\"title\":\"Minha Fé Bem Segura Está\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem segura está tua fé, irmão,\\nMesmo quando em tempos de aflição?\\nHá de a nau ficar firme a navegar,\\nOu, sem leme, a esmo, flutuar?\"},{\"section_type\":\"Coro\",\"content\":\"Sim, minha fé bem segura está;\\nFirme em Jesus continuará;\\nConfiado em Cristo, em Seu amor,\\nHei de triunfar sobre o tentador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mesmo ao sobrevir grande temporal,\\nMinha nau não sofre nenhum mal;\\nEla bem segura navegará,\\nPois que Cristo, o Mestre, ao leme está.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando a morte, enfim, me vier chamar,\\nNoite irá descer por sobre o mar;\\nMesmo assim, com fé, não terei temor:\\nEstará comigo o Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já vislumbro a paz desse porto além,\\nA celestial Jerusalém!\\nLá irei morar com o meu Jesus,\\nPara sempre estar à Sua luz.\"}]},{\"number\":\"263\",\"collection_type\":\"Hinário\",\"title\":\"Deus é Sabedor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que Deus é sabedor\\nDo meu sofrer, da minha dor,\\nMas sei também que o meu penar\\nEm gozo pode transformar;\\nEm gozo pode transformar.\"},{\"section_type\":\"Coro\",\"content\":\"Meu Deus, meu Pai,\\nTu és de tudo sabedor,\\nSim, Deus, meu Pai,\\nVem minorar a minha dor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que Deus é sabedor\\nQue fui um grande pecador,\\nMas com poder e compaixão\\nLivrou-me da destruição;\\nLivrou-me da destruição.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que Deus é sabedor\\nDas minhas faltas, meu temor,\\nMas pronto está pra me valer,\\nDe todo o mal me proteger;\\nDe todo o mal me proteger.\"}]},{\"number\":\"264\",\"collection_type\":\"Hinário\",\"title\":\"Um Dia Ele Esclarecerá\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não sei por que ao meu redor\\nEu vejo tanto dissabor;\\nNão posso ver porque há dor,\\nMas um dia eu saberei.\"},{\"section_type\":\"Coro\",\"content\":\"Um dia o Salvador virá;\\nUm dia Ele esclarecerá;\\nEntão da dor me livrará;\\nUm dia hei de compreender.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não posso o amor aprofundar\\nQue o Pai levou Seu Filho a dar,\\nPara na cruz me regatar,\\nMas um dia eu saberei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não sei por que, em luta e dor,\\nEu, sendo um pobre pecador,\\nJesus me ampara com amor,\\nMas um dia eu saberei.\"}]},{\"number\":\"265\",\"collection_type\":\"Hinário\",\"title\":\"Deus é Sabedor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que Deus é sabedor\\nDo meu sofrer, da minha dor,\\nMas sei também que o meu penar\\nEm gozo pode transformar;\\nEm gozo pode transformar.\"},{\"section_type\":\"Coro\",\"content\":\"Meu Deus, meu Pai,\\nTu és de tudo sabedor,\\nSim, Deus, meu Pai,\\nVem minorar a minha dor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que Deus é sabedor\\nQue fui um grande pecador,\\nMas com poder e compaixão\\nLivrou-me da destruição;\\nLivrou-me da destruição.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que Deus é sabedor\\nDas minhas faltas, meu temor,\\nMas pronto está pra me valer,\\nDe todo o mal me proteger;\\nDe todo o mal me proteger.\"}]},{\"number\":\"266\",\"collection_type\":\"Hinário\",\"title\":\"Conformação\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Prova severa e mui real\\nSofres, em aflição,\\nMas podes ter conforto e paz\\nNa conformação.\"},{\"section_type\":\"Coro\",\"content\":\"Conformação,\\nEis o caminho bom;\\nBusca, pois, este excelso dom,\\nA conformação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando tentado para o mal,\\nRecorre à oração;\\nVais ter vitória no final,\\nNa conformação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vai tudo mal ao teu redor,\\nÉ tudo turbação?\\nVais ter mais força e mais vigor\\nNa conformação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando ofendido por alguém,\\nNão negues teu perdão;\\nOra a Jesus e busca o bem\\nNa conformação.\"}]},{\"number\":\"267\",\"collection_type\":\"Hinário\",\"title\":\"Aprendi o Bom Segredo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Aprendi o bom segredo de confiar em meu Jesus;\\nEncontrei descanso e força, recebendo Sua luz.\\nEu bebi da fonte pura, e provei do Seu amor;\\nEle é, pois, a minha força, meu escudo protetor.\"},{\"section_type\":\"Coro\",\"content\":\"Permaneço em meu Senhor,\\nMeu Amigo e Salvador;\\nE me escondo, sim, me escondo\\nEm Seus braços, Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já estou crucificado, Cristo vive agora em mim;\\nJá cessaram minhas lutas, glória a Cristo, glória, sim!\\nMinha vida e meu futuro entreguei a meu Jesus;\\nO Seu sangue precioso me preserva em Sua luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pra falar prudentemente, para agir em Seu poder,\\nPara andar no bom caminho, Ele deve em mim viver;\\nEle é sempre meu amparo, fonte eterna de prazer;\\nGuarda, salva e santifica, e na luta faz vencer.\"}]},{\"number\":\"268\",\"collection_type\":\"Hinário\",\"title\":\"Aprendi o Bom Segredo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Aprendi o bom segredo de confiar em meu Jesus;\\nEncontrei descanso e força, recebendo Sua luz.\\nEu bebi da fonte pura, e provei do Seu amor;\\nEle é, pois, a minha força, meu escudo protetor.\"},{\"section_type\":\"Coro\",\"content\":\"Permaneço em meu Senhor,\\nMeu Amigo e Salvador;\\nE me escondo, sim, me escondo\\nEm Seus braços, Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já estou crucificado, Cristo vive agora em mim;\\nJá cessaram minhas lutas, glória a Cristo, glória, sim!\\nMinha vida e meu futuro entreguei a meu Jesus;\\nO Seu sangue precioso me preserva em Sua luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pra falar prudentemente, para agir em Seu poder,\\nPara andar no bom caminho, Ele deve em mim viver;\\nEle é sempre meu amparo, fonte eterna de prazer;\\nGuarda, salva e santifica, e na luta faz vencer.\"}]},{\"number\":\"269\",\"collection_type\":\"Hinário\",\"title\":\"Eu Sei Que Vive o Redentor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu sei que vive o Redentor,\\nPois Ele a morte já venceu.\\nAo Céu subiu o Salvador,\\nE Seu perdão me concedeu.\"},{\"section_type\":\"Coro\",\"content\":\"O mundo há de perecer,\\nJamais aqui me vai deter;\\nEm breve ao Mestre seguirei\\nAo lar, à casa paternal.\\nEm breve ao Mestre seguirei\\nAo lar, à casa paternal.\"},{\"section_type\":\"Estrofe\",\"content\":\"A fé deponho em meu Senhor,\\nOs meus pecados perdoou.\\nPor mim sofreu desprezo e dor,\\nE por Seu sangue me salvou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus em breve voltará,\\nA fim de o povo Seu buscar.\\nAo lar eterno os levará,\\nE ali pra sempre irão morar.\"}]},{\"number\":\"270\",\"collection_type\":\"Hinário\",\"title\":\"A Fé em Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A fé em Deus contém poder\\nQue faz tombar muralha.\\nÉ força que nos faz vencer\\nDo mal a atroz batalha.\"},{\"section_type\":\"Estrofe\",\"content\":\"A fé em Deus já fez heróis\\nEm tempos maus da história.\\nBrilharam, sim, e como sóis\\nSerão na eterna glória.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vivendo, assim, com fé em Deus,\\nIremos ver a alva.\\nTenhamos fé nos braços Seus,\\nPois só Jesus nos salva.\"}]},{\"number\":\"271\",\"collection_type\":\"Hinário\",\"title\":\"Que Prazer é Ser de Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que prazer é ser de Cristo,\\nNEle crer e confiar,\\nAceitar os Seus ensinos,\\nSua paz e amor gozar!\"},{\"section_type\":\"Coro\",\"content\":\"Cristo! Cristo! Já confio\\nEm Teu nome, em Teu poder.\\nCristo! Cristo! bem-amado,\\nFaze em mim a fé crescer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, que bênção crer em Cristo,\\nCrer no sangue que verteu!\\nPois os meus pecados todos\\nSepultou e os esqueceu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, quão bom é crer em Cristo,\\nTer certeza do perdão!\\nReceber de Cristo mesmo,\\nVida, paz e salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, feliz eu sou em Cristo,\\nDEle aqui desejo ser;\\nQuero, pois, humildemente,\\nAo Senhor obedecer.\"}]},{\"number\":\"272\",\"collection_type\":\"Hinário\",\"title\":\"Olha com Fé Para Cima\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando te vêm tristezas,\\nDores ao coração,\\nOlha com fé pra cima,\\nDeus dá consolação!\"},{\"section_type\":\"Coro\",\"content\":\"Sempre! Sempre!\\nOlha com fé para cima,\\nOnde Jesus resplandece a luz!\\nOlha com fé para cima!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando os amigos fogem,\\nQuando te encontras só,\\nOlha com fé pra cima,\\nCristo de ti tem dó.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tens uma dor secreta\\nQue ninguém pode cer?\\nOlha com fé pra cima,\\nAlívio hás de ter.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não andes cabisbaixo,\\nPra mais te entristecer;\\nOlha com fé pra cima,\\nProcura a Cristo ver.\"}]},{\"number\":\"273\",\"collection_type\":\"Hinário\",\"title\":\"Confia em Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A vida tem tristezas mil;\\nNem tudo é um céu de anil,\\nMas contra a dor, que é tão sutil,\\nHá um caminho só:\"},{\"section_type\":\"Coro\",\"content\":\"Confia em Deus, que Ele sempre te ouvirá.\\nConfia em Deus, que Ele nunca falhará.\\nConfia em Deus, que a negra nuvem passará.\\nOh, não duvides, mas confia em Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando teu céu escurecer\\nE a sós penares teu sofrer,\\nSe queres forças receber,\\nHá um caminho só:\"},{\"section_type\":\"Estrofe\",\"content\":\"Se tua fé provada for\\nE te esqueceres do Senhor,\\nNecessitando um Salvador,\\nHá um caminho só:\"}]},{\"number\":\"274\",\"collection_type\":\"Hinário\",\"title\":\"Firme nas Promessas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Firme nas promessas de Jesus, Senhor,\\nVou cantar louvores ao meu bom Pastor;\\nSempre exaltarei o Seu eterno amor,\\nFirme nas promessas de Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Firme, firme,\\nFirme nas promessas de Jesus, meu Mestre;\\nFirme, firme,\\nSim, firme nas promessas de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Firme nas promessas, não irei falhar\\nVindo as tempestades neste meu lidar.\\nPelo Verbo eterno sempre irei lutar,\\nFirme nas promessas de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Firme nas promessas do Senhor Jesus,\\nEm amor ligado com a Sua cruz;\\nCada dia mais me alegro nesta luz,\\nFirme nas promessas de Jesus.\"}]},{\"number\":\"275\",\"collection_type\":\"Hinário\",\"title\":\"Qual Firme Cedro\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Qual firme cedro é minha fé, refúgio em temporal;\\nQual arma mui potente é, espada contra o mal.\\nAvante vou sem mais temor,\\nMeus olhos tenho em meu Senhor.\\nEm cada luta quero ser soldado de valor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os passos dos heróis da fé me ajudam ser leal.\\nTrilharam por caminhos bons ou rude pedregal.\\nQue tal exemplo eu siga, sim,\\nPor Deus lutar, gastar-me, enfim.\\nEu quero minha vida pôr nas mãos do Criador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Qual firme cedro é minha fé; abrigo me dará.\\nQual sabre agudo em forte mão, assim não falhará.\\nDo Teu Espírito dá-me, ó Deus,\\nE faz-me andar nos passos Teus.\\nDe amor preenche os dias meus até subir aos Céus.\"}]},{\"number\":\"276\",\"collection_type\":\"Hinário\",\"title\":\"Prece Vespertina\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se acaso eu hoje fui espinho a alguém,\\nOu se deixei de praticar o bem;\\nSe ao mau caminho eu atentei também,\\nPerdão, Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se o meu falar pretensioso e vão,\\nOu se ao faminto recusei o pão,\\nTemendo que ele me faltasse, então,\\nPerdão, Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Perdoa as faltas contra a Tua lei!\\nAs que conheço e as de que não sei.\\nPor Tua graça eu fiel serei,\\nSenhor. Amém!\"}]},{\"number\":\"277\",\"collection_type\":\"Hinário\",\"title\":\"Jesus, Eu Venho a Ti\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus, Senhor eu venho a Ti,\\nÓ, dá-me alívio mesmo aqui,\\nO Teu favor estende a mim;\\nAceita um pecador!\"},{\"section_type\":\"Coro\",\"content\":\"Eu venho como estou;\\nBem sei, indigno sou,\\nMas meu Jesus por mim morreu;\\nEu venho como estou.\"},{\"section_type\":\"Estrofe\",\"content\":\"As minhas culpas grandes são,\\nMas, Tu, que não morreste em vão,\\nMe podes conceder perdão;\\nAceita um pecador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu nada posso merecer,\\nTu vês-me prestes a morrer;\\nJesus, a Ti me vou render;\\nAceita um pecador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem agora, Salvador,\\nSomente Tu és meu Senhor!\\nÓ, salva-me por Teu amor;\\nAceita um pecador!\"}]},{\"number\":\"278\",\"collection_type\":\"Hinário\",\"title\":\"Tal Qual Estou\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tal qual estou, eu venho a Ti,\\nAceita-me, o Salvador!\\nConfiante sou em Teu amor;\\nÓ Salvador, me achego a Ti!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tal qual estou, eu venho a Ti,\\nPerdão me podes conceder,\\nE minhas faltas esquecer;\\nÓ Salvador, me achego a Ti!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tal qual estou, eu venho a Ti,\\nE Tu minhálma limparás,\\nCom Teu amor me envolverás;\\nO Salvador, me achego a Ti.\"}]},{\"number\":\"279\",\"collection_type\":\"Hinário\",\"title\":\"Viver por Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Viver por Cristo a vida veraz;\\nServi-Lo em amor no mundo falaz;\\nFiel ao que ordena a voz do dever,\\nEis o caminho de um puro viver.\"},{\"section_type\":\"Coro\",\"content\":\"Meu Salvador bendito,\\nA Ti me entrego enfim.\\nFizeste o sacrifício\\nNa cruz, por nós, por mim.\\nSó Tu és meu Senhor;\\nDou-Te meu coração.\\nEm mim vive, ó Jesus, então;\\nE eu viverei em Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Viver por Cristo que Se deu por mim,\\nSofrendo na cruz angústia sem fim;\\nÓ amor me impele a Cristo atender,\\nSeguir-Lhe os passos com real prazer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Viver por Cristo onde eu estiver,\\nFazendo em Seu nome o que for mister;\\nE pronto a sofrer agrura e pesar,\\nA cruz levando e sem murmurar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Viver por Cristo, o meu Salvador;\\nAndar sempre à luz do Seu grande amor,\\nLevar aos perdidos a salvação,\\nCumprindo alegre a Sua missão.\"}]},{\"number\":\"280\",\"collection_type\":\"Hinário\",\"title\":\"O Mestre nos Chama\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Mestre nos chama, devemos segui-Lo;\\nSeus passos seguros nos dão direção.\\nNos vales, nos montes, por sendas difíceis,\\nJesus, nosso Guia, é luz, proteção.\\nO Mestre nos chama, urgente conclama;\\nPerdidos esperam as novas de amor.\\nCom fé prossigamos, cristãos verdadeiros,\\nFalemos a todos de Deus, o Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"O Mestre nos chama, devemos ouvi-Lo;\\nÉ tempo de lutas e tribulação.\\nCom fé e coragem, guardados estamos;\\nO Espírito Santo traz consolação.\\nO Mestre nos chama, urgente conclama;\\nSegui-Lo devemos em todo o viver.\\nFelizes estamos, alegres levando\\nMensagem de graça de paz e poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"O Mestre nos chama; enquanto inda é dia,\\nSaíamos à luta com todo o vigor.\\nDeixemos o mundo, prazeres, enganos,\\nSirvamos a Cristo, o nosso Senhor.\\nMestre nos chama, urgente conclama;\\nO tempo mui breve ao fim chegará.\\nJesus breve volta, com anjos em glória,\\nE a todos Seus filhos ao Céu levará.\"}]},{\"number\":\"281\",\"collection_type\":\"Hinário\",\"title\":\"Eu Venho a Ti, Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Triste e sombrio foi meu viver\\nLonge de mim, meu Salvador.\\nPaz e perdão de Ti venho obter,\\nJunto de Ti, Senhor.\\nFoi grande a luta da provação,\\nTenho sofrido muita aflição.\\nPra confortar o meu coração,\\nEu venho a Ti, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minhas vaidades atirarei\\nLonge de mi, ó Salvador;\\nPois Teu querer será minha lei;\\nServir-Te-ei, Senhor.\\nTeu grande amor desejo provar,\\nE Tua graça manifestar;\\nJunto de Ti desejo ficar;\\nEu venho a Ti, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Medo da morte nunca terei,\\nPerto de mim sempre estarás;\\nPois ao Teu lar um dia eu irei,\\nTu me receberás.\\nJunto de Ti desejo viver,\\nJunto de Ti eu vou combater;\\nJunto de Ti, vencer ou morrer;\\nEu venho a Ti, Senhor.\"}]},{\"number\":\"282\",\"collection_type\":\"Hinário\",\"title\":\"Tempo de Ser Santo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tempo de ser santo tu deves tomar;\\nTer vida em teu Mestre, Seu livro estudar;\\nSer junto a Seu povo luz sempre a brilhar,\\nE aos necessitados ir para salvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tempo de ser puro tu deves achar;\\nSempre a sós orando, com Cristo ficar;\\nTeus olhos bem fitos ter no Salvador;\\nPor tua conduta dar provas de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tempo de ser forte tu deves buscar;\\nO Mestre seguindo por onde guiar;\\nEm gozo ou tristeza sempre obedecer;\\nDa Fonte divina, sim, nunca esquecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tempo de ser útil tu deves guardar;\\nMui calmo nas lutas, em Deus confiar;\\nTer para os aflitos voz e atos de amor;\\nSim, mais semelhante ser ao Salvador.\"}]},{\"number\":\"283\",\"collection_type\":\"Hinário\",\"title\":\"No Querer de Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O meu querer a Ti, Senhor, entrego,\\nE para sempre Teu eu quero ser;\\nMeus lábios hoje fazem esta prece:\\nQue em mim se cumpra o Teu querer.\"},{\"section_type\":\"Coro\",\"content\":\"Do Teu querer, conserva-me bem perto,\\nAté que eu tenha Teu poder.\\nDo Teu querer conserva-me bem perto,\\nAté que eu possa, em Ti, viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cansado já, mui triste e tão ferido,\\nAndei nas trevas, longe do Senhor,\\nMas hoje sinto a glória em minh'alma\\nPois encontrei meu Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem junto a Ti segura-me, bom Mestre,\\nE nunca, nunca mais irei falhar,\\nPois se presente tenho Tua graça,\\nSempre na luz eu hei de andar.\"}]},{\"number\":\"284\",\"collection_type\":\"Hinário\",\"title\":\"Tudo por Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Teu, ó Senhor bendito,\\nsempre desejo ser.\\nLivre do mundo iníquo,\\nQuero também viver\"},{\"section_type\":\"Coro\",\"content\":\"Quero viver por Cristo,\\nTudo Lhe dedicar;\\nTudo por Cristo, tudo, tudo\\nQuero renunciar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero servir a Cristo,\\nSempre ao seu lado estar;\\nÚtil na paz, na luta,\\nPor Ele trabalhar\"},{\"section_type\":\"Estrofe\",\"content\":\"Queres, pois, aceitar-me\\nTal como sou, Senhor?\\nVenho entregar-me agora\\nÉs o meu Redentor.\"}]},{\"number\":\"285\",\"collection_type\":\"Hinário\",\"title\":\"Pertenço a Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Já o mundo não me prende,\\nEu pertenço a Cristo!\\nSua voz minh'alma atende,\\nPois pertenço a Cristo.\"},{\"section_type\":\"Coro\",\"content\":\"A Jesus eu seguirei,\\nPois é meu Senhor e Rei;\\nQuer lá fora, quer no lar,\\nEu pertenço a Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não mais temo o inimigo,\\nEu pertenço sou de Cristo!\\nÉ-me sempre bom abrigo,\\nSim, pertenço a Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Desde a Terra até a glória,\\nEu pertenço a Cristo!\\nSempre irei contar a história:\\nEu pertenço a Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá no céu vou contemplá-lo,\\nEu pertenço a Cristo!\\nE eternamente honrá-lo,\\nPois pertenço a Cristo.\"}]},{\"number\":\"286\",\"collection_type\":\"Hinário\",\"title\":\"Pai, Eu me Achego a Ti\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, eu me achego a Ti,\\nPois Tua voz ouvi;\\nTeu grande amor senti,\\nÓ meu Senhor!\\nNão poderei viver,\\nSó, sem o Teu poder.\\nVem inundar meu ser\\nCom Teu amor!\"},{\"section_type\":\"Coro\",\"content\":\"Pai, eu me achego a Ti,\\nSou pecador;\\nQue me conforte aqui\\nTeu santo amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pai, quão distante andei,\\nSó, quebrantando a lei,\\nSem Tua luz, bem sei,\\nSem salvação.\\nSou pecador e vil,\\nSim, com defeitos mil.\\nÓ dá-me em Teu redil\\nPaz e perdão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Teu quero ser, Senhor,\\nSer luz por onde for,\\nQue eu tenha mais fervor,\\nMais mansidão.\\nEm minha vida, ó Deus,\\nPões os caminhos Teus.\\nVem, vem guiar-me aos céus\\nCom tua mão!\"}]},{\"number\":\"287\",\"collection_type\":\"Hinário\",\"title\":\"Minha Entrega\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo, bom Mestre, eis meu querer:\\nTua vontade sempre cumprir;\\nFaze-me forte para vencer\\nDuras fraquezas que possam vir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo, bom Mestre, eis meu querer:\\nMais santidade sempre buscar;\\nFaze-me firme, dá-me poder\\nPara a verdade nunca deixar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo, bom Mestre, eis meu querer:\\nTodas as minhas faltas vencer;\\nFaze-me rijo para lutar,\\nPara a vitória sempre ganhar.\"}]},{\"number\":\"288\",\"collection_type\":\"Hinário\",\"title\":\"Ser Igual a Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, ensina-me a viver;\\nDiz-me como devo andar;\\nComo receber poder,\\nPara ser qual Cristo.\"},{\"section_type\":\"Coro\",\"content\":\"Ser igual a Cristo!\\nSer igual a Cristo!\\nDiz-me como devo andar\\nPara ser igual a Cristo\"},{\"section_type\":\"Estrofe\",\"content\":\"Diz qual seja meu dever,\\nAo servir-te aqui, Senhor;\\nComo devo proceder,\\nPara ser qual Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Como devo eu falar,\\nComo demonstrar amor;\\nComo orar e trabalhar,\\nPara ser qual Cristo.\"}]},{\"number\":\"289\",\"collection_type\":\"Hinário\",\"title\":\"Mais Perto da Tua Cruz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Senhor, sou Teu, Tua voz ouvi\\nA chamar-me com amor.\\nEu almejo estar sempre junto a Ti,\\nÓ Bendito Salvador!\"},{\"section_type\":\"Coro\",\"content\":\"Mais perto da Tua cruz,\\nQuero estar, ó Salvador!\\nMais perto da Tua cruz,\\nSempre quero estar, Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"A seguir-Te aqui me consagro já\\nConstrangido pelo amor.\\nE minha'alma assim bem contente está\\nEm servir-te a Ti, Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, que doce paz, que alegria é,\\nAos Teus santos pés estar!\\nE com terno amor, reverente fé,\\nCom o meu Senhor falar!\"}]},{\"number\":\"290\",\"collection_type\":\"Hinário\",\"title\":\"Jesus, Sempre Te Amo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus sempre Te amo,\\nPorque sei que és meu;\\nA Ti toda glória,\\nNa Terra e no céu!\\nMeu Mestre divino,\\nMeu Deus e meu Rei,\\nA Ti, ó meu Cristo,\\nSubmisso serei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu Te amo porque\\nTu morreste por mim;\\nEu Te amo porque\\nTeu amor não tem fim.\\nEm Ti confiança\\nPra sempre terei;\\nA Ti, ó meu Cristo,\\nSubmisso serei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu Te amo, Meu Mestre,\\nEnquanto viver.\\nEu hei de louvar-Te\\nCom grande prazer.\\nAgora e pra sempre\\nContigo estarei;\\nA Ti, ó meu Cristo,\\nSubmisso serei.\"}]},{\"number\":\"291\",\"collection_type\":\"Hinário\",\"title\":\"Muitos Há Que me Contemplam\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó meu Senhor, eu quero ser mui puro,\\nEu quero ser também, meu Deus, veraz,\"},{\"section_type\":\"Coro\",\"content\":\"Pois muitos há, Senhor, que me contemplam\\nSim, meu Senhor, que olham para mim.\\nSim, meu Senhor, que olham para mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ser mui forte e destemido,\\nSim, quero ser humilde, manso e bom,\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó meu Senhor, eu quero cada dia,\\nÀ Tua lei com fé obedecer,\"}]},{\"number\":\"292\",\"collection_type\":\"Hinário\",\"title\":\"Onde Quer Que Seja\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Onde quer que seja com Jesus irei;\\nEle é meu bendito Salvador e Rei.\\nSeja para a guerra, para batalhar,\\nSeja para os campos, para semear.\"},{\"section_type\":\"Coro\",\"content\":\"Onde quer, onde quer que Jesus mandar\\nSempre junto dEle eu irei andar.\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Sempre seguirei a Cristo meu Senhor\\\",\\nDiz o coração que sente o Seu amor.\\nPerto dEle sempre bem seguro vou\\nOnde quer que seja mui contente estou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Seja, pois, pra onde for que me levar,\\nEu encontrarei ali meu doce lar.\\nOnde quer que seja sempre cantarei:\\n\\\"Tu, Senhor, comigo estás; não temerei.\\\"\"}]},{\"number\":\"293\",\"collection_type\":\"Hinário\",\"title\":\"Teu Divinal Amor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Teu divinal amor, Quis me buscar\\nEm gratidão, meu ser, Vou Te ofertar.\\nPai, ouve lá do Céu, Pois quero andar na luz;\\nMeu fervoroso amor, É de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, dá-me mais amor, Mais devoção.\\nTão mau e fraco é Meu coração!\\nPai, quero Te louvar, Por Cristo lá na cruz,\\nE sempre irei viver, Só pra Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pai, o que tenho e sou, Eu Te darei,\\nPois deste mundo mau, Não mais serei.\\nE quando ao Céu subir, E a meu Senhor eu vir,\\nLá viverei em luz, Junto a Jesus.\"}]},{\"number\":\"294\",\"collection_type\":\"Hinário\",\"title\":\"Não Eu, Mas Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não eu, mas Cristo, seja sempre honrado;\\nNão eu, mas Cristo, quero revelar.\\nNão eu, mas Cristo, em tudo quanto eu faça;\\nNão eu, mas Cristo, em todo o meu pensar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tão só Jesus conforta-me nas mágoas.\\nTão só Jesus, o pranto a me enxugar.\\nTão só Jesus, alivio dá-me às cargas;\\nTão só Jesus, o medo a dissipar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tão só Jesus; não mais falar ocioso;\\nTão só Jesus; não mais queixume vão.\\nTão só Jesus; não mais qualquer vaidade;\\nTão só Jesus; nenhuma presunção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não eu, mas Cristo, a me suprir as faltas;\\nNão eu, mas Cristo, a dar vigor sem fim.\\nTão só Jesus, ao corpo, espírito e alma;\\nTão só Jesus, eternamente, enfim.\"}]},{\"number\":\"295\",\"collection_type\":\"Hinário\",\"title\":\"Tudo Entregarei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tudo, ó Cristo, a Ti entrego,\\nTodo sim, por Ti darei!\\nResoluto, mas submisso,\\nSempre a Ti eu seguirei!\"},{\"section_type\":\"Coro\",\"content\":\"Tudo entregarei! Tudo entregarei!\\nSim, por Ti, Jesus bendito,\\nTudo deixarei!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tudo, ó Cristo, a Ti entrego,\\nCorpo e alma eis aqui!\\nEste mundo mau renego,\\nQuero dedicar-me a Ti!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tudo, ó Cristo, a Ti entrego,\\nQue prazer, ó meu Senhor!\\nPaz perfeita, paz completa!\\nGlória, glória ao Salvador!\"}]},{\"number\":\"296\",\"collection_type\":\"Hinário\",\"title\":\"Que Faria Cristo?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eis que Cristo chama a todos! Eia! Despertai!\\nSeu bendito amor, ide proclamai!\\nPode Cristo a toda hora contigo contar?\\nQue faria Cristo se estivesse em teu lugar?\"},{\"section_type\":\"Coro\",\"content\":\"Que faria, então, Cristo em Teu lugar,\\nSe estivesse aqui e deparasse esta questão?\\nSê-lhe, pois, fiel, e sem hesitar\\nSegue-O sempre, retamente, bem de coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Honras mundanais e glórias querem te cegar,\\nE teu coração, de Jesus, desviar;\\nMas o Mestre necessita do talento teu;\\nQueres consagrar-te a Ele e ao serviço Seu?\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando mais deveres Cristo a ti manifestar,\\nSegue-O com fervor, custe o que custar.\\nDize: \\\" Ó Senhor, eu vou, pois Teu eu quero ser!\\\"\\nSempre o que Jesus faria quero, sim, fazer.\"}]},{\"number\":\"297\",\"collection_type\":\"Hinário\",\"title\":\"Minha Cruz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A cruz que me deu Cristo, o Mestre,\\nPesa menos que o amor;\\nAs dores que sempre assolam\\nNão me apartam do Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"A cruz que me deu para eu levar,\\nAs dores que a mim vêm assolar\\nNão escondem meu Jesus,\\nPois eu ando em Sua luz,\\nVou vencendo para os Céus\"},{\"section_type\":\"Estrofe\",\"content\":\"O mundo a meu Mestre despreza,\\nE persegue os de Jesus,\\nPorém, pelo amor, pela graça,\\nLevarei a minha cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Fazer a vontade de Cristo.\\nSempre estou disposto sim;\\nContando eu a tão bela história,\\nTenho gozo e paz sem fim.\"}]},{\"number\":\"298\",\"collection_type\":\"Hinário\",\"title\":\"Toma, ó Deus, Meu Coração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Toma, ó Deus, em Tua mão,\\nComo está coração.\\nMesmo sem nenhum valor, Faze-o puro, santo e bom,\\nCheio enfim do Teu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Toma, ó Deus, as minhas mãos,\\nOs meus pés e os lábios meus;\\nE em favor dos meus irmãos Ajam sempre com amor,\\nCom prazer por onde for.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando, enfim, voltar Jesus\\nCom poder, em glória e luz\\nToma, ó Deus, meu pobre ser Para sempre ir morar\\nCom Jesus no doce lar.\"}]},{\"number\":\"299\",\"collection_type\":\"Hinário\",\"title\":\"Eis-nos Prontos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"\\\"Todos prontos\\\", disse o Mestre,\\n\\\"A comigo padecer?\\\"\\nE acordando responderam:\\n\\\"Eis-nos prontos a morrer!\\\"\"},{\"section_type\":\"Coro\",\"content\":\"Sim, eis-nos prontos; Senhor, somos Teus.\\nNós vamos ser leais, ó Jesus\\nVem ajudar-nos a olhar para os Céus\\nE a ser templos Teus de paz, amor e luz\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando virmos ondas negras\\nDe tristezas sobre nós\\n\\\"Eis-nos prontos a seguir-Te\\\",\\nErgueremos nossa voz?\"},{\"section_type\":\"Estrofe\",\"content\":\"Muito em breve, quando ao mundo,\\nNosso mestre regressar,\\nDir-Lhe-e-mos: \\\"Eis-nos prontos,\\npara irmos para o lar?\\\"\"}]},{\"number\":\"300\",\"collection_type\":\"Hinário\",\"title\":\"Herdeiro do Reino\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó tu herdeiro do reino celeste,\\nPor que dormitas tão perto do lar?\\nPresto levanta-te, pões tu as armas;\\nEis que a vitória bem podes ganhar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Grandes potências ordenam suas forças\\nPara o combate final se ferir\\nOuve à distância o ruído dos carros!\\nFilho do reino não queiras dormir!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não te detenham prazeres terrenos,\\nPois bem depressa terão de passar!\\nRompe as cadeias que ao mundo te prendem!\\nVem logo a Cristo, que te há de salvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nele confia esperando Sua glória;\\nErgue tua fronte, sê digno cristão!\\nJá no horizonte refulge a alvorada;\\nFilho do reino, prorrompe em canção!\"}]},{\"number\":\"301\",\"collection_type\":\"Hinário\",\"title\":\"Crer e Observar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em Jesus confiar, Sua lei observar,\\nOh, que gozo, que bênção, que paz!\\nSatisfeitos, guardar tudo quanto ordenar,\\nAlegria perene nos traz!\"},{\"section_type\":\"Coro\",\"content\":\"Crer e observar\\nTudo quanto ordenar;\\nO fiel obedece\\nAo que Cristo mandar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O inimigo falaz e a calúnia mordaz\\nCristo pode desprestigiar;\\nNem tristeza, nem dor, nem a intriga maior\\nPoderão ao fiel abalar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que alegria sem-par, que prazer singular\\nTem o crente zeloso e leal!\\nA Jesus contemplar, com Jesus sempre andar,\\nQue consolo constante e real!\"},{\"section_type\":\"Estrofe\",\"content\":\"Resolutos, Senhor, e com fé, zelo e ardor,\\nOs Teus passos queremos seguir;\\nTeus preceitos guardar, o Teu nome exaltar,\\nSempre a Tua vontade cumprir.\"}]},{\"number\":\"302\",\"collection_type\":\"Hinário\",\"title\":\"Minha Oração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mais força me inspira, mais ódio ao mal,\\nMais calma nas lutas, mais alto ideal;\\nMais fé no meu Mestre, mais dedicação,\\nMais gozo em servi-Lo, mais consagração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais justo me faze, mais sábio, Senhor;\\nMais firme na Causa, com zelo e fervor;\\nMais reto na vida, mais triste ao pecar;\\nUm filho submisso, mais pronto em amar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais puro me faze, mais santo em Jesus;\\nMais de Sua graça, mais perto da cruz;\\nMais rica esperança, mais fé e poder,\\nPra sempre servir-Te e Te obedecer.\"}]},{\"number\":\"303\",\"collection_type\":\"Hinário\",\"title\":\"Se Cristo For Comigo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Por vales de aflições, se preciso for passar,\\nOu mesmo se feliz, sempre em paz puder andar,\\nBem sei, seguro estou, se ao sol ou sombra vou;\\nNa luz ou nas trevas, irei com Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"A todo! lugar eu irei, com Jesus;\\nSeguindo Sua lei, do Céu eu terei a santa luz,\\nÉ meu privilégio levar a Sua cruz;\\nIrei, pois, a todo lugar, com Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se as novas do evangelho for meu dever levar\\nAo pecador perdido, nas trevas a vagar;\\nSe é que me toca a mim pregar a Cristo assim,\\nSe Ele me guia, irei com Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se a minha sorte for mesmo em casa a cruz levar,\\nQuando outros a proclamam em terras de além-mar,\\nSe fico, pois, ou vou, contente sempre estou,\\nPois sempre contigo, eu tenho a Jesus.\"}]},{\"number\":\"304\",\"collection_type\":\"Hinário\",\"title\":\"Vêem os Outros Cristo em Ti?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"'Stamos nós tão perto do Salvador,\\nNo jazer, no estudo ou quando em labor,\\nQue em nós se aviste, brilhando em luz,\\nA imagem de Jesus?\"},{\"section_type\":\"Coro\",\"content\":\"Vêem os outros Cristo em mim?\\nVêem os outros Cristo em ti?\\nÉ sincero o teu amor por Jesus, o Salvador?\\nVêem os outros Cristo em ti?\"},{\"section_type\":\"Estrofe\",\"content\":\"Temos nós amor puro e divinal\\nPelos pecadores no lodaçal?\\nDamos-lhes a mão, custe o que custar,\\nPara assim os resgatar?\"},{\"section_type\":\"Estrofe\",\"content\":\"Como livro aberto nos hão de ler,\\nContemplando, assim, nosso proceder,\\nHão de ser levados a Cristo amar,\\nOu a Ele abandonar?\"}]},{\"number\":\"305\",\"collection_type\":\"Hinário\",\"title\":\"O Teu Querer\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Imploro a Ti o Teu poder,\\nSenhor Jesus, meu Salvador!\\nQue eu cumpra aqui, em meu viver,\\nO Teu querer, e com fervor.\"},{\"section_type\":\"Coro\",\"content\":\"Que eu cumpra só o Teu querer,\\nDisposto, assim, a obedecer;\\nQue eu siga aonde me guiar\\nO Teu querer, o Teu mandar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao sobrevir tribulação,\\nSe aflito estou, opresso em dor,\\nRefúgio vou buscar, então,\\nNo Teu querer, ó Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"E lá no Céu, quando eu chegar,\\nE meu Jesus então eu vir,\\nExclamarei sem hesitar.\\n\\\"O Teu querer eu vou cumprir.\\\"\"}]},{\"number\":\"306\",\"collection_type\":\"Hinário\",\"title\":\"Diz, Senhor\",\"author\":\"George Bennard (1873-1958)\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouve o Senhor a Ti chamando:\\n\\\"Queres hoje, tu, servir a Mim?\\nQueres trabalhar pelos perdidos?\\\"\\nOuve o Senhor falar assim.\"},{\"section_type\":\"Coro\",\"content\":\"Diz, Senhor! Diz, Senhor,\\nO que devo eu aqui fazer!\\nDiz, Senhor! Diz, Senhor!\\nEis-me aqui, eu irei responder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os perdidos deste mundo clamam.\\nOuve o suplicar do sofredor!\\nCristo hoje está te convidando\\nPara ser obreiro de valor.\"},{\"section_type\":\"Estrofe\",\"content\":\"O Senhor te chama com ternura;\\nOuve Sua voz a suplicar.\\nVem a Ele unir-te no serviço,\\nSim, buscando almas pra salvar.\"}]},{\"number\":\"307\",\"collection_type\":\"Hinário\",\"title\":\"Cristo nos Conclama\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo nos conclama para trabalhar,\\nÚteis para a causa, sempre até voltar.\\nNesta guerra santa temos um quinhão:\\nAos que estão perdidos proclamar perdão.\"},{\"section_type\":\"Coro\",\"content\":\"Sempre orando, vigiar,\\nCom fervor, até do Céu Jesus voltar.\\nCom trabalho e oração\\nVai, enfim, raiar a nossa redenção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Contra o vil pecado, contra Satanás,\\nSempre declarando guerra, e nunca paz.\\nVamos aos perdidos logo proclamar\\nQue inda tempo existe, Cristo os quer salvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Breve o tempo passa, logo vem o fim;\\nOuvem-se ao longe, toques de clarim;\\nEis que o Mestre volta, volta para dar\\nAos que O aceitarem, gozo e paz no lar.\"}]},{\"number\":\"308\",\"collection_type\":\"Hinário\",\"title\":\"Brilha no Meio do Teu Viver\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não somente pra fazer um feito singular\\nÉ mister agir com muito ardor,\\nMas também as coisas simples para executar,\\nDeves fazê -Ias com fervor.\"},{\"section_type\":\"Coro\",\"content\":\"Brilha no meio do teu viver,\\nBrilha no meio do teu viver,\\nPois talvez algum aflito possas socorrer;\\nBrilha no meio do teu viver\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, talvez alguma vida possas alegrar\\nCom palavras doces, em amor;\\nOu então algumas almas tristes alcançar\\nCom a mensagem do Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao redor, oh, quantas almas vivem a sofrer,\\nEm angústia, em densa escuridão,\\nÀ espera de alguém que venha lhes valer,\\nE que lhes queira dar a mão.\"}]},{\"number\":\"309\",\"collection_type\":\"Hinário\",\"title\":\"Vamos à Colheita\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ceifeiros somos nós, fiéis,\\nCeifando para o Rei dos reis\\nOs frutos prontos pra colher,\\nQue em derredor se estão a ver.\\nAssim, ao nosso Salvador\\nRendemos preito de louvor,\\nAo nosso Mestre, lá no Céu,\\nQue sobre a cruz por nós morreu.\"},{\"section_type\":\"Coro\",\"content\":\"Vamos já obedecer; vamos à colheita!\\nPara quando anoitecer, ver a obra feita.\\nPouco tempo ainda há, breve o prazo acabara,\\nBreve, breve, breve acabara.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós trabalhamos por Jesus,\\nQue para os campos nos conduz;\\nE se os obreiros poucos são,\\nOciosos não fiquemos, não!\\nAinda há campos pra ceifar\\nQue muitos frutos devem dar.\\nNão ouves Cristo perguntar:\\nQuem quer por Mim ir trabalhar?\"},{\"section_type\":\"Estrofe\",\"content\":\"As horas vão passando já,\\nO dia em breve findará,\\nConosco toma o teu lugar\\nE por Jesus vem trabalhar!\\nPor que ocioso ainda estás,\\nSe a noite logo enfrentarás?\\nTu queres fruto ao Céu levar,\\nOu folhas só apresentar?\"}]},{\"number\":\"310\",\"collection_type\":\"Hinário\",\"title\":\"O Mestre Chama\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Já os campos da seara\\nTêm o trigo a madurar!\\nO Senhor procura obreiros,\\nEis que O ouço a me chamar!\"},{\"section_type\":\"Coro\",\"content\":\"Eis que O ouço a me chamar,\\nEis que O ouço a me chamar!\\nO Senhor procura obreiros,\\nEis que O ouço a me chamar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo, amigo dos perdidos,\\nEsta ovelha quis buscar.\\nHoje, aos outros quer que eu busque,\\nEis que O ouço a me chamar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu me entrego ao Seu serviço,\\nSigo aonde me mandar.\\nSão mui poucos os obreiros,\\nEis que O ouço a me chamar!\"}]},{\"number\":\"311\",\"collection_type\":\"Hinário\",\"title\":\"Dai-nos Luz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Uma voz ressoa, num geral clamor:\\nDai-nos luz, dai-nos luz!\\nOs milhões em trevas, cheios de pavor,\\nPedem luz, pedem luz!\"},{\"section_type\":\"Coro\",\"content\":\"Dai-nos luz, a mui gloriosa luz\\nDe perdão, de paz e amor!\\nDai-nos luz, a tão preciosa luz\\nDe Jesus, o Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ansiamos vida, paz, consolação:\\nDai-nos luz, dai-nos luz!\\nSe é por Cristo só que Deus nos dá perdão,\\nDai-nos luz, dai-nos luz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, por toda parte deve reluzir\\nEssa luz de Jesus,\\nQue ilumina a estrada que hemos de seguir.\\nDai-nos luz, dai-nos luz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eia, pois, ó crentes, todo o mundo enchei\\nDessa luz de Jesus!\\nAos milhões sem Cristo sem tardar erguei\\nEssa luz de Jesus!\"}]},{\"number\":\"312\",\"collection_type\":\"Hinário\",\"title\":\"Havemos de Colher\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Semeemos todos a semente santa,\\nDesde a madrugada até o anoitecer;\\nCalmos, aguardando o tempo da colheita,\\nQuando alegremente havemos de colher.\"},{\"section_type\":\"Coro\",\"content\":\"Havemos de colher! Havemos de colher!\\nOh! quão jubilosos, havemos de colher!\\nHavemos de colher! Havemos de colher!\\nMesses abundantes havemos de trazer!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mesmo quando seres maus e perniciosos\\nQuerem a semente boa destruir,\\nVamos semeando, sempre satisfeitos,\\nPois colheita santa havemos de fruir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eia, pois, obreiros, semeai, ousados,\\nA semente viva da verdade e luz;\\nProclamando Cristo, Seu poder e glória,\\nSalvação perfeita que alcançou na cruz!\"}]},{\"number\":\"313\",\"collection_type\":\"Hinário\",\"title\":\"A Grande Comissão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eis os milhões que em trevas e pecado,\\nJazem perdidos, sem o Salvador!\\nOh, quem irá as novas proclamando\\nQue Deus, em Cristo, salva o pecador?\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Todo o poder o Pai Me deu,\\nNa Terra como lá no Céu!\\nIde, pois, e anunciei o evangelho,\\nE eis-Me convosco sempre!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Portas abertas eis por todo o mundo!\\nCrentes em Cristo, a graça proclamai!\\nE na peleja unindo as vossas forças,\\nDa escravidão os povos libertai.\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Ó, vinde a Mim\\\", divina voz proclama.\\nVinde, clamai em nome de Jesus!\\nPra nos salvar da perdição eterna,\\nSeu sangue derramou por nós na cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Deus, apressa o dia tão glorioso,\\nEm que os remidos todos se unirão\\nNum coro excelso, santo e jubiloso,\\nE para sempre glória a Ti darão!\"}]},{\"number\":\"314\",\"collection_type\":\"Hinário\",\"title\":\"Guarda, Faz Troar ao Longe\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Guarda, faz troar ao longe\\nO clarim da redenção!\\nQuem ouvir e arrepender-se\\nHá de obter o galardão.\"},{\"section_type\":\"Coro\",\"content\":\"Faz vibrar por toda parte,\\nSim, por toda terra e mar,\\nA trombeta do evangelho,\\nPara o pecador salvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Toca, pois, por sobre os montes,\\nFaz vibrar até o sertão;\\nChama, assim, os pecadores,\\nPara herdar a salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Faz soar a alegre nova:\\n\\\"Vinde ao real festim!\\\"\\nSim, a vós, que estais aflitos,\\nCristo diz: \\\"Ó, vinde a Mim!\\\"\"}]},{\"number\":\"315\",\"collection_type\":\"Hinário\",\"title\":\"Hoje Ajuda a Alguém\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Lança os olhares em tomo de ti,\\nSim, ajuda hoje a alguém!\\nSê um auxílio ao teu próximo ali,\\nSim, ajuda hoje a alguém!\"},{\"section_type\":\"Coro\",\"content\":\"Sim, ajuda hoje a alguém,\\nDemonstra-lhe amor também;\\nRemove o temor e promove o amor,\\nOh, sim ajuda hoje a alguém.\"},{\"section_type\":\"Estrofe\",\"content\":\"Muitos aguardam Palavras de amor,\\nSim, ajuda hoje a alguém!\\nInda que seja pequeno o favor,\\nSim, ajuda hoje a alguém!\"},{\"section_type\":\"Estrofe\",\"content\":\"Muitos têm cargas pesadas demais,\\nSim, ajuda hoje a alguém!\\nQuantos sucumbem em seus tristes ais!\\nSim, ajuda hoje a alguém!\"},{\"section_type\":\"Estrofe\",\"content\":\"Muitos da vida cansados estão,\\nSim, ajuda hoje a alguém!\\nMuitos procuram obter salvação,\\nSim, ajuda hoje a alguém!\"}]},{\"number\":\"316\",\"collection_type\":\"Hinário\",\"title\":\"Não me Falaram de Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não te importa se algum dos amigos morrer\\nSem saber do convite de Cristo?\\nDeixas que no juízo ele venha a dizer.\\n\\\"Não, jamais me falaram de Cristo?\\\"\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Não me falaram de Cristo!\\nNão me falaram de Cristo!\\nTantos vi que salvou, mas ninguém se importou\\nDe falar-me da graça de Cristo!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Não te importa que as almas, preciosas a Deus,\\nOh! não sejam levadas a Cristo?\\nPois dirão quando o Mestre vier lá dos Céus:\\n\\\"Não, jamais nos falaram de Cristo!'\"},{\"section_type\":\"Estrofe\",\"content\":\"Não te cales, irmão, pede a Deus direção,\\nPara dar testemunho de Cristo;\\nPra ninguém no juízo exclamar com razão:\\n\\\"Não, jamais me falaram de Cristo!\\\"\"}]},{\"number\":\"317\",\"collection_type\":\"Hinário\",\"title\":\"Sobre o Altar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se anelas a paz, ter mais fé e poder,\\nE louvor a Jesus queres dar;\\nPoderás descansar, Sua benção obter,\\nSe tua vida estiver sobre o altar.\"},{\"section_type\":\"Coro\",\"content\":\"Ó, entrega-te, pois, ao serviço de Deus,\\nConsagra-Lhe teu coração.\\nEle te bendirá, far-te-á descansar,\\nE tua vida será uma canção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se caminhas com Deus, pelo brilho da cruz\\nHás de ter o poder pra vencer;\\nViverás, pois, feliz, andarás sempre em luz,\\nOfertando ao Senhor teu viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Recompensa terás em servir ao Senhor,\\nE em falares do amor de Jesus;\\nAlegria hás de ter, e celeste fervor,\\nE um lugar em Seu reino de luz.\"}]},{\"number\":\"318\",\"collection_type\":\"Hinário\",\"title\":\"Servi Alegremente\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao Mestre alegremente, irmãos, deveis servir;\\nA Cristo, o Rei bendito, com fé deveis seguir.\\nOs Céus e a Terra toda proclamam Seu poder;\\nMilhões alegremente observam Seu querer.\"},{\"section_type\":\"Coro\",\"content\":\"Ao Mestre alegremente,\\nIrmãos, deveis servir;\\nA Cristo, o Rei bendito,\\nCom fé deveis seguir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao Mestre alegremente, hosanas entoai;\\nAo Deus do mundo inteiro, prostrados adorai.\\nQual rocha inabalável o Seu domínio é;\\nEterno, incontestável, o Autor da nossa fé.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao Mestre alegremente, na vossa vida honrai.\\nA vinda dEle ao mundo, depressa proclamai.\\nCom glória e majestade, com Seu poder sem-par,\\nUm reino sempiterno Jesus irá fundar.\"}]},{\"number\":\"319\",\"collection_type\":\"Hinário\",\"title\":\"Mãos ao Trabalho\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mãos ao trabalho, jovens, vai já passando o alvor;\\nVamos enquanto temos nossa vida em flor!\\nVamos enquanto é dia, com força trabalhar;\\nEia, que ao vir a noite, não há mais lidar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mãos ao trabalho, adultos, vamos enquanto há luz;\\nEia, que já é tempo de servir Jesus!\\nIde o vigor da vida, todos ao bem votar;\\nEia, que ao vir a noite, não há mais lidar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mãos ao trabalho, idosos, breve nos chega o fim;\\nFirmes enquanto a morte não tocar clarim!\\nVamos, irmãos, à obra, por Cristo trabalhar;\\nEia, que ao vir a noite, vamos descansar.\"}]},{\"number\":\"320\",\"collection_type\":\"Hinário\",\"title\":\"A Todo Semelhante Meu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A todo semelhante meu\\nContarei que Deus é amor.\\nO mundo desconhece o bem\\nE Jesus, o Redentor.\"},{\"section_type\":\"Coro\",\"content\":\"Falarei de Deus\\nE do Seu amor.\\nPara o mundo mostrarei Jesus,\\nCom maior fervor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Da eterna graça sem igual\\nAos perdidos falarei,\\nGuiando-os deste mundo mau\\nPara os pés do amado Rei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais vasto que o imenso mar\\nÉ de Deus o grande amor;\\nPor isso proclamá-lo-ei\\nPara todo pecador.\"}]},{\"number\":\"321\",\"collection_type\":\"Hinário\",\"title\":\"Ao Mundo Vou Contar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao mundo vou contar que sou cristão;\\nDo amor de Cristo eu vou falar.\\nAo mundo vou contar que sou cristão,\\nPois tenho a Cristo no coração.\\nProclamarei o amor de Cristo,\\nQue me salvou do mundo mau;\\nE eu bem sei que crendo nEle,\\nTerás a paz também que eu encontrei.\\nAo mundo vou contar que sou cristão;\\nDo amor de Cristo eu vou falar;\\nQue meu viver a Ele eu entreguei,\\nE em Seu caminho, sempre andarei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao mundo vou falar que Cristo vem;\\nSim, vem mui breve, buscar os Seus.\\nVivamos, pois, em prontidão aqui,\\nE assim iremos morar nos Céus.\\nQuando o Senhor voltar em glória\\nCom anjos mil, oh, que esplendor!\\nVai levar os escolhidos\\nÀ pátria eternal, que é só de amor!\\nAo mundo vou contar que sou cristão;\\nDo amor de Cristo eu vou falar.\\nAo mundo vou contar que sou cristão,\\nPois tenho a Cristo no coração.\"}]},{\"number\":\"322\",\"collection_type\":\"Hinário\",\"title\":\"No Serviço do Meu Rei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Trabalhando por Jesus eu sou feliz,\\nSou feliz e venturoso.\\nA Seus pés eu minha alma satisfiz,\\nEm Jesus eu sou feliz!\"},{\"section_type\":\"Coro\",\"content\":\"Ao serviço do meu Rei\\nMeus talentos eu darei;\\nTenho paz e alegria\\nNo serviço do meu Rei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Jesus sublime paz eu encontrei,\\nSou feliz e venturoso.\\nE agora em gratidão sempre estarei\\nNo serviço do meu Rei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Esse grande amor eu hei de proclamar,\\nSou feliz e venturoso;\\nMinha vida a Cristo eu quero consagrar,\\nE com Ele sempre andar.\"}]},{\"number\":\"323\",\"collection_type\":\"Hinário\",\"title\":\"Eis de Cristo a Voz Que Chama\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eis de Cristo a voz que chama:\\n\\\"Quem irá a trabalhar?\\\"\\nOs trigais estão maduros,\\nVamos todos já ceifar.\\nQuanto tempo o Mestre clama!\\nRecompensas nos quer dar.\\nQuem resposta dá ao Mestre:\\n\\\"Eis-me aqui, vou ajudar\\\"?\"},{\"section_type\":\"Estrofe\",\"content\":\"Não podendo em outras terras\\nA mensagem proclamar,\\nPodes entre os teus vizinhos\\nO evangelho anunciar.\\nSe não podes, como um anjo,\\nBem falar e assim pregar,\\nPodes deste amor tão terno\\nDe Jesus testemunhar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não podendo ser um guarda\\nSobre os muros de Sião,\\nApontando o bom caminho\\nQue conduz à salvação,\\nOrações fazer tu podes,\\nPodes vir e ofertas dar;\\nPodes ter fidelidade,\\nCom fervor a lei guardar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, enquanto muitos morrem,\\nE o clamor se pode ouvir,\\nNão te eximas, murmurando:\\n\\\"Hoje não, não posso ir.\\\"\\nMãos à obra, não dormites,\\nMas trabalha com fervor.\\nA Jesus responde agora:\\n\\\"Eis-me aqui, irei, Senhor!\\\"\"}]},{\"number\":\"324\",\"collection_type\":\"Hinário\",\"title\":\"Mãos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Estas mãos que Deus me deu,\\nForam feitas pra servir\\nO vizinho ao lado meu,\\nQue não sabe mais sorrir!\\nAtravés de minhas mãos,\\nEu pretendo lhe mostrar\\nO sorriso de Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Mãos consagradas para a causa em prol do amor;\\nMãos dedicadas ao serviço do Senhor;\\nMãos preocupadas em se unir às de Jesus;\\nMãos que não temem o encontro com a luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Há no céu, no mar, na flor,\\nUm detalhe de amor;\\nHá também no entardecer\\nA poesia do nascer!\\nNa beleza natural,\\nEu contemplo o digital\\nDessa mão que me criou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minha mão co'a de Jesus\\nVai se unir no ideal\\nDe mostrar que a Sua cruz\\nÉ um fato bem real.\\nAtravés dessa união\\nEu pretendo a integrarão\\nCom Jesus e com você.\"}]},{\"number\":\"325\",\"collection_type\":\"Hinário\",\"title\":\"As Novas do Evangelho\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"As novas do evangelho\\nRessoando estão aqui;\\nBoas novas tão alegres!\\nElas são pra mim e ti.\\nAssim Deus nos amou,\\nSim, a cada pecador,\\nQue nos deu Seu Filho amado\\nPra sofrer a nossa dor.\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Santa paz e perdão!\\\"\\nSão as novas lá dos Céus!\\n\\\"Santa paz e perdão!\\\"\\nDemos glória ao nosso Deus!\"},{\"section_type\":\"Estrofe\",\"content\":\"As novas do evangelho,\\nAnunciam vida e paz,\\nPois Jesus aos pecadores\\nSalvação perene traz.\\nÉ tempo de aceitar\\nO glorioso Salvador,\\nPoderoso e mui bondoso,\\nQue perdoa o pecador.\"},{\"section_type\":\"Estrofe\",\"content\":\"As novas do evangelho\\nLevam todos a saber\\nQue perdão e vida eterna\\nTodos podem receber.\\nÉ só crer em Jesus\\nE confiar em Seu amor,\\nPois na cruz verteu Seu sangue\\nPara ser o Salvador.\"}]},{\"number\":\"326\",\"collection_type\":\"Hinário\",\"title\":\"Vaso de Bênção\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quero ser um vaso de bênção,\\nSim, um vaso escolhido por Deus,\\nPara as novas levar aos perdidos,\\nBoas novas que vêm lá dos Céus.\"},{\"section_type\":\"Coro\",\"content\":\"Faze-me vaso de bênção, Senhor,\\nVaso que leve a mensagem de amor!\\nEis-me submisso pra Teu serviço;\\nTudo consagro-Te agora, Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero ser um vaso de bênção\\nPara todos os dias fazer,\\nAos culpados que vivem nas trevas,\\nO perdão de Jesus conhecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero ser um vaso de bênção,\\nSim, um vaso de bênção sem-par,\\nAvisando que crentes em Cristo,\\nJubilosos, no Céu hão de entrar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Para ser um vaso de bênção\\nÉ mister uma vida real,\\nUma vida de fé e pureza,\\nRevestida do amor divinal.\"}]},{\"number\":\"327\",\"collection_type\":\"Hinário\",\"title\":\"Mensagem ao Mundo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vamos dar a mensagem ao mundo,\\nProclamar a história da cruz;\\nHistória de amor e graça,\\nHistória de paz e luz,\\nHistória de paz e luz.\"},{\"section_type\":\"Coro\",\"content\":\"Pois Jesus, nosso Rei, em breve\\nVoltará Rei dos reis, Senhor;\\nVirá Seu reino de luz fundar,\\nUm reino de paz e amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Uma voz de advertência ao mundo\\nDeve ser o nosso cantar;\\nUm hino de fé que fale\\nDas bênçãos do amor sem-par,\\nDas bênçãos do amor sem-par.\"},{\"section_type\":\"Estrofe\",\"content\":\"Um dever é levar Cristo ao mundo\\nComo alguém que pode salvar;\\nQue pode afastar pecados\\nE a glória de Deus mostrar,\\nE a glória de Deus mostrar.\"}]},{\"number\":\"328\",\"collection_type\":\"Hinário\",\"title\":\"Ide!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Disse Jesus: Ide por todo o mundo\\nE pregai o eterno dom:\\nA salvação que, com amor profundo,\\nDá o Deus grandioso e bom;\\nTendo na cruz a afirmação do amor,\\nProclamai o dom do Redentor.\\nÓ, conquistai almas perdidas, buscai\\nO pecador enfermo, quase moribundo!\"},{\"section_type\":\"Coro\",\"content\":\"Vamos, irmãos, levar essa luz ao mundo inteiro!\\nVamos, irmãos, contar que esse dom é verdadeiro!\\nVamos, irmãos, pregar mui confiantes no Cordeiro\\nQue na cruz proveu a nossa redenção!\"},{\"section_type\":\"Estrofe\",\"content\":\"Todos unidos neste grande intento,\\nProclamemos salvação!\\nSem recuar, sempre mostrando alento,\\nSim, cumpramos a missão\\nQue o Salvador, Cristo Jesus, nos deu!\\nEle está também no posto Seu.\\nDiz-nos o Rei: \\\"Sempre convosco estarei.\\\"\\nVamos, irmãos, por Cristo neste pensamento!\"},{\"section_type\":\"Estrofe\",\"content\":\"Firmes, levemos a mensagem santa\\nDo evangelho de Jesus!\\nEsta mensagem divinal que encanta\\nE que o pecador conduz;\\nPlena de bênçãos do glorioso Deus,\\nQue redime os escolhidos Seus,\\nCheia de amor, traz-nos do Céu o fragor\\nDa compaixão de Deus, da graça sacrossanta!\"}]},{\"number\":\"329\",\"collection_type\":\"Hinário\",\"title\":\"Trabalho Cristão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vamos nós trabalhar, somos servos de Deus,\\nCom o Mestre seguir no caminho dos Céus;\\nCom o Seu bom conselho o vigor renovar,\\nE fazer, diligentes, o que Ele ordenar.\"},{\"section_type\":\"Coro\",\"content\":\"No labor, com fervor,\\nA servir a Jesus,\\nCom desvelo e fé e com oração,\\nAté voltar o Redentor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos nós trabalhar, os famintos fartar;\\nPara a fonte do bem os sedentos levar.\\nSó a cruz do Senhor nossa glória será,\\nPois Jesus salvação pela graça nos dá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos nós trabalhar para Cristo, o Senhor;\\nContra o reino das trevas será vencedor.\\nE então para sempre exaltado será,\\nQuem real salvação pela graça nos dá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos nós trabalhar ajudados por Deus,\\nQue coroa real nos dará lá nos Céus.\\nNa mansão dos fiéis o descanso será,\\nPois Jesus salvação pela graça nos dá.\"}]},{\"number\":\"330\",\"collection_type\":\"Hinário\",\"title\":\"Trabalhar e Orar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu quero trabalhar por meu Senhor,\\nConfiante em Seu poder, em Seu amor;\\nVou orar e trabalhar, e ocupado sempre estar\\nNa seara do Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"Trabalhar e orar\\nFielmente na seara do Senhor,\\nMeu anelo é orar e ocupado sempre estar,\\nNa seara do Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero cada dia trabalhar,\\nEscravos do pecado libertar,\\nE levá-los a Jesus, nosso Guia, nossa luz,\\nNa seara do Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ser obreiro de valor,\\nConfiante no poder do Salvador,\\nE quem queira trabalhar, achará também lugar\\nNa seara do Senhor.\"}]},{\"number\":\"331\",\"collection_type\":\"Hinário\",\"title\":\"As Searas Maduras\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Contemplai as searas maduras,\\nVede os grãos tremulando no ar;\\nEis a voz do Senhor com ternura\\nOs fiéis para a ceifa chamar.\"},{\"section_type\":\"Coro\",\"content\":\"Oh! quem, pois, dirá para o Mestre:\\n\\\"Eis-me aqui, eu vou, Senhor!\\\"\\nOh! quem a ceifar se consagra\\nCom prazer, força e fé, com amor?\"},{\"section_type\":\"Estrofe\",\"content\":\"Do semear já o tempo é passado,\\nE chegou a estação outonal;\\nEis de Deus o anelante chamado:\\n\\\"Partilhai da colheita final!\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Com prazer, afinal, o ceifeiro\\nJuntamente com o semeador,\\nReceber vai o prêmio do obreiro,\\nLá no Céu, no eternal lar de amor.\"}]},{\"number\":\"332\",\"collection_type\":\"Hinário\",\"title\":\"Compensa Servir a Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Servir a Jesus, que prazer sem igual!\\nNEle há salvação e vida eternal.\\nÉ só confiar e seguir Sua luz;\\nCompensa servir a Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Compensa servir a Jesus mais e mais,\\nCompensa, pois bênçãos produz.\\nSeja a senda da glória difícil demais,\\nÉ prazer, sim, servir a Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ainda que as sombras nos venham cercar,\\nE espinhos do mal nos possam magoar,\\nO bom Redentor já sofreu sobre a cruz;\\nCompensa servir a Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Compensa servir a Jesus com amor,\\nEmbora a sofrer, em lutas e dor;\\nO Mestre com graça nos guarda e conduz;\\nCompensa servir a Jesus.\"}]},{\"number\":\"333\",\"collection_type\":\"Hinário\",\"title\":\"Há um Dever\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há um dever que Deus nos confiou:\\nIr e anunciar Jesus ao pecador,\\nIr proclamar que já o resgatou,\\nSim, expandir a fé no Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não demoreis, o fim se aproximou;\\nJá brilha o céu no alvor da redenção.\\nAo infeliz que o mal escravizou,\\nÓ, ide já livrar da perdição.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus vos chamou a fim de trabalhar;\\nSim é Jesus o nosso Capitão;\\nGraça e perdão deveis anunciar.\\nQuem for fiel, terá o galardão.\"}]},{\"number\":\"334\",\"collection_type\":\"Hinário\",\"title\":\"Sou Peregrino e Forasteiro\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sou peregrino e forasteiro,\\nUma noite aqui demoro e nada mais.\\nNão me detenhas, pois que vou indo\\nPra onde há fontes sempre fluindo.\"},{\"section_type\":\"Coro\",\"content\":\"Sou peregrino e forasteiro,\\nUma noite aqui demoro e nada mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! quanta glória lá brilha sempre!\\nLá está meu anelante coração.\\nAqui no mundo escuro e triste\\nEu ando errante, e a dor existe.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá na cidade pra onde eu sigo,\\nMeu Senhor, sim, meu Senhor é sua luz.\\nLá não há pranto, não há tristeza,\\nEm tudo há graça, real beleza.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó terra triste, eu vou deixar-te,\\nMas um dia voltarás à perfeição.\\nPor Cristo foste criada linda,\\nE restaurada serás ainda.\"}]},{\"number\":\"335\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Quão Doces as Novas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! quão doces as novas ao triste viajor,\\nEm exílio, distante do lar!\\nMuito em breve virá Jesus Cristo, seu Senhor,\\nE com Ele no reino há de entrar.\"},{\"section_type\":\"Coro\",\"content\":\"Sim, logo vem o bendito Salvador,\\nVem Seu povo levar para o lar.\\nPeregrinos, breve, hão de ao Céu subir\\nE ao bom Rei, com louvor adorar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ressurgindo os que dormem, da tumba sairão,\\nPara ver o Senhor regressar.\\nOh! que encontro feliz os remidos fruirão,\\nQuando Cristo do Céu retomar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis que o Éden perdido, de novo surgirá,\\nAnte o toque da mão de Jesus;\\nE do norte e do sul Cristo então recolherá\\nOs remidos na pátria de luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aleluia! Amém! Aleluia ao Rei Jesus!\\nLogo mais estaremos no lar.\\nMuito em breve, do Céu, com poder, em glória e luz,\\nNós veremos Jesus regressar.\"}]},{\"number\":\"336\",\"collection_type\":\"Hinário\",\"title\":\"Almejo o Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Almejo o lar, paterno lar amado;\\nDe meu Jesus ao peito estar;\\nBem longe andar do mundo e do pecado,\\nNo perenal e doce lar.\\nCom sonhos mil eu comecei na lida,\\nUm só, de todos, resta, em minha vida;\\nMeu peito arde em forte desejar:\\nAlmejo o lar, almejo o lar!\"},{\"section_type\":\"Coro\",\"content\":\"Desejo ao lar, desejo ao lar,\\nDesejo ao lar, ao lindo e eterno lar,\\nSaudoso estou e canto em triste exílio:\\nEu quero ao lar, ao doce lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Almejo o lar; eu vi, em doce sonho,\\nPaís melhor, a pátria além;\\nMansões, jardins, e tudo tão risonho\\nRefulge à luz, à paz e ao bem!\\nNo mundo, aqui, as flores se murcharam,\\nAs aves já seu ninho abandonaram,\\nE a alma geme em triste suspirar:\\nAlmejo o lar, almejo o lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Almejo o lar; o barco busca o porto;\\nAs águas do regato, o mar.\\nO filho vem da mãe ao seio, absorto;\\nEu quero ir também ao lar.\\nEm meu viver, em riso ou desventura,\\nTambém cantei, e o eco só perdura,\\nQual triste voz, dolente, a soluçar.\\nAlmejo o lar, almejo o lar!\"}]},{\"number\":\"337\",\"collection_type\":\"Hinário\",\"title\":\"Sou Forasteiro Aqui\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sou forasteiro aqui, em terra estranha estou,\\nDo reino lá do Céu embaixador eu sou.\\nMeu Rei e Salvador vos manda em Seu amor\\nAs boas novas de perdão.\"},{\"section_type\":\"Coro\",\"content\":\"Eis a mensagem que nos deu,\\nAquele que por nós morreu.\\nReconciliai-vos já, é ordem que Ele dá,\\nReconciliai-vos já, com Deus!\"},{\"section_type\":\"Estrofe\",\"content\":\"É ordem do meu Rei que todo pecador,\\nArrependido já, se volte ao Salvador,\\nE salvação terá, pois Cristo prometeu\\nDar o perdão, por Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"No meu eterno lar não haverá temor,\\nNem lutas e aflições, nem mais tristeza ou dor;\\nE os redimidos já, ali receberão\\nAs boas-vindas do Senhor.\"}]},{\"number\":\"338\",\"collection_type\":\"Hinário\",\"title\":\"Brilho Celeste\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Peregrinando pelas montanhas,\\nDentro dos vales, sempre na luz,\\nCristo promete nunca deixar-me!\\n\\\"Eis-Me convosco\\\", disse Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Brilho celeste! Brilho celeste!\\nEnche minha alma, glória de Deus!\\nAleluia! Sigo cantando,\\nDando louvores, indo pra os Céus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se vejo sombras por toda parte,\\nAo Salvador não hão de ocultar!\\nPois Cristo é luz que nunca se apaga,\\nBem ao Seu lado sempre hei de andar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Luzes benditas vão-me guiando\\nEm meu caminho para Sião.\\nMais e mais perto o Mestre seguindo,\\nTenho alegria na salvação!\"}]},{\"number\":\"339\",\"collection_type\":\"Hinário\",\"title\":\"Inda é Longe Canaã?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O caminho é longo e mau, nossos pés feridos 'stão;\\nInda é longe Canaã? Inda é longe Canaã?\\nNo deserto anelamos mais e mais Sua proteção\\nEstará inda longe Canaã?\"},{\"section_type\":\"Coro\",\"content\":\"'Stamos fracos, tão cansados!...\\nJá viajamos por valados, por deserto abrasadorl\\n'Stamos fracos, tão cansados!\\nEstará inda longe Canaã?\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós seguimos, por desertos, o caminho do cristão;\\nInda é longe Canaã? Inda é longe Canaã?\\nQuantas vezes tem faltado nosso leito, nosso pão.\\nEstará inda longe Canaã?\"},{\"section_type\":\"Estrofe\",\"content\":\"Quanto anseiam nossas almas por um lar de paz e amor!\\nInda é longe Canaã? Inda é longe Canaã?\\nOnde não há mais pesares, não mais lutas, não mais dor.\\nEstará inda longe Canaã?\"}]},{\"number\":\"340\",\"collection_type\":\"Hinário\",\"title\":\"Saudade\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Da linda pátria estou mui longe, triste eu estou;\\nEu tenho de Jesus saudade; quando será que vou?!\\nPassarinhos, belas flores, fazem-me almejar\\nAs maravilhas e esplendores do meu celeste lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo me deu fiel promessa, vem me buscar;\\nMeu coração está com pressa, eu quero já voar.\\nMeus pecados eram muitos, e culpado sou,\\nMas o Seu sangue põe-me limpo, e para a pátria vou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Qual filho, do seu lar, saudoso, eu quero ir;\\nQual passarinho para o ninho, eu quero ao Céu subir.\\nÉ fiel, a vinda é certa; quando, não o sei,\\nMas Ele me achará alerta; com Ele ao Céu irei!\"}]},{\"number\":\"341\",\"collection_type\":\"Hinário\",\"title\":\"Vinde Fiéis\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vinde fiéis, as lutas e o labor\\nEnfrentai com fervor.\\nSem timidez, avante, pois, marchai,\\nSó em Deus confiai.\\nMelhor será assim lutar;\\nCuidados vãos irão passar.\\nAvante pois até vencer,\\nSem temor! Com prazer!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tendes temor? Pesada é vossa cruz?\\nContemplai a Jesus!\\nComo esperar a glória conquistar,\\nSem sair a lutar?\\nCoragem pois tomai então\\nE ireis sentir de Deus a mão;\\nE em breve assim Jesus dirá:\\nBem está! Bem está!\"},{\"section_type\":\"Estrofe\",\"content\":\"Logo entrareis no eterno lar de amor,\\nCom Jesus, Salvador.\\nRecebereis eterna vida e paz\\nQue Jesus sempre traz.\\nAli então louvor dareis\\nEm doce voz ao Rei dos reis;\\nE em meio à paz direis também:\\nGlória ao Rei! Glória ao Rei!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mas se afinal a morte nos chamar,\\nQue feliz há de ser\\nQuando Jesus a vida restaurar\\nAos fiéis, com poder.\\nOh, que prazer quando Jesus\\nVier dos Céus pra nos buscar!\\nDirá então ao povo Seu:\\nVinde ao lar! Vinde ao lar!\"}]},{\"number\":\"342\",\"collection_type\":\"Hinário\",\"title\":\"Grande Comandante\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Grande Comandante Cristo nos será,\\nNesta guerra santa à frente marchará;\\nNunca Suas hostes abandonará;\\nHá de até o fim lutar.\"},{\"section_type\":\"Coro\",\"content\":\"Sempre avante, manda o General.\\nSempre avante! guerra contra o mal!\\nFirmes, fortes, nunca vacilar!\\nCom Jesus havemos de ganhar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Seu pendão glorioso vamos defender,\\nHostes inimigas sempre combater;\\nNosso General por certo irá vencer.\\nSeguiremos a Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na feroz batalha temos proteção,\\nE afinal, em coro, junto à multidão,\\nEntoaremos todos a real canção,\\nQuando nós chegarmos lá\"}]},{\"number\":\"343\",\"collection_type\":\"Hinário\",\"title\":\"Vamos Batalhar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vamos batalhar, juntos pelejar,\\nTodos a lutar, vamos já.\\nEis que nosso Rei com as hostes vem\\nTão glorioso! Quem O vencerá?\"},{\"section_type\":\"Coro\",\"content\":\"Vamos, crentes, vamos já avante,\\nFirmes sempre, com o Rei da paz.\\nCristo é nosso forte Comandante,\\nEle é nosso General capaz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos avançar, sem temor alçar,\\nSim, fazer brilhar nossa luz.\\nTrevas vão fugir, glórias hão de vir,\\nVenham todos aclamar Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus, glorioso Pai, sempre à frente vai,\\nFirmes, pois, Lutar com ardor.\\nQuando o fim chegar, findo o batalhar,\\nVem-nos coroar, por Teu amor!\"}]},{\"number\":\"344\",\"collection_type\":\"Hinário\",\"title\":\"Ó Cristãos, Avante!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó cristãos, avante! Sem temor marchar!\\nPela cruz de Cristo, com ardor lutar.\\nCristo, o nosso Mestre, guia o batalhão;\\nNo calor da guerra ergue Seu pendão.\"},{\"section_type\":\"Coro\",\"content\":\"Ó cristãos, avante!\\nMarchar, marchar, marchar!\\nPela cruz de Cristo,\\nCom ardor lutar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó cristãos, avante, contra Satanás!\\nA Jesus seguindo, príncipe da paz.\\nNunca o inimigo prevalecerá!\\nCom as hostes santas Cristo vencerá!\"},{\"section_type\":\"Estrofe\",\"content\":\"Reinos pereceram, tronos e nações,\\nMas a Igreja vence, mesmo em aflições.\\nVamos, pois, avante, com fervor marchar,\\nRumo para a glória, nosso eterno lar.\"}]},{\"number\":\"345\",\"collection_type\":\"Hinário\",\"title\":\"Lutai por Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Lutai, lutai por Cristo! Soldados sois da cruz.\\nAlçai Seu estandarte, fazei brilhar a luz,\\nA fim de que outros vejam o amor que nos conduz\\nÀ mais feliz vitória, com Deus e com Jesus!\"},{\"section_type\":\"Coro\",\"content\":\"Lutai por Cristo,\\nSoldados sois da cruz!\\nAlçai Seu estandarte,\\nBem alto deixei brilhar a luz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Estai bem preparados ao toque do clarim;\\nSegui de perto a Cristo, até da luta o fim!\\nAs armas empunhando, cobertos de valor;\\nDispostos, bem ousados, marchai, pois, sem temor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, confiai em Cristo, na Sua proteção,\\nPois vem o fim da guerra, já vem a redenção!\\nEntão, fiéis soldados, em luz resplendereis;\\nNo lar do Rei da glória, em paz descansareis.\"}]},{\"number\":\"346\",\"collection_type\":\"Hinário\",\"title\":\"Cristãos, Despertai!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristãos, despertar e segui ao Senhor;\\nCom fé avançai e lutai com ardor!\\nSegui corajosos sem desfalecer,\\nAté que o Senhor vos conceda vencer.\"},{\"section_type\":\"Coro\",\"content\":\"Sempre lutar!\\nSim, combater!\\nTe que o Senhor\\nVos conceda vencer.\"},{\"section_type\":\"Estrofe\",\"content\":\"O escudo da fé prontamente empunhai;\\nCalçados os pés, nas fileiras entrai.\\nA causa do Mestre deveis defender,\\nAté que o Senhor vos conceda vencer.\"},{\"section_type\":\"Estrofe\",\"content\":\"E seja o que for que tenhais de enfrentar,\\nAtrás não volteis, para não fracassar.\\nNa luta renhida deveis combater,\\nAté que o Senhor vos conceda vencer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Confiai em Jesus, vosso bom General,\\nQue já triunfou sobre as hostes do mal.\\nSó Ele a Seus filhos na luz guiará,\\nE enfim o Senhor a vitória dará.\"}]},{\"number\":\"347\",\"collection_type\":\"Hinário\",\"title\":\"O Pendão Real\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Um pendão real vos entregou o Rei,\\nA vós, soldados Seus.\\nCorajosos, pois, de tudo o defendei,\\nMarchando para os Céus.\"},{\"section_type\":\"Coro\",\"content\":\"Com valor, sem temor,\\nPor Cristo prontos a sofrer;\\nBem alto erguei o Seu pendão,\\nFirmes sempre até morrer!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis que estão formados já os batalhões\\nDo grande usurpador.\\nDeclarai-vos hoje bravos campeões;\\nAvante, sem temor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quem tiver receio no seu coração,\\nE fraco se mostrar,\\nNão receberá o eterno galardão\\nQue Cristo tem pra dar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, sejamos todos a Jesus leais,\\nE a Seu real pendão.\\nOs que na batalha sempre são fiéis,\\nCom Ele reinarão.\"}]},{\"number\":\"348\",\"collection_type\":\"Hinário\",\"title\":\"Quantos Fiéis Descansam do Labor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quantos fiéis descansam do labor!\\nPor sua fé, por seu exemplo e amor,\\nA Ti, Jesus, nós damos o louvor.\\nAleluia! Aleluia!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu foste a Rocha forte, sem igual,\\nE na batalha, grande General;\\nNas densas trevas, brilho divinal.\\nAleluia! Aleluia!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que nós, Senhor, lutemos com valor,\\nIguais aos santos, nobres, com vigor,\\nAté galgarmos o eternal fulgor.\\nAleluia! Aleluia!\"},{\"section_type\":\"Estrofe\",\"content\":\"Um mais glorioso dia irá surgir,\\nE os santos todos hão de ao Céu subir.\\nAo Rei da glória irão, fiéis, servir.\\nAleluia! Aleluia!\"}]},{\"number\":\"349\",\"collection_type\":\"Hinário\",\"title\":\"Consolação\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que consolação tem meu coração,\\nDescansando no poder de Deus!\\nSigo com prazer neste meu viver,\\nDescansando no poder de Deus.\"},{\"section_type\":\"Coro\",\"content\":\"Descansando\\nNos eternos braços do meu Deus,\\nVou seguro\\nDescansando no poder de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre avante vou, bem contente estou,\\nDescansando no poder de Deus.\\nSinto a grande paz que me satisfaz,\\nDescansando no poder de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lutas hei de ter, mas hei de vencer,\\nDescansando no poder de Deus.\\nNão terei temor, onde quer que for,\\nDescansando no poder de Deus.\"}]},{\"number\":\"350\",\"collection_type\":\"Hinário\",\"title\":\"Eu Pertenço ao Meu Rei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu pertenço ao meu Rei, filho sou do Senhor,\\nNas eternas mansões morarei.\\nJá das glórias ouvi, lá da pátria de amor;\\nCom Seus filhos as desfrutarei.\"},{\"section_type\":\"Coro\",\"content\":\"Eu pertenço ao meu Rei, filho sou do Senhor;\\nEle nunca me esquece, eu o sei.\\nDar-me-á salvação por Seu grande favor,\\nE na glória perene estarei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu pertenço ao meu Rei, é por mim Seu amor;\\nSua paz e descanso terei.\\nSeu conforto me vem mitigar qualquer dor;\\nCom amor guardará Sua grei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu pertenço ao meu Rei, a promessa é real;\\nSalvará os que amarem Sua lei.\\nJunto ao trono de Deus, na cidade eternal,\\nCom os salvos um dia estarei.\"}]},{\"number\":\"351\",\"collection_type\":\"Hinário\",\"title\":\"Nunca me Deixar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Neste mundo, sozinho não quero nem posso avançar,\\nPois eu sou tão fraquinho, sem forças para lutar,\\nMas Jesus vai comigo, disposto sempre a salvar,\\nSim, Ele mesmo promete que nunca me há de deixar.\"},{\"section_type\":\"Coro\",\"content\":\"Nunca me deixar! Nunca me deixar!\\nPois Ele mesmo promete comigo caminhar.\\nNunca me deixar! Nunca me deixar!\\nPois Ele mesmo promete que nunca me há de deixar\"},{\"section_type\":\"Estrofe\",\"content\":\"Inimigos mui fortes procuram minh'alma vencer;\\nE se sozinho andasse, que poderia fazer?\\nCom Jesus ao meu lado, alegre posso avançar,\\nSim, Ele mesmo promete que nunca me há de deixar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nas tristezas da vida, nas dores e nas aflições,\\nNa calma ou na lida, ao virem as tentações,\\nCristo anda ao meu lado, comigo, para ajudar,\\nSim, Ele mesmo promete que nunca me há de deixar.\"}]},{\"number\":\"352\",\"collection_type\":\"Hinário\",\"title\":\"Meu Refúgio Está no Monte\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu refúgio está no monte,\\nOnde posso descansar\\nE beber da limpa fonte\\nDe água pura e salutar.\"},{\"section_type\":\"Coro\",\"content\":\"Bem cedinho e de tarde\\nSempre vou me refugiar;\\nVou subindo para o monte\\nA beber da limpa fonte,\\nBem cedinho e de tarde\\nVou com Cristo me encontrar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minha força está no monte,\\nOnde fico a meditar;\\nMeu poder provém da fonte,\\nQuando estou humilde a orar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minha glória está no monte\\nEm que Cristo padeceu,\\nOnde vejo a rubra fonte\\nDe Seu sangue que verteu.\"}]},{\"number\":\"353\",\"collection_type\":\"Hinário\",\"title\":\"Meu Jesus me Guia Sempre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus me guia sempre: que mais posso desejar?\\nDuvidar do meu Amado? De meu Deus desconfiar?\\nTenho paz perfeita infinda, gozo Sua proteção,\\nPois eu sei que por mim vela Seu bondoso coração,\\nPois eu sei que por mim vela Seu bondoso coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus me guia sempre, ensinando-me a viver,\\nConcedendo graça e força para me desenvolver;\\nPerecer jamais eu posso, pois quem pode resistir\\nAo Deus forte, Pai eterno, que minh'alma quis remir?\\nAo Deus forte, Pai eterno, que minh'alma quis remir?\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus me guia sempre, pelo Seu tão terno amor!\\nVida santa, glória eterna me garante o Salvador.\\nOh! mui breve vem o dia, o da grande redenção,\\nQuando salva, transformada, há de ser a criação!\\nQuando salva, transformada, há de ser a criação!\"}]},{\"number\":\"354\",\"collection_type\":\"Hinário\",\"title\":\"Entrega a Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Entrega a Deus as tuas horas tristes,\\nQuando ninguém te pode confortar;\\nRecorre a Deus, pois paz deseja dar\\nAo coração quebrantado pela dor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Entrega a Deus as tuas amarguras;\\nSem hesitar, confia-Lhe tua dor.\\nNão deixará que sombras de temor\\nCubram teu ser de tristezas e pesar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Entrega a Deus as lutas desta vida;\\nSem mais tardar, entrega-Lhe teu ser,\\nPois, afinal, sem dor e sem sofrer,\\nDescansarás para sempre em Seu lar.\"}]},{\"number\":\"355\",\"collection_type\":\"Hinário\",\"title\":\"Oh, Não Temas, Sou Contigo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se a fé por vezes falta,\\nQuando o Sol não posso ver,\\nA Jesus eu digo humilde:\\nOh, vem meu Piloto ser.\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Oh, não temas, sou contigo,\\nTeu Piloto até o fim!\\nNão te importes co'o perigo;\\nEis a mão, confia em Mim.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando a tentação me envolve\\nE não posso a Cristo ver,\\nEis que em meio à tempestade,\\nOuço o Salvador dizer:\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando a alma está ferida\\nPelas ondas da aflição,\\nVolvo o olhar ao meu Piloto,\\nE este canto escuto então:\"},{\"section_type\":\"Estrofe\",\"content\":\"Se do mar à praia chego,\\nMesmo havendo turbilhão,\\nVejo meu Piloto ao lado,\\nCreio em Sua direção.\"}]},{\"number\":\"356\",\"collection_type\":\"Hinário\",\"title\":\"Conduze-me, Meu Mestre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Conduze-me, meu Mestre, com Tua mão,\\nE assim jamais me falte a proteção.\\nNão quero nem um passo sem Ti andar.\\nOh, faze-me hoje e sempre na luz trilhar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Teu amor envolve meu coração,\\nE dá-lhe paz e calma em aflição.\\nQue eu tenha em Ti repouso bem junto à cruz,\\nE que jamais me afaste de Ti, Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"E mesmo quando a luta tremenda for,\\nSeguro hás de guiar-me, meu Redentor.\\nConduze-me, meu Mestre, com Tua mão,\\nE assim jamais me falte a proteção.\"}]},{\"number\":\"357\",\"collection_type\":\"Hinário\",\"title\":\"Sob Suas Asas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sob Suas asas estou descansando,\\nInda que noite, confiante eu estou;\\nSob Suas asas vou sempre abrigado,\\nFui redimido e Seu filho já sou.\"},{\"section_type\":\"Coro\",\"content\":\"Descansarei, descansarei\\nSob Suas asas benditas,\\nAo Seu abrigo, pois, gozarei\\nPaz e alegria infinitas.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sob Suas asas refúgio eu encontro,\\nMeu coração poderá descansar.\\nE se este mundo não presta socorro,\\nSob Suas asas a paz hei de achar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sob Suas asas promessa preciosa!\\nSempre me posso do mal ocultar.\\nSalvo em Jesus e confiante na graça,\\nNada no mundo me pode abalar.\"}]},{\"number\":\"358\",\"collection_type\":\"Hinário\",\"title\":\"Guia, Cristo, Minha Nau\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Guia, Cristo, minha nau\\nSobre o revoltoso mar.\\nTão enfurecido e mau,\\nQuer fazê-la naufragar.\\nVem, Jesus, oh, vem guiar,\\nMinha nau vem pilotar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Como sabe serenar\\nBoa mãe o filho seu,\\nVem, acalma assim o mar\\nQue se eleva até ao céu;\\nVem, Jesus, oh, vem guiar,\\nMinha nau vem pilotar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se, no porto, quando entrar,\\nMais o mar se enfurecer,\\nQue me possa deleitar\\nEm ouvir Jesus dizer:\\n\\\"Entra, pobre viajor,\\nNo descanso do Senhor.\\\"\"}]},{\"number\":\"359\",\"collection_type\":\"Hinário\",\"title\":\"Dia a Dia\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dia a dia, em todos os momentos,\\nForça encontro em lutas ou labor,\\nPois de Deus recebo sempre alento;\\nQue razão terei eu pra temor?\\nDeus, que é bom, e sábio e compassivo,\\nCada dia dá-me o que é melhor.\\nUma dor, e logo um lenitivo;\\nLuta e paz eu sinto em derredor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cada dia Deus está bem perto,\\nE conselhos dEle posso obter;\\nSegurança e auxílio em tempo certo\\nMe concede pelo Seu poder.\\nCom carinho Deus protege e guia,\\nQual zeloso pai, os filhos Seus;\\n\\\"Dar-te-ei poder a cada dia\\\"\\nÉ a certeza que Ele ofereceu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero, ó Deus, em cada sofrimento,\\nConfiar em Teu cuidado e amor.\\nE com fé, eu permaneça atento\\nÀs promessas Tuas, meu Senhor.\\nE que eu possa, em lutas, dores, trevas,\\nAceitar, ó Deus, de Tua mão,\\nUm a um, os dias que me entregas,\\nNesta minha peregrinação.\"}]},{\"number\":\"360\",\"collection_type\":\"Hinário\",\"title\":\"Fixa Teus Olhos no Mestre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se amargas tristezas da vida\\nCurvarem-te a fronte em dor,\\nE vendo a esperança perdida,\\nCaíres nas mãos do temor,\"},{\"section_type\":\"Coro\",\"content\":\"Fixa teus olhos no Mestre,\\nConfia no bom Salvador;\\nFruirás, na luta terrestre,\\nMaravilhas do Seu doce amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se as ondas cruéis do oceano\\nQuiserem a nave tragar,\\nE as vagas do mal tão insano\\nFizerem-te a fé vacilar,\"},{\"section_type\":\"Estrofe\",\"content\":\"Se aflito, sem fé, sem coragem,\\nVagando nas sendas do mal,\\nDo mundo seguindo a miragem,\\nNão ouves a voz divinal,\"}]},{\"number\":\"361\",\"collection_type\":\"Hinário\",\"title\":\"Ó Tu Que Aflito Estás\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó tu que aflito estás, Deus, Pai bondoso,\\nEm compaixão e amor, quer te livrar;\\nQuer te salvar do mal, quer dar-te gozo.\\nVem logo a Cristo, e paz hás de achar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó meu irmão, se tens grandes tormentos,\\nPõe tua mente em Deus, teu Protetor.\\nSó Ele irá banir teus sofrimentos,\\nSó Ele pode curar tua dor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se pesaroso estás em tua lida,\\nBusca teu Redentor, Cristo Jesus;\\nSeu tão profundo amor traz luz e vida,\\nDá forças para levar tua cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que consolação temos em Cristo,\\nPois da tristeza e dor nos livrará!\\nSempre sustenta os Seus, somos benquistos,\\nEle nos ama e forças nos dá.\"}]},{\"number\":\"362\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Ajudará\",\"author\":\"Ada Ruth Habershon (1861-1918) / Robert Harkness (1880-1961)\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vacilando minha fé,\\nCristo ajudará.\\nPerseguido, sem mercê,\\nCristo ajudará.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo ajudara,\\nSim, me ajudara!\\nSeu amor por mim não muda;\\nSempre ajudara.\"},{\"section_type\":\"Estrofe\",\"content\":\"Crente inútil eu serei\\nSe não me valer,\\nNem serviço prestarei,\\nSem o Seu poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com Seu sangue me comprou,\\nNão me deixará;\\nVida eterna me outorgou;\\nSim, me ajudará.\"}]},{\"number\":\"363\",\"collection_type\":\"Hinário\",\"title\":\"Terra de Beulá\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouço ao longe sons de lutas, brados de batalha,\\nÉ a Terra envolta em guerra de pecado e dor;\\nMas as coisas deste mundo já não me perturbam,\\nPois habito em Terra de Beulá.\"},{\"section_type\":\"Coro\",\"content\":\"Vivo no alto da montanha,\\nSob um céu de puro azul,\\nJunto à fonte de águas vivas,\\nQue nunca secara,\\nE me alimento cada dia\\nDesse bom maná do Céu,\\nPois habito em Terra de Beulá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá distante a tempestade ruge sobre o mundo;\\nDúvidas, temores grassam em todo lugar;\\nMas estou bem firme na Palavra de meu Deus,\\nPois habito em Terra de Beulá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nem as nuvens mais escuras podem assustar-me;\\nEu não temo pois seguro estou nas mãos de Deus;\\nVivo à luz do Sol e da presença de meu Rei,\\nPois habito em Terra de Beulá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando aqui eu vejo, de meu Deus, as maravilhas,\\nQuedo-me silente e adoro em contemplação;\\nCompreendo Seu amor e a grande salvação,\\nPois habito em Terra de Beulá.\"}]},{\"number\":\"364\",\"collection_type\":\"Hinário\",\"title\":\"Sombras\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Muita vez das tristes sombras nós falamos,\\nAo seguirmos pela senda rumo ao lar;\\nMas as sombras, as mais densas, olvidamos,\\nQuando ao Sol, então, volvemos nosso olhar.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo é o Sol que resplandece em nossa estrada,\\nSombras vemos ao as costas Lhe voltar,\\nVamos pois olhar a Cristo na jornada,\\nE veremos toda sombra se afastar\"},{\"section_type\":\"Estrofe\",\"content\":\"Se o espírito sentires perturbado,\\nÉ porque à luz as costas deste já;\\nOlha a Cristo que teu coração cansado,\\nInundado por Sua doce luz será.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos, pois, volver a Cristo a alma aberta,\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele que é do mundo a radiante luz,\\nE das sombras desta vida nos liberta;\\nE, felizes, seguiremos a Jesus.\"}]},{\"number\":\"365\",\"collection_type\":\"Hinário\",\"title\":\"Vede o Lírio a Florescer\",\"author\":\"Melodia Tradicional Alemã\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vede o lírio a florescer, terna e bela flor do prado!\\nQuem assim o fez crescer, e por ele tem cuidado?\\nQuem assim o adornou, de beleza o dotou,\\nPra viver no lindo prado, sim, no lindo prado?\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus foi quem o fez crescer, e lhe deu graça e beleza,\\nPra alegrar nosso viver e afastar-nos a tristeza;\\nPara a todos ensinar que a Deus devem olhar,\\nE confiar em Sua graça, sim, em Sua graça.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eia, pois, meu coração, abandona teus cuidados;\\nDeixa teus anseios vãos, Deus é nosso Pai amado.\\nQuem os lírios faz crescer, não nos deixa perecer;\\nSomos pelo Pai lembrados, sim, do Pai lembrados.\"}]},{\"number\":\"366\",\"collection_type\":\"Hinário\",\"title\":\"O Anjo do Senhor\",\"author\":\"Franklin Edson Belden (1858-1945)\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O anjo do Senhor se acampa\\nAo redor dos que O temem;\\nEle os guarda dia e noite,\\nSem cessar.\"},{\"section_type\":\"Coro\",\"content\":\"Ó nuvem luzente, nuvem de glória,\\nGuia, guia-nos ao Céu!\\nO nuvem luzente, nuvem de glória,\\nGuia, guia-nos ao Céu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando em temores e perigos,\\nO Senhor nos tem guardado;\\nSob as Suas santas asas,\\nTemos paz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Tua direção confiamos,\\nAtravés deste deserto,\\nTé à Canaã chegarmos,\\nLá no Céu.\"}]},{\"number\":\"367\",\"collection_type\":\"Hinário\",\"title\":\"Ao Passares Pelas Águas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"\\\"Ao passares pelas águas, serei contigo;\\nAo passares pelas águas, serei contigo.\\nRios caudalosos a ti não podem submergir;\\nAo passares pelo fogo não, oh, não te queimarás!\\nAo passares pelas águas, serei contigo;\\nAo passares pelas águas, serei contigo.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Ao passares pelas águas, serei contigo;\\nAo passares pelas águas, serei contigo.\\nAs duras provas a ti não podem derrotar;\\nSe por Minha causa sofres, Tu me glorificarás.\\nAo passares pelas águas, serei contigo;\\nAo passares pelas águas, serei contigo.\\\"\"}]},{\"number\":\"368\",\"collection_type\":\"Hinário\",\"title\":\"Mágoas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se tens mágoas volve agora a Cristo,\\nO melhor Amigo que tu tens,\\nEis que está a ti sempre achegado,\\nPronto a dar-te Seus melhores bens.\"},{\"section_type\":\"Coro\",\"content\":\"Leva a Cristo as tuas mágoas,\\nVai com Ele ter, vai sem mesmo te deter,\\nLeva a Cristo as tuas mágoas\\nQue Ele as muda todas em prazer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se a ingratidão ferir-te a alma,\\nSe amarguras vêm ao coração,\\nVê então que Cristo está ao lado,\\nE te dá consolo na aflição.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo compreende as tuas dores,\\nQuer tua alma enferma restaurar,\\nOh, confia em Seu amor imenso,\\nQue só Ele pode alívio dar!\"}]},{\"number\":\"369\",\"collection_type\":\"Hinário\",\"title\":\"Segura Minha Mão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Com Tua mão segura bem a minha,\\nPois eu tão fraco sou, ó Salvador,\\nQue não me atrevo a dar nenhum só passo\\nSem Teu amparo, meu Jesus, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com Tua mão segura bem a minha,\\nE faz-me assim mais firme em Ti, Jesus;\\nPor Teu poder, que eu nunca me desvie\\nDe Ti, Senhor, a minha vida e luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com Tua mão segura bem a minha,\\nE pelo mundo alegre seguirei;\\nMesmo onde as sombras caem mais escuras,\\nTeu rosto vendo, nada temerei.\"},{\"section_type\":\"Estrofe\",\"content\":\"E se eu chegar à beira desse rio,\\nQue Tu por mim quiseste atravessar,\\nCom Tua mão segura bem a minha,\\nE sobre a morte hei de triunfar.\"}]},{\"number\":\"370\",\"collection_type\":\"Hinário\",\"title\":\"Cada Momento\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sendo remido por Cristo na cruz,\\nSinto prazer caminhando na luz,\\nCheio da graça que vem de Jesus;\\nCada momento o Senhor me conduz.\"},{\"section_type\":\"Coro\",\"content\":\"Cada momento me guia o Senhor,\\nCada momento dispensa favor.\\nSua presença me outorga vigor;\\nCada momento sou Teu, ó Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Junto com Cristo na luta moral,\\nContra o pecado, o engano e o mal,\\nErgo bem alto a bandeira real,\\nCada momento mais firme e leal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nas minhas lutas me pode amparar,\\nE do maligno também me livrar;\\nCada momento por onde eu andar,\\nCristo, meu Mestre, me pode amparar.\"}]},{\"number\":\"371\",\"collection_type\":\"Hinário\",\"title\":\"Cuidará de Mim Também\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Por que estarei eu triste, por que na treva andar,\\nSentir-me tão sozinho, sempre a desanimar,\\nSe Cristo é meu conforto, amigo na aflição,\\nSe até as aves esperam na Sua proteção?\\nSe até as aves esperam na Sua proteção?\"},{\"section_type\":\"Coro\",\"content\":\"Feliz e mui alegre,\\nCantando viverei;\\nSe Deus protege as aves,\\nCuidará de mim também.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando estou abatido, se envolto em sombra vou,\\nO coração ferido, ou perseguido sou,\\nJesus é meu amparo, é meu consolador,\\nEnvolve-me em Seus braços e alívio dá-me à dor;\\nEnvolve-me em Seus braços e alívio dá-me à dor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao me sentir cansado, em meio de aflição,\\nOuço Jesus dizer-me, ao segurar-me a mão:\\n\\\"Confia em Mim somente, somente em Meu poder,\\nE nas mansões eternas, comigo irás viver;\\nE nas mansões eternas, comigo irás viver.\\\"\"}]},{\"number\":\"372\",\"collection_type\":\"Hinário\",\"title\":\"Meu Jesus me Guia os Passos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Todos falam dos perigos\\nDo caminho em que eu estou,\\nMas não vêem a luz que brilha\\nAo redor por onde vou.\"},{\"section_type\":\"Coro\",\"content\":\"Meu Jesus me guia os passos,\\nPois já veio em mim morar;\\nNeste mundo perigoso,\\nSó por mim não posso andar\"},{\"section_type\":\"Estrofe\",\"content\":\"Falam só de muito engano\\nE de dura provação;\\nMas Jesus me ampara sempre\\nE me dá consolação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sei que meu amor é fraco,\\nSou propenso a pecar,\\nMas, com Seu divino auxílio,\\nHei de sempre triunfar.\"}]},{\"number\":\"373\",\"collection_type\":\"Hinário\",\"title\":\"Deus Cuidará de Ti\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Aflito e triste coração,\\nDeus cuidará de ti;\\nPor ti opera a Sua mão;\\nDeus cuidará de ti.\"},{\"section_type\":\"Coro\",\"content\":\"Deus cuidara de ti,\\nEm cada dia proverá,\\nSim, cuidará de ti;\\nDeus cuidará de ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na dor cruel, na provação,\\nDeus cuidará de ti;\\nSocorro dá e proteção;\\nDeus cuidará de ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sentes a fé a vacilar?\\nDeus cuidará de ti;\\nAo teu amor quer forças dar;\\nDeus cuidará de ti.\"}]},{\"number\":\"374\",\"collection_type\":\"Hinário\",\"title\":\"Abrigo na Rocha\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus, amoroso e fiel Salvador,\\nTão maravilhoso pra mim!\\nNo abrigo da rocha me esconde ao calor,\\nE dá-me alegria sem fim.\"},{\"section_type\":\"Coro\",\"content\":\"No abrigo da rocha me esconde ao calor,\\nEm árida terra de sol;\\nOculta minh'alma em Seu plácido amor,\\nE cobre-me com Sua mão,\\nSim, cobre-me com Sua mão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, amoroso e fiel Salvador,\\nAfasta-me a carga e o pesar;\\nRestaura-me as forças, renova o fervor,\\nE assim já não temo lutar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Coroa-me as horas com bênçãos a flux;\\nNos lábios me põe o louvor;\\nCantando, contente, dou glória a Jesus,\\nExcelso e leal Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"E enfim, quando em glória eu feliz ressurgir,\\nE for meu Jesus abraçar,\\nDelícias perenes eu hei de fruir,\\nNo reino sublime, sem-par.\"}]},{\"number\":\"375\",\"collection_type\":\"Hinário\",\"title\":\"Ao Tomar Minha Frágil Mão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dias turvos há em que busco em vão\\nO semblante de meu Jesus,\\nMas em meio às trevas vislumbro a luz\\nAo Jesus me tomar a mão.\"},{\"section_type\":\"Coro\",\"content\":\"Ao tomar minha frágil mão,\\nAo tomar minha frágil mão,\\nSinto vir do além força em Seu poder,\\nAo Jesus me tomar a mão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando as forças faltam no jornadear,\\nE me vem tentação vulgar,\\nSinto a fé voltar e me animo então,\\nAo Jesus me tomar a mão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando a noite vem e não posso ver\\nQue caminho seguir então,\\nFulgurante luz vejo resplender,\\nAo Jesus me tomar a mão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando o instante atroz, derradeiro, enfim,\\nFor chegado também a mim,\\nHá de estar em calma meu coração,\\nAo Jesus me tomar a mão.\"}]},{\"number\":\"376\",\"collection_type\":\"Hinário\",\"title\":\"Guia-me, Meu Salvador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Guia-me, meu Salvador!\\nSempre me conduz, Senhor!\\nSim, seguro e forte estou,\\nPois contigo andando vou.\"},{\"section_type\":\"Coro\",\"content\":\"Guia, guia,\\nSempre guia, Salvador!\\nCom ternura, com amor,\\nGuia-me, meu Redentor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sob a Tua proteção,\\nFirme está meu coração\\nOh, dirige-me, Senhor,\\nNeste mundo enganador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu me guiarás a mim,\\nTé chegar da vida o fim;\\nE ao voltares, ó Jesus,\\nEu habitarei na luz.\"}]},{\"number\":\"377\",\"collection_type\":\"Hinário\",\"title\":\"Refúgio em Temporal\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eterna rocha é meu Jesus,\\nRefúgio sempre em temporal.\\nA confiança nele eu pus,\\nRefúgio sempre em temporal.\"},{\"section_type\":\"Coro\",\"content\":\"Rocha eterna, nossa proteção,\\nNosso abrigo, nosso Salvador,\\nSempre certo na tribulação,\\nPresente sempre em nossa dor\"},{\"section_type\":\"Estrofe\",\"content\":\"Defesa forte e proteção,\\nRefúgio sempre em temporal;\\nNão temeremos provação,\\nRefúgio sempre em temporal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Rocha eterna, meu Jesus,\\nRefúgio sempre em temporal,\\nSê Tu meu guia, força e luz,\\nRefúgio sempre em temporal.\"}]},{\"number\":\"378\",\"collection_type\":\"Hinário\",\"title\":\"Alguém me Vê\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando na luta me falta poder,\\nAlguém me vê, Alguém me vê.\\nE se tristezas me vêm abater,\\nAlguém me vê: é Cristo.\"},{\"section_type\":\"Coro\",\"content\":\"Alguém me vê, Alguém me vê,\\nQuando me oprimem as vis tentações.\\nNunca me encontro sozinho,\\nAlguém me vê: é Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando há pesares em meu coração,\\nAlguém me vê, Alguém me vê;\\nSe sobre mim desce o véu da aflição,\\nAlguém me vê: é Cristo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando me ferem as setas do mal,\\nAlguém me vê, Alguém me vê.\\nQuando em saudade do lar celestial,\\nAlguém me vê: é Cristo.\"}]},{\"number\":\"379\",\"collection_type\":\"Hinário\",\"title\":\"Ó Mestre, o Mar se Revolta\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó Mestre, o mar se revolta, as ondas nos dão pavor!\\nO céu se reveste de trevas, não temos um salvador!\\nNão se Te dá que morramos? Podes assim dormir,\\nSe a cada momento nos vemos já prestes a submergir?\"},{\"section_type\":\"Coro\",\"content\":\"\\\"As ondas atendem ao Meu mandar: Sossegai!\\nQuer seja este revolto mar,\\nA ira dos homens, o gênio do mal,\\nTais águas não podem a nau tragar,\\nQue leva o Senhor, Rei do céu e mar,\\nPois todos ouvem o Meu mandar:\\nSossegai! Sossegai!\\nConvosco estou para vos salvar;\\nSim, sossegai.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Mestre, na minha tristeza estou quase a sucumbir.\\nA dor que perturba minh'alma, eu peço-Te, vem banir!\\nDe ondas do mar que me encobrem, quem me fará sair?\\nPereço sem Ti, ó meu Mestre! Vem logo, vem me acudir!\"},{\"section_type\":\"Estrofe\",\"content\":\"Mestre, chegou a bonança, em paz eis o céu e o mar!\\nO meu coração goza calma que não poderá findar.\\nFica comigo, ó meu Mestre, dono da Terra e Céu,\\nE assim chegarei bem seguro ao porto, destino meu.\"}]},{\"number\":\"380\",\"collection_type\":\"Hinário\",\"title\":\"Ó Amante de Minh'Alma\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó Amante de minh'alma, deixa-me em Teu peito estar,\\nQuando o vento rouba a calma, quando brame irado o mar.\\nGuarda-me, bom Salvador, té o temporal passar;\\nGuia-me em Teu terno amor, quero em Ti me refugiar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Só em Ti eu tenho abrigo, aos Teus pés está meu ser;\\nNão me deixes, sê comigo, Teu conforto eu quero ter.\\nSó confio em Ti, Senhor, meu auxílio de Ti vem;\\nTu dissipas o temor, e o Teu braço me sustém.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu encerras quanto anseio, sim, e mais, e muito mais;\\nJá não tenho mais receio, mesmo em meio a vendavais.\\nJusto e santo és Tu, Jesus, só fraqueza habita em mim;\\nAndarei em Tua luz, bem seguro até o fim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tua graça inesgotável pode me lavar do mal;\\nTeu amor incomparável puro e bom faz-me, afinal.\\nFonte eterna, meu Jesus, manancial de todo bem,\\nCom ternura me conduz, ao eterno lar. Amém.\"}]},{\"number\":\"381\",\"collection_type\":\"Hinário\",\"title\":\"Jesus Proverá\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó tu que, cansado, só buscas a luz,\\nDo mundo enfadado, te apegas à cruz,\\nNão tenhas cuidado do que sobrestá:\\nSe doenças, se mágoas, Jesus proverá!\"},{\"section_type\":\"Coro\",\"content\":\"Jesus proverá!\\nSim, crê, pecador,\\nNas ricas promessas\\nDo teu Redentor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se laços amigos ameaçam quebrar,\\nJesus é contigo, te pode amparar.\\nNas lutas renhidas Seu braço te dá.\\nPor que te afadigas? Jesus proverá!\"},{\"section_type\":\"Estrofe\",\"content\":\"No fim desta lida, feliz entrarás,\\nVencida a fadiga, no reino da paz.\\nDo mundo os cuidados não mais haverá,\\nSerão dissipados, Jesus proverá!\"}]},{\"number\":\"382\",\"collection_type\":\"Hinário\",\"title\":\"Não Ando Só\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não ando só, pois Cristo me acompanha\\nPor toda a parte, aonde quer que eu for;\\nMeu coração se alegra em Sua graça,\\nE quantos queiram, fruem Seu amor.\"},{\"section_type\":\"Coro\",\"content\":\"Não ando só, Jesus ao lado tenho,\\nE nEle achei Amigo sem igual.\\nDe tal Amigo apoio e guia obtenho;\\nNão ando só, pois Ele me é real.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não ando só, em meio à tempestade;\\nMesmo que o vento esteja a me açoitar,\\nSeguro vou pois Cristo está comigo,\\nE os braços Seus estão a me rodear.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não ando só, se as tentações me assaltam,\\nComigo está Jesus a me guiar,\\nE quando enfim eu for ao lar eterno,\\nAinda ali com Ele eu hei de andar.\"}]},{\"number\":\"383\",\"collection_type\":\"Hinário\",\"title\":\"Importará?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Importará ao Senhor Jesus\\nQue eu viva sempre a sofrer,\\nTendo o coração cheio de aflição?\\nSentirá meu triste viver?\"},{\"section_type\":\"Coro\",\"content\":\"Oh! sim, eu sei, Jesus bem vê\\nO que eu estou a sofrer!\\nEm cruel peleja, pavor, inveja,\\nJesus me quer valer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Importará ao Senhor Jesus\\nQue eu viva com dissabor?\\nQue me falte a luz, a que vem da cruz?\\nSentirá o meu Salvador?\"},{\"section_type\":\"Estrofe\",\"content\":\"Importará ao Senhor Jesus\\nQue eu caia na tentação?\\nE se o mal puder minha fé vencer,\\nDar-me-á de novo o perdão?\"},{\"section_type\":\"Estrofe\",\"content\":\"Importará ao Senhor Jesus\\nSe a morte ferir meu lar?\\nSe eu disser adeus aos queridos meus,\\nSentirá, Jesus, meu pesar?\"}]},{\"number\":\"384\",\"collection_type\":\"Hinário\",\"title\":\"Jesus me Guia\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus me guia, que prazer!\\nQue paz me vem ao coração!\\nEm todo transe em que estiver\\nMe guia sempre a Sua mão.\"},{\"section_type\":\"Coro\",\"content\":\"Jesus me guia, que prazer!\\nÉ Sua mão que me conduz.\\nEm cada passo me é mister\\nQue me dirija meu Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Às vezes, quando em aflição,\\nEm meio de perigo e dor,\\nPor água mansa ou bravo mar\\nMe guia a mão do meu Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ajuda-me a não murmurar\\nQualquer que seja a condição;\\nContente vou, pois guiarás\\nCom Tua mui bondosa mão.\"}]},{\"number\":\"385\",\"collection_type\":\"Hinário\",\"title\":\"Deus Está nas Sombras\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se da noite as sombras te cercarem,\\nE a obra finda parecer,\\nAmanhã risonho, Deus promete,\\nSem mais nuvens negras a temer.\"},{\"section_type\":\"Coro\",\"content\":\"Sombras, Deus está nas sombras;\\nFirme é Seu amor em cuidar de nós.\\nSombras, Deus está nas sombras;\\nNão nos deixará lutar em dor, a sós.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se a Jesus anelas ver nas sombras,\\nSe anseias dele Seu amor,\\nHás de achar o Salvador ao lado,\\nUm constante amigo e protetor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando as sombras o meu céu toldarem,\\nMesmo que o sol não possa ver,\\nEm Jesus encontro meu refúgio,\\nNas tormentas deste meu viver.\"}]},{\"number\":\"386\",\"collection_type\":\"Hinário\",\"title\":\"Nunca te Deixarei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! como é grande e doce a promessa\\nDo Salvador, Jesus, nosso Rei!\\nAo que confia na Sua graça,\\nEle diz: \\\"Sempre te guardarei.\\\"\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Ó, não temas, ó, não temas,\\nPois Eu contigo sempre serei!\\nÓ, não temas, ó, não temas,\\nPois Eu nunca te deixarei.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Eu sou teu Deus e para livrar-te\\nDe ti bem perto sempre estarei;\\nNão tenhas medo, pois, bem seguro,\\nEu pela mão te conduzirei.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Para remir-te dei o Meu sangue,\\nPelo teu nome já te chamei;\\nMeu para sempre tu és agora,\\nCrê pois, que nunca te deixarei.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Eras indigno, mas escolhi-te;\\nNão temas, pois Eu muito te amei.\\nQuem dos Meus braços pode arrancar-te?\\nSempre seguro te guardarei.\\\"\"}]},{\"number\":\"387\",\"collection_type\":\"Hinário\",\"title\":\"Deus vos Guarde\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus vos guarde pelo Seu poder,\\nProtegidos e velados,\\nDesfrutando Seus cuidados;\\nDeus vos guarde pelo Seu poder.\"},{\"section_type\":\"Coro\",\"content\":\"Pelo Seu poder e no Seu amor,\\nTé nos encontrarmos com Jesus.\\nPelo Seu poder e no Seu amor,\\nOh, que Deus vos guarde em Sua luz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus vos guarde em Seu eterno amor,\\nBem unidos e contentes,\\nAchegados sempre aos crentes;\\nDeus vos guarde em Seu eterno amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus vos guarde do poder do mal,\\nDa ruína e do pecado,\\nMui felizes ao Seu lado;\\nDeus vos guarde do poder do mal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus vos guarde para o Seu louvor,\\nSeu serviço tão glorioso,\\nUm viver mui vitorioso;\\nDeus vos guarde para o Seu louvor.\"}]},{\"number\":\"388\",\"collection_type\":\"Hinário\",\"title\":\"Vem, Alma Cansada\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem, alma cansada, tão cheia de dor;\\nVem, traze teus fardos aos pés do Senhor.\\nA Cristo confia teu grande pesar,\\nPois nEle descanso tu podes achar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mágoas e tristezas, vem, traze ao Senhor;\\nNão, oh, não receies vir tudo Lhe expor.\\nDo mal que te oprime, te pode curar.\\nTem Ele o desejo de te confortar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se tu já provaste tal consolação,\\nVai, leva aos contritos luz, paz e perdão;\\nAs almas aflitas, em lutas e dor,\\nVai, traze-as depressa aos pés do Senhor.\"}]},{\"number\":\"389\",\"collection_type\":\"Hinário\",\"title\":\"Nas Agruras Desta Vida\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nas agruras desta vida,\\nNo descanso ou no labor,\\nDá-me força na fadiga,\\nVem guardar-me o Salvador.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, me ampara! Oh, me abriga,\\nOnde o mal chegar não possa!\\nSim, me ampara! Sim, me abriga!\\nSê Tu, pois, minha salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os perversos só me odeiam,\\nE me querem destruir;\\nMas os anjos me rodeiam,\\nNão me deixam sucumbir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mesmo que o mal me assalte,\\nVacilar não poderei;\\nMesmo que a força falte,\\nPor Jesus eu vencerei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu, enquanto neste mundo,\\nTenho sempre que lutar,\\nMas de Cristo o amor profundo,\\nCerto, faz-me descansar.\"}]},{\"number\":\"390\",\"collection_type\":\"Hinário\",\"title\":\"Olhando Para Cima\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, mantém teu olhar pra o Céu,\\nPra sentir o poder do amor;\\nEis que Deus responderá\\nA oração do pecador\\nQue buscar Sua mão.\"},{\"section_type\":\"Coro\",\"content\":\"Ó, mantém teu olhar pra o Céu,\\nSó Jesus dará poder.\\nSua paz hás de então sentir,\\nE conforto receber.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Jesus deves confiar\\nTeus pesares, teu prantear,\\nE verás que lá do Céu\\nHás de forças receber\\nPra vencer todo mal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao olhar para o Salvador,\\nNova vida vais receber,\\nE em luz sempre andarás,\\nE desejo hás de ter\\nDe servir a Jesus.\"}]},{\"number\":\"391\",\"collection_type\":\"Hinário\",\"title\":\"Cada Vez Mais Puro\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cada vez mais puro faz-me o coração,\\nMais e mais buscando Tua direção,\\nSendo confiante sempre em Ti, Senhor,\\nFirme em Tua força, salvo em Teu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cada vez mais calmo ao cercar-me a dor,\\nCheio de paciência onde quer que for;\\nDá-me mais bondade, mais resignação\\nAos divinos planos, sob a Tua mão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cada vez mais santo, sempre mais leal,\\nFaz-me firme e forte sempre contra o mal.\\nQuero herdar a vida de bondade e luz,\\nEm Teu lar eterno, ó meu bom Jesus.\"}]},{\"number\":\"392\",\"collection_type\":\"Hinário\",\"title\":\"Bem Junto a Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem junto a Cristo eu quero estar,\\nBem junto a cruz doce paz desfrutar.\\nSim, ao teu peito eu busco a paz,\\nPois teu amor divinal satisfaz!\\nPois teu amor divinal satisfaz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não trago nada mais ao Senhor,\\nSó este meu coração pecador,\\nMas te suplico em contrição,\\nOh salvador dá-me paz e perdão!\\nOh Salvador dá-me paz e perdão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, quero a Cristo junto estar,\\nTé lá no além conseguir aportar.\\nOh, lar eterno, lar de esplendor!\\nLá estarei junto ao meu Salvador.\\nLá cantarei todo o Seu grande amor.\"}]},{\"number\":\"393\",\"collection_type\":\"Hinário\",\"title\":\"Sentado às Ribas d'Água Viva\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sentado às ribas d'água viva,\\nQue corre salutar,\\nSequioso busco haurir a vida\\nQue dela sei manar.\"},{\"section_type\":\"Coro\",\"content\":\"Sentado às ribas d'água viva,\\nSantas ribas d'água viva,\\nQuero haurir divina vida,\\nQuero a sede mitigar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cansado da penosa lida,\\nAnseio repousar,\\nE nessa fonte d'água viva\\nMinh'alma restaurar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, vem provar dessa água viva\\nQue Cristo quer te dar.\\nÉ água que renova a vida\\nE a sede faz cessar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O que beber dessa água viva\\nDe novo nascerá,\\nE, lá no Céu, do rio da vida\\nUm dia beberá.\"}]},{\"number\":\"394\",\"collection_type\":\"Hinário\",\"title\":\"De Ti Careço, ó Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"De Ti careço, ó Deus,\\nHabita, pois, em mim,\\nE vencedor serei\\nFiel até o fim.\"},{\"section_type\":\"Coro\",\"content\":\"Jesus, meu Salvador,\\nSê comigo aqui,\\nBendize-me agora;\\nEu creio em Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"De Ti careço, ó Deus,\\nDe Ti, meu Salvador.\\nÓ, vem fazer de mim,\\nHumilde servidor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Tua santa lei,\\nSenhor, vem-me instruir;\\nE Teu tão grande amor,\\nAlmejo então sentir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu grande Protetor\\nÉs Tu, na provação;\\nConcedes-me vigor\\nE eterna salvação.\"}]},{\"number\":\"395\",\"collection_type\":\"Hinário\",\"title\":\"Jesus, Pastor Amado\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus, Pastor amado, contempla-nos aqui;\\nConcede que sejamos um corpo só, em Ti.\\nContendas e malícias de nós bem longe vão;\\nNenhum desgosto impeça a nossa comunhão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pois sendo resgatados por um só Salvador,\\nDevemos ser unidos por santo e forte amor;\\nOlhar com simpatia os erros de um irmão\\nE todos ajudá-lo, com terna compaixão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, suave e meigo, ensina-nos a amar,\\nE faz-nos bem dispostos também no perdoar.\\nOh! quanto carecemos do auxílio do Senhor!\\nUnidos, suplicamos a Ti por esse amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, se a Igreja toda andar em santa união,\\nEntão será bendito o nome de cristão.\\nAssim o que pediste em nós se cumprirá,\\nE o mundo, em nós, Teus filhos, então distinguirá.\"}]},{\"number\":\"396\",\"collection_type\":\"Hinário\",\"title\":\"Ouve-nos, Pastor Divino\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouve-nos, Pastor divino, neste santo e bom lugar;\\nTeu rebanho congregado, vimos juntos Te adorar.\\nCristo amado, Cristo amado,\\nVem Teu povo abençoar;\\nCristo amado, Cristo amado,\\nVem Teu povo abençoar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aos perdidos no pecado, seu perigo faz sentir.\\nChama os pobres enganados, faze-os Tua voz ouvir.\\nAos enfermos, aos enfermos\\nVem depressa acudir;\\nAos enfermos, aos enfermos\\nVem depressa acudir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Traze o pobre desgarrado ao Teu bom redil, Senhor.\\nToma o tenro cordeirinho em Teu braço protetor.\\nDá-lhe abrigo, dá-lhe abrigo\\nEm Teu santo e doce amor;\\nDá-lhe abrigo, dá-lhe\\nEm Teu santo e doce amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Jesus, escuta o rogo, nossa humilde petição;\\nVem, desperta em Teu rebanho mais sincera devoção.\\nCantaremos, cantaremos\\nTua afável proteção;\\nCantaremos, cantaremos\\nTua afável proteção.\"}]},{\"number\":\"397\",\"collection_type\":\"Hinário\",\"title\":\"Comigo Habita\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Comigo habita, ó Deus, a noite vem!\\nAs trevas descem, eis, Senhor, convém\\nQue me socorra a Tua proteção!\\nOh, vem fazer comigo habitação!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem revelar-Te a mim, Jesus, Senhor,\\nDivino Mestre, Rei, Consolador!\\nMeu Guia forte, amparo em tentação!\\nOh, vem fazer comigo habitação!\"},{\"section_type\":\"Estrofe\",\"content\":\"Breve, Senhor, terei meu fim mortal;\\nÉ tão fugaz a vida terreal!\\nTem tudo aqui mudança e corrupção!\\nOh, vem fazer comigo habitação!\"},{\"section_type\":\"Estrofe\",\"content\":\"Se eu estiver nas trevas ou na luz,\\nNão há perigo, andando com Jesus;\\nA morte e a tumba não aterrarão!\\nOh, vem fazer comigo habitação!\"}]},{\"number\":\"398\",\"collection_type\":\"Hinário\",\"title\":\"Sonda-me, o Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sonda-me, ó Deus, pois vês meu coração;\\nProva-me, ó Pai, Te peço em oração.\\nDe todo o mal liberta-me, Senhor,\\nDa transgressão também, que oculta for.\"},{\"section_type\":\"Estrofe\",\"content\":\"Limpa-me o ser dos vis pecados meus,\\nConforme prometeste, meu bom Deus.\\nFaz-me inflamar e consumir de amor,\\nPois quero Te glorificar, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Todo o meu ser, que já não chamo meu,\\nQuero gastá-lo no serviço Teu.\\nMinhas paixões Tu podes dominar;\\nÓ santo Deus, vem sempre em mim estar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sei que do Céu o avivamento vem,\\nA começar em mim e indo além.\\nO Teu poder, Tuas bênçãos e favor\\nConcede aos que são Teus, ó Pai de amor.\"}]},{\"number\":\"399\",\"collection_type\":\"Hinário\",\"title\":\"Salva-me Também\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Salvador benigno, atende,\\nOh, não vás além!\\nOutros tens abençoado,\\nSalva-me também.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo! Cristo!\\nOh, não vás além,\\nOutros tens abençoado,\\nSalva-me também.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aos Teus pés estou prostrado,\\nVenho em contrição;\\nPeço-Te que me consoles\\nEste coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em virtude do Teu sangue,\\nBusco Teu favor;\\nQue minh'alma atribulada\\nTenha o Teu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"És a Fonte de conforto\\nDe onde a vida vem;\\nDá-me alívio mesmo agora,\\nE perdão também.\"}]},{\"number\":\"400\",\"collection_type\":\"Hinário\",\"title\":\"Quero Ter Jesus Comigo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quero ter Jesus comigo,\\nQuero a sós com Ele andar.\\nQuero ver Seu lindo rosto,\\nEm Seus braços descansar.\"},{\"section_type\":\"Coro\",\"content\":\"Tendo fé no Salvador,\\nDescansando em Seu amor,\\nSeguirei no meu caminho,\\nSem tristeza, sem temor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero ter Jesus comigo;\\nFrágil sou em minha fé.\\nSua voz me dá conforto\\nQuando me vacila o pé.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero ter Jesus comigo,\\nSempre aqui em meu viver,\\nNo lazer e no trabalho,\\nNo pesar e no prazer.\"}]},{\"number\":\"401\",\"collection_type\":\"Hinário\",\"title\":\"Abre, Senhor, os Olhos Meus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Abre, Senhor, os olhos meus\\nAo resplendor da Tua luz.\\nDá-me o poder de me libertar,\\nE de servir e amar Jesus.\\nEm contrição espero em Ti,\\nMostra-me, pois, o Teu querer.\\nAbre, Senhor, os olhos meus,\\nEu quero ver!\"},{\"section_type\":\"Estrofe\",\"content\":\"Abre, Senhor, o ouvido meu,\\nPara escutar a Tua voz.\\nQuero entender o Teu santo amor,\\nQuero ficar contigo a sós.\\nEm contrição espero em Ti,\\nQuero ser Teu e a paz fruir.\\nAbre, Senhor, o ouvido meu,\\nEu quero ouvir!\"},{\"section_type\":\"Estrofe\",\"content\":\"Abre-me, ó Pai, o coração,\\nQuero sentir o Teu calor.\\nAbre-me então, a boca também,\\nPara eu falar do Teu amor.\\nEm contrição espero em Ti,\\nEnche-me o ser com Teu amor.\\nToma-me, enfim, nos braços Teus,\\nÓ meu Senhor!\"}]},{\"number\":\"402\",\"collection_type\":\"Hinário\",\"title\":\"Fala à Minh'Alma\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Fala à minha alma ó Cristo, fala-lhe com amor!\\nSegreda com ternura: \\\"Eu sou Teu Salvador!\\\"\\nFaze-me bem disposto para te obedecer\\nSempre louvar Teu nome dedicar-te o ser.\"},{\"section_type\":\"Coro\",\"content\":\"Faze-me ouvir bem manso, em suave murmurar;\\nNa cruz verti Meu sangue, para te libertar;\\nFala-me cada dia, fala com terno amor;\\nSegreda-me ao ouvido: tu tens um Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Fala aos Teus filhos sempre, dá-lhes a direção;\\nEnche-os de grande gozo mesmo na provação;\\nFaze-os bem consagrados, prontos a trabalhar;\\nPara do reino eterno a vinda abreviar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Como na antigüidade mostravas Teu querer;\\nRevela-me hoje e sempre qual seja meu dever;\\nA Ti somente eu quero louvores entoar;\\nTeu nome eternamente engrandecer e honrar.\"}]},{\"number\":\"403\",\"collection_type\":\"Hinário\",\"title\":\"Mais de Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mais de Cristo quero ser,\\nmais do Seus amor obter,\\nMais de sua compaixão,\\nmais de sua mansidão\"},{\"section_type\":\"Coro\",\"content\":\"Mais, mais de Cristo!\\nMais, mais de Cristo!\\nMais do Seu puro e santo amor,\\nMais de meu Mestre meu Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais de Cristo perto estar,\\nSua comunhão gozar,\\nQuero Sua voz ouvir,\\nsempre Sua lei cumprir\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais a Cristo quero olhar,\\nVê-Lo em glória enfim reinar\\nReine sempre em mim também,\\nDesde agora até no além.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais de Cristo quero Ter,\\nmais igual a Ele ser\\nDando ao triste sofredor,\\nmais conforto e mais amor\"}]},{\"number\":\"404\",\"collection_type\":\"Hinário\",\"title\":\"Ó Deus, Contigo Almejo Andar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó Deus contigo almejo andar,\\nsim como Enoc contigo andou\\nÓ toma, pois a minha mão,\\npois sabes que mui débil sou\\nE se o caminho escuro for,\\nContigo quero andar, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não posso andar sozinho, ó Deus,\\na tempestade ruge hostil\\nMil laços se armam aos meus pés;\\nà espreita estão perigos mil\\nPara arrastar-me à perdição;\\nsó tenho em Ti a salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Podendo andar contigo, ó Deus,\\no mundo aqui é sem valor\\nEu sigo pois a Tua luz,\\nE avanço firme, sem temor\\nE ainda lá no eterno lar Contigo,\\nó Deus almejo andar\"}]},{\"number\":\"405\",\"collection_type\":\"Hinário\",\"title\":\"Vem, Jesus, nos Despertar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tu que sobre a amarga cruz\\nRevelaste Teu amor\\nTu que vives ó Jesus\\nVivificamos Senhor!\"},{\"section_type\":\"Coro\",\"content\":\"Vem, oh, vem, Jesus, Senhor,\\nNossas almas despertar\\nTeu puro e santo amor,\\nVem, oh nos inflamar\\nOh, vem! Oh, vem\\nNossas almas inflamar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis o mundo tentador\\nProcurando nos trair\\nSem Teu fogo abrasador,\\nPresto estamos a cair\"},{\"section_type\":\"Estrofe\",\"content\":\"Quantos que corriam bem,\\nDe ti longe hoje vão.\\nOutros seguem, que também\\nFrios, sem amor estão\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem agora consumir\\nTudo quanto ó Salvador\\nQuer altivo resistir\\nAo Teu brando e doce amor!\"}]},{\"number\":\"406\",\"collection_type\":\"Hinário\",\"title\":\"Em Mim Vem Habitar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em mim vem habitar, ó vem Jesus,\\nE em mim fazer brilhar a tua luz!\\nEis a minha ambição: ter e sentir, Senhor,\\nMais gratidão e mais amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os passos Teus seguir eu quero sim,\\nPrá te servir e amar até o fim.\\nEis o meu desejo, meu ideal maior,\\nContigo andar ó Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em meu interior vem Tu brilhar.\\nFaz-me com mais ardor da cruz falar.\\nReveste o coração de Teu excelso amor,\\nDe retidão e de fervor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! Que consolação a Cristo amar,\\nPois que com tanto amor me quis salvar!\\nNada me alegra mais, gozo não há maior\\nQue Tua paz, ó Salvador.\"}]},{\"number\":\"407\",\"collection_type\":\"Hinário\",\"title\":\"Ao Teu Lado Quero Andar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu sou fraco, sem vigor;\\nVivo sempre a vacilar.\\nSê, Jesus meu protetor;\\nSó contigo, Senhor quero andar.\"},{\"section_type\":\"Coro\",\"content\":\"Ao teu lado quero andar,\\nLivre de qualquer temor;\\nQuero em Ti sempre confiar,\\nE viver para Ti, ó Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Neste mundo aterrador,\\nQuem se importa se eu cair?\\nQuem está em meu favor?\\nSó Jesus me poderá me remir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Junto a Ti, meu Salvador,\\nPara sempre eu quero estar;\\nÓ conduz-me com amor\\nÀs moradas do teu doce lar.\"}]},{\"number\":\"408\",\"collection_type\":\"Hinário\",\"title\":\"Dá-me Tua Paz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dá-me Tua paz, Mestre, dá-me Tua paz,\\nSe tristezas vêem conturbar-me o coração;\\nNão serei tentado, nem o mal verei,\\nSe me deres paz, bom Mestre; dá-me Tua paz.\"},{\"section_type\":\"Coro\",\"content\":\"Dá-me Tua paz, Mestre,\\nDá-me Tua paz, Mestre,\\nPois andar sem Ti não posso;\\nDá-me Tua paz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dá-me Tua paz, Mestre, dá-me Tua paz,\\nSim, nas horas más, quando em treva envolto estou.\\nGuia, pois, meus passos, para eu não cair,\\nPois andar sem Ti não posso; dá-me Tua paz.\"}]},{\"number\":\"409\",\"collection_type\":\"Hinário\",\"title\":\"Rosa de Saron\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Rosa de Sarom, vem ao meu coração;\\nDá-lhe da fragrância desse amor sem-par,\\nPara que eu rescenda em minha vida aqui,\\nO aroma que só Teu amor pode exalar.\"},{\"section_type\":\"Coro\",\"content\":\"Rosa de Sarom,\\nAbre em rediante amor\\nEm nosso coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Rosa de Sarom, dom que desceu do Céu,\\nFaz de minha vida um vaso em Teu louvor,\\nE que eu viva sempre assim a perfumar\\nAqueles que estão em sofrimento e dor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Rosa de Sarom, reine pra sempre aqui;\\nTua glória impere em terra, céu e mar.\\nVenham as nações render louvor a Ti;\\nE o Universo inteiro irá Te adorar.\"}]},{\"number\":\"410\",\"collection_type\":\"Hinário\",\"title\":\"Faz Brilhar a Tua Luz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Faz brilhar em mim, Jesus,\\nTua luz, divina luz!\\nTira o véu dos olhos meus,\\nPara ver os feitos Teus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Reine em mim a Tua paz,\\nTeu amor que bênçãos traz!\\nSinta eu o perdão\\nO poder da redenção!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que prazer será pra mim,\\nÓ Jesus, viver assim!\\nSou feliz em tua luz,\\nMui feliz, ó meu Jesus!\"}]},{\"number\":\"411\",\"collection_type\":\"Hinário\",\"title\":\"Súplica\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem guiar-me, ó Senhor,\\nMeu Amigo, meu Pastor!\\nGuarda-me de todo o mal,\\nPela graça divinal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Fraco sou e pecador,\\nNada tenho em meu favor.\\nSó Tu podes, meu Jesus,\\nDar-me vida, força e luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Guarda-me das tentações,\\nNeste mundo de aflições.\\nAjudar-me vem, meu Deus;\\nQuero andar nos passos Teus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando o Bom Pastor voltar,\\nE as ovelhas vier buscar,\\nLeva-me, Senhor, também,\\nAo eterno lar. Amém.\"}]},{\"number\":\"412\",\"collection_type\":\"Hinário\",\"title\":\"Comunhão Preciosa\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quão preciosas são as horas\\nNa presença de Jesus!\\nComunhão deliciosa,\\nDe minh'alma com a luz!\\nOs cuidados deste mundo\\nNão me podem abalar,\\nPois é Ele o meu abrigo\\nQuando o tentador chegar,\\nQuando o tentador chegar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao sentir-me rodeado\\nDe cuidados terreais,\\nConturbado ou abatido,\\nOu em dúvidas fatais,\\nA Jesus eu me dirijo\\nNestes tempos de aflição;\\nAs palavras que Ele fala\\nTrazem paz ao coração,\\nTrazem paz ao coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se Lhe conto meus temores,\\nToda a minha imperfeição,\\nEle escuta com paciência\\nEssa triste confissão;\\nCom ternura repreende\\nMeu pecado e todo o mal.\\nÉ Jesus o meu amigo,\\nO melhor e mais leal,\\nO melhor e mais leal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se quereis saber quão doce\\nÉ a secreta comunhão,\\nPodereis mui bem prová-la,\\nFruireis consolação;\\nProcurai estar sozinhos,\\nEm conversa com Jesus:\\nProvareis na vossa vida\\nSua graça e Sua luz,\\nSua graça e Sua luz.\"}]},{\"number\":\"413\",\"collection_type\":\"Hinário\",\"title\":\"Lugar de Paz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sei de um lugar de paz,\\nLonge de toda dor;\\nAonde vou a luz buscar.\\nEntre a vegetação,\\nProstrado, em oração,\\nA Deus entrego meu pesar.\\nBem cedo, de manhã,\\nOu ao cair do Sol,\\nEu deixo lá o meu temor;\\nE deste bom lugar,\\nEu saio pra enfrentar a vida\\nCom muito mais amor.\"}]},{\"number\":\"414\",\"collection_type\":\"Hinário\",\"title\":\"Santa Hora de Oração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Santa hora de oração! Reina paz divinal,\\nE volvemos a Cristo, o Amigo leal;\\nHora santa em que a Jesus nós podemos falar.\\nQue poder para a alma! Oh! quão doce é orar!\"},{\"section_type\":\"Coro\",\"content\":\"Doce é orar, com fervor, orar!\\nQue poder para a alma! Oh! quão doce é orar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Santa hora de oração, quando a alma conduz\\nOs pesares da vida aos pés de Jesus,\\nE prorrompe em Seu louvor como as ondas do mar.\\nQue poder para a alma! Oh! quão doce é orar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Santa hora de oração, quando o vil tentador\\nÉ vencido com forças que vem do Senhor;\\nE do Céu faz descer Sua graça sem par.\\nQue poder para a alma! Oh! quão doce é orar!\"}]},{\"number\":\"415\",\"collection_type\":\"Hinário\",\"title\":\"Só, com Teu Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Só, com teus Deus, sublime paz e bênção!\\nSim, sempre a sós com Deus por onde for.\\nSó, com teus Deus, Seu rosto contemplando,\\nSó, sempre ouvindo Sua voz de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Só, com teus Deus, nas horas mais difíceis,\\nPaz Ele tem a dar aos filhos Seus.\\nSó, com teus Deus, serás o exemplo vivo,\\nLuz da verdade e do amor de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Só, com teus Deus, supremo bem infindo!\\nTal comunhão dará prazer sem par.\\nSó, com teus Deus, fiel até a morte,\\nVais para sempre com Teu Deus andar.\"}]},{\"number\":\"416\",\"collection_type\":\"Hinário\",\"title\":\"Ao Pé da Cruz de Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao pé da cruz de Cristo, feliz desejo estar,\\nRepouso ter à sombra ali, e então a paz gozar;\\nUm lar feliz no ermo achar, e aqui, na vida, o amor;\\nAlívio à dor e graça há aos pés do meu Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao pé da cruz de Cristo, aqui e no jardim,\\nEu vejo a dor cruel em que Jesus morreu por mim.\\nCompreendo, então, quão débil sou, quão mau e sem valor;\\nCompreendo, sim, quão grande é o Seu sagrado amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Estar eu quero à sombra da cruz, bendita cruz!\\nEu posso ali obter perdão e estar junto a Jesus.\\nEu posso então certeza ter do amor de Deus por mim,\\nE em breve irei fruir no Céu a paz do amor sem fim.\"}]},{\"number\":\"417\",\"collection_type\":\"Hinário\",\"title\":\"Meu Deus e Eu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Deus e eu andamos pelos prados,\\nQuais bons amigos, juntos a passear;\\nDadas as mãos, alegres conversamos,\\nSem nada, nada a nos atrapalhar;\\nDadas as mãos, alegres conversamos,\\nSem nada, nada a nos atrapalhar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Deus me conta de outros tempos, quando\\nEternos planos Ele fez por mim;\\nQuando o que vejo era apenas sonho,\\nQuando Ele o mundo fez tão belo assim;\\nQuando o que vejo era apenas sonho,\\nQuando Ele o mundo fez tão belo assim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Deus e eu, eternamente juntos,\\nQuais bons amigos, vamos sempre andar;\\nInda que o Céu e a própria Terra passem,\\nNada de Deus me pode separar;\\nInda que o Céu e a própria Terra passem,\\nNada de Deus me pode separar.\"}]},{\"number\":\"418\",\"collection_type\":\"Hinário\",\"title\":\"O Jardim de Oração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus num jardim 'stá esperando,\\nNum lugar de eternal perfeição;\\nEle é luz e Sua glória cintila,\\nNeste lindo jardim de oração.\"},{\"section_type\":\"Coro\",\"content\":\"Oh! que lindo jardim, o jardim de oração!\\nOh! que lindo jardim de oração!\\nMeu Jesus perto está, e o portão abrirá,\\nDeste lindo jardim de oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus num jardim 'stá esperando,\\nOnde vou suplicar-Lhe perdão;\\nQuero ouvi-lo falar de conforto.\\nNeste lindo jardim de oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus num jardim 'stá esperando,\\nE convida o que sofre aflição\\nPara entrar e fruir Seu descanso,\\nNeste lindo jardim de oração.\"}]},{\"number\":\"419\",\"collection_type\":\"Hinário\",\"title\":\"Bendita Hora de Oração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bendita hora de oração,\\nPois traz-nos paz ao coração,\\nE vence o mal e toda a dor,\\nTrazendo auxílio do Senhor.\\nEm tempos maus, na provação,\\nNa dor maior, na tentação,\\nIrei buscar ao meu Senhor,\\nCom zelo, fé e mais fervor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bendita hora de oração,\\nDe doce calma e devoção,\\nQue eleva ao Céu o seu odor\\nEm cheiro suave a meu Senhor.\\nE finda a hora de aflição,\\nOs dias maus, a tentação,\\nEntão darei melhor louvor\\nA meu Jesus, a meu Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bendita hora de oração,\\nPois liga-nos em comunhão,\\nE traz-nos fé e mais amor,\\nEnchendo o mundo de dulçor.\\nDesejo a vida aqui findar\\nCom fé, amor, constante orar;\\nE lá no Céu, junto ao Senhor,\\nSerá eterno meu louvor.\"}]},{\"number\":\"420\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Que Amigo em Cristo Temos!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! que amigo em Cristo temos! Mais chegado que um irmão!\\nQuer que tudo nós levemos Ao bom Deus em oração.\\nOh! que paz perdemos sempre, Oh! que dor de coração!\\nSó porque não recorremos ao bom Deus em oração!\"},{\"section_type\":\"Estrofe\",\"content\":\"Há tristezas e pesares, Há na vida tentação;\\nNão ficamos sem conforto, Indo a Cristo em oração.\\nPode haver um outro amigo Tão grandioso em compaixão?\\nAos humildes e contritos, Cristo atende em oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando em dor desfalecemos, Cristo estendenos a mão,\\nPois é sempre a nossa força, É refúgio em oração.\\nE se aqui nos menosprezam, Cristo é nosso em oração;\\nEm Seus braços nos acolhe, E nos dá consolação.\"}]},{\"number\":\"421\",\"collection_type\":\"Hinário\",\"title\":\"Brando Qual Coro Celeste\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Brando qual coro celeste, Vem nos de longe um rumor:\\nVoz de suspiro e de alento, Voz inefável de amor.\\nEia, que após tempestades, Vem a bonança embalar\\nO coração perturbado, Dando-lhe calma sempar.\"},{\"section_type\":\"Coro\",\"content\":\"Oh doce voz Que me vem embalar!\\nMeu coração vem, Senhor, confortar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se no crepúsculo da tarde, Podes adiante enxergar,\\nLá no profundo das trevas, Vais ver a estrela a brilhar.\\nSe vindo as trevas da noite, Tens porventura temor,\\nNão desanimes que logo Há de brilhar o alvor.\"},{\"section_type\":\"Estrofe\",\"content\":\"E se nas lutas da vida, Sentes tristezas e dor,\\nHá de raiar novo dia Cheio de luz e dulçor.\\nEternamente com Cristo, Vamos a paz desfrutar,\\nE alegria perene Hemos de ter lá no lar.\"}]},{\"number\":\"422\",\"collection_type\":\"Hinário\",\"title\":\"Assentado aos Pés de Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Assentado aos pés de Cristo, Oh, que suave comunhão!\\nAs palavras que Lhe escuto Trazem paz ao coração.\\nAo rever o meu passado, Quando estou junto a Jesus,\\nMais e mais eu avalio Seu amor por mim na cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Assentado aos pés de Cristo, Suas bênçãos muitas são;\\nEu deponho os meus pecados E Ele dá-me Seu perdão.\\nAssentado aos pés de Cristo, Eu demoro-me a orar;\\nSinto então a plenitude De Sua graça e amor sempar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Jesus bendito, inclina Com amor o Teu olhar!\\nPossa eu sempre livremente Tua face contemplar.\\nDá-me sentimentos puros, Faz-me santo, meu Jesus.\\nQue eu demonstre aos semelhantes, Ser Teu filho e andar na luz!\"}]},{\"number\":\"423\",\"collection_type\":\"Hinário\",\"title\":\"Música Celeste\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que música celete vem das vagas do mar;\\nComove minha'lma qual santa canção;\\nSão as vozes de anjos soando no ar,\\nA mim estão cantando celeste saudação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Do Jordão nas lindas praias, me detenho a orar,\\nE com fervente prece estendo a mão;\\nÓ, envia os Teus anjos, amável Jesus!\\nE deixa-me cantar, sim, a santa canção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em forte borrasca que infunde pavor,\\nNão tenho temor se Jesus me guiar,\\nPois a santa melodia envolveu-me de amor;\\nJunto ao coro dos anjos desejo cantar.\"}]},{\"number\":\"424\",\"collection_type\":\"Hinário\",\"title\":\"Como a Brisa Suave\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Como a brisa suave dos prados em flor,\\nÉ Tua voz, ó meu Mestre, pra mim,\\nQuando às vezes, no auge da angústia e dor,\\nMinha mão quase deixa Tua mão.\"},{\"section_type\":\"Coro\",\"content\":\"Como a brisa suave Tua voz é, Senhor,\\nComo a brisa de um claro arrebol;\\nDos momentos de sombras liberto já estou,\\nPois ouvi Tua voz me falar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Como a brisa suave Tua voz é, Senhor,\\nQuando a noite me encontra tão só;\\nDe minha'lma o fardo deixou de existir,\\nQuando as nuvens fizeste fugir.\"}]},{\"number\":\"425\",\"collection_type\":\"Hinário\",\"title\":\"Que Tempo Já Faz?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que tempo já faz que falaste com Deus.\\nContando os segredos da alma?\\nQue tempo já faz que oraste ao Senhor\\nE de joelhos ouviste-Lhe a voz?\\nQue tempo já faz que não andas com Deus,\\nDeixando-O guiar tua vida?\\nTeu Amigo quer ser,\\nQuer dar-te poder\\nTu precisas sentir Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que tempo já faz que ajoelhaste a sós\\nE oraste ao Teu Deus lá do Céu?\\nQue tempo já faz que o Teu coração\\nSe apega aos pecados teus?\\nQue tempo já faz que não falas de Deus,\\nPregando a mensagem do Mestre?\\nTeu Amigo quer ser,\\nQuer dar-te poder,\\nImplantar Seu amor em Teu ser.\"}]},{\"number\":\"426\",\"collection_type\":\"Hinário\",\"title\":\"No Jardim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu fui ao jardim bem a sós,\\nAos primeiros raios celestes,\\nPude então ouvir doce e meiga voz,\\nA voz gentil do Mestre.\"},{\"section_type\":\"Coro\",\"content\":\"Que alegria sempre essa voz ouvir;\\n\\\"Eu te amo, ó pecador!\\nMesmo a morte lá sobre a cruz sofri,\\nPara ser o teu Salvador\\\".\"},{\"section_type\":\"Estrofe\",\"content\":\"Ouvi Sua voz divinal\\nEm acentos muito suaves,\\nQue fala a mim com ternura igual\\nÀ voz gentil das aves.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu fico a escutar Sua voz\\nNa vibrante luta terrestre,\\nE ao me vir tentar o inimigo atroz,\\nQuão bom ouvir o Mestre!\"}]},{\"number\":\"427\",\"collection_type\":\"Hinário\",\"title\":\"Mais Perto Quero Estar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mais perto quero estar,\\nMeu Deus, de Ti,\\nInda que seja a dor\\nQue me una a Ti.\"},{\"section_type\":\"Coro\",\"content\":\"Eis meu constante orar:\\nMais perto quero estar,\\nMais perto quero estar,\\nMeu Deus, de Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Andando triste aqui,\\nNa solidão,\\nPaz e descanso a mim\\nTeus braços dão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minh'alma cantará\\nA Ti, Senhor,\\nCheia de gratidão,\\nPor Teu amor.\"}]},{\"number\":\"428\",\"collection_type\":\"Hinário\",\"title\":\"Glória Perene\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando meu tempo de lutas passar,\\nQuando meu Mestre vier me buscar,\\nGrato, perante Ele então me prostrar,\\nGlória perene será para mim!\"},{\"section_type\":\"Coro\",\"content\":\"Sim, há de ser glória pra mim!\\nGlória pra mim! Glória pra mim!\\nQuando puder o Seu rosto mirar,\\nOh! há de ser grande glória pra mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando, por graça do Seu grande amor,\\nEu alcançar o infinito favor\\nDe ir para perto do meu Salvador,\\nGlória perene será para mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Muitos amigos ali hei de achar,\\nPaz, alegria, prazer, bem estar;\\nMas, quando meu Salvador me saudar,\\nGlória perene será para mim!\"}]},{\"number\":\"429\",\"collection_type\":\"Hinário\",\"title\":\"Eu Face a Face Vê-Lo-ei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em breve irei, de meu Jesus,\\nO rosto meigo contemplar.\\nQuanta alegria fruirei\\nE doce paz irei gozar!\\nAnte Seu trono adorarei,\\nE meu louvor então darei;\\nAlmejo estar no eterno lar,\\nE face a face o contemplar.\"},{\"section_type\":\"Coro\",\"content\":\"Eu, face a face, vê-lo-ei;\\nPor graça salvo, cantarei;\\nSim, face a face, vê-lo-ei\\nE Dele sempre então serei.\"},{\"section_type\":\"Estrofe\",\"content\":\"A vida aqui irá passar,\\nO novo Éden Surgirá.\\nPecado ali não se achará,\\nNem mal algum existirá.\\nPois o Senhor com a sua luz\\nJá os baniu na rude cruz;\\nAlmejo estar no novo lar,\\nE sua face contemplar.\"}]},{\"number\":\"430\",\"collection_type\":\"Hinário\",\"title\":\"O Eterno Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó irmãos, cantai nesta peregrinação,\\nDentro em pouco iremos para o lar!\\nVai então raiar nossa eterna redenção,\\nDentro em pouco iremos para o lar!\"},{\"section_type\":\"Coro\",\"content\":\"Dentro em breve, sim,\\nDentro em breve, sim,\\nEstaremos lá no lar;\\nSim, depois de o mar\\nDeste mundo atravessar,\\nNós iremos para o eterno lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos, pois, fazer o que está à nossa mão,\\nDentro em pouco iremos para o lar!\\nCada dia Deus nos será a salvação,\\nDentro em pouco iremos para o lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Há um repouso além, um alívio a todo mal,\\nDentro em pouco iremos para o lar!\\nNão há pranto ou dor na cidade celestial,\\nDentro em pouco iremos para o lar!\"}]},{\"number\":\"431\",\"collection_type\":\"Hinário\",\"title\":\"Sim, Glória Haverá no Final\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Findo o labor, que prazer sem-par,\\nPra quem por Cristo aqui lutar,\\nLevar os molhos que ganhar\\nPara ti, Jerusalém!\"},{\"section_type\":\"Coro\",\"content\":\"Sim, Glória haverá no final,\\nSim, glória sublime, eternal;\\nOh! quanto prazer, quanto amor\\nLá no Céu junto ao Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Doces canções entoaremos lá;\\nGrato louvor a Jeová\\nEternamente se ouvirá,\\nLá em ti, Jerusalém!\"},{\"section_type\":\"Estrofe\",\"content\":\"Puro e bendito o prazer será,\\nLindas mansões sim, haverá,\\nCristo conosco se achará,\\nLá em ti, Jerusalém!\"}]},{\"number\":\"432\",\"collection_type\":\"Hinário\",\"title\":\"Hei de Ver o Rei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Hei de ver o Rei junto à Sua grei,\\nVê-Lo-ei um dia além,\\nNum país melhor, anjos ao redor,\\nNa feliz Jerusalém.\"},{\"section_type\":\"Coro\",\"content\":\"Sim, na glória hei de ver o Rei\\nE louvores sempre cantarei.\\nNo Calvário Cristo morreu por mim;\\nHei de vê-lo um dia enfim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que prazer será com os salvos lá\\nComtemplar o Salvador.\\nGratidão sem-par hei de Lhe ofertar\\nPelos bens do Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis que a dor passou nada mais ficou\\nDeste mundo sofredor.\\nNesse bom país viverei feliz,\\nCom Jesus, meu Salvador.\"}]},{\"number\":\"433\",\"collection_type\":\"Hinário\",\"title\":\"O Triunfo do Messias\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus é rejeitado, o mundo não O quer,\\nRecusa com orgulho seu Rei reconhecer;\\nMas, eis que vem glorioso do Seu celeste lar,\\nPara logo com poder aqui reinar!\"},{\"section_type\":\"Coro\",\"content\":\"Logo vem o dia eterno da Sua exaltação!\\nVem, sim, para o livramento de toda a criação.\\nOh! que canto de vitória então há de soar,\\nQuando Cristo triunfante aqui reinar!\"},{\"section_type\":\"Estrofe\",\"content\":\"O Sol ao meio dia não tem o resplendor\\nQual há de ter a Igreja na vinda do Senhor;\\nPorque do Esposo a glória, a noiva há de ostentar,\\nQuando Cristo triunfante aqui reinar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Já temos privilégio de pela fé prever\\nA divina herança que vamos receber\\nA dor e o sofrimento jamais terão lugar,\\nQuando Cristo triunfante aqui reinar!\"}]},{\"number\":\"434\",\"collection_type\":\"Hinário\",\"title\":\"Quando for Chamado\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando Cristo Sua trombeta lá do Céu mandar tocar;\\nQuando o dia mui glorioso em luz romper,\\nE aos remidos, triunfantes, meu Jesus se apresentar,\\nE chamado então eu for, sim, lá estarei.\"},{\"section_type\":\"Coro\",\"content\":\"Quando for então chamado,\\nQuando for então chamado,\\nQuando for então chamado,\\nAprovado hei de estar perante o Rei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nesse tão glorioso dia, quando o crente ressurgir,\\nE da gloria de Jesus participar;\\nQuando os salvos ressurgidos atingirem o porvir,\\nE chamdo então eu for, sim, lá estarei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lidarei por meu Jesus até o dia terminar;\\nFalarei do seu amor por nós aqui;\\nQuando tudo aqui cessar em meu constante labutar,\\nE chamado então eu for, sim, lá estarei.\"}]},{\"number\":\"435\",\"collection_type\":\"Hinário\",\"title\":\"Estrelas Terei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu deleite é pensar noutra terra de além,\\nOnde irei, finda a luta de aquem;\\nQuando, enfim, por Jesus, conseguir lá chegar,\\nNa coroa eu estrela terei?\"},{\"section_type\":\"Coro\",\"content\":\"Na coroa de luz, eu estrela terei,\\nQuando o sol aqui não aqui mais raiar?\\nQuando Deus me levar para o reino dos Céus\\nNa coroa eu estrelas terei?\"},{\"section_type\":\"Estrofe\",\"content\":\"No poder de Jesus vou orar e lutar,\\nPara o Céu muitas almas guiar.\\nQuero, pois, receber nesse dia final\\nA coroa de glória a brilhar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que gozo será, o Seu rosto mirar\\nE a Seus pés com louvor adorar!\\nNa cidade eternal minha glória será\\nReceber a coroa a brilhar.\"}]},{\"number\":\"436\",\"collection_type\":\"Hinário\",\"title\":\"Que Será Ver a Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há prazer sem igual lá no lar celestial,\\nJunto às margens do mui belo rio.\\nSurpresas sem fim ali há pra mim,\\nMas oh! que será ver a Cristo?!\"},{\"section_type\":\"Coro\",\"content\":\"Oh! que será ver a Cristo!\\nVer a meu bom Salvador!\\nSurpresas sem fim ali há pra mim,\\nMas oh! que será ver a Cristo?!\"},{\"section_type\":\"Estrofe\",\"content\":\"Uns deveram morrer, pra seu nome viver;\\nSua vida por Cristo entregaram.\\nUm dia, no lar, os quero encontrar,\\nMas, oh! que será ver a Cristo?!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que direi da emoção, ter na mão Sua mão,\\nLá na pátria dos salvos, pra sempre;\\nJá livre do mal, feliz, afinal!\\nMas oh! que será ver a Cristo?!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando a luz desse olhar o meu ser inundar,\\nQuando eu vir o Seu rosto divino,\\nSorrindo o Senhor, em Seu grande amor,\\nOh! sim, que será ver a Cristo?!\"}]},{\"number\":\"437\",\"collection_type\":\"Hinário\",\"title\":\"Vitória em Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouvi da bela história\\nQue Jesus desceu da glória\\nE no Gólgota enfim morreu\\nPor quantos como eu.\\nOuvi dos Seus gemidos,\\nDe Seus sangue e dos remidos;\\nE ao fim, contrito me prostrei,\\nVitória nEle achei.\"},{\"section_type\":\"Coro\",\"content\":\"Vitória em Cristo,\\nEterna vitória!\\nBuscou-me, salvou-me,\\nNa cruz por mim morreu.\\nQue paz e alegria!\\nRaiou um novo dia!\\nVitória Jesus me deu,\\nNo sangue que verteu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ouvi que Ele cura,\\nSim, a todo que O procura;\\nQue o coxo fez andar, então,\\nE ao cego deu visão.\\nOrei, clamei: \\\"Meu Mestre,\\nVem restaura minha vida.\\\"\\nE logo Cristo me atendeu,\\nE a mim vitória deu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ouvi falar da glória\\nQue virá após vitória,\\nPara os redimidos por Jesus,\\nNa resplendente luz;\\nDe anjos lá cantando,\\nE mansões já me aguardando;\\nSerá glorioso ali chegar,\\nE então poder cantar:\"}]},{\"number\":\"438\",\"collection_type\":\"Hinário\",\"title\":\"Hei de Vê-Lo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando ao fim da carreira desta vida nos chegar,\\nE o mortal se revestir do imortal,\\nHei de ver meu amado, meu bendito Salvador;\\nSeu sorriso para mim é divinal.\"},{\"section_type\":\"Coro\",\"content\":\"Hei de vê-Lo, hei de vê-Lo;\\nAo Seu lado pra sempre habitarei.\\nHei de vê-Lo, hei de vê-Lo;\\nE na Sua mão ferida pegarei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que gozo supremo, quando vir o rosto Seu,\\nE estiver pra sempre junto ao meu Senhor!\\nQue vibrante alegria, quando entrar no lar do Céu!\\nMas primeiro quero ver meu Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao entrar pelas portas da celeste habitação,\\nOnde findam os gemidos e o sofrer,\\nCantarei com os salvos, a dulcíssima canção,\\nMas primeiro meu Jesus eu quero ver.\"}]},{\"number\":\"439\",\"collection_type\":\"Hinário\",\"title\":\"Primeiro Quero Ver Meu Salvador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"No céu há muita, muita coisa que eu anseio ver,\\nSuas mil belezas, glórias e esplendor;\\nMas antes de fruir de tais delícias o prazer,\\nPrimeiro quero ver meu Salvador.\"},{\"section_type\":\"Coro\",\"content\":\"Primeiro quero ver meu Salvador,\\nSim, antes dos queridos ao redor;\\nE então por longos dias,\\nQue doces alegrias!\\nMas quero ver primeiro o Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"As ruas de ouro eu quero ver, o e brilho dos portais,\\nEu quero ver os paços celestiais;\\nA árvore da vida e o lindo rio do Senhor,\\nMas quero ver primeiro o Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ver mamãe e estar com ela no jardim,\\nLembrar dos dias idos, com amor;\\nQueridos quero ver, os quais partiram antes, sim,\\nMas quero ver primeiro o Salvador.\"}]},{\"number\":\"440\",\"collection_type\":\"Hinário\",\"title\":\"Para Além das Montanhas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Para além das montanhas do celeste lar,\\nA cidade santa nos espera já;\\nMui cansados vamos de subir, galgar,\\nMas, avante, sempre, não desanimar!\"},{\"section_type\":\"Coro\",\"content\":\"Perto, sim, do lar!\\nPerto, sim, do lar!\\nEis as luzes deste deslumbrante lar!\\nE esplendores junto aos seus portais sem par!\\nPerto está o dia se rever Jesus,\\nE subir com Ele para a Sua luz!\\nPerto, sim, do lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Os profetas antigos nos falaram já\\nDa cidade bela, de ouro e cristal;\\nJá nos vêm vislumbres, divisamos lá\\nAs mansões luzentes que não tem rival.\"},{\"section_type\":\"Estrofe\",\"content\":\"Neste lar tão somente poderão entrar\\nOs remidos pela graça de Jesus;\\nNossas vozes juntas hão de ali vibrar\\nEm louvor Àquele que morreu na cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meus irmãos, meus queridos, estaremos lá,\\nNesta terra linda, sem tristeza ou dor?\\nAceitai, pois, a mensagem de Jeová,\\nE em Seu reino vos receberá co'amor.\"}]},{\"number\":\"441\",\"collection_type\":\"Hinário\",\"title\":\"Junto ao Rio Jordão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem junto estou ao rio Jordão\\nE lanço além o olhar.\\nSaudoso estou e anseio herdar\\nMeu doce, doce lar.\"},{\"section_type\":\"Coro\",\"content\":\"Eu irei descansar no eterno lar,\\nQuando enfim transpuser o rio Jordão\\nCom os salvos sempre poderei me alegrar,\\nCantando minha redenção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já farto estou de tanta dor,\\nDos males e dos ais;\\nA morte ali no lar de amor\\nNão entra nunca mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Apressa, ó Deus, o reino Teu,\\nNão tardes mais, Senhor!\\nEu quero já subir ao Céu,\\nMeu doce lar de amor.\"}]},{\"number\":\"442\",\"collection_type\":\"Hinário\",\"title\":\"Tão Grato me é Lembrar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tão grato me é lembrar\\nQue cada dia estou\\nMais perto do celeste lar,\\nEm que morar eu vou!\"},{\"section_type\":\"Coro\",\"content\":\"Cada vez mais\\nPerto do lar,\\nPerto do meu eterno lar\\nEm que morar eu vou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em breve vou partir\\nPara onde não há dor.\\nEterna vida vou fruir\\nNaquele lar de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Mestre, que leal\\nEu seja sempre aqui,\\nPois quero junto aos salvos mil,\\nContigo estar aí.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! quando ali chegar,\\nQue dia tão feliz!\\nDescanso e paz irei gozar\\nNaquele bom país.\"}]},{\"number\":\"443\",\"collection_type\":\"Hinário\",\"title\":\"Eis Que as Estrelas Vêm\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eis que as estrelas vêm,\\nDo Sol fenece a luz!\\nO coração mergulha em paz do além\\nQue atrai e que seduz;\\nE nesta hora sobe ao coração\\nA voz de anseios mil,\\nCálido almejar de redenção,\\nSaudade atroz de um lar gentil.\\nJá negras sombras vêm,\\nE cai a escuridão!\\nA embarcação dos sonhos meus\\nTambém se faz ao mar;\\nEu posso ver a praia além;\\nIrei em breve ali chegar.\\nEspero ver meu Mestre,\\nE afinal encontrarei meu lar.\"}]},{\"number\":\"444\",\"collection_type\":\"Hinário\",\"title\":\"Face a Face\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quanto almejo ver a Cristo!\\nVer-Lhe o rosto, que prazer!\\nQuando enfim, no lar eterno,\\nPoderei pra sempre O ver!\"},{\"section_type\":\"Coro\",\"content\":\"Face a face eu hei de vê-Lo,\\nQuando vier em glória e luz;\\nFace a face lá na glória\\nHei de ver meu bom Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Muito ao longe já O avisto,\\nVejo como por um véu,\\nMas desejo em breve vê-Lo\\nFace a face lá no Céu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que encanto estar com Cristo,\\nOnde já não há mais dor!\\nLivre de qualquer perigo,\\nDesfrutando Seu amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Face a face, que alegria\\nHá de ser viver assim,\\nVendo o rosto tão querido\\nDe quem morto foi por mim!\"}]},{\"number\":\"445\",\"collection_type\":\"Hinário\",\"title\":\"As Riquesas Mundanas Nada Valem\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"As riquezas mundanas nada valem pra mim;\\nQuero ir para o reino onde há vida sem fim.\\nSim, no livro da vida, que é escrito por Ti,\\nCerto estou, ó meu Mestre, tens o meu nome aí.\"},{\"section_type\":\"Coro\",\"content\":\"Foi escrito por Ti o meu nome no céu;\\nSim, no livro da vida, foi escrito por Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meus pecados são muitos, como areia do mar;\\nMas Jesus me revela caridade em par.\\nVeio para salvar-me, o Seu sangue verteu,\\nE as delícias eternas, Ele a mim prometeu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, cidade festiva, refulgente de luz!\\nDoce lar dos remidos e fiéis de Jesus!\\nSó verá tua glória o que crê no Senhor,\\nCujo nome já esteja com o Seu Redentor.\"}]},{\"number\":\"446\",\"collection_type\":\"Hinário\",\"title\":\"Junto ao Trono de Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Junto ao trono de Deus preparado,\\nHá lugar, ó cristão, dado a ti;\\nÉ de Cristo precioso legado;\\nAlegria terás sempre ali.\\nSim, ali, sim, ali,\\nDe Seus anjos fiéis rodeado,\\nE cercado de glória e de luz\\nJunto ao Pai já te espera Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não nos podem da Terra os encantos\\nDar idéia do que há ali;\\nSe no mundo os prazeres são tantos,\\nSão prazeres que cessam aqui;\\nMas ali, Mas ali,\\nAs venturas eternas concorrem,\\nNa existência de bênçãos a flux,\\nPara a vida feliz com Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Conservemos em nossa lembrança\\nAs belezas do lindo país,\\nE guardemos conosco a esperança\\nDe uma vida radiosa e feliz,\\nPois ali, pois ali,\\nUma voz mui suave não cansa\\nDe falar-nos do reino de luz:\\nÉ a voz divinal de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se quisermos fruir da ventura,\\nQue na pátria gloriosa haverá,\\nÉ somente pedir de alma pura,\\nQue Jesus Sua graça nos dá.\\nSim, ali, sim, ali,\\nCom desvelo, amor e ternura,\\nCom amor revelado na cruz,\\nNos espera, sorrindo, Jesus.\"}]},{\"number\":\"447\",\"collection_type\":\"Hinário\",\"title\":\"Almas Gêmeas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Almas gêmeas que se enlaçam\\nPelos elos da afeição,\\nTé que a morte ao fim os venha separar;\\nLado a lado um do outro,\\nPela vida seguirão,\\nPara, unidos, os encantos desfrutar.\"},{\"section_type\":\"Coro\",\"content\":\"Chovam bênçãos sobre o venturoso par\\nQue se encontra dado a lado neste altar;\\nDá-lhes, Deus, a proteção e uma sólida união,\\nAlicerces para o seu ditoso lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A beleza da grinalda\\nE a finura deste véu\\nSejam símbolos de um puro e casto amor;\\nSeja o lar aqui na Terra\\nMiniatura lá do Céu,\\nHospedando sempre a Cristo, Redentor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pela fé sempre aquecidos,\\nCom amor no coração,\\nOmbro a ombro, lado a lado irão lutar;\\nQuer nos dias de bonança,\\nNa borrasca ou na aflição\\nHão de a vida sempre juntos partilhar.\"}]},{\"number\":\"448\",\"collection_type\":\"Hinário\",\"title\":\"Duas Vidas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Duas vidas, Senhor, unem-se no altar;\\nDuas vidas e dois nobres corações.\\nPelo amor e afeição possam caminhar,\\nSempre juntos na calma e nas aflições.\"},{\"section_type\":\"Coro\",\"content\":\"Abençoa, Senhor, esta santa união,\\nDerramando Tua graça e o Teu divino amor;\\nNeste lar haja paz, haja compreensão,\\nQual fragrância de um belo jardim em flor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais um lar que se faz, cheio de dulçor,\\nSob a bênção de Deus, Sua proteção;\\nHaja nele prazer e sincero amor,\\nBem firmado na fé e na oração.\"}]},{\"number\":\"449\",\"collection_type\":\"Hinário\",\"title\":\"Perfeito Amor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, colocaste já no ser humano,\\nTeus sentimentos, Teu divino amor.\\nEis que, segundo Teu sagrado plano,\\nVem este par perante Ti, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem como às aves dás seguro abrigo,\\nBem como aos ninhos dás também calor,\\nVem dar aos noivos lar ameno e amigo,\\nPaz, proteção e o mais sincero amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem conceder-lhes luz em sua história,\\nFé confiança, muito amor também;\\nE, quando Cristo vier em Sua glória,\\nÓ, dá-lhes Tu, um lar feliz no além.\"}]},{\"number\":\"450\",\"collection_type\":\"Hinário\",\"title\":\"Abençoa Este Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Abençoa, bom Senhor, de Teus filhos, este lar.\\nVem eterna proteção e Tua santa paz nos dar.\\nMesmo quando em prova e dor, reine aqui somente amor.\\nHaja sempre neste lar, harmonia e bem estar.\"},{\"section_type\":\"Estrofe\",\"content\":\"E na senda do viver, guia-nos com Tua mão.\\nUne nossos corações pelos laços da afeição.\\nLivra-nos de todo o mal, nesta vida terreal.\\nE prepara-nos, ó Deus, para o eterno lar dos Céus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nossos filhos, ó Senhor, tenham Tua proteção.\\nDá-lhes forças e poder pra vencer a tentação.\\nE que juntos, em amor, recebamos Teu favor.\\nE que neste nosso lar possas Tu também morar.\"}]},{\"number\":\"451\",\"collection_type\":\"Hinário\",\"title\":\"Recordação da Infância\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"É doce agora relembrar\\nOs dias infantis,\\nEm que a voz de minha mãe\\nOuvia mui feliz:\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Filhinho, dorme, dorme em paz;\\nDeus cuidará de nós.\\nNão chores mais e dorme bem;\\nDeus velará por nós.\\\"\\nSua fé me fez confiar em Deus,\\nQue não nos deixa a sós.\\nApraz-me sempre repetir:\\n\\\"Deus cuidará de nós.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Tomando-me nos braços seus,\\nBem junto ao coração,\\nCantava para me aninar,\\nA maternal canção:\"},{\"section_type\":\"Estrofe\",\"content\":\"E quando estou em aflição,\\nEm desalento e dor,\\nPareço ainda ouvir-lhe a voz\\nDizer-me com amor:\"}]},{\"number\":\"452\",\"collection_type\":\"Hinário\",\"title\":\"Meu Nome na Oração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando inda eu tinha a vida em flor,\\nNa mocidade vã,\\nNos dias sem cuidado ou dor,\\nDe vida folgazã,\\nEu vi, ao suave anoitecer,\\nDe joelhos, minha mãe,\\nE num suspiro ouvi-lhe, então,\\nMeu nome na oração.\"},{\"section_type\":\"Coro\",\"content\":\"Meu nome na oração,\\nMeu nome na oração!\\nOuvi dos lábios de mamãe,\\nOuvi meu nome na oração!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não dei então, nenhum valor\\nÀ prece de mamãe,\\nMas comoveu-me o coração\\nSentir seu grande amor;\\nE quando a vida se tornou\\nRepleta de amargor,\\nEm vão eu quis ouvir então\\nMeu nome na oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu prossegui, sem atender\\nÀ terna voz de Deus,\\nQue me queria converter,\\nLevar-me ao seio Seu;\\nMas quando o meu pecado eu vi,\\nPerdido me senti;\\nEntão lembrei com emoção,\\nMeu nome na oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aquele aflito coração,\\nNa terra há muito jaz,\\nMas traz-me ainda sempre paz\\nLembrar a oração;\\nE lá no Céu, mamãe e eu\\nLouvores vamos dar\\nA Deus, que em Sua compaixão,\\nOuviu a oração.\"}]},{\"number\":\"453\",\"collection_type\":\"Hinário\",\"title\":\"Amor no Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tudo é belo em derredor,\\nCom amor no lar;\\nHá beleza em cada flor,\\nCom amor no lar.\\nEste amor promove paz,\\nToda mágoa e dor desfaz;\\nLuz, saúde e gozo traz\\nSempre o amor no lar.\"},{\"section_type\":\"Coro\",\"content\":\"Com amor, com amor,\\nNão há dor, não há pesar,\\nCom amor no lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na choupana há prazer,\\nCom amor no lar;\\nÓdio e mal não pode haver,\\nCom amor no lar.\\nCada rosa em seu matiz,\\nVozes de aves tão gentis,\\nTudo faz-se mais feliz,\\nCom amor no lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus, que eu seja Teu;\\nDá-me amor no lar;\\nFaz-me renunciar o eu,\\nFaz-me mais amar.\\nVida mais feliz terei,\\nHei de estar aos pés do Rei,\\nSempre andando em Sua lei,\\nCom amor no lar.\"}]},{\"number\":\"454\",\"collection_type\":\"Hinário\",\"title\":\"Vem Entre Nós Morar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem, ó Jesus, entre nós morar,\\nSeja também Teu o nosso lar;\\nSê com mamãe e com papai;\\nVem-nos, Senhor, abençoar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Reine afeição e perfeito amor,\\nLonge do mal, de qualquer temor;\\nNosso viver, em tudo aqui,\\nHonre tão só o Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando a manhã perenal raiar,\\nE a redenção se concretizar,\\nNós Te rogamos, ó Senhor,\\nSalva também o nosso lar.\"}]},{\"number\":\"455\",\"collection_type\":\"Hinário\",\"title\":\"Oração Para Uma Criança\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vê, Senhor, este menino,\\nMeigo, frágil como a flor;\\nNecessita de carinho,\\nNecessita de amor.\\nSeus olhinhos são tão puros,\\nSeu sorriso é como a luz;\\nEles mostram a beleza\\nQue emana de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem guiar os seus passinhos,\\nEnsiná-lo a caminhar\\nNo seguro e bom caminho,\\nE em Tua força confiar;\\nVem livrá-lo das maldades\\nQue este mundo pode impor;\\nPai querido, cuida dele,\\nDá a ele o Teu amor.\"}]},{\"number\":\"456\",\"collection_type\":\"Hinário\",\"title\":\"Sabes Quantas Estrelinhas?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sabes quantas estrelinhas\\nLá no céu brilhando estão?\\nSabes quantas nuvenzinhas\\nPelo vasto mundo vão?\\nDeus a todas tem contado,\\nUma só não há faltado;\\nNem de tantas, uma só;\\nNem de tantas, uma só.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sabes quantos passarinhos\\nVoam, livres, pelo ar?\\nQuantos peixes que não cansam,\\nDivertindo-se no mar?\\nDeus a todos deu a vida,\\nCada um tem sua lida,\\nAlegria e prazer;\\nAlegria e prazer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sabes quantas criancinhas,\\nAo raiar do arrebol,\\nSe levantam contentinhas,\\nDespertando com o Sol?\\nDeus a todas 'stá olhando,\\nE do Céu abençoando;\\nVê e ama a ti também;\\nVê e ama a ti também.\"}]},{\"number\":\"457\",\"collection_type\":\"Hinário\",\"title\":\"Sim, Cristo me Ama\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo tem amor por mim,\\nCom certeza eu creio assim;\\nPor amor de mim morreu,\\nVivo está por mim no Céu.\"},{\"section_type\":\"Coro\",\"content\":\"Sim, Cristo me ama,\\nSim, Cristo me ama,\\nSim, Cristo me ama,\\nA Bíblia assim me diz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, Jesus me tem amor,\\nE Se fez meu Salvador;\\nHoje ainda tem prazer\\nDe crianças receber.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por gozar Seu rico amor,\\nHei de amar meu Salvador,\\nE desejo aqui mostrar\\nSeu amor tão singular.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus comigo está,\\nE afinal me levará\\nPara o lindo Céu de luz,\\nPois me resgatou na cruz.\"}]},{\"number\":\"458\",\"collection_type\":\"Hinário\",\"title\":\"Vinde, Meninos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vinde meninos, vinde a Jesus;\\nEle ganhou-vos bênçãos na cruz.\\nOs pequeninos Ele conduz;\\nOh, vinde ao Salvador!\"},{\"section_type\":\"Coro\",\"content\":\"Que alegria, sem pecado ou mal,\\nReunir-nos todos, afinal,\\nJuntos na pátria celestial,\\nPerto do Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Já, sem demora, muito convém\\nIr caminhando à glória de além.\\nCristo vos chama, quer vosso bem;\\nOh, vinde ao Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que ama aos meninos, Cristo vos diz;\\nQuer receber-vos nesse país,\\nQuer conceder-vos vida feliz;\\nOh, vinde ao Salvador!\"}]},{\"number\":\"459\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Ama as Criancinhas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo às crianças tem amor,\\nBênçãos Ele aqui lhes deu;\\nSempre a todas atraiu o Salvador.\\nCom doçura as acolheu;\\nOlvidá-las, oh, jamais!\\nTodas elas para Ele são iguais.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo ama as criancinhas\\nQue no mundo inteiro há;\\nDiz a todas com dulçor,\\nQue Ele as quer com muito amor;\\nBênçãos mil a todas elas Cristo dá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Há crianças, sim, aos mil,\\nEm países lá de além,\\nQue ignoram de Jesus o amor gentil!\\nVamos ajudar também\\nA levar-lhes salvação,\\nPara terem a Jesus no coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos essa nova dar,\\nDela a Terra toda encher,\\nO evangelho a todo o povo anunciar.\\nCom fervor e com prazer\\nFalaremos de Jesus\\nPra que em toda terra brilhe Sua luz.\"}]},{\"number\":\"460\",\"collection_type\":\"Hinário\",\"title\":\"Jesus Me Quer Bem\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, que prazer que o bom Pai lá do Céu,\\nFala na Bíblia do amor que me tem.\\nHá nesse livro mil coisas sem par!\\nE ele me diz que Jesus me quer bem\"},{\"section_type\":\"Coro\",\"content\":\"Oh, que prazer, Jesus me quer bem!\\nSim me quer bem, sim me quer bem!\\nOh, que prazer, Jesus me quer bem!\\nSim Ele me quer bem!\"},{\"section_type\":\"Estrofe\",\"content\":\"Inda que mau seja o meu coração,\\nCristo me ama e quer dar-me o perdão.\\nEle me acolhe em Seus braços também;\\nOh, que alegria, Jesus me quer bem!\"},{\"section_type\":\"Estrofe\",\"content\":\"Caso um só canto eu puder entoar,\\nQuando em presença do Rei me encontrar,\\nHei de louvá-Lo assim lá no além:\\n\\\"Que maravilha, Jesus me quer bem!\\\"\"}]},{\"number\":\"461\",\"collection_type\":\"Hinário\",\"title\":\"Deus Sempre me Ama\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus sempre me ama,\\nCo'amor me chama,\\nE assim me inflama\\nDo mesmo amor;\"},{\"section_type\":\"Coro\",\"content\":\"Por isso canto\\nO amor divino;\\nSerá meu hino\\nO amor de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cativo estive,\\nMas graça obtive\\nDo amor que vive\\nE faz viver;\"},{\"section_type\":\"Estrofe\",\"content\":\"Enviou Seu filho,\\nPrestou-me auxílio,\\nMostrou-me o trilho\\nQue ao Céu conduz;\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus buscou-me,\\nJesus salvou-me,\\nEle aceitou-me\\nCom terno amor;\"}]},{\"number\":\"462\",\"collection_type\":\"Hinário\",\"title\":\"Jóias Preciosas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eis que Cristo vem à Terra em busca das jóias,\\nSuas jóias mui preciosas de muito valor.\"},{\"section_type\":\"Coro\",\"content\":\"Como estrelas na aurora brilhando em glória,\\nNa coroa de Cristo pra sempre estarão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem buscá-las, vai levá-las ao reino celeste,\\nSuas jóias resplendentes de muito valor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os meninos e as meninas que seguem a Cristo,\\nSão-lhe jóias, ricas jóias, de muito valor.\"}]},{\"number\":\"463\",\"collection_type\":\"Hinário\",\"title\":\"Brilhando, Brilhando!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vejo no céu resplendente,\\nDo sol a clara luz;\\nQuero viver tão somente\\nBrilhando por Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Brilhando, brilhando,\\nQuero brilhar como a luz!\\nBrilhando, brilhando,\\nSempre brilhar por Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero em tudo exaltá-Lo\\nNa escola e no estudar;\\nNunca também olvidá-Lo\\nEm casa e no brincar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com um viver diligente,\\nAssim me quer Jesus;\\nSempre com rosto contente,\\nBrilhando como a luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se esta é Sua vontade,\\nBrilhando viverei,\\nE pela Sua bondade,\\nAo lindo Céu irei.\"}]},{\"number\":\"464\",\"collection_type\":\"Hinário\",\"title\":\"Belas Mãozinhas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Com as minhas duas mãos\\nPosso a Bíblia segurar;\\nCom os dois olhinhos meus,\\nSuas lições estudar.\"},{\"section_type\":\"Coro\",\"content\":\"Lindas, mui lindas as tenras mãos\\nQue trabalham para Deus;\\nBelos, mui belos os olhos são,\\nQuando contemplam os Céus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com os dois olhinhos meus,\\nMil coisinhas posso ver;\\nCom as minhas duas mãos,\\nMuitas coisinhas fazer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Minhas pequeninas mãos\\nPra Jesus trabalharão;\\nE estes dois olhinhos meus\\nO bom caminho verão.\"}]},{\"number\":\"465\",\"collection_type\":\"Hinário\",\"title\":\"Brilhemos por Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus dá às criancinhas,\\nPor onde Ele as conduz,\\nO encargo tão glorioso:\\nBrilhar por seus Jesus.\\nSejamos belos raios\\nDa luz do Deus de amor,\\nPra dissipar as trevas\\nDispersas ao redor.\"},{\"section_type\":\"Coro\",\"content\":\"Pequenos raios somos\\nDa verdadeira luz;\\nEm todos os lugares,\\nBrilhemos por Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"As nuvens tão escuras\\nEscondem nossa luz;\\nA vida tem tristezas,\\nPesada é nossa cruz.\\nMas, como belos raios,\\nCumpramos a missão\\nDe dar sempre alegria\\nA cada coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que grande privilégio:\\nBrilhar, sim, por Jesus!\\nE desfazer as trevas\\nPra dar lugar à luz!\\nCom pensamentos puros,\\nVivamos com amor;\\nSejamos raiozinhos\\nQue brilhem sem temor.\"}]},{\"number\":\"466\",\"collection_type\":\"Hinário\",\"title\":\"Louvai-O\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Louvai-O! Louvai-O!\\nTodas as crianças;\\nDeus é amor! Deus é amor!\\nLouvai-O! Louvai-O!\\nTodas as crianças;\\nDeus é amor! Deus é amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Servi-O! Servi-O!\\nTodas as crianças;\\nDeus é amor! Deus é amor!\\nServi-O! Servi-O!\\nTodas as crianças;\\nDeus é amor! Deus é amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Amai-O! Amai-O!\\nTodas as crianças;\\nDeus é amor! Deus é amor!\\nAmai-O! Amai-O!\\nTodas as crianças;\\nDeus é amor! Deus é amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Louvai e Adorai-O!\\nTodas as crianças;\\nDeus é amor! Deus é amor!\\nLouvai e Adorai-O!\\nTodas as crianças;\\nDeus é amor! Deus é amor!\"}]},{\"number\":\"467\",\"collection_type\":\"Hinário\",\"title\":\"Ouço o Clamor do Bom Pastor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouço o clamor do bom Pastor,\\nPelo deserto assolador,\\nSeus cordeirinhos a chamar,\\nMui desejoso de os salvar.\"},{\"section_type\":\"Coro\",\"content\":\"\\\"Vai buscar, vai buscar\\nEsses Meus cordeirinhos, já!\\nVai buscar, vai buscar,\\nPara que os possa abençoar.\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh!, quem não quer auxílio dar,\\nSeus cordeirinhos abrigar,\\nE encaminhá-los a Jesus,\\nFonte de vida, amor e luz?\"},{\"section_type\":\"Estrofe\",\"content\":\"Pelo deserto a padecer,\\nPelas estradas a morrer,\\nSeus cordeirinhos vai buscar,\\nPara que os possa abençoar.\"}]},{\"number\":\"468\",\"collection_type\":\"Hinário\",\"title\":\"Preceitos Para os Pequenos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dez são os mandamentos\\nDa santa lei de Deus,\\nQue podem ser contados\\nNos dez dedinhos meus.\\nOs Meus dois olhinhos\\nServem para os ler,\\nE estes meus dedinhos,\\nPara os escrever.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dos dez preceitos, quatro\\nNos dizem quanto amor\\nA Deus devemos todos,\\nO nosso Criador.\\nOs meus dois ouvidos\\nServem para ouvir;\\nA boquinha minha,\\nPara os proferir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Amai aos semelhantes,\\nExortam os finais;\\nAmai como a vós mesmos,\\nE a Deus sereis leais.\\nOs meus dois pezinhos\\nServem para andar\\nPelo bom caminho\\nQue hemos de trilhar.\"}]},{\"number\":\"469\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Que Esperança!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! Que esperança vibra em nosso ser,\\nPois aguardamos o Senhor!\\nFé possuímos, que Jesus nos dá,\\nFé na promessa que nos fez.\\nEis que o tempo logo vem,\\nE as nações daqui e além\\nBem alerta vão cantar:\\nAleluia! Cristo é Rei!\\nOh! Que esperança vibra em nosso ser,\\nPois Aguardamos o Senhor.\"}]},{\"number\":\"470\",\"collection_type\":\"Hinário\",\"title\":\"O Senhor Está Aqui\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Coro\",\"content\":\"O Senhor está aqui!\\nO Senhor está aqui!\\nVinde adorá-Lo!\\nVinde exaltá-Lo!\\nO Senhor está aqui!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos entoar louvores ao Seu nome,\\nVamos exaltar as Suas maravilhas!\\nToda a Terra e Céu dêem o seu louvor!\\nVamos adorar o grande Criador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Nuvens e trovões proclamem Sua glória,\\nMundos e nações inclinem-se a Ele!\\nDele é o poder, dEle é o louvor!\\nVamos adorar o grande Criador!\"}]},{\"number\":\"471\",\"collection_type\":\"Hinário\",\"title\":\"Confiei no Meus Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Confiei no meu Senhor,\\nE Ele me ouviu;\\nDo pecado me livrou,\\nE a vida em mim surgiu.\"},{\"section_type\":\"Coro\",\"content\":\"Muitos O verão e temerão,\\nDeus, Criador da terra e Céu.\\nBem aventurado o que confia no Senhor.\\nA Cristo honra, glória e louvor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Os meus pés guiou no bem;\\nUm sol em mim nasceu;\\nMinha vida há de ser\\nUm hino ao meu bom Deus.\"}]},{\"number\":\"472\",\"collection_type\":\"Hinário\",\"title\":\"Deus é Tão Bom\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus é tão bom,\\nDeus é tão bom,\\nDeus é tão bom,\\nDeus é bom pra mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus me quer bem,\\nDeus me quer bem,\\nDeus me quer bem,\\nDeus é bom pra mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus me salvou,\\nDeus me salvou,\\nDeus me salvou,\\nDeus é bom pra mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus me sustém,\\nDeus me sustém,\\nDeus me sustém,\\nDeus é bom pra mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus é amor,\\nDeus é amor,\\nDeus é amor,\\nDeus é bom pra mim!\"}]},{\"number\":\"473\",\"collection_type\":\"Hinário\",\"title\":\"Maravilhoso És, Meu Mestre\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Maravilhoso és, meu Mestre!\\nQual Tu não há ninguém.\\nMaravilhoso és, meu Mestre!\\nÉs para mim supremo bem.\\nMaravilhoso és, meu Mestre!\\nTenho-Te imenso amor.\\nNobre entre os nobres Tu és,\\nMeu Rei e Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Maravilhoso és, meu Mestre!\\nAmigo mui leal,\\nMaravilhoso és, meu Mestre!\\nTeu grande amor é sempre igual.\\nMaravilhoso és, meu Mestre!\\nTeu eu desejo ser,\\nPara servir-Te agora\\nE sempre, até morrer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Maravilhoso és, meu Mestre!\\nSei que irás voltar.\\nMaravilhoso és, meu Mestre!\\nTenho prazer em Te esperar.\\nMaravilhoso és, meu Mestre!\\nA Ti fiel serei,\\nE lá no lar eterno\\nTeu nome exaltarei.\"}]},{\"number\":\"474\",\"collection_type\":\"Hinário\",\"title\":\"Seguindo a Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Estou seguindo a Jesus Cristo;\\nDeste caminho eu não desisto.\\nEstou seguindo a Jesus Cristo;\\nAtrás não volto, nunca mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se me deixarem os pais e amigos,\\nSe me cercarem muitos perigos;\\nSe me deixarem os pais e amigos,\\nAtrás não volto, nunca mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Atrás o mundo, Jesus na frente,\\nJesus, o Guia onipotente;\\nAtrás o mundo, Jesus na frente,\\nAtrás não volto, nunca mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Depois da luta, vem a coroa;\\nA recompensa é certa e boa.\\nDepois da luta, vem a coroa;\\nAtrás não volto, nunca mais.\"}]},{\"number\":\"475\",\"collection_type\":\"Hinário\",\"title\":\"Diante da Face de Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Diante da face de Cristo Jesus,\\nAnseio a paz e o perdão.\\n\\\"Aceita-me ó Pai, assim como estou,\\nPois fraco e débil eu sou.\\\"\\nDiante da face de Cristo Jesus,\\nHumilde lhe imploro vencer.\\nSeu terno olhar me faz decidir,\\nBuscar mais poder na oração.\\nSeu terno olhar me faz almejar,\\nAndar passo a passo na luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Diante da face de Cristo Jesus,\\nAnseio por consagração.\\nSe vêm provações, ou vêm tentações,\\nApego-me à cruz com ardor.\\nDiante da face de Cristo Jesus,\\nHumilde lhe entrego meu ser.\\nSeu terno olhar me faz decidir,\\nBuscar mais poder na oração.\\nSeu terno olhar me faz almejar,\\nSer mais semelhante a Jesus.\"}]},{\"number\":\"476\",\"collection_type\":\"Hinário\",\"title\":\"Eu Achei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu achei, sim eu achei\\nUma fonte em que me satisfiz,\\nQuando aceitei a Jesus, meu Rei;\\nFoi meu dia mais feliz!\\nRecebi, sim, eu recebi\\nPlenitude de vida em Jesus,\\nQue me trouxe a luz\\nQue provém da cruz;\\nSeu amor então senti.\"},{\"section_type\":\"Coro\",\"content\":\"A vida era triste, só dor e aflição,\\nMas hoje é diferente\\nCom Jesus em meu coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Seu perdão, ele trouxe a mim,\\nEsperança em Jesus eu ganhei,\\nDesde que busquei, desde que encontrei,\\nEsse amor que não tem fim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero, sim, a Jesus amar,\\nPois Seu sangue por mim derramou;\\nAo Seu lado estou, para o céu eu vou;\\nQuero a vida lhe entregar.\"}]},{\"number\":\"477\",\"collection_type\":\"Hinário\",\"title\":\"Canção da Vida\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai querido obrigado pelos planos,\\nGrandes sonhos especiais pra mim.\\nTu me guias nos caminhos desta vida.\\nAo Teu lado nada faltará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu Te amo mais que tudo.\\nQuando forte, quando fraco,\\nAo meu lado estás.\\nAgradeço Pai querido,\\nPor ligar a nossa vida\\nEm num só coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu Te amo mais que tudo.\\nQuando fraco, Tua força\\nNunca falhará.\\nPor Tua graça, Pai, imploro\\nTransformar a minha vida\\nEm uma canção.\"}]},{\"number\":\"478\",\"collection_type\":\"Hinário\",\"title\":\"Jesus, Tu És a Minha Vida\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus, Tu és a minha vida.\\nJesus, Tu és o meu cantar.\\nTu és a estrada mais bonita,\\nPor onde eu devo caminhar.\\nJesus, Tu és a primavera\\nQue faz a vida florescer.\\nTu és a chama da alegria\\nQue faz brilhar todo o meu ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, Tu és a melodia,\\nA voz, o canto, a emoção.\\nTu és a força que me inspira\\nA dar louvor na provação.\\nJesus, Tu és a esperança\\nQue faz vibrar meu coração.\\nJesus, Tu és a energia\\nQue move a vida do cristão\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, Tu és o meu caminho,\\nVerdade, vida e salvação.\\nJesus, Tu és a minha glória,\\nMotivo de minha adoração.\\nJesus, Tu és meu Pai querido\\nA quem dedico o meu viver.\\nTu és pra sempre a minha vida;\\nJesus, és vida no meu ser.\"}]},{\"number\":\"479\",\"collection_type\":\"Hinário\",\"title\":\"Querido Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Querido Jesus, Tu és meu Salvador;\\nHei de ser-Te pra sempre fiel,\\nPois cuidas de mim com desvelo e amor,\\nE me livras do mundo cruel.\"},{\"section_type\":\"Coro\",\"content\":\"Ó meu querido Salvador,\\nHei de amar-te até morrer;\\nE leva-me, enfim, ao Teu lar de amor,\\nNo lindo alvorecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Querido Jesus sempre és para mim\\nUm amigo bondoso e leal;\\nQuem importa se um dia chegar o meu fim?\\nVida eterna hás de dar-me afinal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Querido Jesus, sempre em Ti confiarei,\\nMesmo em meio de lutas de dor;\\nPois sei que contigo bem firme estarei,\\nAo abrigo do Teu grande amor.\"}]},{\"number\":\"480\",\"collection_type\":\"Hinário\",\"title\":\"Em Tuas Mãos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em Tuas mãos, em Tuas mãos,\\nQuero, ó Deus, me colocar em Tuas mãos.\\nVem mostrar-me, ó Senhor,\\nTeu carinho e Teu amor,\\nMeus temores vou depor\\nEm Tuas mãos.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Tuas mãos, em Tuas mãos,\\nQuero, ó Deus, me colocar em Tuas mãos.\\nEsta é minha oração,\\nTer a vida em Tuas mãos,\\nToma pois meu coração\\nEm Tuas mãos.\"}]},{\"number\":\"481\",\"collection_type\":\"Hinário\",\"title\":\"Nos Passos de Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sigo a perigosa estrada deste meu viver,\\nOnde cada passo em falso pode ser meu fim.\\nMas eu sigo em frente, pondo sempre os meus pés\\nSobre as pegadas que Jesus deixou pra mim.\\nEu vou para onde este trilho me levar;\\nQuero no final dele encontrar o meu Jesus.\\nE se alguém vier atrás de mim por onde vou,\\nVai ver que Cristo e eu deixamos uma pegada só.\"}]},{\"number\":\"482\",\"collection_type\":\"Hinário\",\"title\":\"Jesus Precisa de Ti\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus precisa hoje, sim, de jovens de valor,\\nSua força solicita pra obra terminar.\\nLevanta-te, empunha hoje a Bíblia com amor,\\nProclama a todo mundo que Jesus irá voltar.\"},{\"section_type\":\"Coro\",\"content\":\"Marcha firme, com força e vigor,\\nSempre conduzindo a palavra do Senhor.\\nJuntos vamos a todos ensinar,\\nQue Jesus virá mui breve aqui reinar.\"},{\"section_type\":\"Estrofe\",\"content\":\"À nobre luta hoje Cristo está a te chamar,\\nLevanta-te, proclama os dons da Sua luz!\\nSe as sombras desta vida vem o brilho ocultar,\\nEsconde os teus talentos, que ao teu lado está Jesus.\"}]},{\"number\":\"483\",\"collection_type\":\"Hinário\",\"title\":\"Partilhai Vossa Fé\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Partilhai a vossa fé, vós os jovens de Deus,\\nNesta estrada de luz que nos leva aos Céus;\\nQue alegria é fazer o que pede Jesus:\\nProclamar com ardor o evangelho de luz.\"},{\"section_type\":\"Coro\",\"content\":\"Jovens de Deus, erguei-vos!\\nÉ tempo de brilhar!\\nPartilhai com outros a vossa fé;\\nJesus não irá tardar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Partilhai a vossa fé, vós os jovens de Deus,\\nVossa fé no Senhor que criou Terra e Céus;\\nVossa fé em Jesus nosso bom Salvador,\\nQue mui breve virá com poder e esplendor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Partilhai a vossa fé, vós os jovens de Deus,\\nQue na luta feroz o Senhor guarda os Seus;\\nE sejamos fiéis té a batalha final,\\nPois Jesus nos dará galardão triunfal.\"}]},{\"number\":\"484\",\"collection_type\":\"Hinário\",\"title\":\"Faze Como Daniel\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu irmão intenta ser\\nTal qual Daniel,\\nResoluto em combater\\nO usurpador cruel?\"},{\"section_type\":\"Coro\",\"content\":\"Faze como Daniel,\\nServe o eterno Deus.\\nEntre os infiéis, fiel,\\nMarcha para os Céus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em coragem singular,\\nFirme em prol do Rei\\nSempre ousado em proclamar\\nJesus e Sua lei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não se turbe o coração,\\nDeixa a timidez.\\nMuitos males cairão\\nPerante a intrepidez.\"},{\"section_type\":\"Estrofe\",\"content\":\"Para o crente no Senhor,\\nHá nas trevas luz;\\nEle avança sem temor,\\nEm nome de Jesus\"}]},{\"number\":\"485\",\"collection_type\":\"Hinário\",\"title\":\"Levantai-vos, Jovens\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Levantai-vos, jovens crentes, firmes pela cruz!\\nDesfraldai o estandarte do Senhor Jesus!\"},{\"section_type\":\"Coro\",\"content\":\"Lealdade, ó jovens crentes,\\nA Jesus, Senhor!\\nFirmes, sempre, nos preceitos\\nDo bom Redentor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vede as hostes inimigas, Cheias de furor;\\nOh, unidos combatamos, sempre, sem temor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Avançai, com lealdade, firmes em Jesus!\\nSeja a Bíblia vosso guia, a celeste luz.\"}]},{\"number\":\"486\",\"collection_type\":\"Hinário\",\"title\":\"Sal da Terra\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus nos deu esta missão:\\nO Seu amor compartilhar.\\nSomente entraremos em ação se o amor de Deus nos motivar.\\nO Seu poder nos moverá\\nE assim iremos repartir\\nO amor de Deus, a verdadeira paz e a doce esperança no porvir.\"},{\"section_type\":\"Coro\",\"content\":\"Vós sois o sal da terra;\\nVós sois o sal da terra,\\nRestaurando o sabor\\nE a alegria de viver.\\nVós sois o sal da terra.\"},{\"section_type\":\"Estrofe\",\"content\":\"A vida que Jesus viveu,\\nO exemplo que Ele nos deixou,\\nDemonstram o real sentido da missão que o Senhor nos confiou.\\nSaber a todos perdoar,\\nQuerer a todos aceitar,\\nRevela a grandeza do serviço e aponta para o Salvador.\"}]},{\"number\":\"487\",\"collection_type\":\"Hinário\",\"title\":\"Cristo, Conta Comigo Agora!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus Cristo está chamando\\nNovos braços recrutando,\\nMuita coisa existe pra fazer.\\nA missão é importante,\\nA tarefa é estafante\\nMas não posso dela me esconder.\\nSim, Cristo conta comigo agora!\\nConta comigo agora!\\nEu não posso me esquivar\\nAo ouvir o Teu chamar!\\nConta comigo já!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que seria se eu vivesse\\nPra meu próprio interesse\\nVendo o mundo quase a explodir;\\nVendo tanta amargura,\\nTantas almas a procura\\nDe alguém que as queira acudir!\\nSim, Cristo conta comigo agora!\\nConta comigo agora!\\nEis-me aqui meu Salvador,\\nEu estou a Teu dispor;\\nConta comigo já!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não importa o que eu faça,\\nOs caminhos que Deus traça\\nSempre são melhores que os meus.\\nVou fazer todo o possível\\nPra tornar-me disponível\\nE cumprir sempre o querer de Deus.\\nSim, Cristo conta comigo agora!\\nConta comigo agora!\\nSe Deus quer desprendimento,\\nQue me importa o sofrimento?\\nConta comigo, conta comigo,\\nConta comigo já!\"}]},{\"number\":\"488\",\"collection_type\":\"Hinário\",\"title\":\"Novo Canto Há em Meu Ser\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Foram mui pesados os meus fardos de aflição,\\nMas supremo alívio em Cristo achou meu coração!\"},{\"section_type\":\"Coro\",\"content\":\"Novo canto há em meu ser,\\nDes'que Cristo me salvou;\\nÉ um canto de prazer,\\nPois Jesus me resgatou.\\nToda culpa e todo mal\\nEm Seu sangue, assim, lavou;\\nQue prazer, que paz,\\nTanto amor me traz!\\nNovo canto há em meu ser!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que transformação em minha vida se operou,\\nQuando Cristo achou-me e meus pecados perdoou!\"},{\"section_type\":\"Estrofe\",\"content\":\"Nunca cessarei de amar a Cristo, meu Senhor,\\nPela salvação que me proveu em Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Muito em breve um canto angelical irei ouvir,\\nSim, ao coro alegre eu hei de a minha voz unir\"}]},{\"number\":\"489\",\"collection_type\":\"Hinário\",\"title\":\"Grande Alegria\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Coro\",\"content\":\"Grande alegria inundou meu coração,\\nAo descobrir que Cristo logo vai voltar!\\nGrande alegria explodiu a emoção\\nPelo que Cristo fez e faz pra me salvar\"},{\"section_type\":\"Estrofe\",\"content\":\"Olhando ao redor eu vejo a dor,\\nPessoas sofrendo sem amor,\\nComendo miséria para não morrer,\\nTentando na vida não sofrer!\\nOlhando ao redor eu vejo fé,\\nNum mundo que quer mudar até\\nMas esta mudança nunca vai chegar,\\nSe não quando Cristo retornar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Olhando ao redor eu vejo o fim\\nDe tudo que tem valor pra mim;\\nOs sonhos da vida todos pelo chão,\\nO mundo é só desolação!\\nOlhando ao redor eu vejo o céu,\\nFechado e coberto por um véu.\\nO brilho do mundo então se apagou\\nE a vinda de Cristo então brilhou.\"}]},{\"number\":\"490\",\"collection_type\":\"Hinário\",\"title\":\"Caminhando\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Alegre eu já vou para o lar celestial,\\nCaminhando, caminhando;\\nPois não me encanta mais o prazer terrenal;\\nCaminhando para aquele lar.\"},{\"section_type\":\"Coro\",\"content\":\"Caminhando, caminhando,\\npara aquele lar onde está Jesus.\\nCaminhando, caminhando,\\nPela mão divina de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero pecadores comigo levar,\\nCaminhando, caminhando;\\nQue em Cristo possam eles a paz encontrar;\\nCaminhando para aquele lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com Cristo, meu Senhor, para sempre estarei,\\nCaminhando, caminhando;\\nSeu nome eternamente então louvarei;\\nCaminhando para aquele lar.\"}]},{\"number\":\"491\",\"collection_type\":\"Hinário\",\"title\":\"Além do Céu Azul\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Além do céu azul,\\nFoi Jesus preparar\\nUm lar pra dar a quem\\nA vitória alcançar.\\nAnelo conseguir\\nA vida no porvir,\\nCom fé no meu Senhor Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem sei que eu, de mim,\\nNada tenho pra dar,\\nMas sei que meu Jesus\\nJá me veio salvar.\\nAgora quero eu\\nTer fé no coração,\\nAté Seu rosto ver além.\"}]},{\"number\":\"492\",\"collection_type\":\"Hinário\",\"title\":\"Lado a Lado\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Lado a lado aqui, Crendo em Seu amor,\\nAdorando o Rei, Senhor;\\nAvançando em fé, movidos pelo amor,\\nDeus nos acompanhará.\"},{\"section_type\":\"Coro\",\"content\":\"Vamos para o Céu, com mãos em mãos unidas;\\nLado a lado com Jesus\\nNós vamos para o Céu, cantar canções em coro;\\nEu e você vamos lá!\"},{\"section_type\":\"Estrofe\",\"content\":\"Joias somos nós, Da pedra angular,\\nFazer o mundo ver quem é Jesus,\\nPara erguer murais, colunas de palácios,\\nLá nas mansões celestiais\"},{\"section_type\":\"Coro\",\"content\":\"Vamos para o Céu, com mãos em mãos unidas;\\nLado a lado com Jesus\\nNós vamos para o Céu, cantar canções em coro;\\nEu e você vamos lá!\\nLá nas mansões celestiais.\"}]},{\"number\":\"493\",\"collection_type\":\"Hinário\",\"title\":\"Minha Mão em Tua Mão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Uma vez pela noite mui triste me achava,\\nNum intenso e terrível negror,\\nE ao sentir-me tão só eu clamei: ó Pai,\\nNão escondas Teu rosto de amor.\"},{\"section_type\":\"Coro\",\"content\":\"Minha mão em Tua mão\\nQuero ter ao seguir\\nDaqui ao distante lar.\\nVem me guiar com Teu amor,\\nSempre junto de Ti, Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Poderei, qual um rei, habitar um palácio,\\nTer poder e riquezas na mão,\\nMas mui triste serei se estiver a sós,\\nEm angústia e cruel solidão.\"}]},{\"number\":\"494\",\"collection_type\":\"Hinário\",\"title\":\"Vem Dedicar-te, ó Mocidade\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem dedicar-te ó mocidade!\\nÀ obra santa lancemos mão,\\nAntegozando felicidade\\nQue só os santos alcançarão.\"},{\"section_type\":\"Estrofe\",\"content\":\"A hora é tarde, a ceifa é grande,\\nVem, jovem, antes de o sol se pôr!\\nNão te demores, vem logo, atende\\nO amável Mestre e Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"No fim da safra, faremos molhos,\\nSerão as almas que Deus nos deu;\\nAo levantarmos os nossos olhos,\\nVeremos Cristo descer do Céu.\"},{\"section_type\":\"Estrofe\",\"content\":\"A alegria que Deus prepara\\nPara os remidos já começou:\\nUm movimento que não mais pára,\\nNa mocidade que Deus salvou.\"}]},{\"number\":\"495\",\"collection_type\":\"Hinário\",\"title\":\"Haja Paz na Terra\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Haja paz na terra, a começar em mim;\\nHaja paz na terra, a começar em mim.\\nIrmãos nós todos somos,\\nFilhos do mesmo Deus.\\nJuntos pois caminhemos,\\nNa paz que vem dos Céus.\\nA começar em mim, prometo ao meu Senhor\\nQue a cada passo que eu der, e seja onde for,\\nA cada momento estarei vivendo em plena paz e amor.\\nHaja paz na terra, a começar em mim.\"}]},{\"number\":\"496\",\"collection_type\":\"Hinário\",\"title\":\"Cristo, Dá-nos Tua Paz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, deixa Cristo, o grande Mestre,\\nEnvolver-te com amor;\\nAbre o coração e escuta a Sua voz.\\nMuitos problemas que te trazem\\nA tristeza e a dor,\\nNão terão lugar se Cristo em ti morar.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo, ó Cristo,\\nDá-nos Tua paz!\\nCristo, ó Cristo,\\nDá-nos Tua paz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, canta agora a melodia\\nQue enternece o coração,\\nCom louvor suave e doce ao Senhor.\\nSim, toda lágrima e tristeza\\nHão de desaparecer;\\nHás de ter mais vida em Cristo, o Salvador.\"}]},{\"number\":\"497\",\"collection_type\":\"Hinário\",\"title\":\"Queremos Dar Louvor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem nos inspirar\\nVem nos ensinar, Senhor,\\nNa luz do Teu Espírito.\\nVem nos animar,\\nVem nos transformar, Senhor,\\nCom Teu poder e glória.\"},{\"section_type\":\"Coro\",\"content\":\"Senhor, queremos dar louvor\\nEm gratidão a Ti.\\nAceita nosso coração.\\nVem transformar nosso ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem nos ajudar,\\nVem nos consolar, Senhor;\\nQue a tua paz esteja em nós.\\nDá-nos Teu poder\\nPra te obedecer e crer\\nEm Teu sacrifício\"}]},{\"number\":\"498\",\"collection_type\":\"Hinário\",\"title\":\"Nada Impossível É\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu li na Escritura a promessa de Deus\\nDe seu grande amor e poder\\nO mais impossível por Deus se fará\\nSe na Sua Palavra se crer\"},{\"section_type\":\"Coro\",\"content\":\"Nada impossível é,\\nSe a fé em Deus tu tens\\nNada impossível é,\\nSe na Bíblia crês também\\nEis a voz de Deus falando a ti:\\n\\\"Nada é impossível para Mim\\\"!\\nConfia, pois, somente em Deus\\nE na Palavra crê,\\nPois tudo, sim, oh, tudo enfim,\\nSim, sempre bem possível é com Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, tudo é possível, a Bíblia o diz!\\nTu deves portanto aceitar.\\nSim, crê na Palavra de nosso bom Deus;\\nAs promessas não hão de falhar.\"}]},{\"number\":\"499\",\"collection_type\":\"Hinário\",\"title\":\"Não Me Esqueci de Ti\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se as ondas desta vida destruírem tua fé\\nE fizerem que duvides de que em breve voltarei,\\nVolve os olhos ao passado, vê na cruz o Meu sofrer.\\nQueres provas mais do que esta? Tanto amei que a vida dei!\"},{\"section_type\":\"Coro\",\"content\":\"Mas ainda que demore ou mesmo que pareça,\\nUm dia prometi voltar e pronto estou a cumprir.\\nMas ainda que demore ou mesmo que pareça,\\nEu não Me esqueci de ti: Virei outra vez.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pensas mesmo ser tão fácil, esquecer o que falei,\\nSe na história deste mundo já Meus pés empoeirei?\\nMesmo que uma mãe viesse de seu filho se esquecer,\\nInda assim não haveria de Me esquecer de ti.\"}]},{\"number\":\"500\",\"collection_type\":\"Hinário\",\"title\":\"Deus Sabe, Deus Ouve, Deus Vê\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Você que se sente pequeno,\\nDirija seus olhos a Deus;\\nNão deixe que sombras o envolvam,\\nEntregue sua vida a Deus.\"},{\"section_type\":\"Coro\",\"content\":\"Deus sabe o que vai dentro d'alma,\\nDeus ouve a oração suplicante,\\nDeus vê sua angústia e o acalma,\\nDeus faz de você um gigante.\\nDeus sabe o que vai dentro d'alma,\\nDeus ouve a oração suplicante,\\nDeus vê sua angústia e o acalma;\\nDeus sabe, Deus ouve, Deus vê.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se a vida levou os castelos,\\nQue em sonhos você construiu,\\nNão dê por vencidos seus planos,\\nEntregue seus planos a Deus.\"}]},{\"number\":\"501\",\"collection_type\":\"Hinário\",\"title\":\"Mansão Sobre o Monte\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Aguardo o dia de emoção sem-par,\\nNo qual terei um belíssimo lar,\\nEntre colinas e vales formosos,\\nDonde se avista a cidade eternal.\"},{\"section_type\":\"Coro\",\"content\":\"Terei uma casa, no alto do monte,\\nCom flores lindas por todo o jardim;\\nAves cantando nas copas frondosas,\\nRejubilando, na vida sem fim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Manhãs bem claras, sem nuvens escuras,\\nO Sol radiante, está sempre a brilhar;\\nAnimaizinhos, sem susto ou temores,\\nEntre crianças a correr e a brincar.\"}]},{\"number\":\"502\",\"collection_type\":\"Hinário\",\"title\":\"Vaso Novo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ser Senhor amado;\\nComo um vaso nas mãos do oleiro,\\nQuebra a minha vida e faz-se-a de novo.\\nEu quero ser, Eu quero ser\\nUm Vaso Novo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Faz teu querer Senhor amado,\\nÉs o oleiro e eu esse vaso.\\nQuebra minha vida e faz-se a de novo.\\nEu quero ser, eu quero ser\\nUm Vaso Novo\"}]},{\"number\":\"503\",\"collection_type\":\"Hinário\",\"title\":\"Deixa-me Contigo Andar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deixa-me, Senhor, contigo andar\\nNo caminho ao lar de amor.\\nSó contigo quero caminhar,\\nPois confio em Ti, Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"Meu Deus, meu Deus,\\nEis-me ao Teu lado!\\nSó contigo quero caminhar,\\nPois confio em Ti, Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tão sozinho andou meu coração,\\nLonge dos caminhos Teus!\\nHoje eu canto em minha oração:\\nQuero andar contigo, ó Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ah! se o mundo inteiro meditar\\nNo valor real da cruz!\\nLogo arrependido vai estar,\\nCaminhando com Jesus.\"}]},{\"number\":\"504\",\"collection_type\":\"Hinário\",\"title\":\"Da Igreja o Fundamento\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Da Igreja o fundamento é Cristo, o Salvador,\\nE nele ela descansa, é forte em Seu amor;\\nEm Cristo edificada, bem firme ficará,\\nPois sobre a Rocha eterna, jamais se abalará.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Pedra mui preciosa que Deus providenciou,\\nSustenta pedras vivas que a graça trabalhou;\\nSejamos sempre unidos, vivendo em plena luz,\\nE a glória desta Igreja será do Rei Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em meio às duras lutas que deve confrontar,\\nEspera a Igreja, em Cristo, um dia triunfar,\\nPois a visão gloriosa enfim se cumprirá,\\nE a Igreja vitoriosa, em paz repousará.\"}]},{\"number\":\"505\",\"collection_type\":\"Hinário\",\"title\":\"Somos um Pequeno Povo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Somos um pequeno povo mui feliz!\\nSomos um pequeno povo mui feliz!\\nCristo veio nos salvar, breve nos virá buscar;\\nSomos um pequeno povo mui feliz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Os sinais de Sua volta aí estão,\\nEis os povos em tremenda inquietação;\\nEis a ciência a aumentar, e a impiedade a se agravar;\\nLogo Cristo nos trará libertação!\"},{\"section_type\":\"Estrofe\",\"content\":\"'Stá mui prestes o momento da emoção!\\nVai bater acelerado o coração!\\nNossos olhos levantar! Para o céu bem firme olhar!\\nJá vem vindo a tão sonhada redenção!\"},{\"section_type\":\"Estrofe\",\"content\":\"Somos um pequeno povo mui feliz!\\nSomos um pequeno povo mui feliz!\\nCristo veio nos salvar, breve nos virá buscar;\\nSomos um pequeno povo mui feliz!\"}]},{\"number\":\"506\",\"collection_type\":\"Hinário\",\"title\":\"Fortalece Tua Igreja\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Fortalece Tua Igreja, ó bendito Salvador;\\nAquecendo nossas almas no divino, santo amor.\\nVem, derrama sobre todos toda a graça de Jesus,\\nDando as bênçãos da verdade que nos mostram Tua luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pai, contempla Tua Igreja, vem, estende Tua união.\\nDá-lhe a graça insondável da divina redenção,\\nAntes que ela desfaleça, e se tome sem vigor;\\nVivifica, vivifica nossas almas, ó Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Santifica Tua Igreja pela graça divinal;\\nFaze-a sempre triunfante no conflito contra o mal;\\nDá-lhe forças na jornada em demanda para o lar,\\nque esteja preparada quando Cristo regressar!\"}]},{\"number\":\"507\",\"collection_type\":\"Hinário\",\"title\":\"Ó, Vem à Igreja Comigo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que prazer, que alegria celeste,\\nEstarmos perante o Senhor!\\nTodos juntos, unidos em Cristo,\\nAo bom Deus elevarmos louvor!\"},{\"section_type\":\"Coro\",\"content\":\"Ó, vem, vem, vem, vem,\\nVem à igreja comigo,\\nLouvar e adorar ao Senhor!\\nOh, quão bom é estarmos unidos\\nPelos laços fraternos do amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Privilégio maior não existe,\\nQue estarmos com nosso bom Deus;\\nEscutar Seus amáveis conselhos,\\nReceber ricas bênçãos dos Céus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre aguardo ansioso a chegada\\nDo dia do Deus, Criador;\\nNesse dia minh'alma contente\\nRende graças e ações de louvor.\"}]},{\"number\":\"508\",\"collection_type\":\"Hinário\",\"title\":\"Rumo à Escola Sabatina\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Prontidão às armas vamos demonstrar\\nE a bandeira do Senhor já desfraldar;\\nPela honra e glória dele batalhar;\\nNão voltemos para trás!\"},{\"section_type\":\"Coro\",\"content\":\"Dai louvor, dai louvor!\\nAclamai, exaltai\\nAo Senhor, ao Senhor,\\nCriador da Terra e Céu!\\nCom fervor aqui na escola de Jesus,\\nPela fé andemos na divina luz,\\nA coroa vem após amarga cruz;\\nNão voltemos para trás!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, na Escola Sabatina quero estar,\\nPara as armas aprender a manejar,\\nE depois, no campo, fora, batalhar;\\nNão voltemos para trás!\"},{\"section_type\":\"Estrofe\",\"content\":\"Alegria eterna segue a luta aqui;\\nNossas mágoas nunca chegarão ali;\\nEm Sião há gozo para mim e ti;\\nNão voltemos para trás!\"}]},{\"number\":\"509\",\"collection_type\":\"Hinário\",\"title\":\"A Escola Sabatina\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em Teu nome começamos\\nEsta escola, ó Senhor!\\nCom fervor nós Te rogamos\\nSejas o nosso Diretor.\"},{\"section_type\":\"Coro\",\"content\":\"Cada sábado nós vimos\\nÀ Tua escola, ó Jesus!\\nVem, ó Mestre, instruir-nos\\nNo caminho Teu de luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Esta escola nos ensina\\nEm Tua santa lei viver,\\nE nos manda que sejamos\\nSempre fiéis, até morrer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem, Senhor, vem ensinar-nos\\nTeus preceitos bem cumprir.\\nEis, reunidos, esperamos\\nTua presença aqui sentir.\"}]},{\"number\":\"510\",\"collection_type\":\"Hinário\",\"title\":\"Meu Jesus Está Chamando\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus está chamando,\\nCom amor me convidando,\\nSua voz, solicitando:\\nVem a Mim e segue-Me.\"},{\"section_type\":\"Coro\",\"content\":\"Minha cruz eu tomo e sigo,\\nA Jesus eu sempre sigo;\\nAonde for, a Ele eu sigo,\\nSeguirei a meu Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se o caminho for custoso,\\nE o trabalho mui penoso,\\nMesmo assim fico animoso,\\nQuando sigo a meu Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo sempre vai adiante\\nCom a Sua luz brilhante;\\nSempre avanço triunfante,\\nQuando sigo a meu Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pelo vale Cristo guia;\\nQuando fraco, me auxilia;\\nMinhas dores alivia;\\nSeguirei a meu Jesus.\"}]},{\"number\":\"511\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Que Belos Hinos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! que belos hinos cantam lá nos Céus!\\nÉ que o filho mau, ao lar voltou!\\nVede lá ao longe o Pai já abraçar\\nEsse filho que Ele tanto amou.\"},{\"section_type\":\"Coro\",\"content\":\"Glória, anjos mil entoam lá!\\nGlória, ouvem-se, as harpas já!\\nÉ o santo coro dando o seu louvor,\\nPois se converteu um pecador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que belos hinos cantam lá nos Céus!\\nPois se converteu um pecador!\\nAlma revoltosa, convertida a Deus,\\nDeixa o mundo e volta ao Pai de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! arrependidos, hoje festejai,\\nComo os anjos fazem com fervor!\\nIde pressurosos, vós, e anunciai,\\nQue se resgatou um pecador.\"}]},{\"number\":\"512\",\"collection_type\":\"Hinário\",\"title\":\"Às Águas do Jordão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Às águas do Jordão desceu\\nJesus, o Redentor,\\nO Deus eterno que morreu\\nPor nós em santo amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"O exemplo Seu devemos ter\\nPor lei a nos cingir.\\nQuem salvo está por Seu poder,\\nSeus passos quer seguir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por nós morreu Jesus na cruz,\\nE nos remiu do mal;\\nAbriu caminho que conduz\\nÀ vida divinal.\"}]},{\"number\":\"513\",\"collection_type\":\"Hinário\",\"title\":\"As Águas Batismais\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nas claras águas deste mar,\\nOs meus pecados deixarei,\\nDepois, então, irei morar\\nCom o divino Rei.\"},{\"section_type\":\"Coro\",\"content\":\"Deixarei no mar,\\nMinhas culpas deixarei, deixarei;\\nDeixarei, no mar,\\nE no Céu irei morar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Desejo agora consagrar\\nA minha vida ao Salvador,\\nDeixando todo o meu pesar\\nAos pés do Redentor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aqui as culpas vou deixar,\\nE vida nova então terei,\\nE assim um dia irei morar\\nCom o divino Rei.\"}]},{\"number\":\"514\",\"collection_type\":\"Hinário\",\"title\":\"O Alvo Supremo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O mundo vil já desprezei\\nE seu prazer abominei;\\nE rogo a Ti, ó Salvador,\\nQue agora eu viva em Teu amor.\"},{\"section_type\":\"Coro\",\"content\":\"Ó meu Jesus, me guia, sim,\\nCom Tua luz e amor sem fim,\\nE me sustém até chegar\\nÀs portas do celeste lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"No mundo aqui não tenho paz,\\nPois ele não me satisfaz;\\nMas com Jesus eu hei de ter\\nGrande alegria em meu viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"De meu Senhor eu quero ser,\\nE Sua causa promover.\\nE pela fé já avistei\\nO lar em que descansarei.\"}]},{\"number\":\"515\",\"collection_type\":\"Hinário\",\"title\":\"Importa Renascer\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Um rico, de noite, chegou a Jesus,\\nA fim de saber o caminho da luz.\\nO Mestre, bem claro lhe fez entender:\\nImporta renascer!\"},{\"section_type\":\"Coro\",\"content\":\"Importa renascer!\\nImporta renascer!\\nCom voz infalível o disse Jesus:\\nImporta renascer!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vós, filhos do mundo, escutai ao Senhor,\\nQue sempre vos chama com mui terno amor.\\nOuvi que o Senhor nunca cessa em dizer:\\nImporta renascer!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó vós que no santo descanso de Deus\\nQuereis ter entrada e viver com os Seus,\\nDeveis à palavra de Cristo atender:\\nImporta renascer!\"}]},{\"number\":\"516\",\"collection_type\":\"Hinário\",\"title\":\"Agora Posso Ver\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Agora enfim eu posso ver\\nDa fonte, ali, correr\\nO sangue que o meu Jesus\\nPor mim verteu na cruz.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, fonte, sim, de vida e amor,\\nQue vem tirar o mal e a dor!\\nOh, graças mil ao bom Jesus\\nQue a vida deu por mim na cruz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Que nova luz, mudança e paz\\nNo coração se faz!\\nO antigo ser, corrupto e vil,\\nNão mais se mostra hostil.\"},{\"section_type\":\"Estrofe\",\"content\":\"Andando estou à luz do Céu;\\nPerdão se deu ao réu!\\nJustiça Cristo me outorgou,\\nE agora salvo estou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Grandiosa graça revelou\\nQuem sangue derramou!\\nPor toda a vida hei de cantar\\nA redenção sem-par!\"}]},{\"number\":\"517\",\"collection_type\":\"Hinário\",\"title\":\"Volto ao Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem longe do Senhor vaguei,\\nVolto agora ao lar.\\nVeredas más eu já trilhei;\\nÓ Deus, volto ao lar.\"},{\"section_type\":\"Coro\",\"content\":\"Volto ao lar, volto ao lar,\\nNão há mais vagar.\\nAbre, ó Pai, os braços Teus;\\nVolto ao lar, meu Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu tempo em vão desperdicei,\\nVolto agora ao lar.\\nLamento haver ferido a lei;\\nÓ Deus, volto ao lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já farto estou do mal, da dor,\\nVolto agora ao lar.\\nConfio em Ti, em Teu amor;\\nÓ Deus, volto ao lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O teu perdão me é mister,\\nVolto agora ao lar.\\nBem puro e limpo faz-me ser;\\nÓ Deus, volto ao lar.\"}]},{\"number\":\"518\",\"collection_type\":\"Hinário\",\"title\":\"A Jesus Seguir Eu Quero\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A Jesus seguir eu quero,\\nSeja a sorte, sim, qualquer;\\nOnde quer que vá meu Mestre,\\nSeguirei, sem mais temer.\"},{\"section_type\":\"Coro\",\"content\":\"Ó Jesus, seguir-Te quero;\\nTu morreste, foi por mim.\\nMesmo que Te neguem todos,\\nEu Te sigo até o fim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se o caminho for custoso,\\nNele houver escuridão,\\nPor ali Tu já passaste,\\nE me tomas pela mão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se encontrar dificuldades,\\nE envolver-me a tentação,\\nTu também tentado foste,\\nE sofreste provação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se Tu queres conduzir-me\\nPela triste solidão,\\nTu andaste no deserto,\\nE meus pés seguir-Te-ão.\"},{\"section_type\":\"Estrofe\",\"content\":\"E se for Tua vontade\\nQue eu transponha o rio Jordão,\\nTu também o atravessaste;\\nSeguirei com prontidão.\"}]},{\"number\":\"519\",\"collection_type\":\"Hinário\",\"title\":\"O Pão da Vida\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó Tu que deste o pão, lá junto ao mar,\\nVem dá-lo a mim também, Jesus, vem dar!\\nPois, na Palavra, ó Deus, pão busco achar,\\nO santo pão que me há de sustentar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Tua bênção dar, vem, ó Senhor;\\nVem e revela, então, o Teu amor.\\nPai, muitas graças dou por este pão,\\nLuz que provém do Céu e traz perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"É vida o Teu falar, sim, ao que crer.\\nEu quero a lei guardar, e em Ti viver,\\nMas fraco sou, Senhor, vem me ajudar,\\nSim, sempre até ao lar de além chegar.\"}]},{\"number\":\"520\",\"collection_type\":\"Hinário\",\"title\":\"A Ceia do Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Como irmãos, nos acheguemos ao festim do Salvador;\\nEsta é a santa ceia, memorial do eterno amor.\\nOs emblemas que hoje temos simbolizam redenção,\\nPois de Deus o sacrifício limpa o mal e traz perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nosso mau e vil pecado, trouxe dor e perdição,\\nMas de Deus o amor profundo nos livrou da escravidão.\\nAo pensarmos que esta ceia lembra a morte de Jesus,\\nVemos, sim, a nossa culpa; morto foi por nós na cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tudo, enfim, de rude e triste, nessa cruz desfeito está;\\nPara nós somente existe gozo em Deus, que durará.\\nDamos graças e louvores, homenagens ao Senhor;\\nTemos fé em Sua vinda, Seu real e eterno amor.\"}]},{\"number\":\"521\",\"collection_type\":\"Hinário\",\"title\":\"Senhor, Tu nos Convidas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Senhor, Tu nos convidas a ceia a celebrar,\\nDeixar as nossas lidas e o Teu favor gozar.\\nPor nós provaste a morte, e dás o vinho e o pão,\\nQue são um simbolismo de fé na redenção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Do Céu, o Pão partido em dores e aflição,\\nPor Deus oferecido, nos trouxe a salvação.\\nA taça de amargura tomaste Tu, Jesus!\\nMas cálix de doçura nos dás em vez de cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, Teu sacrifício proveu libertação,\\nNos trouxe vida nova, nos deu a redenção.\\nAo Céu acesso temos por Ti, Jesus Senhor;\\nAgora compreendemos o Teu eterno amor.\"}]},{\"number\":\"522\",\"collection_type\":\"Hinário\",\"title\":\"Pelo Pão Nós Oramos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pelo pão nós oramos, ó Senhor.\\nPelo pão nós oramos, ó Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"E contritos aqui meditamos em Teu amor.\\nSenhor, ouve a nossa voz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Pelo vinho oramos, ó Senhor.\\nPelo vinho oramos, ó Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"E agora louvamos-Te, ó Senhor.\\nE agora louvamos-Te, ó Senhor.\"}]},{\"number\":\"523\",\"collection_type\":\"Hinário\",\"title\":\"Envio a Ti\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Envio a ti aos campos da seara,\\nSemear, ceifar, sem honras receber;\\nSofrer por Mim ingratidão e escárnio;\\nContigo- estou, terás o Meu poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Envio a ti aos corações que odeiam\\nAos olhos cegos que não querem ver;\\nGastar-te até o sangue, sem poupar-te;\\nÓ, vai e lembra todo o Meu sofrer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Envio a ti às almas quebrantadas,\\nE por alguém orar, chorar, velar;\\nO fardo erguer de corações cansados;\\nVai com fervor do Meu amor falar.\\nComo o Pai enviou-Me a Mim,\\nEu envio a ti.\"}]},{\"number\":\"524\",\"collection_type\":\"Hinário\",\"title\":\"Quem se Dispõe a Ir?\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quem se dispõe a ir aos campos do Senhor?\\nE com disposição sair, ceifar com todo ardor?\\nChegado já está o tempo de ceifar;\\nO nosso Redentor virá os molhos Seus buscar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Crescem as ervas más que o trigo estragarão;\\nDeixai o joio para trás, trazei do trigo o grão.\\nA noite logo vem, depressa ao campo entrai;\\nAs sombras descem já do além, depressa trabalhar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Quantos atenderão à voz do Salvador?\\nÓ, vinde para a frente então, à frente do labor!\\nO grande Rei dos reis será o Capitão,\\nE lá no Céu enfim tereis eterno galardão.\"}]},{\"number\":\"525\",\"collection_type\":\"Hinário\",\"title\":\"Obedecer é Melhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Obedecer é melhor do que sacrificar;\\nMelhor é sempre atender a Deus e a lei guardar.\"},{\"section_type\":\"Coro\",\"content\":\"A Deus com fé, nossa alma volvamos,\\nÀ Sua lei obedeçamos,\\nPois obedecer é melhor do que sacrificar,\\nMelhor é sempre atender a Deus\\nE a lei guardar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dizeis que não é preciso mais a lei guardar?\\nOlhai que a Bíblia em lugar algum a faz tombar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Virão as bênçãos de Deus a quem a lei seguir;\\nOh! sim, Jesus nos ajuda a toda a lei cumprir.\"}]},{\"number\":\"526\",\"collection_type\":\"Hinário\",\"title\":\"A Lei do Meu Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sábia, justa, santa e pura\\nÉ a lei do meu Senhor,\\nQue corrige a vida impura\\nDo perdido pecador.\\nDo Senhor o ensinamento\\nSempre ali perfeito está;\\nÉ tão rica em Seus preceitos\\nE conselhos santos dá!\"},{\"section_type\":\"Estrofe\",\"content\":\"Do Senhor os bons conselhos,\\nJustos e benignos são;\\nNeles vejo, quais espelhos,\\nQuanto é mau meu coração.\\nMais que o Sol resplandecente,\\nOs preceitos do Senhor\\nIluminam nossa mente,\\nCom divino resplendor.\"}]},{\"number\":\"527\",\"collection_type\":\"Hinário\",\"title\":\"Sábado do Meu Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Gosto de cantar um hino\\nAo sentir cercar-me o mal,\\nAo vagar qual peregrino\\nPara o lar celestial.\\nMas real prazer no canto\\nSinto ao dar o meu louvor,\\nAo cantar no dia santo,\\nSábado do meu Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que prazer ouvir as vozes,\\nCoros mil angelicais!\\nDores vis, as mais atrozes,\\nLogo não as sinto mais.\\nMas real prazer no canto\\nSinto ao dar o meu louvor,\\nAo cantar no dia santo,\\nSábado do meu Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ouço a voz da Natureza\\nA louvar o Criador;\\nPenso a sós, com tal beleza,\\nQuanto é débil meu louvor.\\nMas real prazer no canto\\nHei de ter no lar de amor,\\nAo louvar o Mestre santo,\\nGrande Deus e Redentor.\"}]},{\"number\":\"528\",\"collection_type\":\"Hinário\",\"title\":\"Sábado\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Como estão felizes nossos corações!\\nLivres de cuidados, lutas e aflições.\\nDamos-Te louvores, nosso Criador,\\nNeste santo dia, dia do Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Somos atraídos pelo Teu amor,\\nNestas horas santas, cheias de dulçor.\\nEste amor nos fala bem ao coração,\\nSobre a eterna graça, nossa redenção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Seja-nos suave para o coração,\\nTeu sagrado dia, Tua criação.\\nNossos vis pecados, lança para trás;\\nDá-nos neste dia Tua excelsa paz!\"}]},{\"number\":\"529\",\"collection_type\":\"Hinário\",\"title\":\"A Semana Já Passou\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A semana já passou, o Senhor guiou-nos bem;\\nO Seu povo se lembrou que, reunido, bênçãos tem.\\nÉ dos sete o dia melhor, de descanso e de louvor,\\nÉ dos sete o dia melhor, de descanso e de louvor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vimos Te pedir perdão, dom do amado Redentor,\\nDá-nos Tua compaixão, e Teu manto protetor;\\nLivres de cuidado aqui, descansamos hoje em Ti;\\nLivres de cuidado aqui, descansamos hoje em Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Desejamos Te louvar, Tua presença aqui sentir;\\nNeste culto vislumbrar esperanças do porvir.\\nPaz e glória lá dos Céus, manifesta já, ó Deus!\\nPaz e glória lá dos Céus, manifesta já, ó Deus!\"}]},{\"number\":\"530\",\"collection_type\":\"Hinário\",\"title\":\"O Sábado Chegou\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Lento e calmo foge o dia, já a tarde se apagou;\\nOh, que paz e que alegria, pois o sábado chegou!\\nÉs bem-vindo, és bem-vindo, santo dia do Senhor!\\nÉs bem-vindo, és bem-vindo, santo dia do Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Esta hora de bonança lembra o Deus que nos criou,\\nPois o dia de lembrança, nosso Pai santificou.\\nÉs bem-vindo, és bem-vindo, memorial da criação!\\nÉs bem-vindo, és bem-vindo, memorial da criação!\"},{\"section_type\":\"Estrofe\",\"content\":\"Esta hora de harmonia lembra o Deus que nos salvou,\\nCristo lá na tumba fria, neste dia descansou.\\nÉs bem-vindo, és bem-vindo, memorial da redenção!\\nÉs bem-vindo, és bem-vindo, memorial da redenção!\"}]},{\"number\":\"531\",\"collection_type\":\"Hinário\",\"title\":\"Do Santo Sábado Es Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Horas benditas,\\nSantas e felizes,\\nSão as que passo\\nJunto a Ti, meu Deus.\"},{\"section_type\":\"Coro\",\"content\":\"Ó Mestre amado,\\nCriador divino,\\nDo santo sábado,\\nTu és Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Busco Tua face\\nDe manhã bem cedo,\\nPois Tuas bênçãos\\nQuero receber.\"},{\"section_type\":\"Estrofe\",\"content\":\"E logo à tarde,\\nQuando o Sol se esconde,\\nQuero, prostrado,\\nAos Teus pés estar.\"}]},{\"number\":\"532\",\"collection_type\":\"Hinário\",\"title\":\"Bem-vindo o Sábado\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem-vindo é a nós, o sábado feliz!\\nDo grande amor de Deus, de Seu poder nos diz.\\nBem longe põe o mundo vil,\\nA luta, a dor, trabalhos mil;\\nO amor e a doce paz do Céu nos traz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Príncipe dos Céus, renova-nos o ser,\\nAté se achar em nós justiça, amor, poder.\\nPor Teu amor que é sem igual,\\nOh, livra-nos de todo o mal,\\nE dá-nos proteção, e salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com Teu poder, oh, vem, bendize-nos, Senhor;\\nConserva-nos no bem, na luz do Teu amor.\\nA cada um concede, então,\\nO Teu favor e o Teu perdão,\\nE lá no bom país, um lar feliz.\"}]},{\"number\":\"533\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Salva\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ó, vinde, vós aflitos, já\\nAo trono do Senhor;\\nAbrigo Cristo vos dará,\\nRefúgio em Seu amor.\"},{\"section_type\":\"Coro\",\"content\":\"Cristo salva, Cristo salva,\\nSalva o pecador!\\nCristo salva, Cristo salva,\\nPor Seu grande amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Seu sangue derramou por nós,\\nE assim nos veio abrir\\nEstrada reta que conduz\\nAo Céu, o bom porvir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus é vida, paz e luz,\\nDo mundo o Redentor;\\nE tudo, enfim, Jesus concede\\nAo pobre pecador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó, vinde, pois, ó, vinde já\\nA Cristo vos unir!\\nPerdão Jesus concederá\\nA quem a luz seguir.\"}]},{\"number\":\"534\",\"collection_type\":\"Hinário\",\"title\":\"Salvo em Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Salvo em Jesus, meu Mestre, tenho perfeita paz;\\nTal comunhão com Ele toda aflição desfaz.\\nEle me deu certeza da minha salvação;\\nOh, que prazer glorioso enche meu coração!\"},{\"section_type\":\"Coro\",\"content\":\"Salvo em Jesus, meu Mestre,\\nTenho perfeita paz,\\nTal comunhão com Ele\\nToda aflição desfaz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é minha vida, fonte Ele é de amor.\\nTira de mim as mágoas, todo o pesar e a dor.\\nE, se eu sofrer a prova, fácil será ganhar;\\nE, se verter o pranto, logo Ele enxugará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Hei de passar a noite sem mais sentir temor;\\nBreve virá o dia de perenal fulgor.\\nOh, que prazer supremo ver a Jesus no lar,\\nE na mansão de glória com Ele então reinar!\"}]},{\"number\":\"535\",\"collection_type\":\"Hinário\",\"title\":\"Para o Céu por Jesus Irei\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Foi Jesus que abriu o caminho do Céu,\\nCaminho através da cruz.\\nNunca irei entrar no celeste lar\\nSe o caminho da cruz errar.\"},{\"section_type\":\"Coro\",\"content\":\"Para o Céu por Jesus irei,\\nPara o Céu por Jesus irei.\\nGrande é meu prazer de certeza ter:\\nPara o Céu pela cruz, irei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Certamente eu vou no caminho da cruz,\\nCom grande fervor andar.\\nÉ desejo meu desfrutar no Céu\\nEssa herança que Cristo deu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os caminhos maus deste mundo deixei;\\nJamais neles vou seguir.\\nSigo, pois, Jesus, com a minha cruz,\\nNo caminho que ao Céu conduz.\"}]},{\"number\":\"536\",\"collection_type\":\"Hinário\",\"title\":\"Por um Pecador Qual Eu\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Por um pecador qual eu,\\nSobre a cruz Jesus morreu;\\nQuis Seu sangue ali verter\\nPara eu poder viver;\\nSou eternamente Seu;\\nDEle sou e Ele é meu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que ilimitado amor\\nRevelou o Redentor!\\nNão é tão profundo o mar,\\nNem tão alto o céu sem-par!\\nEsse amor me procurou,\\nDespertou-me e me salvou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sei que pecador eu sou,\\nMas Jesus já me salvou.\\nSeu perdão eu vou buscar,\\nMeus pecados lança ao mar,\\nEm Seus braços me sustém,\\nE me guia até o além.\"}]},{\"number\":\"537\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Salva o Pecador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo salva o pecador,\\nLava o rude coração;\\nAo contrito, com amor,\\nOferece salvação.\"},{\"section_type\":\"Coro\",\"content\":\"Confiai em Seu poder;\\nConfiai em Seu amor,\\nCrede, sim, que Cristo quer\\nLibertar o pecador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo salva o pecador\\nE concede-lhe perdão.\\nAceitai o bom Senhor,\\nAceitai de coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vinde todos, e achareis\\nPaz e luz no Redentor,\\nVinde, então recebereis\\nVida eterna, do Senhor.\"}]},{\"number\":\"538\",\"collection_type\":\"Hinário\",\"title\":\"Ó, Vem a Jesus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus lá no Céu, já de glória revestido,\\nO meu Advogado Se constituiu;\\nE sempre sustenta e defende o redimido;\\nOh, podes dizer que também te remiu?\"},{\"section_type\":\"Coro\",\"content\":\"Ó, vem a Jesus! Ó, vem a Jesus!\\nEterna ventura terás pela cruz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Minh'alma tem paz, tudo é calmo como um rio;\\nÉ paz que no Céu tem o seu manancial;\\nFoi Deus quem ma deu, por Jesus em quem confio.\\nE tu, inda não tens a paz divinal?\"},{\"section_type\":\"Estrofe\",\"content\":\"Um manto tão alvo a mim foi outorgado,\\nLavado no sangue do meu Redentor!\\nO crente em Cristo, por Deus é perdoado;\\nTambém tu serás, crendo já no Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Morada já tenho com todos os remidos,\\nUm lar preparado na casa de Deus;\\nAli não há morte, nem mágoas, nem gemidos;\\nTerás tu também um lugar lá nos Céus?\"}]},{\"number\":\"539\",\"collection_type\":\"Hinário\",\"title\":\"Justificado\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Posso eu justificado ser,\\nCom meu passado mau de pecador?\\nMeu Jesus crucificado foi\\nE salvo então eu sou, por Seu amor.\\nQuão sublime graça e amor sem fim!\\nDons que Cristo dá a ti e a mim!\\nCom Jesus eu bem seguro estou,\\nPois Sua graça já me libertou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pela fé, justificado sou,\\nEm Cristo meu Senhor e Salvador;\\nPosso assim santificado ser,\\nE sempre andar no bem por onde for.\\nSei que minha força frágil é,\\nClamo a Deus se fraca sinto a fé;\\nSim, Jesus me diz que posso então\\nJustificado ser, por Seu perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Glória a Deus, justificado sou,\\nPois Cristo já limpou meu coração!\\nE a Jesus pra sempre exaltarei,\\nLouvores cantarei, em gratidão.\\nSei que vida eterna vai me dar,\\nSei que Cristo em breve irá voltar;\\nE porque justificado fui,\\nCom Ele ali no Céu terei meu lar.\"}]},{\"number\":\"540\",\"collection_type\":\"Hinário\",\"title\":\"A Revelação da Cruz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quão cego outrora eu já vaguei\\nDistante do Senhor,\\nQue veio lá dos altos Céus,\\nSalvar o pecador.\"},{\"section_type\":\"Coro\",\"content\":\"Foi na cruz, foi na cruz\\nEm que alfim percebi:\\nMeu pecado recaiu em Jesus!\\nFoi então, pela fé, que meus olhos abri,\\nQue prazer sinto agora em Sua luz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Do grande amor sem-par ouvi,\\nO amor de meu Jesus,\\nPorém eu surdo então me fiz\\nE desprezei a luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Temor da morte eu já senti,\\nPairando sobre mim;\\nAos pés de Cristo então corri\\nE achei abrigo enfim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Remido, ó Cristo, o coração\\nEu ponho ao Teu dispor;\\nTeu nome quero sempre honrar,\\nHonrar Teu santo amor.\"}]},{\"number\":\"541\",\"collection_type\":\"Hinário\",\"title\":\"De Jesus a Doce Voz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"De Jesus, a doce voz,\\nOuvi, eu, pecador.\\nAceitei, de coração,\\nJesus, meu Salvador.\"},{\"section_type\":\"Coro\",\"content\":\"Meu pecado, sim,\\nJá na cruz pagou,\\nE por graça sem igual,\\nJesus me resgatou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Retidão em mim não há,\\nPor graça salvo sou.\\nA Jesus sou devedor,\\nPois já me perdoou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por Jesus eu gozo paz,\\nE tenho Seu favor.\\nNada aqui me faltará,\\nSe estou junto ao Senhor.\"}]},{\"number\":\"542\",\"collection_type\":\"Hinário\",\"title\":\"Jesus é o Salvador\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Somente Cristo é Salvador,\\nE de outro não sabemos.\\nMorreu por nós em santo amor\\nE vida nEle temos.\"},{\"section_type\":\"Coro\",\"content\":\"Jesus, Jesus é o Salvador,\\nE não há outro mediador.\\nFoi Ele quem por nós morreu,\\nE vivo está por nós no Céu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os homens santos, bons, fiéis,\\nNós sempre respeitamos;\\nMas a Jesus, o Rei dos reis,\\nHumildes adoramos.\"},{\"section_type\":\"Estrofe\",\"content\":\"No santo sangue de Jesus\\nConfia todo crente.\\nO que Ele fez na rude cruz\\nÉ todo suficiente.\"}]},{\"number\":\"543\",\"collection_type\":\"Hinário\",\"title\":\"Na Balança do Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao pesar nossos motivos\\nO Juiz, em retidão,\\nNos terá por ouro puro,\\nOu refugo mau e vão?\"},{\"section_type\":\"Coro\",\"content\":\"Sim, na balança do Senhor\\nFoste pesado?\\nPela palavra do Senhor,\\nFoste aprovado?\"},{\"section_type\":\"Estrofe\",\"content\":\"O Senhor irá dizer-nos:\\n\\\"Bem está, servo fiel\\\"?\\nOu a nós dará a sentença:\\n\\\"Servo mau e infiel\\\"?\"},{\"section_type\":\"Estrofe\",\"content\":\"Hoje a voz de Deus ouçamos\\nA falar ao coração,\\nAntes que, passando a graça,\\nFique além a salvação.\"}]},{\"number\":\"544\",\"collection_type\":\"Hinário\",\"title\":\"O Juízo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Juiz Se assentou, abriram-se os livros;\\nQuem dentre nós subsistirá?\\nPois as ações e os pensamentos,\\nNosso Juiz à luz trará.\"},{\"section_type\":\"Coro\",\"content\":\"Quem haverá de subsistir?\\nQual há de ser a decisão?\\nVai ser perdido o nosso caso,\\nOu alcançamos o perdão?\"},{\"section_type\":\"Estrofe\",\"content\":\"O juízo iniciou-se pelos que dormem,\\nE então a nós irá passar.\\nLogo também os nossos casos\\nVai o Juiz apresentar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! como será perante o juízo?\\nNossas ações à luz virão!\\nQuando soar a voz dos livros,\\nQual há de ser a decisão?\"}]},{\"number\":\"545\",\"collection_type\":\"Hinário\",\"title\":\"Vem o Grande Dia\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem o grande dia, o grande dia,\\nVem o grande dia, sem tardar,\\nQuando os ímpios e santos separados hão de ser;\\n'Stais vós prontos para o dia final?\"},{\"section_type\":\"Coro\",\"content\":\"'Stais vós prontos? 'Stais vós prontos?\\n'Stais vós prontos para o dia final?\\n'Stais vós prontos? 'Stais vós prontos\\nPara o dia final?\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem o alegre dia, o alegre dia,\\nEste alegre dia perto está,\\nMas alegre será somente ao que ama o Salvador,\\n'Stais vós prontos para o dia final?\"},{\"section_type\":\"Estrofe\",\"content\":\"Um glorioso dia, glorioso dia,\\nUm glorioso dia há de ser,\\nMas a glória virá somente ao que ama o Salvador, '\\nStais vós prontos para o dia final?\"}]},{\"number\":\"546\",\"collection_type\":\"Hinário\",\"title\":\"Quando o Livro Aberto For\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando no juízo o livro aberto for\\nHás de ter real prazer?\\nEstará teu nome ao lado do Senhor\\nOu dos que hão de perecer?\"},{\"section_type\":\"Coro\",\"content\":\"Com fervor eu hei de então cantar\\nUm hino de louvor,\\nPois tenho, sim, o nome escrito já\\nNo livro do meu Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando ressoar o toque do clarim\\nE do Céu descer o Juiz,\\nEstarás então com os amigos Seus,\\nOu os inimigos vis?\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando o teu registro apresentado for\\nOuvirás Jesus dizer.\\n'Pai, o sangue Meu por ele derramei,\\nDeixa o pecador viver.'?\"}]},{\"number\":\"547\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Bela Terra de Esplendor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pra terra abençoada vou,\\nAnsioso peregrino sou\\nEm busca do feliz lugar\\nNo qual eu hei de descansar.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, bela terra de esplendor,\\nQuerida herança do Senhor;\\nOlhando, velo além do mar\\nQue em breve eu hei de atravessar,\\nA linda praia perenal,\\nDo eterno lar celestial.\"},{\"section_type\":\"Estrofe\",\"content\":\"Comigo vai o meu Senhor,\\nDo mal me guarda com amor,\\nDe paz transborda o coração,\\nE certo estou da salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na vastidão celestial\\nHá de soar canto imortal\\nDa triunfante multidão\\nCantando a grande redenção.\"}]},{\"number\":\"548\",\"collection_type\":\"Hinário\",\"title\":\"Há um País de Eterna Luz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há um país de eterna luz, um lar feliz nos Céus;\\nPra sempre ali está Jesus com os remidos Seus.\\nHá primavera sempre ali, e as flores durarão.\\nE longe não está daqui, dos salvos a mansão.\"},{\"section_type\":\"Estrofe\",\"content\":\"A terra é santa e pura, sim, e nela reina amor.\\nNenhum pecado mancha ali, o reino do Senhor.\\nAli não há de entrar o mal, nem chega a corrupção.\\nNaquela terra sem igual os justos reinarão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quisera já poder subir ao santo Céu de luz,\\nPerfeito ser e a paz fruir aos pés de meu Jesus!\\nSubindo o monte, com Moisés, avisto o bom país;\\nEsqueço o mundo e pela fé, eu sinto-me feliz.\"}]},{\"number\":\"549\",\"collection_type\":\"Hinário\",\"title\":\"A Glória Suprema\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tenho ouvido falar da cidade\\nMergulhada em reflexos de luz,\\nE dos anjos que, com majestade,\\nCantam hinos a Cristo Jesus.\\nAlegria terei\\nNa presença do Rei,\\nMas a glória maior fruirei\\nQuando vir almas salvas por mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tenho ouvido da terra formosa,\\nDe colinas e vales sem fim,\\nDe campinas com flores mimosas\\nE do rio no lindo jardim;\\nVida eterna há de ser\\nMeu quinhão, que prazer!\\nMas o gozo supremo hei de ter\\nQuando vir almas salvas por mim!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantaremos os frutos e as flores,\\nE as mansões de ouro puro e cristal,\\nA alegria perene, sem dores,\\nQue terão os fiéis afinal;\\nMas pra mim há de ser\\nMais glorioso prazer\\nQuando enfim Cristo me conceder\\nVer no Céu almas salvas por mim!\"}]},{\"number\":\"550\",\"collection_type\":\"Hinário\",\"title\":\"Marchando Para Sião\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O filhos de Sião, Honrai o Rei dos Reis\\nLouvor em alta voz cantai, Louvor em alta voz cantai.\\nEm breve ao Céu ireis, Em breve ao Céu ireis.\"},{\"section_type\":\"Coro\",\"content\":\"Sião é a nossa Santa é Gloriosa Cidade\\nTambém perene morada dos Salvos\\nEm Cristo Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os que do mundo são A Deus não dão louvor;\\nMas, filhos do Celeste Rei, mas filhos do celeste Rei,\\nLouvai o Salvador, Louvai o Salvador!\"},{\"section_type\":\"Estrofe\",\"content\":\"Erguei-vos ó cristãos, Marchando sem cessar,\\nAté herdardes lá no além, Até herdades lá no além,\\nSião, o eterno lar, Sião o eterno lar.\"}]},{\"number\":\"551\",\"collection_type\":\"Hinário\",\"title\":\"Muito Além do Sol\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu aqui no mundo não tenho riquezas,\\nMas sei que na Glória, eu terei mansão.\\nCom minh' alma triste, em meio à pobreza,\\nDe mim, Jesus Cristo teve compaixão.\"},{\"section_type\":\"Coro\",\"content\":\"Muito além do Sol, muito além do Sol.\\nEstá o meu lar, um belo lugar, muito além do Sol.\\nMuito além do Sol, muito além do Sol.\\nEstá o meu lar, um belo lugar, muito além do Sol.\"},{\"section_type\":\"Estrofe\",\"content\":\"Assim pelo mundo, eu vou caminhando;\\nEnfrentando lutas, prova e tentação.\\nMas, Jesus Meu Mestre, que me fortalece,\\nVai levar-me a salvo à real mansão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vinde, vós, cansados deste mundo escuro,\\nCristo vos concede plena salvação;\\nE também morada, feita não por homens,\\nQuer oferecer-vos na eternal Sião.\"}]},{\"number\":\"552\",\"collection_type\":\"Hinário\",\"title\":\"Cristo Foi Preparar-nos Lugar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo foi preparar-nos lugar\\nNa celeste morada do Pai,\\nOnde havemos de em breve chegar,\\nE onde nunca o pecado nos trai.\\nLá no Céu, lá no Céu,\\nCristo foi preparar-nos lugar;\\nLá no Céu, lá no Céu,\\nNa celeste morada do Pai.\"},{\"section_type\":\"Estrofe\",\"content\":\"Estaremos ali com Jesus,\\nDesfrutando sem fim Seu amor,\\nNa perene morada de luz,\\nInefável jardim do Senhor.\\nLá no Céu, lá no Céu,\\nEstaremos ali com Jesus;\\nLá no Céu, lá no Céu,\\nDesfrutando sem fim Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nesse lar tão feliz e eternal,\\nO pecado jamais há de entrar;\\nSó há glória, pureza e prazer;\\nLá os salvos com Cristo hão de estar.\\nLá no Céu, lá no Céu,\\nNesse lar tão feliz e eternal;\\nLá no Céu, lá no Céu,\\nAcharemos descanso afinal.\"}]},{\"number\":\"553\",\"collection_type\":\"Hinário\",\"title\":\"Há um Rio Cristalino\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Junto ao rio cristalino,\\nNo país do bom Senhor,\\nReunidos estaremos\\nCom os salvos, em louvor?\"},{\"section_type\":\"Coro\",\"content\":\"Sim, às margens desse rio,\\nNa mansão de glória e luz,\\nCom os santos cantaremos\\nEm louvor ao Rei Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Antes que daquele rio\\nNos possamos abeirar,\\nA justiça e santidade\\nCristo vai nos outorgar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós veremos breve o rio,\\nFinda a peregrinação,\\nE louvores sempiternos\\nNossos lábios cantarão.\"}]},{\"number\":\"554\",\"collection_type\":\"Hinário\",\"title\":\"Vamos Ver Jesus Ali\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se infeliz nos corre a vida terreal,\\nHemos de deixá-la um dia,\\nPara ir morar no lar celestial,\\nOnde tudo é mui feliz.\"},{\"section_type\":\"Coro\",\"content\":\"Vamos ver Jesus ali,\\nSua santa paz fruir;\\nE com Ele estar, Seu rosto contemplar,\\nE alegria desfrutar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Muitos são os males desta vida aqui;\\nHemos de deixá-la um dia.\\nRegozijo pleno vamos ter ali,\\nOnde tudo é mui feliz.\"},{\"section_type\":\"Estrofe\",\"content\":\"A vitória eterna que Jesus nos dá,\\nVamos recebê-la um dia.\\nAo findar a luta, calma nos virá,\\nOnde tudo é mui feliz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Todos os remidos se conhecerão,\\nSim, ali no Céu, um dia.\\nNa harmonia santa sempre viverão,\\nOnde tudo é mui feliz.\"}]},{\"number\":\"555\",\"collection_type\":\"Hinário\",\"title\":\"Até Então\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu coração alegre hoje canta,\\nAo relembrar que as dores cessarão;\\nVirá o fim a este mundo escuro;\\nMeu lar será nas terras de Sião.\"},{\"section_type\":\"Coro\",\"content\":\"Mas té então eu seguirei cantando,\\nTé então contente eu hei de estar,\\nAté o dia em que a cidade eu veja,\\nE ouça a Deus chamar-me ao lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A morte a e dor não mais pavor nos trazem,\\nPois eu bem sei que em breve findarão.\\nDe todo o mal que aqui nos faz trementes,\\nAo recordar os salvos sorrirão.\"}]},{\"number\":\"556\",\"collection_type\":\"Hinário\",\"title\":\"A Bela Cidade\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tenho lido da bela cidade,\\nConstruída por Cristo Jesus;\\nÉ murada de jaspe luzente;\\nToda cheia de glória e de luz;\\nE no meio da praça há um rio;\\nÉ qual fonte de vida eternal,\\nMas metade da glória celeste\\nJamais se contou ao mortal.\"},{\"section_type\":\"Coro\",\"content\":\"Jamais se contou ao mortal;\\nJamais se contou ao mortal;\\nMetade da glória celeste\\nJamais se contou ao mortal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tenho lido das lindas moradas\\nQue Jesus foi, no Céu, preparar,\\nOnde os crentes fiéis, para sempre,\\nMui felizes irão habitar.\\nNem tristeza, nem dor, nem temores\\nEntrarão na mansão paternal,\\nMas metade da glória celeste\\nJamais se contou ao mortal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tenho lido das vestes brilhantes,\\nDas coroas que os santos terão,\\nQuando o Pai os chamar e disser-lhes:\\n\\\"Recebei o eternal galardão.\\\"\\nTenho lido que os santos na glória\\nPisarão ruas de ouro e cristal,\\nMas metade da glória celeste\\nJamais se contou ao mortal.\"}]},{\"number\":\"557\",\"collection_type\":\"Hinário\",\"title\":\"Grandes Coisas, Mui Gloriosas\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Grandes coisas mui gloriosas,\\nDa cidade de Sião,\\nQue palavras não traduzem,\\nPreparadas já estão.\\nSeus preciosos fundamentos,\\nDeus os pôs, e eternos são.\\nEm moradas sempiternas\\nOs fiéis enfim reinarão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis as fontes cristalinas\\nD'águas vivas a jorrar;\\nNelas podem os remidos\\nSua sede saciar.\\nQue felizes habitantes\\nLá pra sempre viverão!\\nOh, que gozo, que alegria\\nHá de haver em ti, ó Sião!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó meu Mestre, quanto almejo\\nCom os santos ir morar!\\nNa cidade pelas portas,\\nCoroado hei de entrar.\\nPela graça inaudita\\nViverei na redenção.\\nGlória, glória, aleluia!\\nCantarei em ti, ó Sião!\"}]},{\"number\":\"558\",\"collection_type\":\"Hinário\",\"title\":\"Meu Doce Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pela estrada um dia ouvi\\nVoz melodiosa e mui gentil:\\n\\\"No Céu Eu estou a te preparar\\nUm belo, belíssimo lar.\\\"\"},{\"section_type\":\"Coro\",\"content\":\"Doce lar, doce lar,\\nOnde eu irei morar;\\nEu vejo ao longe a cidade de Luz,\\nMeu doce lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá hei de achar queridos meus\\nDando louvores a Jesus;\\nTambém vou louvá-lo nos altos Céus,\\nNo belo, belíssimo lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao lar eterno em breve irei,\\nJunto ao Senhor eu morarei.\\nAlém, bela praia a convidar\\nAo belo, belíssimo lar!\"}]},{\"number\":\"559\",\"collection_type\":\"Hinário\",\"title\":\"Feliz Manhã\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Já cansados seguimos de noite a penar,\\nNa jornada da vida cristã,\\nMas será para nós tão brilhante o raiar\\nDa gloriosa e feliz manhã.\"},{\"section_type\":\"Coro\",\"content\":\"Findarão as agruras da vida,\\nQuando a névoa do mal passar.\\nHá de a noite fugir ante o vivo luzir,\\nQuando o dia eternal raiar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Há tão grandes mistérios na trilha a seguir,\\nE prenúncios de lutas e dor,\\nMas de nós fugirão quando virmos luzir\\nSua face em real fulgor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mesmo que nos pareça o caminho sem fim,\\nTendo os olhos a lacrimejar,\\nRecompensas gloriosas teremos enfim,\\nNo bendito e eterno lar.\"}]},{\"number\":\"560\",\"collection_type\":\"Hinário\",\"title\":\"A Cidade de Ouro e Cristal\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"No Céu não há nenhum desgosto,\\nCansaço, tristeza nem dor,\\nNenhum coração quebrantado,\\nNem hino, senão de louvor.\\nAs nuvens que aqui são escuras,\\nNão mais haverão de existir,\\nLá tudo será alegria,\\nSem nunca um suspiro se ouvir.\"},{\"section_type\":\"Coro\",\"content\":\"Irei para aquela cidade\\nQue Deus para mim preparou;\\nAli todos os redimidos\\nSó cantam canções de louvor.\\nÀs vezes eu sinto saudade\\nDesta terra gloriosa eternal;\\nQue alegria será ver o meu Salvador,\\nNa cidade de ouro e cristal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na pátria que Deus nos prepara\\nDe graça teremos um lar,\\nAs vestes serão sempre novas,\\nNão hão de rasgar, nem manchar.\\nLá não haverá fome ou sede,\\nNem quem venha esmola pedir,\\nPois Deus Suas vastas riquezas\\nAos santos irá repartir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá não haverá dor ou pranto,\\nNem morte veremos jamais;\\nLá não mais nos separaremos,\\nNão mais se ouvirão tristes ais.\\nOs salvos serão sempre jovens\\nPois Cristo os transformará,\\nE num abrir e fechar d'olhos,\\nComo Ele, imortais nos fará.\"}]},{\"number\":\"561\",\"collection_type\":\"Hinário\",\"title\":\"No Celeste Lar Glorioso\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"No celeste lar glorioso\\nDa Jerusalém de Deus,\\nEu espero mui ansioso\\nEncontrar queridos meus!\\nLá hei de rever amigos,\\nQue me amavam como irmão,\\nE que aguardam, no jazigo,\\nA feliz ressurreição.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, vem tu também comigo,\\nÀ nova Jerusalém!\\nPois a ti, ó meu amigo,\\nQuero lá rever também.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá anseio ver amados\\nQue inda aqui em erro estão,\\nPois Jesus, seu Advogado,\\nInda faz intercessão.\\nLá desejo ouvir louvores\\nDe teus lábios meu irmão,\\nQuando após terrestres dores,\\nNós cantarmos em Sião.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando lá no lar divino\\nAo teu lado eu caminhar,\\nOh! Que gozo peregrino!\\nOh! Que glória singular!\\nQueres este gozo ansiado,\\nEsta glória que seduz?\\nSermos todos estreitados\\nPelos braços de Jesus?\"}]},{\"number\":\"562\",\"collection_type\":\"Hinário\",\"title\":\"Quão Doce é a Promessa\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quão doce e preciosa a promessa de Deus,\\nDe um lar com Jesus nos Céus!\\nAli peregrinos sem repouso ou paz,\\nTerão descanso eficaz.\"},{\"section_type\":\"Coro\",\"content\":\"Anseio meu lar; no Céu desejo estar!\\nQuando entrarei nas plagas de Sião?\\nAli não há mágoa ou morte a prantear;\\nAnseio a celeste mansão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Acima de tudo o que ali me seduz,\\nÉ ver meu Senhor Jesus,\\nBanhar-me na graça e aos pés do meu Senhor,\\nDepor todo o meu louvor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, pátria de luz onde espero morar,\\nE sempre com Cristo estar!\\nAli, com remidos, sempre viverei,\\nLouvando a Jesus, meu Rei!\"}]},{\"number\":\"563\",\"collection_type\":\"Hinário\",\"title\":\"Querido Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Querido lar, ali no Céu,\\nAlem do mundo, além do véu!\\nViver ali será prazer,\\nOh, quanto almejo já o ver!\"},{\"section_type\":\"Coro\",\"content\":\"Querido lar, oh, doce lar!\\nOnde eu pra sempre irei morar.\\nUm pouco mais e eu partirei;\\nNo eterno lar descansarei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Querido lar, ditoso lar!\\nAli ninguém vai mais chorar.\\nTristeza e dor, ou tentação,\\nNaquele lar não entrarão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Só vai entrar no lar de luz\\nQuem for remido por Jesus;\\nEu sei que Cristo, meu Senhor,\\nMe espera ali, no lar de amor.\"}]},{\"number\":\"564\",\"collection_type\":\"Hinário\",\"title\":\"Jamais se Diz Adeus Ali\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quão bom, amigos meus, é termos encontro aqui feliz,\\nMas sempre vem a hora triste em que adeus se diz.\"},{\"section_type\":\"Coro\",\"content\":\"Jamais se diz adeus ali,\\nJamais se diz adeus;\\nNo eterno lar de amor e paz,\\nJamais se diz adeus;\"},{\"section_type\":\"Estrofe\",\"content\":\"Quão doce é lembrarmos que quando Cristo aqui voltar,\\nNós juntos viveremos pra nunca mais nos separar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não mais teremos dor e nem despedida lá no lar,\\nMas grata união e paz iremos pra sempre desfrutar.\"}]},{\"number\":\"565\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Nunca Separar!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há um país de gozo e luz\\nOnde só santos há;\\nPrazeres há ali a flux;\\nÉ sempre dia lá.\"},{\"section_type\":\"Coro\",\"content\":\"Marchamos para a terra além\\nE vamos a Jerusalém;\\nIremos com Jesus reinar\\nE nunca mais nos separar.\\nOh, nunca separar?\\nNão, nunca separar!\\nOh, nunca separar?\\nNão, nunca separar!\\nIremos com Jesus reinar\\nE nunca mais nos separar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Há sempre primavera lá,\\nFlores não murcharão;\\nTão perto, sim, de nós está\\nA eternal mansão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Já nós estamos qual Moisés,\\nVendo o futuro lar;\\nE divisamos pela fé\\nA morada sem par.\"}]},{\"number\":\"566\",\"collection_type\":\"Hinário\",\"title\":\"Doce Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"À terra nós vamos dos fiéis e dos santos,\\nPaís de glória infinda, de bênçãos e luz;\\nJá fartos estamos de vaguear pelas trevas;\\nAo lar em breve iremos com Cristo Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Doce lar! Doce lar! Doce lar! Doce lar!\\nNo lar habitaremos com o nosso Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não entram desgostos neste lar, nem tristeza\\nSó paz e alegria ali reinarão.\\nEm nosso caminho vamos, pois, animosos,\\nPois Cristo, nosso Mestre, nos deu salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Andemos ousados para o lar, bem contentes,\\nEmbora carregando o opróbrio da cruz.\\nA terra avistamos com os seus lindos campos;\\nAli nós viveremos com nosso Jesus.\"}]},{\"number\":\"567\",\"collection_type\":\"Hinário\",\"title\":\"A Cidade de Luz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"No livro de Deus eu já li de um lar,\\nA cidade onde noite não há.\\nO sol e o luar lá não hão de existir,\\nA glória de Deus é a luz;\\nA glória de Deus é a luz.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, cidade de luz onde noite não há!\\nLá irei encontrar, eu bem sei,\\nMeus queridos de aqui e também meu Jesus,\\nNa cidade de glória e de luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na praça central, bela árvore está,\\nNela o fruto da vida se vê.\\nE as folhas darão para os filhos do Rei,\\nSaúde que não findará;\\nSaúde que não findará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, doce porvir, de celeste fulgor,\\nQuando os salvos na glória hão de entrar!\\nAo lado de Deus, neste lar tão feliz,\\nIrei para sempre morar;\\nIrei para sempre morar.\"}]},{\"number\":\"568\",\"collection_type\":\"Hinário\",\"title\":\"Lar, Doce Lar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Na pátria celeste, de Deus doce lar,\\nPrepara Jesus para os Seus um lugar;\\nPois longe do mal, do pecado e da dor,\\nConsigo pra sempre os que Ter o Senhor.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, doce, doce lar!\\nAli com Jesus vou pra sempre morar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, lar sacrossanto, de paz e de amor;\\nAli sobre o trono verei meu Senhor,\\nO meigo Cordeiro, reinando na luz,\\nPor todos louvado, bendito Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não são teus prazeres que anseio gozar,\\nMas, sim, com Jesus para sempre morar.\\nCom Ele na glória, feliz, bendizer\\nA quem, pra salvar-me, por mim quis morrer.\"}]},{\"number\":\"569\",\"collection_type\":\"Hinário\",\"title\":\"Oh, Vale do Éden, Formoso!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, vale do Éden, formoso,\\nPátria de amor e luz!\\nTrazes aos tristes o gozo,\\nFala-nos de Jesus.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, vale do Éden, formoso,\\nPátria que não tem par!\\nOh! Como eu me sinto saudoso\\nDe ti, meu eterno lar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem cedo nossos anseios\\nHão de se realizar;\\nNão mais teremos receios,\\nNem aflições, pesar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lá junto ao trono divino,\\nOs salvos cantarão\\nDoces acordes de um hino\\nQue fala de perdão.\"}]},{\"number\":\"570\",\"collection_type\":\"Hinário\",\"title\":\"Além do Rio\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tenho ouvido de uma Terra linda, encantada,\\nDe um lugar onde a felicidade é total.\\nOs meus olhos já divisam não tão distante,\\nMeus ouvidos já escutam sons divinais.\\nTão cansado estou da vida aqui deste lado,\\nQue os meus braços quase já não podem remar,\\nCalejados e feridos por tantos dias,\\nQuerem em bálsamo daquele porto encontrar.\"},{\"section_type\":\"Coro\",\"content\":\"Além do rio existe um lugar pra mim,\\nAlém do rio existe paz.\\nAlém do rio a vida não terá mais fim;\\nE com Jesus irei morar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tenho já sonhado com aquelas moradas,\\nQue olho algum aqui não viu e nunca verá;\\nTêm beleza incapaz de ser comparada,\\nPois a glória do Senhor presente está.\\nMuito mais bonito que o sol no poente.\\nOu a gota d'água em prisma, como cristal;\\nÉ o encontro de irmãos de fé, redimidos;\\nCompensou viver, lutar, vencer afinal.\"}]},{\"number\":\"571\",\"collection_type\":\"Hinário\",\"title\":\"Lindo País\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há um país nas terras de além rio,\\nCheio de flores, de prazer e luz;\\nÉ destinado às almas resgatadas;\\nLá não terão mais lutas nem mais cruz.\\nPois é ali que a morte não mais entra,\\nNem mais pecado o brilho tirará.\\nJesus, o Rei dessas mansões tão lindas,\\nOs salvos todos com prazer abraçará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lindo país! Eu vejo a brisa mansa\\nAcariciar campinas e jardins,\\nE embalar as palmas prateadas\\nDos perfumados vales com jasmins.\\nE quando o Sol se põe no horizonte,\\nEu julgo ver em sonhos este lar;\\nVejo os amigos já ressuscitados,\\nE todos nós o nosso bom Jesus louvar.\"}]},{\"number\":\"572\",\"collection_type\":\"Hinário\",\"title\":\"Lar Feliz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu avisto uma terra feliz,\\nOnde irei para sempre morar;\\nHá mansões neste lindo país\\nQue Jesus foi, no Céu, preparar.\\nVou morar, vou morar,\\nNeste lar perenal e feliz;\\nVou morar, vou morar,\\nNeste lar perenal e feliz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantarei neste lindo país\\nBelos hinos ao meu Salvador,\\nPois ali viverei bem feliz,\\nSem temor, sem tristeza, nem dor.\\nVou cantar, vou cantar,\\nNeste lar perenal e feliz;\\nVou cantar, vou cantar,\\nNeste lar perenal e feliz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Deixarei este mundo afinal,\\nPara ir a Jesus adorar;\\nNeste lar mui feliz e eternal,\\nCom Jesus para sempre hei de estar.\\nHei de estar, hei de estar,\\nNeste lar perenal e feliz;\\nHei de estar, hei de estar,\\nNeste lar perenal e feliz.\"}]},{\"number\":\"573\",\"collection_type\":\"Hinário\",\"title\":\"O Senhor Está em Seu Templo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Senhor está em Seu santo templo,\\nO Senhor está em Seu santo templo;\\nO Céu, o mar e a Terra,\\nE vós guardai silêncio perante Deus;\\nSilêncio, silêncio perante Deus.\\nAmém.\"}]},{\"number\":\"574\",\"collection_type\":\"Hinário\",\"title\":\"Deus Está Presente\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus está presente, Vamos adorá-lo\\nCom fervor e zelo sem par;\\nSim, humildemente, Em silêncio, honrá-lo:\\nRei dos Céus, da Terra e do mar.\\nVamos, pois, Lhe prestar\\nCulto reverente.\\nDeus está presente.\"}]},{\"number\":\"575\",\"collection_type\":\"Hinário\",\"title\":\"Silêncio\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Silêncio! Silêncio!\\nÉ santo o lugar.\\nEnsinos preciosos\\nProvêm deste altar.\"},{\"section_type\":\"Coro\",\"content\":\"Silêncio!, Silêncio\\nNa casa de Deus!\\nEscuta a mensagem\\nQue vem lá dos Céus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Silêncio! Silêncio!\\nPerante o Senhor!\\nAtenta às palavras\\nDe luz e de amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Silêncio! Silêncio!\\nÉ tempo de orar,\\nE com reverência\\nEm Deus meditar.\"}]},{\"number\":\"576\",\"collection_type\":\"Hinário\",\"title\":\"Pai, Sê Presente\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, sê presente neste templo;\\nFaz-nos ouvir a Tua voz;\\nBrilhe em Jesus o nosso exemplo,\\nE Habita em nós.\"}]},{\"number\":\"577\",\"collection_type\":\"Hinário\",\"title\":\"Santo És, Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Coro\",\"content\":\"Santo, santo, santo, santo és, Senhor.\\nSanto, santo, santo, Deus e Criador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Terra e céus formaste para o Teu louvor.\\nSanto, santo, santo, sumo benfeitor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Teu, Senhor, é o reino, Teu é o poder,\\nTua é a glória, para sempre, amém!\"}]},{\"number\":\"578\",\"collection_type\":\"Hinário\",\"title\":\"Sinto a Presença do Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sinto a presença do Senhor neste lugar,\\nSeu poder e Sua graça, Seu amor.\\nPosso ver em cada face Sua beleza irradiar.\\nSinto a presença do Senhor neste lugar.\"}]},{\"number\":\"579\",\"collection_type\":\"Hinário\",\"title\":\"Eu Te Amo, ó Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu te amo ó Deus, ergo meu louvor.\\nMinh 'alma vem te adorar, Senhor.\\nAceita, pois, este meu louvor,\\nComo gratidão por teu grande amor.\"}]},{\"number\":\"580\",\"collection_type\":\"Hinário\",\"title\":\"Invocação\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tua santa presença rogamos-Te, ó Senhor;\\nManda-nos Teu Espírito;\\nDá-nos Teu santo poder.\\nQueremos dar-Te graças, queremos Teu perdão;\\nQueremos cantar louvores a Ti,\\nPor Teu infinito amor.\"}]},{\"number\":\"581\",\"collection_type\":\"Hinário\",\"title\":\"Adoração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A Deus supremo Criador,\\nVós, anjos e homens, dai louvor;\\nA Deus, o Filho, a Deus, o Pai,\\nA Deus, Espírito, glória dai.\"}]},{\"number\":\"582\",\"collection_type\":\"Hinário\",\"title\":\"Vem, Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"No Teu sagrado templo vem,\\nSenhor, oh, vem estar!\\nAqui estamos todos nós\\nPra Teu louvor cantar!\"},{\"section_type\":\"Estrofe\",\"content\":\"A Ti rendemos graças mil,\\nPorque és justo e bom;\\nSenhor, oh, vem, concede-nos\\nO Teu sublime dom!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, vem! Não te demores, não!\\nVem dar aos filhos Teus,\\nO Teu poder, e a Tua paz.\\nOh, vem, Senhor, bom Deus!\"}]},{\"number\":\"583\",\"collection_type\":\"Hinário\",\"title\":\"Glória a Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Glória ao Pai seja dada,\\nAo Filho e ao Espírito Santo,\\nComo era no princípio,\\nÉ hoje e para sempre.\\nGlória sem fim!\\nAmém, amém!\"}]},{\"number\":\"584\",\"collection_type\":\"Hinário\",\"title\":\"Oh, Como é Bom Louvar\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh, como é bom louvar a Deus,\\nsempre louvá-lo assim!\\nPor Seu amor, favores Seus,\\nlouvor terá de mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu coração de pedra é,\\nmas novo há de ser,\\nQuando por fim co'amor e fé,\\nJesus mudar meu ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao palmilhar a senda aqui,\\nfaze-me bom Senhor.\\nPossa viver, viver por Ti,\\nEm Teu divino amor.\"}]},{\"number\":\"585\",\"collection_type\":\"Hinário\",\"title\":\"Oh! Adorai\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! Adorai ao Deus triúno,\\nPois Ele é Deus onipotente!\\nOh! Adorai ao Rei divino,\\nPois Ele reina, eternamente!\\nAmém.\"}]},{\"number\":\"586\",\"collection_type\":\"Hinário\",\"title\":\"Doxologia\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus, Criador do Universo,\\nRendo um louvor neste verso.\\nÉs Redentor e Salvador;\\nDeus Pai, Deus Filho, Deus Espírito Santo.\"}]},{\"number\":\"587\",\"collection_type\":\"Hinário\",\"title\":\"Santo, Santo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Santo, santo, Pai bondoso,\\nSanto, santo, Deus poderoso,\\nEntregamos nossos corações a Ti, em devoção.\\nPai bondoso, Te adoramos.\"},{\"section_type\":\"Estrofe\",\"content\":\"Santo, santo, Cristo amado,\\nPela cruz nós somos redimidos;\\nElevamos nossas mentes em constante adoração.\\nCristo amado, Te adoramos.\"},{\"section_type\":\"Estrofe\",\"content\":\"Santo, santo, Santo Espírito,\\nEnche de poder nossas vidas.\\nSuplicamos Tua graça, Teu auxilio e direção.\\nSanto espírito, Te adoramos.\"}]},{\"number\":\"588\",\"collection_type\":\"Hinário\",\"title\":\"Bendito Jesus!\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bendito Jesus, divino Pastor,\\nÓ vem conceder Teu rico favor.\\nAs súplicas ouve, aceita dos Céus\\nO culto ofertado a Ti, nosso Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não temos valor pra dar-te aqui;\\nResgate nenhum trazemos a Ti,\\nPois nosso pecado foi pago na cruz,\\nDivino Cordeiro, bondoso Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Divino Senhor, ó, vem ensinar\\nA alma a sentir e a língua a falar\\nCom muita ternura e grande fervor,\\nO santo evangelho, as novas do amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Concede-nos paz e amor no viver;\\nDá forças à fé, aumenta o poder.\\nOh! Faze a pureza em todos florir,\\nE Cristo, a Verdade, em nós refulgir!\"}]},{\"number\":\"589\",\"collection_type\":\"Hinário\",\"title\":\"A Melhor Dádiva\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Traziam as ofertas aos pés do Salvador,\\nE todo o sacrifício mostrava ser de amor.\\nNenhuma oferenda tornava sem valor;\\nA todas aceitava, o meigo Salvador.\"},{\"section_type\":\"Coro\",\"content\":\"Também, Senhor eu quero\\nTrazer-te este Dom,\\nIndigno, mas sincero:\\nO impuro coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao longe, retraído, está um pecador;\\nAo ver os donativos, sua alma sofre em dor.\\nNão tem nenhuma prenda pra dar ao Salvador!\\nCom olhos lacrimosos, suplica com fervor:\"},{\"section_type\":\"Estrofe\",\"content\":\"\\\"Ó Mestre\\\", exclama, aflito, \\\"eu sei quão mau eu sou;\\nMas toma a pobre oferta: Meu coração Te dou.\\\"\\nJesus responde, manso: \\\"A dádiva aceitei;\\nDe todas as ofertas, a tua Eu mais amei!\\\"\"}]},{\"number\":\"590\",\"collection_type\":\"Hinário\",\"title\":\"Adoração a Ti, Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Queremos dar, em oração\\nAdoração a Ti Senhor.\\nAceita, pois, a gratidão:\\nDemonstração do nosso amor.\\nAmém.\"}]},{\"number\":\"591\",\"collection_type\":\"Hinário\",\"title\":\"Ofertório\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"São Teus, ó Pai, os dízimos\\nDaquilo que nos dás;\\nE ofertas que Te damos\\nDe coração, Aceitarás.\"}]},{\"number\":\"592\",\"collection_type\":\"Hinário\",\"title\":\"Pai, Imploramos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, imploramos Teu favor;\\nConcede Tua santa paz, Senhor.\\nAmém.\"}]},{\"number\":\"593\",\"collection_type\":\"Hinário\",\"title\":\"Ao Orarmos, Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Faze que ao orar,\\neu esqueça tudo ao redor\\nPra que nada me venha impedir\\nDo Teu trono a graça fruir\"},{\"section_type\":\"Coro\",\"content\":\"Vem meu ser transformar pelo amor\\nQue do alto dimana, ó Senhor.\\nPossam todos os que aqui estão,\\nBem unidos estar em oração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem, Senhor elevar\\nos que diante de Ti hoje estão\\nEm espírito de oração,\\nProcurando o mundo deixar.\"}]},{\"number\":\"594\",\"collection_type\":\"Hinário\",\"title\":\"Ouve-nos, Senhor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouve-nos, Senhor,\\nSanto Salvador;\\nEnclina-Te a ouvir\\nE dá-nos Tua paz. Amém.\"}]},{\"number\":\"595\",\"collection_type\":\"Hinário\",\"title\":\"Ao Meu coração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem, ó Jesus! Vem, ó Jesus!\\nAo meu coração, Jesus, vem!\\nVem hoje, vem;\\nVem pra ficar,\\nEm meu coração, ó Cristo!\"}]},{\"number\":\"596\",\"collection_type\":\"Hinário\",\"title\":\"Vem Morar em Mim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Santo Espírito de Deus,\\nVem morar em mim.\\nSanto Espírito de Deus,\\nVem morar em mim.\\nVem moldar-me, transformar-me.\\nSanto Espírito de Deus,\\nVem morar em mim.\"}]},{\"number\":\"597\",\"collection_type\":\"Hinário\",\"title\":\"Humilde Oração\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em humilde oração,\\nQuero dedicar, Senhor,\\nMeu indigno coração,\\npara Teu louvor.\\nFaz-me puro, santo e bom\\npra cumprir o Teu querer.\\nDá-me amor, Teu grande dom;\\nDá-me Teu poder\"}]},{\"number\":\"598\",\"collection_type\":\"Hinário\",\"title\":\"Vem, Espírito Santo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem Espírito Santo,\\nVem transforma meu ser.\\nDá-me Tua paz, a luz do Teu bem,\\nÉ o que eu te peço, Amém.\"}]},{\"number\":\"599\",\"collection_type\":\"Hinário\",\"title\":\"Paz\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Paz eu preciso sentir;\\nPaz divinal.\\nSó esta paz transmitir;\\nDom real.\"}]},{\"number\":\"600\",\"collection_type\":\"Hinário\",\"title\":\"Deus Esteja em Mim\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus esteja em mim,\\nE em todo o meu pensar.\\nSim, que o Deus do Céu,\\nconduza meu olhar;\\nE ao me despedir,\\ndirija meu andar.\\nÓ Pai, no coração,\\nVem logo então reinar.\"}]},{\"number\":\"601\",\"collection_type\":\"Hinário\",\"title\":\"A Mão de Deus\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A mão de Deus e Seu poder\\nguardar-vos-ão de todo o mal;\\nEm Sua luz possais viver,\\nna doce paz do amor real.\\nAmém.\"}]},{\"number\":\"602\",\"collection_type\":\"Hinário\",\"title\":\"Graça, Amor e Comunhão\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que a graça de Jesus, o amor de Deus o Pai,\\nE a comunhão do Espírito habite em nós;\\nQue a graça de Jesus, o amor de Deus o Pai,\\nE a comunhão do Espírito em nós.\\nEstejam pra sempre, Eternamente,\\nAmém.\"}]},{\"number\":\"603\",\"collection_type\":\"Hinário\",\"title\":\"Benditos Laços\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Benditos, sagrados serão\\nOs laços fraternos do amor,\\nSe juntos, com Cristo,\\nFicarmos unidos,\\nNa causa, na luta, na dor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se juntos orarmos a Deus,\\nSe juntos buscarmos poder,\\nAs hostes contrárias,\\nAs forças das trevas,\\nCom Cristo iremos vencer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se desta sagrada reunião\\nNós vamos distantes ficar,\\nNa pátria celeste,\\nPra sempre com Cristo,\\nUnidos havemos de estar.\"}]},{\"number\":\"604\",\"collection_type\":\"Hinário\",\"title\":\"Preitos de Louvor\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, Te rendemos preitos de louvor,\\nPois Tua palavra mostra Teu amor.\\nEm findo o culto conduzir-nos-ás,\\nE para sempre Tu nos guiarás.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem conduzir-nos para o nosso lar,\\nPois nós queremos só contigo andar.\\nOh, purifica nosso coração;\\nA cada intento dá Tua direção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao protegeres nosso caminhar,\\nPai, quantas bênçãos Teu amor nos traz!\\nMas, quando a luta nossa terminar,\\nÓ Deus, concede Tua eterna paz.\"}]},{\"number\":\"605\",\"collection_type\":\"Hinário\",\"title\":\"Vem Despedir-nos\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem despedir-nos ó Salvador,\\nCom Tua graça, Teu santo amor.\\nNossos caminhos guia-os aqui;\\nDá-nos descanso junto de Ti.\\nAmém.\"}]},{\"number\":\"606\",\"collection_type\":\"Hinário\",\"title\":\"Amigo, Não Saia Sem Cristo\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Amigo, não saia sem Cristo.\\nNão saia daqui sem Jesus,\\nPois quer hoje mesmo salvá-lo;\\nPor isso morreu numa cruz.\\nReceba esta oferta de graça,\\nE aceite de Cristo o perdão.\\nAmigo, não saia sem Cristo\\nNo seu coração.\"}]},{\"number\":\"607\",\"collection_type\":\"Hinário\",\"title\":\"Fim de Culto\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Água da vida aqui jorrou,\\nDa fonte eterna do viver;\\nDela viemos nos saciar,\\nE em Jesus renovar poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Findamos esta comunhão,\\nCulto de glória ao Criador,\\nReconsagrando o coração,\\nNo altar do divino amor.\\nAmém.\"}]},{\"number\":\"608\",\"collection_type\":\"Hinário\",\"title\":\"Que Deus Te Abençoe\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que Deus te abençoe,\\nE faça brilhar Seu rosto sobre ti;\\nE que o Senhor te dê a paz;\\nSim, que Deus sobre ti levante o rosto Seu;\\nQue te guarde e abençoe sempre.\\nMisericórdia tenha Deus de ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Améns...)\"}]},{\"number\":\"609\",\"collection_type\":\"Hinário\",\"title\":\"Pai Nosso\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai nosso que estás nos céus,\\nSantificado Teu nome;\\nTeu reino venha,\\nTua vontade na Terra e no Céu se faça\\nO nosso pão vem hoje dar;\\nNossas dívidas perdoa,\\ncomo nós a quem nos deve;\\nE livra-nos das tentações\\ne dos males deste mundo,\\nPois Teu é o reino, o poder\\ne a glória pra sempre.\\nAmém.\"}]},{\"number\":\"610\",\"collection_type\":\"Hinário\",\"title\":\"Améns\",\"author\":\"\",\"folder_id\":null,\"folder_name\":\"\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A. Amém\\nB. Amém\\nC. Amém, Amém, Amém\\nD. Amém, Amém, Amém\"}]}],\"coletanea\":[{\"number\":\"1992-01\",\"collection_type\":\"Coletânea\",\"title\":\"Nosso Sol é Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1992\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O nosso sol\\nVeio iluminar\\nO caminho\\nQue vamos andar\\nQuero sempre viver\\nCom essa Grande Luz\\nNosso Sol é Jesus\\nQue nos Conduz\\nNosso Sol é Jesus\\nQue nos conduz\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Senhor Brilhar\\nTua luz mostrar\\nTua paz fluir\\nE alegria dar\\nQuero sempre viver\\nCom essa Grande Luz\\nNosso Sol é Jesus\\nQue nos Conduz\\nNosso Sol é Jesus\\nQue nos conduz\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero sempre viver\\nCom essa Grande Luz\\nNosso Sol é Jesus\\nQue nos Conduz\\nNosso Sol é Jesus\\nQue nos conduz\"}]},{\"number\":\"1992-02\",\"collection_type\":\"Coletânea\",\"title\":\"Brilha Jesus\",\"author\":\"Igreja Adventista do Sétimo Dia\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1992\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, o Teu grande amor me inspira\\nPai, o Teu resplendor me anima\\nTua luz ilumina os caminhos meus\\nComo um sol, o amor desse olhos Teus\"},{\"section_type\":\"Estrofe\",\"content\":\"Brilha em mim, brilha em mim\\nBrilha Jesus, Vem trazer a luz que vem da glória\\nO Teu calor traz a paz e amor\\nVem como um sol às nações trazer misericórdia\"},{\"section_type\":\"Estrofe\",\"content\":\"Brilha Jesus, vem trazer Tua luz\\nPai, a Tua real grandeza traz à vida real beleza\\nTeu amor transformou nossa história\\nHoje a luz que nos vem lá da glória\\nBrilha em mim, brilha em mim\"}]},{\"number\":\"1992-03\",\"collection_type\":\"Coletânea\",\"title\":\"Jesus Meu Melhor Amigo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1992\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando fico a pensar\\nNo que Cristo fez por mim\\nEu não posso duvidar\\nDo seu grande amor sem fim\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nVamos nós cantar\\nQue Jesus é o melhor amigo\\nEle quer contar\\nCom você e comigo\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus meu melhor amigo\\nNele eu posso confiar\\nE nas horas de tristezas\\nEle diz: \\\"-quero te ajudar\\\"\"},{\"section_type\":\"Estrofe\",\"content\":\"O seu sangue derramou\\nPra salvar a ti e a mim\\nE a esse grande amigo\\nVou seguir até o fim\"}]},{\"number\":\"1992-04\",\"collection_type\":\"Coletânea\",\"title\":\"Ele Está Ao Leme\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1992\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus conduz\\nE me guia para o céu\\nCristo é a luz\\nQue ilumina meu caminho\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nEle está ao leme\\nVai no mar da vida\\nEle está ao leme\\nMostra a direção\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é o farol\\nQue me livra do perigo\\nÉ o capitão\\nO meu rei e meu amigo\"},{\"section_type\":\"Estrofe\",\"content\":\"(final)\\nEle está ao leme\\nMostra a direção\"}]},{\"number\":\"1992-05\",\"collection_type\":\"Coletânea\",\"title\":\"Avançai Juvenis\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1992\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Avançai juvenis afrontando a estrada ao pó\\nSempre avante, garbosos gentis\\nPois assim juvenil sede ja reais\\nCorajoso e bravo, leais\"},{\"section_type\":\"Estrofe\",\"content\":\"Juvenis, he! he!\\nIsto é que é viver\\nCante ao levantar\\nCante ao deitar\\nEia que prazer venham todos ver\\nComo marcham os bons juvenis\"}]},{\"number\":\"1992-06\",\"collection_type\":\"Coletânea\",\"title\":\"Hino dos Desbravadores\",\"author\":\"Henry T. Bergh\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1992\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nós somos os Desbravadores Os servos do Rei dos reis\\nSempre avante assim marchamos Fiéis às Suas leis.\\nDevemos ao mundo anunciar As novas da salvação\\nQue Cristo virá em breve dar o galardão.\"}]},{\"number\":\"1993-01\",\"collection_type\":\"Coletânea\",\"title\":\"Já É Tempo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1993\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Já é tempo de crescer, de amar e de sorrir\\nJá é tempo de brilharmos por Jesus\\nJá é tempo de abraçarmos o ideal de nossa fé\\nJá é tempo de abraçarmos sua cruz\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nJá é tempo de mostrar o Salvador\\nJá é tempo de falar do seu amor\\nO mundo espera ouvir da mensagem do Senhor\\nCabe a nós levar Jesus ao pecador\"},{\"section_type\":\"Estrofe\",\"content\":\"Já é tempo de mudar, já é tempo de viver\\nJá é tempo de buscarmos seu poder\\nJá é tempo de orarmos com fervor e união\\nJá é tempo de Jesus no coração\"}]},{\"number\":\"1993-02\",\"collection_type\":\"Coletânea\",\"title\":\"Todos Animados No Senhor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1993\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ao rever o amigo\\nAo rever o irmão\\nAbra seu sorriso e seu coração\\nDê um forte abraço\\nMostre seu amor\\nTodos animados no Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando eu for embora\\nAça uma oração\\nAgradeça a Deus\\nPeça seu perdão\\nPeça sua benção\\nPara lhe guardar\\nNo retorno certo para o lar\"},{\"section_type\":\"Estrofe\",\"content\":\"Todo o seu poder está na oração\\nPeça que Jesus estenda a sua mão\\nE ao orarmos todos\\nO Céu está a ouvir\\nVamos dar as mãos e ao lar subir\"}]},{\"number\":\"1993-03\",\"collection_type\":\"Coletânea\",\"title\":\"Com Jesus Em Meu Caminho\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1993\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se tentações procuram desviar o meu viver\\nMe apego a Deus, me apoio em seu amor\\nAo meu redor sua luz\\nO meu andar conduz\\nJesus em minha vida tem valor\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nCom Jesus em meu caminho\\nMal algum eu temerei\\nPois jamais irei sozinho\\nToda luta vencerei\\nCom Jesus em meu caminho\\nMal algum eu temerei\\nPois jamais irei sozinho\\nToda luta vencerei\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus por toda vida em meu viver irá reinar\\nSó assim as frustrações não tem poder\\nA fonte de sua paz\\nAbrigo e força traz\\nNem dor nem solidão há de vencer\"},{\"section_type\":\"Estrofe\",\"content\":\"Se dúvidas surgirem sobre minha decisão\\nDe seguir o rumo que me leva ao lar\\nSeguro estarei\\nPois perto eu verei\\nJesus que em minha vida há de estar\"}]},{\"number\":\"1993-04\",\"collection_type\":\"Coletânea\",\"title\":\"Vamos Semear\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1993\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nVamos jogar as sementes,\\nque são as Palavras do nosso Senhor\\nSobre terreno bem fértil,\\nque são as pessoas sedentas de amor\\nVamos colher novos frutos,\\nque vem da semente que ali germinou\\nFrutos que vão cultivar e plantar mais sementes,\\npois Cristo mandou\\nVem meu irmão,\\nvem semear campos sem vida, sem luz\\nVem meu irmão,\\nvem semear em cada vida: Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nEm cada Vida: Jesus\"}]},{\"number\":\"1993-05\",\"collection_type\":\"Coletânea\",\"title\":\"Jesus Toda Vida\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1993\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cristo ilumina meu viver\\nCristo ilumina meu andar\\nEu sei que posso confiar em sua proteção\\nFeliz eu sigo pois seguro estou em suas mãos\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, toda vida\\nA razão do meu cantar\\nJesus, toda vida\\nA razão do meu falar\\nFeliz estou, confiante vou\\nPois meu poder está em Jesus\\nMinha vida e alegria de meu ser\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo me dá força pra lutar\\nCristo é a luz do meu olhar\\nMeu coração se alegra\\nAo pensar em seu amor\\nReal felicidade eu tenho agora no Senhor\"}]},{\"number\":\"1993-06\",\"collection_type\":\"Coletânea\",\"title\":\"Dê Glória\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1993\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dê glória ao Senhor Jesus\\nDê glória ao Santo Deus\\nPorquê seu Filho amado enviou aqui\"},{\"section_type\":\"Estrofe\",\"content\":\"E agora o fraco há de dizer:\\nEu sou forte no Senhor\\nPorque Jesus em seu amor me salvou\\nE agora o pobre há de dizer\\nEu sou rico no Senhor,\\nPorque Jesus em seu amor me salvou\"}]},{\"number\":\"1993-07\",\"collection_type\":\"Coletânea\",\"title\":\"Vem, Espírito Santo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1993\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem, Espírito Santo\\nVem, transforma meu ser\\nDá-me tua paz\\nA luz do teu bem\\nÉ o que eu te peço. amém\"}]},{\"number\":\"1994-01\",\"collection_type\":\"Coletânea\",\"title\":\"Rei dos Reis\",\"author\":\"Igreja Adventista do Sétimo Dia\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1994\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Rei dos reis! Deus, Criador do Céu!\\nHonra e glória ao Deus infinito em poder!\\nTerra e Céu, cantai ao grande Rei!\\nDeus Criador, Deus Redentor, Deus, Rei dos reis!\\nAdorai, glorificai o nome de Cristo!\\nExaltai, magnificai Jesus, o Senhor!\\nTerra e Céu, cantai louvor a Deus! - bis\\nEle morreu! Ele venceu! É Rei dos reis!\"}]},{\"number\":\"1994-02\",\"collection_type\":\"Coletânea\",\"title\":\"Tu és Deus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1994\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(3X)\\nTu és Deus, nós Te amamos\\nTu és Rei, Te adoramos\\nTu és meu Pai eterno\\nMeu louvor darei a Ti\\nMeu louvor darei a Ti, Amém\"}]},{\"number\":\"1994-03\",\"collection_type\":\"Coletânea\",\"title\":\"Bem Junto a Cristo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1994\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem junto a Cristo eu quero estar,\\nBem junto à cruz doce paz desfrutar.\\nSim, ao Teu peito eu busco a paz,\\nPois Teu amor divinal satisfaz!\\nPois Teu amor divinal satisfaz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não trago nada mais ao Senhor,\\nSó este meu coração pecador,\\nMas te suplico em contrição,\\nOh, Salvador, dá-me paz e perdão!\\nOh, Salvador, dá-me paz e perdão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, quero a Cristo bem junto estar,\\nTé lá no além conseguir aportar.\\nOh, lar eterno, lar de esplendor!\\nLá estarei junto ao meu Salvador.\\nLá cantarei todo Seu grande amor.\"}]},{\"number\":\"1994-04\",\"collection_type\":\"Coletânea\",\"title\":\"Mais semelhante a Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1994\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mais semelhante a Jesus\\nÉ o que mais eu desejo na vida\\nMais semelhante a Jesus\\nÉ a vontade sincera nascida em meu ser\\nMais semelhante a Jesus\\nÉ o ponto de minha partida\\nPara ter nessa vida alegria e poder\\nQuero ser mais semelhante a Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais semelhante a Jesus\\nÉ a mensagem ganhada e vivida\\nMais semelhante a Jesus\\nÉ a vontade contida de sempre louvar\\nMais semelhante a Jesus\\nÉ o alvo de minha corrida\\nPara ter nessa vida alegria e poder\\nQuero ser mais semelhante a Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais semelhante a Jesus\\nÉ a minha comida e bebida\\nMais semelhante a Jesus\\nÉ a vontade acolhida no meu coração\\nMais semelhante a Jesus\\nÉ a certeza da luta vencida\\nPara ter nessa vida alegria e poder\\nQuero ser mais semelhante a Jesus\"}]},{\"number\":\"1994-05\",\"collection_type\":\"Coletânea\",\"title\":\"Faz-me Um Servo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1994\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Faz-me um servo\\nHumilde e bom\\nQue eu possa ajudar\\nO meu irmão\\nQue a oração sempre esteja em meu ser\\n(homens)faz-me um servo\\n(mulheres)faz-me um servo\\n(todos)faz-me um servo, Senhor\"}]},{\"number\":\"1994-06\",\"collection_type\":\"Coletânea\",\"title\":\"Sinto a Presença do Senhor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1994\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sinto a presença do Senhor neste lugar\\nAo sentir seu poder, seu amor\\nPosso ouvir dos anjos o louvor\\nE a sua glória contemplar\\nSinto a presença do Senhor neste lugar\"}]},{\"number\":\"1995-01\",\"collection_type\":\"Coletânea\",\"title\":\"A Diferença É Cristo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1995\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vivendo aqui neste mundo,\\nPor maus caminhos andei;\\nMas um dia ouvi falar do Senhor,\\nSó Ele me pode salvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A diferença é Cristo,\\nQue pode minha vida mudar;\\nA diferença é Cristo,\\nQue veio minh’alma limpar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se estás distante de Cristo,\\nProcura Sua luz encontrar;\\nSe em problemas tu estás,\\nSó Ele te pode ajudar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Agora proclamo a Cristo,\\nEu louvo ao meu Rei e Senhor;\\nEu tenho alegria, pois tenho a Bíblia,\\nE agora só dEle eu sou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quem faz diferença é Cristo. (final)\"}]},{\"number\":\"1995-02\",\"collection_type\":\"Coletânea\",\"title\":\"Andando Com Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1995\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Abrace seu amigo e diga que o ama,\\nConvide-o pra andar com Jesus;\\nGrande alegria verá em sua face.\\nQuando descobrir que Cristo o quer salvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A palavra de Deus guarde em seu coração,\\nDeixe a paz de Jesus nos unir;\\nE iremos juntos louvar de todo o coração\\nO nosso eterno Rei Criador.\"}]},{\"number\":\"1995-03\",\"collection_type\":\"Coletânea\",\"title\":\"Em Uma Voz\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1995\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, nós queremos lhe pedir\\nVenha o mundo transformar\\nQue a sua glória nós possamos\\nRefletir então\\nTodos saberão\\nQue Cristo é o Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nEm uma voz, Pai\\nQueremos louvar\\nEm uma voz, Pai\\nFalar que é o Rei dos reis\\nEm uma voz, Pai\\nCompartilhar o amor\\nE oramos, Pai\\nTemos união\"},{\"section_type\":\"Estrofe\",\"content\":\"Este é o momento de ouvir\\nA voz do Espírito de Deus\\nE deixar que ele\\nFaça em nós habitação então\\nTodos saberão\\nQue Cristo é o Senhor!\"}]},{\"number\":\"1995-04\",\"collection_type\":\"Coletânea\",\"title\":\"Eu Me Ofereço a Ti\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1995\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Levanto a minha voz, levanto as mãos,\\nCom gratidão por viver, eu me ofereço a Ti.\\nDeus, usa a minha voz e as minhas mãos,\\nDeus, usa a vida que tenho, eu me ofereço a Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tudo o que tenho, tudo o que sou,\\nTudo o que espero ser, entrego a Ti,\\nEntrego a Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Levanto a minha voz, levanto as mãos,\\nCom gratidão por viver, eu me ofereço a Ti,\\nEu me ofereço a Ti.\"},{\"section_type\":\"Estrofe\",\"content\":\"Levanto a minha voz, levanto as mãos,\"}]},{\"number\":\"1995-05\",\"collection_type\":\"Coletânea\",\"title\":\"Unidos em Cristo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1995\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Santo é o nome do Senhor\\nEle é digno de todo o louvor\\nEm adoração erguemos nossas mãos\\nE unidos em Cristo, juntos em Cristo\\nDamos glória ao nome do Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"(final)\\nE unidos em Cristo, juntos em Cristo\\nDamos glória ao nome do Senhor\"}]},{\"number\":\"1995-06\",\"collection_type\":\"Coletânea\",\"title\":\"Tudo Entregarei\",\"author\":\"Judson Van DeVenter / Winfield Scott Weeden\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1995\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh Jesus, a Ti entregarei, sim tudo a Ti darei\\nCom resolução, submisso irei depor-me aos pés do Rei\"},{\"section_type\":\"Estrofe\",\"content\":\"(Refrão)\\nPor meu Salvador, eu me entregarei\\nSim, a tudo enfim, por ti Senhor renegarei\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh Jesus Senhor entregarei meu corpo e alma a Ti\\nPois o mundo mal renegarei, serei só teu aqui\"},{\"section_type\":\"Estrofe\",\"content\":\"(Refrão)\\nPor meu Salvador, eu me entregarei\\nSim, a tudo enfim, por ti Senhor renegarei\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh Jesus Senhor, desprezarei a tudo em teu favor\\nPaz desfruto em Ti, completo amor, sim glória ao meu Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"(Refrão)\\nPor meu Salvador, eu me entregarei\\nSim, a tudo enfim, por ti Senhor renegarei\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu me entregarei.\"}]},{\"number\":\"1995-07\",\"collection_type\":\"Coletânea\",\"title\":\"Eu só quero estar onde Estás\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1995\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu só quero estar onde estás\\nE viver em tua presença\\nVer a tua face e o adorar\\nJunto a Ti eu quero estar\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu só quero estar onde estás\\nOnde tudo é para sempre\\nLeva-me pra este lugar\\nPois eu quero ali morar\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero estar contigo,\\nVendo a tua face\\nE sentar à mesa, envolvido por tua glória\\nNa presença do meu Senhor eu quero estar\\nSim, eu quero estar, quero estar contigo, oh Deus\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu só quero estar onde estás\\nE viver em tua presença\\nVer a tua face e o adorar\\nJunto a Ti eu quero estar\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh meu Deus, Tu és a força e canção\\nE quando estou contigo, se sou fraco Tu és forte\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu só quero estar onde estás\\nOnde tudo é para sempre\\nLeva-me pra este lugar\\nSim, eu quero estar, quero estar contigo, oh Deus\\nSim, eu quero estar, quero estar contigo, oh Deus\"}]},{\"number\":\"1996-01\",\"collection_type\":\"Coletânea\",\"title\":\"A Diferença É Cristo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1996\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vivendo aqui neste mundo,\\nPor maus caminhos andei;\\nMas um dia ouvi falar do Senhor,\\nSó Ele me pode salvar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A diferença é Cristo,\\nQue pode minha vida mudar;\\nA diferença é Cristo,\\nQue veio minh’alma limpar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se estás distante de Cristo,\\nProcura Sua luz encontrar;\\nSe em problemas tu estás,\\nSó Ele te pode ajudar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Agora proclamo a Cristo,\\nEu louvo ao meu Rei e Senhor;\\nEu tenho alegria, pois tenho a Bíblia,\\nE agora só dEle eu sou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quem faz diferença é Cristo. (final)\"}]},{\"number\":\"1996-02\",\"collection_type\":\"Coletânea\",\"title\":\"Em Pé Na Congragação\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1996\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Fico em pé na congregação pra exaltá-o, ó Deus\"},{\"section_type\":\"Estrofe\",\"content\":\"As crianças me acompanham em suas orações aleluia\"},{\"section_type\":\"Estrofe\",\"content\":\"Fico em pé na congregação e louvo o nome Seu\"},{\"section_type\":\"Estrofe\",\"content\":\"Fico em pé na congregação e louvo o nome Seu\"},{\"section_type\":\"Estrofe\",\"content\":\"Dou a mão ao meu amigo demonstrando amor aleluia\"},{\"section_type\":\"Estrofe\",\"content\":\"Aleluia, aleluia, aleluia, aleluia\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é a inspiração que tenho pra louvar. aleluia\"},{\"section_type\":\"Estrofe\",\"content\":\"Reunidos na congregação o exaltaremos.\"},{\"section_type\":\"Estrofe\",\"content\":\"Levantando as nossas mãos em santa adoração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Toda a criação entoa um canto ao seu Autor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aleluia, aleluia, aleluia.\"}]},{\"number\":\"1996-03\",\"collection_type\":\"Coletânea\",\"title\":\"Repartir o Pão\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1996\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tudo aquilo que temos\\nDo bom Deus recebemos\\nE ao mundo devemos prontamente levar\\nNão importa o que seja\"},{\"section_type\":\"Estrofe\",\"content\":\"Falte à alma ou à mesa\\nÉ tarefa que a igreja deve realizar\\nHá milhares de perdidos\\nInfelizes, excluidos\"},{\"section_type\":\"Estrofe\",\"content\":\"Não conhecem a Deus\\nNem partilham o pão\\nSeja o pão de cada dia\\nComo o pão que o céu envia\"},{\"section_type\":\"Estrofe\",\"content\":\"Repartir é o dever\\nAtender é a missão\"}]},{\"number\":\"1996-04\",\"collection_type\":\"Coletânea\",\"title\":\"Somos Jovens de Valor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1996\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há quem diga que o amor,\\nÉ difícil de encontrar\\nHá quem diga que ele não existe mais.\\nHá quem diga que viver\\nSem amar não tem razão\\nHá quem diga que a esperança já se foi\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós somos jovens de valor,\\nMensageiros do Senhor\\nPra trazer a este mundo a solução\\nNós não querermos mais falar\\nSobre drogas e prazer\\nHoje é tempo de falar do amor de Deus.\"}]},{\"number\":\"1996-05\",\"collection_type\":\"Coletânea\",\"title\":\"Sou Feliz Com Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1996\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se paz a mais doce me deres gozar,\\nSe dor a mais forte sefrer;\\nOh, seja o que for, tu me fazes saber\\nQue feliz com Jesus hei de estar.\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nSou feliz com Jesus!\\nSou feliz com Jesus,\\nMeu Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Embora me assalte o cruel Satanás,\\nE ataque com vis tentações,\\nOh, sim certo estou, mesmo em tais provações, em Jesus acharei força e paz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus meu Senhor, ao morrer sobre a cruz\\nLivrou-me da culpa e do mal;\\nSalvou-me Jesus, oh, mercê sem igual!\\nSou feliz, hoje vivo na luz.\"},{\"section_type\":\"Estrofe\",\"content\":\"A vinda eu anseio do meu Salvador;\\nEm breve virá me buscar;\\nE então lá no Céu vou pra sempre morar,\\nCom remidos na luz do Senhor\"}]},{\"number\":\"1996-06\",\"collection_type\":\"Coletânea\",\"title\":\"A Única Saída\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1996\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se na escuridão da vida tu não sabes pra onde ir,\\nSe andas cheio de motivos pra parar e desistir,\\nUma coisa eu te digo, preste muita atenção:\\nJesus Cristo é a saída, Jesus Cristo é solução!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele é mais que uma resposta, é a mão que te conduz;\\nQuando tudo está escuro, Ele é a própria luz;\\nÉ a fonte da esperança, da alegria e do prazer;\\nEle é a única saída pra tua vida renascer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os problemas e as tristezas não vão mais te dominar,\\nMuita paz e segurança, em Jesus tu vais achar;\\nPela estrada deste mundo, Ele vai te esperar\\nE ao mostrar-te a saída, vai sorrir e te abraçar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus Cristo é a saída pra tua vida renascer. (final)\"}]},{\"number\":\"1996-07\",\"collection_type\":\"Coletânea\",\"title\":\"Tudo o Que Eu Preciso\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1996\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tudo o que é bom, verdade e luz.\\nTudo o que é puro, justo e fiel.\\nTudo o que é santo, retrato de Deus.\\nÉ o que preciso em meu viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tudo de mim, dou a Jesus, em Gratidão, por tanto me amar.\"}]},{\"number\":\"1996-08\",\"collection_type\":\"Coletânea\",\"title\":\"Nos Braços de Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1996\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Hoje aqui\\nMeu Jesus\\nMe tomou em seus braços\\nE ao sentir o calor\\nDo Espírito Santo\\nVou em paz pois o meu Deus\\nAo meu lado vai ficar\\nE em breve sua face eu verei\\nLá no Céu\"}]},{\"number\":\"1997-01\",\"collection_type\":\"Coletânea\",\"title\":\"Na Direção de Deus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu quero caminhar rumo ao futuro,\\nEu quero renovar a minha fé em Deus.\\nTambém eu quero partilhar com meu semelhante,\\nNem que seja por um instante,\\nTodo amor que me faz viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na direção de Deus nós caminhamos,\\nNa direção de Deus nós sempre andamos.\\nNa direção de Deus vamos outros levar,\\nDe mãos dadas lutemos pra caminhar\\nNa direção de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero entender o amor que salva,\\nEu quero alcançar meu irmão sem Deus.\\nTambém eu quero partilhar com o meu amigo,\\nA verdade que vem comigo,\\nTodo amor que me faz crescer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na direção de meu mestre\\nPra sempre vou caminhar.\"}]},{\"number\":\"1997-02\",\"collection_type\":\"Coletânea\",\"title\":\"Que Bom é Estar Aqui\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nQue bom é estar aqui\\n(Que bom é estar aqui)\\nFalando com Jesus\\n(Falando com Jesus)\\nRevendo meu irmão\\n(Revendo meu irmão)\\nBuscando luz\\n(Buscando luz)\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nEu vou louvar ao meu Senhor\\ne ao meu irmão vou abraçar\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu vou louvar\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nQue bom é te encontrar\\n(Que bom é te encontrar)\\nNum mesmo ideal\\n(Num mesmo ideal)\\nDevemos trabalhar\\n(Devemos trabalhar)\\nBuscando o Céu\\n(Buscando o Céu)\"},{\"section_type\":\"Estrofe\",\"content\":\"(4X)\\nEu vou louvar ao meu Senhor\\ne ao meu irmão vou abraçar\"},{\"section_type\":\"Estrofe\",\"content\":\"(4X)\\nEu vou louvar\"}]},{\"number\":\"1997-03\",\"collection_type\":\"Coletânea\",\"title\":\"Descanso em Deus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nestes dias em que a vida rouba nossa atenção\\nNestes dias em que o tempo passa sem direção\\nEntrego a minha vida\\nEntrego o meu andar\\nEu Te entrego ó Pai meu coração, minha vida veio andar\"},{\"section_type\":\"Estrofe\",\"content\":\"(Refão)\\nEu quero ó Deus ser Teu enfim, ver minha vida transformar\\nEu quero ó Deus ser Teu enfim, vem minh'alma renovar\\nMe ajuda a Te conheçer, me ajuda a querer Te amar\\nEu quero em Teus braços Pai, descansar já\"},{\"section_type\":\"Estrofe\",\"content\":\"Nestes dias em que eu quero ouvir a voz do Senhor\\nNestes dias em que o mundo pára ao meu redor\\nEu quero ser mudado\\nEu quero ver nasçer\\nVem do alto, vem depressa\\nVem ó Pai me socorrer\"}]},{\"number\":\"1997-04\",\"collection_type\":\"Coletânea\",\"title\":\"Paz no Viver\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tenho um amigo a me guiar\\nPor caminhos seguros\\nEle é Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é vida eterna\\nFonte de paz e amor ao perdido\\nFonte de Luz\"},{\"section_type\":\"Estrofe\",\"content\":\"O caminho é Cristo\\nEle é paz no viver\\nÉ promessa de vida, Ele é o poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é a força que move o mundo\\nEle quer mudar você\"},{\"section_type\":\"Estrofe\",\"content\":\"O caminho é Cristo\\nEle é a luz do teu ser\\nClareando a noite, mudando o viver\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo quer te ajudar no caminho\\nEle quer mudar você\"},{\"section_type\":\"Estrofe\",\"content\":\"Raio de esperança\\nQue ilumina o viver dos seus filhos\\nEle é Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Pai dos pecadores\\nManifestou Seu amor pelo mundo\\nSenhor da cruz\"},{\"section_type\":\"Estrofe\",\"content\":\"O caminho é Cristo\\nEle é paz no viver\\nÉ promessa de vida, Ele é o poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é a força que move o mundo\\nEle quer mudar você\"},{\"section_type\":\"Estrofe\",\"content\":\"O caminho é Cristo\\nEle é a luz do teu ser\\nClareando a noite, mudando o viver\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo quer te ajudar no caminho\\nEle quer mudar você\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele quer mudar você\"}]},{\"number\":\"1997-05\",\"collection_type\":\"Coletânea\",\"title\":\"Só Pela Graça\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Só pela graça de Cristo\\nSó pela graça de Deus\\nNão por esforços humanos\\nMas pelo sangue da cruz\"},{\"section_type\":\"Estrofe\",\"content\":\"Tua bondade nos chama\\nNos leva a pregar\\nTua presença ilumina\\nNos leva a trabalhar\\nNos leva a trabalhar\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nSó pela graça de Cristo\\nhá salvação\\nSó pelo sangue da cruz\\nConseguimos perdão\"},{\"section_type\":\"Estrofe\",\"content\":\"Só pela graça de Cristo\\nSó pela graça de Deus\\nNão por esforços humanos\\nMas pelo sangue da cruz\"},{\"section_type\":\"Estrofe\",\"content\":\"Tua bondade nos chama\\nNos leva a pregar\\nTua presença ilumina\\nNos leva a trabalhar\\nNos leva a trabalhar\"},{\"section_type\":\"Estrofe\",\"content\":\"Nos leva a trabalhar\\nNos leva a trabalhar\"}]},{\"number\":\"1997-06\",\"collection_type\":\"Coletânea\",\"title\":\"Fala à Minh'Alma\",\"author\":\"Ministério Jovem - APLaC\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Fala à minh'alma, ó Cristo, fala-lhe com amor!\\nSegreda com ternura: \\\"Eu sou teu Salvador!\\\"\\nFaze-me bem disposto para Te obedecer\\nSempre louvar Teu nome e dedicar-Te o ser\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nFaze-me ouvir bem manso, em suave murmurar\\nNa cruz verti meu sangue para te libertar\\nFala-me cada dia, fala com terno amor\\nSegreda-me ao ouvido: tu tens um Salvador\"},{\"section_type\":\"Estrofe\",\"content\":\"Fala aos Teus filhos sempre, dá-lhes a direção\\nEnche-os de grande gozo mesmo na provação\\nFaze-os bem consagrados, prontos a trabalhar\\nPara do reino eterno a vinda abreviar\"},{\"section_type\":\"Estrofe\",\"content\":\"Como na antigüidade mostravas Teu querer\\nRevela-me hoje e sempre qual seja meu dever\\nA Ti somente eu quero louvores entoar\\nTeu nome eternamente engrandecer e honrar\"},{\"section_type\":\"Estrofe\",\"content\":\"(fim)\\nTu tens um Salvador\"}]},{\"number\":\"1997-07\",\"collection_type\":\"Coletânea\",\"title\":\"Vitória Só Vem Do Senhor\",\"author\":\"Projet'art\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Perdidos, cansados os homens estão\\nVitória só vem do Senhor\\nSozinho, sem rumo, o fardo é demais\\nVitória só vem do Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nDeus é glória, honra\\nForça e poder Ele é\\nDeus é glória, honra\\nForça e poder Ele é\"},{\"section_type\":\"Estrofe\",\"content\":\"Se os problemas da vida nos fazer temer\\nVitória só vem do Senhor\\nEm Cristo a fé vamos todos buscar\\nVitória só vem do Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\"},{\"section_type\":\"Estrofe\",\"content\":\"Os anjos de Cristo por nós lutarão\\nVitória só vem do Senhor\\nNo céu então juntos nós vamos cantar\\nVitória só vem do Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X coro)\"},{\"section_type\":\"Estrofe\",\"content\":\"(3X)\\nEle é\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele, Ele é, Senhor!\"}]},{\"number\":\"1997-08\",\"collection_type\":\"Coletânea\",\"title\":\"Além do Rio\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tenho ouvido de uma terra linda, encantada,\\nDe um lugar onde a felicidade é total.\\nOs meus olhos já divisam não tão distante,\\nMeus ouvidos já escutam sons divinais.\\nTão cansado estou da vida aqui deste lado\\nQue meus braços quase já não podem remar,\\nCalejados e feridos por tantos dias,\\nQuerem bálsamos daquele porto encontrar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Além do rio existe um lugar pra mim,\\nAlém do rio existe paz.\\nAlém do rio a vida não terá mais fim,\\nE com Jesus irei morar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tenho já sonhado com aquelas moradas\\nQue olho algum aqui não viu e nunca verá;\\nTem beleza incapaz de ser comparada,\\nPois a glória do Senhor presente está.\\nMuito mais bonito que o sol no poente,\\nOu a gota d’água em prisma , como um cristal\\nÉ o encontro de irmãos de fé redimidos\\nCompensou viver, lutar, vencer afinal.\"}]},{\"number\":\"1997-09\",\"collection_type\":\"Coletânea\",\"title\":\"Ao Deixar Este Lugar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! nosso Pai vem nos guiar nos caminhos teus.\\nDespede, ó Pai, teu povo aqui,\\nDá-nos teu amor sem fim,tua graça,\\nTeu constante amparo, queremos ter ao deixar este lugar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! nosso Pai vem nos guiar nos caminhos teus.\\nConcede, o Pai, o teu calor. dá-nos graça e teu amor.\\nTua bênção nós queremos receber.\\nQueremos ter teu poder habitando em nós.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! nosso Pai vem nos guiar nos caminhos teus.\\nDespede, ó Pai, teu povo aqui, vem nos dar o teu calor.\\nRestaura, revifica, faz viver.\"}]},{\"number\":\"1997-10\",\"collection_type\":\"Coletânea\",\"title\":\"A verdadeira Alegria\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A alegria está no coração\\nDe quem já conhece a Jesus.\\nA verdadeira paz só tem aquele\\nQue já conhece a Jesus\\nO sentimento mais precioso\\nQue vem do nosso Senhor\\nÉ o amor que só tem quem já conhece a Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"(Repete tudo 2x dividindo com):\\nAleluia, aleluia, aleluia, aleluia\"},{\"section_type\":\"Estrofe\",\"content\":\"Final:\\nÉ o amor que só tem quem já conhece a Jesus\\nQue só tem, quem já conhece a Jesus.\\nAleluia Amém.\"}]},{\"number\":\"1997-11\",\"collection_type\":\"Coletânea\",\"title\":\"O Ministério da Mulher na Missão global\",\"author\":\"Letra e Música: Anailton Corrêa\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(só no CD)\"},{\"section_type\":\"Estrofe\",\"content\":\"Cante, ó maravilhosa. Ore, ó doce mulher.\\nLeia a tão preciosa Palavra de Deus em seu lar\\nO bom Jesus é o seu Guia, por isso cante com fé\\nEsta é a sua Missão Global, mulher adventista.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mulher que fala de Cristo, da vida do Salvador,\\nQue ensina a história divina da redenção por amor.\\nMulher que ajuda na igrejacom alegria e fé,\\nEsta é a sua Missão Global, mulher adventista.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mulher que ama a Cristo, que faz o que Ele mandou,\\nVisita a comunidade pregndo a lei do amor.\\nMulher que espera em breve com seu Senhor encontrar,\\nEsta é a sua Missão Global, mulher adventista.\"}]},{\"number\":\"1997-12\",\"collection_type\":\"Coletânea\",\"title\":\"Guia-me Senhor\",\"author\":\"Ministério Jovem - APLaC\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1997\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Usando as minhas mãos em gestos de amor\\nEu quero aos meus irmãos transmitir a paz que vem do Senhor\\nOrienta meus passos, guia-me, ó Deus\\nConserva meu ser, eu quero poder mais humilde ser\"},{\"section_type\":\"Estrofe\",\"content\":\"Falar do amor de Deus, semear os dons dos céus\\nColher os frutos deste labor e aos pés do Mestre depor\\nOrienta meus passos, guia-me, ó Deus\\nConserva meu ser, eu quero poder mais humilde ser\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais humilde ser\"}]},{\"number\":\"1998-01\",\"collection_type\":\"Coletânea\",\"title\":\"Missão\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O mundo inteiro vive\\nNa incerteza do amanhã\\nNão conseguem encontrar a paz\\nVivem grande solidão\\nQuem irá pregar,\\nQuem irá falar\\nDa esperança e do perdão?\\nCada um de nós deve ser a luz\\nQue aponte pra Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)(final 2x)\\nPor isso aponte pra Jesus\\nPra o mundo iluminar\\nAponte pra Jesus\\nPra crescer e conquistar\\nEm nome de Jesus\\nvamos levar o amor\\nE mostrar ao mundo\\nJesus é o melhor\"},{\"section_type\":\"Estrofe\",\"content\":\"A igreja inteira vive\\nNa esperança do amanhã\\nProcurando cada dia mais\\nMelhorar o seu viver\\nTemos de pregar,\\nTemos de falar\\nDa esperança e do perdão?\\nCada um de nós deve ser a luz\\nQue aponte pra Jesus\"}]},{\"number\":\"1998-02\",\"collection_type\":\"Coletânea\",\"title\":\"Em Oração\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em oração me encontro, oh Pai, a te render louvores,\\nA te entregar meu falho coração e a te pedir favores.\\nEm oração me encontro, oh Pai, pedindo segurança,\\nRogando que estejas junto a mim, me dando confiança.\\nEm oração preciso, oh Deus, viver a todo instante,\\nPara vencer o mundo ao meu redor\\nE prosseguir avante.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vou dedicar, em oração, meu coração e alma.\\nSó teu amor me traz consagração,\\nSó tua paz me acalma.\\nSó tua luz reflete salvação, só teu poder restaura.\\nEm oração me encontro a te pedir,\\nSenhor Jesus me salva!\"}]},{\"number\":\"1998-03\",\"collection_type\":\"Coletânea\",\"title\":\"Boas Novas\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quero te falar como é bom te Ter aqui\\nQuero te mostrar como é bom a Jesus seguir\\nQuero te contar sobre a paz que eu consegui,\\nAleluia! Aleluia! Como é bom te Ter aqui!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos dar as mãos e seguir o Salvador,\\nVamos dar as mãos e adorá-Lo em Seu fulgor\\nVamos dar as mãos e salvar o pecador\"},{\"section_type\":\"Estrofe\",\"content\":\"Aleluia! Aleluia! Vamos dar as nossas mãos\\nAleluia! Aleluia! E crescer em união.\"}]},{\"number\":\"1998-04\",\"collection_type\":\"Coletânea\",\"title\":\"Virá Um Novo Tempo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nós hoje vivemos num mundo de guerra e pavor.\\nEm volta só existem tristeza,angústia e dor;\\nMas sei que o relógio da história\\nAponta pra um tempo melhor;\\nUm tempo de alegria e perfeita união.\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nVirá um novo tempo de amor e de luz.\\nNo céu, o lar dos salvos, dos remidos por Jesus;\\nVirá um novo tempo,novo tempo só de paz;\\nVirá um novo tempo quando Cristo voltar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A nossa tarefa e contar que Jesus logo vem;\\nE vai colocar neste mundo um ponto final\\nUm mundo perfeito virá com a vinda de Cristo Jesus:\\nUm mundo sem a dor, nem a tristeza.\"}]},{\"number\":\"1998-05\",\"collection_type\":\"Coletânea\",\"title\":\"Cordeiro de Deus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dai glória ao Santo de Israel, pois é eterno e fiel.\\nRefúgio nele encontrarás, e das prisões te livrará.\"},{\"section_type\":\"Estrofe\",\"content\":\"No Céu esteve em esplendor, mas escolheu viver na dor.\\nExtrema angústia enfrentou, para salvar um pecador.\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nCordeiro de Deus, Senhor Jesus, nos dá perfeita paz e luz,\\nDe nossa angústia nos livrou e nos conforta em seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"O seu olhar é força e luz, o seu falar poder traduz,\\nBendito seja o Senhor, meu Rei amado e Salvador\"},{\"section_type\":\"Estrofe\",\"content\":\"Cordeiro de Deus, Senhor Jesus, nos dá perfeita paz e luz,\\nNa perdição nos libertou, e a vida eterna nos guiou.\"}]},{\"number\":\"1998-06\",\"collection_type\":\"Coletânea\",\"title\":\"Eu Quero Ser a Voz\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Prazer maior não há que ao mundo proclamar\\nA nova que Jesus está bem perto de voltar\\nEm breve o mundo vai vai o Mestre receber\\nQual Rei e Salvador em grande glória e poder\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nEu quero ser aqui, bom Deus a Tua voz\\nEu quero anunciar que Cristo vai voltar\\nEu quero transmitir ao mundo o Teu amor\\nE anunciar de Cristo a breve volta em esplendor\"},{\"section_type\":\"Estrofe\",\"content\":\"Desastres, guerra e dor, sinais em terra e mar\\nA voz da natureza está a proclamar\\nA voz da mocidade vai se unir a esta voz\\nE proclamar bem alto que Jesus irá voltar\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero transmitir ao mundo o Teu amor\\nE anunciar de Cristo a breve volta em esplendor\\nEu quero ser a tua voz, Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor\"}]},{\"number\":\"1998-07\",\"collection_type\":\"Coletânea\",\"title\":\"Minha Oração\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Mais força me inspira\\nMais ódio ao mal\\nMais clma nas lutas\\nMais alto ideal\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais fé no meu Mestre\\nMais dedicação\\nMais gozo em servi-lo\\nMais consagração\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais justo me faze\\nMais sábio Senhor\\nMais firme na causa\\nCom zelo e fervor\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais reto na vida\\nMais triste ao pecar\\nUm filho submisso\\nMais pronto em amar\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais puro me faze\\nMais santo em Jesus\\nMais de Sua graça\\nMais perto da cruz\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais rica esperança\\nMais fé e poder\\nPra sempre servir-te\\nE te obedecer\"}]},{\"number\":\"1998-08\",\"collection_type\":\"Coletânea\",\"title\":\"Dá-nos Tua Perfeita Paz\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vamos deixar este lugar cheios de paz e de poder\\nVamos a Deus agradecer por em amor e em fé nos manter\\nDá-nos Tua perfeita paz, que Tua forte mão venha estar conosco\\nPai, confiamos em Teu poder para nos protejer\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nAté quando enfim nos virmos\"},{\"section_type\":\"Estrofe\",\"content\":\"Grande Senhor, Tu és fiel, vem nos dar bençãos e proteção\\nNada irá nos abater pois Tu és bom e eterno Tu és\\nDá-nos Tua perfeita paz, que Tua forte mão venha estar conosco\\nPai, confiamos em Teu poder para nos protejer\"},{\"section_type\":\"Estrofe\",\"content\":\"Até quando enfim nos virmos\\nTua mão nos guardará\"},{\"section_type\":\"Estrofe\",\"content\":\"Bênçãos virão quando em fé nós orarmos\\nE juntos então alcançarmos poder\\nSó Tua destra nos dá firmesa\\nPois Tu és o Deus de Israel\"},{\"section_type\":\"Estrofe\",\"content\":\"Dá-nos Tua perfeita paz, que Tua forte mão venha estar conosco\\nPai, confiamos em Teu poder para nos protejer\"},{\"section_type\":\"Estrofe\",\"content\":\"Até quando enfim nos virmos\"},{\"section_type\":\"Estrofe\",\"content\":\"Até quando Deus voltar\"}]},{\"number\":\"1998-09\",\"collection_type\":\"Coletânea\",\"title\":\"Ide\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando olho ao redor percebo que não há paz\\nPrecisamos de amor que só o Senho nos traz\\nNão há mais tempo pra sermos omissos\\nJesus precisa de nós. Oh! Ide, Ide\"},{\"section_type\":\"Estrofe\",\"content\":\"Precisamos curar e ao mundo levar amor\\nVAmos dar o perdão a um mundo de mal e dor\\nNão há mais tempo a perder, precisamos crescer\\nPois Cristo nos diz: Oh! Ide, Ide\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando tudo acabar veremos a luz sem par\\nViveremos com Deus no eterno lugar de paz\\nNosso Senhor voltará\\nE então nos dirá: bem vindos ao lar\"},{\"section_type\":\"Estrofe\",\"content\":\"(3X)\\nOh! Vinde, Vinde\"}]},{\"number\":\"1998-10\",\"collection_type\":\"Coletânea\",\"title\":\"Face a Face\",\"author\":\"Ministério Jovem - APLaC\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quanto almejo ver a Cristo!\\nVê-lhe o rosto,que prazer!\\nQuando enfim,no lar eterno,\\nPoderei pra sempre o ver!\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nFace a face eu hei de vê-o,\\nQuando vier em gloria e luz;\\nFace a face lá na glória,\\nHei de ver meu bom Jesus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Muito ao longe já o avisto,\\nVejo como por um véu;\\nMas desejo em breve vê-lo,\\nFace a face lá no Céu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! que encanto estar com Cristo,\\nOnde já não há mais dor!\\nLivre de qualquer perigo,\\nDesfrutando seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Face a face que alegria,\\nHá de ser viver assim,\\nVendo o rosto tão querido,\\nDe quem morto foi por mim!\"}]},{\"number\":\"1998-11\",\"collection_type\":\"Coletânea\",\"title\":\"Mensagem ao Mundo\",\"author\":\"Ministério Jovem - APLaC\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vamos dar a mensagem ao mundo, proclamar a história da cruz\\nHistória de amor e graça, história de paz e luz\\nHistória de paz e luz\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nPois Jesus nosso Rei, em breve voltará Rei dos reis, Senhor\\nVirá Seu reino de luz fundar, um reino de paz e amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Uma voz de advertência ao mundo deve ser o nosso cantar\\nUm hino de fé que fale das bênçãos do amor sem-par\\nDas bênçãos do amor sem-par\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\"},{\"section_type\":\"Estrofe\",\"content\":\"Um dever é levar Cristo ao mundo, como alguém que pode salvar\\nQue pode afastar pecados e a glória de Deus mostrar\\nE a glória de Deus mostrar\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\"}]},{\"number\":\"1998-12\",\"collection_type\":\"Coletânea\",\"title\":\"Vamos Juntos Cantar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1998\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(repete 3x)\\nVamos juntos cantar\\nLouvores a Deus\\nVamos hoje buscar\\nPoder lá do Céu\\nErgamos as mãos\\nEm honra e louvor\\nErgamos a voz (repete 3x no final)\\nEm glória ao Senhor\"}]},{\"number\":\"1999-01\",\"collection_type\":\"Coletânea\",\"title\":\"Rumo ao Porto Seguro\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu barco navega no mar de águas revoltas, sem paz;\\nTerríveis trovões, tempestades de alto-mar.\\nEu vou confiante pois sei que o meu Redentor vai também,\\nE tem em suas mãos o controle da embarcação.\\nMas se tento o timão controlar quase deixo o barquinho afundar,\\nPois meus braços não podem a força do mar suportar.\\nCristo então me estende sua mão e controla a embarcação,\\nSorrindo pra mim, me oferece a salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"O meu barco vai firme ao porto seguro,\\nPois seu rumo está sob as mãos de Jesus.\\nNavegando nas águas geladas da Terra\\nSinto o calor daquEle que a tudo liberta.\"},{\"section_type\":\"Estrofe\",\"content\":\"Depois que entreguei a Jesus o rumo da embarcação\\nNão tive mais medo das ondas do alto-mar.\\nEm breve irei atracar no mar onde a água é cristal,\\nE onde estarei para sempre liberto do mal.\\nSó então saberei como foi que Jesus até ali me guiou,\\nSó então saberei como foi que ele o barco salvou.\\nFinalmente atraco no cais, que alegria poder encontrar\\nOs barcos de irmãos que também chegaram ao lar.\"}]},{\"number\":\"1999-02\",\"collection_type\":\"Coletânea\",\"title\":\"Vaso do Honra / Renova-me\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ser um vaso de honra.\\nMoldado pelo Senhor.\\nCom a mensagem de amor e de esperança.\\nAos homens por onde for.\\nReaviva-me, inspira minha vida\\nPrepara-me, pra fazer o teu querer.\\nAprofunda-me em Teu poder e graça.\\nPara honrar o teu nome, Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Renova-me, Senhor Jesus. Já não quero ser igual.\\nRenova-me, Senhor Jesus. Põe em mim Teu corarão.\\nPorque tudo o que há dentro mim\\nNecessita ser mudado Senhor.\\nPorque tudo o que há dentro do meu coração.\\nNecessita mais de Ti.\"}]},{\"number\":\"1999-03\",\"collection_type\":\"Coletânea\",\"title\":\"Rocha Eterna\",\"author\":\"Ministério Jovem - APLaC\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Rocha eterna, meu Jesus, Tu morreste lá na cruz!\\nVem de Ti um sangue tal que me vem lavar do mal!\\nTraz as bênçãos do perdão: paz, conforto e salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nem trabalho, nem penar pode alguém aqui salvar,\\nMas só Tu, meu bom Jesus, podes dar-me a vida e luz.\\nPeço-Te perdão, Senhor, pois confio em teu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis que vem a morte atrás desta vida tão fugaz!\\nQuando ao lar do Céu subir, e Teu rosto em glória vir,\\nRocha eterna, que prazer eu terei de em Ti viver!\"}]},{\"number\":\"1999-04\",\"collection_type\":\"Coletânea\",\"title\":\"O Poder do Amor\",\"author\":\"Rafaela Pinho\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Venho a Ti Jesus, quero renovar meu ser\\nSei que a graça vem só de Ti, Senhor\\nEu descobri, oh Deus, que tudo que é mal em mim\\nVai se transformar com o poder do amor\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nMeu Jesus\\nTeu amor me envolve\\nQuero estar\\nFirme em Tuas mãos\\nEu vou voar\\nBem alto como a águia\\nPlanando na amplidão\\nDo Espirito de Deus\\nCom o poder do amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Abre os olhos meus, quero ver o Teu olhar\\nMostra o Teu amor, vem viver em mim\\nRenova o meu pensar, ensina-me o Teu querer\\nCada dia mais, com o poder do amor\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X Coro)\"},{\"section_type\":\"Estrofe\",\"content\":\"Planando na amplidão,\\nDo Espírito de Deus\\nCom o poder do amor!...\"}]},{\"number\":\"1999-05\",\"collection_type\":\"Coletânea\",\"title\":\"Oh! Que Esperança!\",\"author\":\"Hinos Adventistas\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(repetir tudo)\\nOh! Que esperança vibra em nosso ser,\\nPois aguardamos o Senhor!\\nFé possuímos, que Jesus nos dá,\\nFé na promessa que nos fez.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eis que o tempo logo vem,\\nE as nações daqui e além\\nBem alerta vão cantar:\\nAleluia! Cristo é Rei!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! Que esperança vibra em nosso ser,\\nPois Aguardamos o Senhor.\"}]},{\"number\":\"1999-06\",\"collection_type\":\"Coletânea\",\"title\":\"Eu Não Me Esqueci de Ti\",\"author\":\"Prisma Brasil\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se as ondas desta vida destruírem tua fé\\nE fizerem que duvides de que em breve voltarei\\nVolve os olhos ao passado, vê na cruz o meu sofrer\\nQueres provas mais do que esta: tanto amei, que a vida dei\"},{\"section_type\":\"Estrofe\",\"content\":\"Pensas mesmo ser tão fácil esquecer o que falei\\nSe na história deste mundo já meus pés empoeirei?\\nMesmo que uma mãe viesse de seu filho se esquecer\\nAinda assim não haveria de me esquecer de ti\"},{\"section_type\":\"Estrofe\",\"content\":\"Mas ainda que demore ou mesmo que pareça\\nUm dia prometi voltar e pronto estou a cumprir\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nMas ainda que demore ou mesmo que pareça\\nEu não me esqueci de ti, virei outra vez\"}]},{\"number\":\"1999-07\",\"collection_type\":\"Coletânea\",\"title\":\"Sob o Sangue\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nTenho o sangue que vem do Cordeiro sobre a porta do meu coração\\nEspanta as trevas, me dá compreensão da força do Seu grande amor\\nSatã vive sempre acusando-me, mas sei quem é meu Salvador\\nAgora nenhuma condenação, estou sob o sangue de Deus\\nEstou sob o sangue de Deus, cobriu meus pecados na cruz\\nPela graça do Céu, santo e justo serei\\nEstou sob o sangue de Deus. Salvo e seguro do plano do mal\\nSuas ciladas não vão me afastar. Estou sob o sangue de Deus\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nEstou sob o sangue de Deus\"}]},{\"number\":\"1999-08\",\"collection_type\":\"Coletânea\",\"title\":\"Refrigera Minha Alma\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nVem refrigera-me em Tua presença\\nNão há maior benção do que andar Contigo\\nMinh'alma restaura, renova minha vida\\nEstar em Tua graça, é mais que euforia\"},{\"section_type\":\"Estrofe\",\"content\":\"Minh'alma restaura, renova minha vida\\nEstar em Tua graça, é mais que euforia\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nVem refrigera-me em Tua presença\\nNão há maior benção do que andar Contigo\\nMinh'alma restaura, renova minha vida\\nEstar em Tua graça, é plena alegria\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nEstar em Tua graça, é plena alegria\"}]},{\"number\":\"1999-09\",\"collection_type\":\"Coletânea\",\"title\":\"Cante Ao Senhor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Cristo que Salva, não há ninguém igual,\\ncada vez mais quero louvar teu grande e poderoso amor.\\nConforto refúgio és proteção para mim,\\nque meu viver tudo que sou nunca deixe de adorar.\"},{\"section_type\":\"Estrofe\",\"content\":\"(2x)\\nCante ao Senhor toda a terra e céu,\\nLouve o poder majestoso do Rei,\\ntremam os montes e todo o mar ao seu nome ouvi\"},{\"section_type\":\"Estrofe\",\"content\":\"Com alegria eu canto ao Senhor,\\nDEle para sempre será meu amor,\\nnada supera a promessa que ele\"},{\"section_type\":\"Estrofe\",\"content\":\"Cante ao Senhor toda a terra e céu,\\nLouve o poder majestoso do Rei,\\ntremam os montes e todo o mar ao seu nome ouvi\"},{\"section_type\":\"Estrofe\",\"content\":\"Com alegria eu canto ao Senhor,\\nDEle para sempre será meu amor,\\nnada supera a promessa que ele fez\"},{\"section_type\":\"Estrofe\",\"content\":\"nada supera a promessa que ele fez\"}]},{\"number\":\"1999-10\",\"collection_type\":\"Coletânea\",\"title\":\"Santo Lugar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 1999\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nos reunimos no Santo Monte,\\nE eu eu sei que existe anjos ao redor\\nVamos louvar a Jesus\\nPois se faz presente,\\nNeste santo e bom lugar\"},{\"section_type\":\"Estrofe\",\"content\":\"Nos reunimos no Santo Monte,\\nE eu eu sei que existe anjos ao redor\\nVamos louvar a Jesus\\nPois se faz presente,\\nNeste santo e bom lugar\\nPois se faz presente,\\nNeste santo e bom lugar\"}]},{\"number\":\"2000-01\",\"collection_type\":\"Coletânea\",\"title\":\"Venho Em Tua Presença\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Venho em Tua presença\\nCom louvor no coração\\nPra Te buscar\\nE adorar\"},{\"section_type\":\"Estrofe\",\"content\":\"Venho em Tua presença\\nCom louvor no coração\\nLevanto a voz\\nCom gratidão\"},{\"section_type\":\"Estrofe\",\"content\":\"Dou glória e honra ao poderoso Deus\\nCristo, Tu és o grande Rei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Venho em Tua presença\\nCom louvor no coração\\nPra Te buscar\\nE adorar\"},{\"section_type\":\"Estrofe\",\"content\":\"Venho em Tua presença\\nCom louvor no coração\\nLevanto a voz\\nCom gratidão\"},{\"section_type\":\"Estrofe\",\"content\":\"Dou glória e honra ao poderoso Deus\\nCristo, Tu és o grande Rei.\"}]},{\"number\":\"2000-02\",\"collection_type\":\"Coletânea\",\"title\":\"Minha Vida Está em Ti Senhor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Senhor, és a vida e amor.\\nÉs a força e poder.\\nA esperança que tenho em meu ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Enquanto eu viver louvarei\\nO nome do meu Salvador.\\nEu vou proclamar com todas as forças:\\nQue Tu és o Rei dos reis.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, és a vida e amor.\\nÉs a força e poder.\\nA esperança que tenho em meu ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Enquanto eu viver louvarei\\nO nome do meu Salvador.\\nEu vou proclamar com todas as forças:\\nQue Tu és o Rei dos reis.\"}]},{\"number\":\"2000-03\",\"collection_type\":\"Coletânea\",\"title\":\"Cristo Volte, Volte já\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O mundo perdeu a esperança,\\nA vida não tem segurança,\\nO sonho acabou, a fome aumentou\\nFoi tudo o que restou?\\nA triste certeza da guerra,\\nA falta de paz sobre a Terra,\\nA fuga do amor, o império da dor\\nFoi tudo o que restou?\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo volte, volte já!\\nEu não quero aqui ficar.\\nVolte Jesus! Volte Jesus!\\nVenha logo me buscar.\\nCristo volte, volte já!\\nCristo volte, volte já.\"},{\"section_type\":\"Estrofe\",\"content\":\"A falta de fé e harmonia,\\nA crise na economia;\\nA terra tremeu, o ódio cresceu;\\nFoi tudo o que restou?\\nA luta por sobrevivência,\\nA vida imoral a indecência,\\n\\\"Doença ruim\\\", o choro sem fim,\\nFoi tudo o que restou?\"}]},{\"number\":\"2000-04\",\"collection_type\":\"Coletânea\",\"title\":\"Jesus Muito Obrigado\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus, muito obrigado\\nPor ser meu amigo\\nJesus, muito obrigado\\nPor ter o seu cuidado\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus, muito obrigado\\nPor ser meu Pai amado\\nJesus, muito obrigado\\nPor dar a Sua vida\"},{\"section_type\":\"Estrofe\",\"content\":\"Por Ter me perdoado\\nPor dar a esperança\\nJesus, muito obrigado\\nPor tudo o que Tu és.\"}]},{\"number\":\"2000-05\",\"collection_type\":\"Coletânea\",\"title\":\"Tu És minha Canção\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Logo de manhã eu louvo a Ti.\\nCom gratidão por teu grande amor.\\nEntrego o meu viver somente a Ti.\\nE Tu dás pra mim a doce canção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor Tu és minha canção.\\nÉs a razão do meu louvor a Ti.\\nSenhor Tu és minha canção.\\nÉs a razão do meu viver.\\nÉs a razão do meu louvor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantarei da paz que deu a mim.\\nNova canção do coração.\\nNada há que eu não possa fazer.\\nPois Tu és pra mim a forca e poder.\"}]},{\"number\":\"2000-06\",\"collection_type\":\"Coletânea\",\"title\":\"Esperança, é Tempo de Ver Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nesta terra há tristeza, só miséria e aflição, tanta\\ngente sem resposta vive na escuridão.\\nMas eu tenho um bom Amigo,\\nÉ Jesus no coração,\\nEle em breve voltará,\\nÉ tempo de ver Jesus chegar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A esperança é ver\\nJesus voltando em glória.\\nA esperança é ir, com Ele para o lar.\\nJesus nos ensinou, o caminho a seguir,\\nNão há tempo pra perder,\\nÉ tempo de ver Jesus voltar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando lá no céu chegar, meus queridos quero ver.\\nVou ouvir Jesus chamar:\\nVem Meu filho desfrutar.\\nJesus Cristo me guiou, até hoje me orientou,\\nE por isso vou falar, o amor do Senhor cantar.\"}]},{\"number\":\"2000-07\",\"collection_type\":\"Coletânea\",\"title\":\"Sorria\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se na vida falta um sorriso,\\nÉ porque você não cantou;\\nPois quando juntos cantamos\\nA alegria tira a dor.\\nSe os problemas são infinitos,\\nE não há razão pra cantar,\\nOlhe a Cristo e sua vida vai mudar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Então sorria partilhando esta alegria;\\nE assim transmita muita força, muita união.\\nSe os problemas são infinitos,\\nE não há razão pra cantar,\\nOlhe a Cristo que sua vida vai mudar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se os amigos vivem tão tristes\\nVocê deve sempre cantar\\nPois quando juntos cantamos\\nA alegria vai começar.\\nE sentimos que fomos feitos\\nPra sorrir e sempre amar;\\nTenha sempre um sorriso para dar.\"}]},{\"number\":\"2000-08\",\"collection_type\":\"Coletânea\",\"title\":\"Creio em Seu Amor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Creio em Seu amor\\nCreio em Sua graça\\nCreio em Seu poder\\nQue me transformou\\nResgatou-me do pecado e da dor\\nQuão grande é o amor do querido Pai\\nGrande é o amor do querido Pai\\nGrande é o amor do querido Pai\"},{\"section_type\":\"Estrofe\",\"content\":\"Não dá pra esquecer Seu perdão\\nNão dá pra esquecer o que fez por mim\\nEle é poder\\nEle é a paz\\nEle satisfaz o meu coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Grande é o amor\\nGrande é o amor\\nGrande é o amor\\nDo querido Pai .\"}]},{\"number\":\"2000-09\",\"collection_type\":\"Coletânea\",\"title\":\"Bem Junto a Cristo\",\"author\":\"Ministério Jovem - APLaC\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Bem junto a Cristo eu quero estar,\\nBem junto à cruz doce paz desfrutar.\\nSim, ao Teu peito eu busco a paz,\\nPois Teu amor divinal satisfaz!\\nPois Teu amor divinal satisfaz!\"},{\"section_type\":\"Estrofe\",\"content\":\"Não trago nada mais ao Senhor,\\nSó este meu coração pecador,\\nMas te suplico em contrição,\\nOh, Salvador, dá-me paz e perdão!\\nOh, Salvador, dá-me paz e perdão!\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, quero a Cristo bem junto estar,\\nTé lá no além conseguir aportar.\\nOh, lar eterno, lar de esplendor!\\nLá estarei junto ao meu Salvador.\\nLá cantarei todo Seu grande amor.\"}]},{\"number\":\"2000-10\",\"collection_type\":\"Coletânea\",\"title\":\"Adorai\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Adorai, quem tudo fez,\\nE nos mantém\\nCom o Seu poder.\\nOh! Louvai\\nO grande Deus,\\nQue quer reinar em teu viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Em problemas e tristezas,\\nNos ampara em Suas mãos\\nCada dia vou louvá-Lo\\nPois Sua graça\\nNos dá proteção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Céus e terra rendem glórias\\nAo eterno Criador,\\nVou seguindo pela estrada\\nAmparado em seus braços de amor.\"}]},{\"number\":\"2000-11\",\"collection_type\":\"Coletânea\",\"title\":\"Amigos\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Foram poucos dias\\nTanta coisa pra contar\\nTantas experiências\\nEmoções pra relembrar\\nRostos e sorrisos\\nQue jamais se perderão\\nPois pra sempre\\nEm nosso peito ficarão\"},{\"section_type\":\"Estrofe\",\"content\":\"A amizade aqui formada\\nNós jamais esqueceremos\\nMuito em breve todos juntos\\nPara sempre viveremos\\nCristo irá voltar\\nEu quero me preparar\\nE neste lugar, amigo\\nQuero muito te encontrar\"},{\"section_type\":\"Estrofe\",\"content\":\"A saudade é grande\\nAntes mesmo de partir\\nTantos sentimentos\\nÉ difícil resistir\\nLágrimas e abraços\\nNos ajudam a compreender\\nComo vai ser bom\\nCom Cristo ali viver.\"}]},{\"number\":\"2000-12\",\"collection_type\":\"Coletânea\",\"title\":\"Eterno Lar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Um novo céu, um novo lar\\nCom meu Jesus eu vou morar\\nNão mais pesar e nem mais dor\\nPra sempre eu quero lá estar\\nFeliz serei no eterno lar\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele prometeu que vai voltar\\nE as lágrimas vai enxugar\\nContemplarei o seu olhar\\nPra sempre quero lá estar\\nFeliz serei no eterno lar\"},{\"section_type\":\"Estrofe\",\"content\":\"Com meu Jesus irei morar.\"}]},{\"number\":\"2000-13\",\"collection_type\":\"Coletânea\",\"title\":\"Não Tardará\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2000\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não tardará, Cristo irá voltar.\\nNão tardará, vamos para o lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero me preparar,\\nPois vamos logo subir\\nE quero junto a você,\\nLá no Céu\\nConversar com Jesus.\\nNão tardará, Cristo irá voltar.\\nNão tardará, vamos para o lar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero me preparar,\\nPois vamos logo subir\\nE quero junto a você,\\nLá no Céu\\nConversar com Jesus.\"}]},{\"number\":\"2001-01\",\"collection_type\":\"Coletânea\",\"title\":\"Poderoso Deus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Poderoso, Poderoso, Poderoso\\nPoderoso é o meu Deus\\nEle abriu o Mar Vermelho pra livrar Israel\\nMeu Deus é o supremo Rei\\nFechou a boca dos leões pra salvar Daniel\\nMeu Deus é o supremo Rei\\nO mesmo zelo que Ele tinha por seu povo\\nÉ o zelo que Ele ainda tem por nós\\nPor isso sei que estarei sempre seguro pois\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Deus é o supremo Rei\\nMeu Deus é o supremo Rei dos reis\\nE reina com Seu poder sobre terra e céu\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Deus é o supremo Rei\\nMeu Deus é o supremo Rei\\nMeu Deus é o supremo Rei\"},{\"section_type\":\"Estrofe\",\"content\":\"Poderoso, Poderoso, Poderoso\\nPoderoso é o meu Deus\"}]},{\"number\":\"2001-02\",\"collection_type\":\"Coletânea\",\"title\":\"Quase no Lar\",\"author\":\"Jader Santos\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"No arraial dos santos\\nOuvem-se muitas vozes\\nEstão felizes cantando\\nEm celebração\\nAlguns estão pregando\\nOutros vão ensinando\\nMas o amor é o tom da canção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Estamos quase no lar, quase no lar!\\nFaltando pouco tempo pra esse dia chegar.\\nEstamos quase no lar!\\nCom Jesus viveremos nas mansões celestiais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus está voltando\\nVamos falar a todos\\nEnfim está chegando a libertação\\nDevemos Ter coragem de viver a mensagem\\nQue foi plantada lá no coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos dar as mãos\\nE juntos vamos prosseguir\\nNo poder de Deus\\nVitória vamos conseguir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Estamos quase no lar, quase no lar!\\nFalta pouco tempo pra esse dia chegar.\\nEstamos quase no lar, quase no lar!\\nCom Jesus viveremos\\nCom Jesus viveremos\\nCom Jesus viveremos\\nNas mansões celestiais.\"}]},{\"number\":\"2001-03\",\"collection_type\":\"Coletânea\",\"title\":\"Medley - Quão Bom, Satisfação, o Amor Sem Deus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nQuão bom e quão maravilhoso é\\nQue os irmãos vivam em união\"},{\"section_type\":\"Estrofe\",\"content\":\"Aperte a mão do seu irmão\\nE dê um sorriso pra ele\\nAperte a mão do seu irmão\\nE cante esta canção\"},{\"section_type\":\"Estrofe\",\"content\":\"Satisfação é Ter a Cristo\\nNão há melhor prazer já visto\\nSou de Jesus e agora eu sinto satisfação sem fim\\nSim paz real, sim gozo na aflição\\nAchei o segredo é Cristo no coração\"},{\"section_type\":\"Estrofe\",\"content\":\"O amor sem Deus tão passageiro é\\nMas o doce amor de meu mestre\\nÉ algo que jamais morrerá\\nNão morrerá, não morrerá\\nÉ algo que jamais morrerá\\nSim o doce amor de meu mestre\\nÉ algo que jamais morrerá\"},{\"section_type\":\"Estrofe\",\"content\":\"Aperte a mão do seu irmão\\nE dê um sorriso pra ele\\nAperte a mão do seu irmão\\nE cante esta canção\"},{\"section_type\":\"Estrofe\",\"content\":\"Satisfação é não Ter medo\\nPois meu Jesus virá bem cedo\\nLogo em glória eu hei de vê-lo\\nSatisfação sem fim\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim o doce amor de meu Mestre\\nÉ algo que jamais morrerá\"},{\"section_type\":\"Estrofe\",\"content\":\"Quão bom e quão maravilhoso é\\nQue os irmãos vivam em união\"}]},{\"number\":\"2001-04\",\"collection_type\":\"Coletânea\",\"title\":\"Estende a Tua Mão\",\"author\":\"Cleiton Schaefer\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Estende a Tua mão\\nTem misericórdia\\nEstende a Tua mão\\nE cura o Teu povo\\nEssa mão que nos restaura\\nCom perdão que vem da cruz\\nPurifica nossa alma\\nCom o sangue de Jesus\\nTraz de volta a paz\\nAo coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Resplandece oh Senhor\\nE transborda Teu amor\\nResplandece oh Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Traz de volta a paz ao coração\\nTraz de volta a paz ao coração\\nEstende a Tua mão\\nTem misericórdia\\nEstende a Tua mão\\nE cura o Teu povo\\nEssa mão que nos restaura\\nCom perdão que vem da cruz\\nPurifica nossa alma\\nCom o sangue de Jesus\\nTraz de volta a paz\\nAo coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Resplandece oh Senhor\\nE transborda Teu amor\\nResplandece oh Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Traz de volta a paz ao coração\\nTraz de volta a paz ao coração\"}]},{\"number\":\"2001-05\",\"collection_type\":\"Coletânea\",\"title\":\"A Esperança É Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não há esperança alguma\\nPra um mundo onde Deus não está\\nNão há esperança de amor e de paz\\nOnde o ódio deixa marcas fatais\\nNão há esperança de vida\\nNaqueles que não amam a Deus\\nNão há esperança de um mundo de paz,\\nSe o homem deixa Deus para trás\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nA esperança é Jesus,\\nEle é o caminho\\nA esperança é Jesus,\\nNossa luz entre espinhos\\nA esperança é Jesus,\\nSegurança de salvação\\nOnde o mundo\\nPode achar solução\\nA esperança é Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Só há esperança e certeza\\nNaquele que é vencedor\\nSó há esperança no nome de Deus\\nPara um povo que não tem mais amor\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)(2X)\"},{\"section_type\":\"Estrofe\",\"content\":\"A esperança é Jesus\"}]},{\"number\":\"2001-06\",\"collection_type\":\"Coletânea\",\"title\":\"Estaremos Juntos Pra Sempre\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A vida vai depressa\\nE hoje temos que sofrer\\nSó dor e morte vemos\\nO pranto é nosso pão\\nAmigos temos hoje\\nQue por certo durarão\\nMas breve fugirão daqui e\\nTudo passará\"},{\"section_type\":\"Estrofe\",\"content\":\"Um dia não iremos mais chorar\\nViveremos todos unidos em amor\\nConfiando nas promessas do Senhor\\nEstaremos juntos pra sempre\"},{\"section_type\":\"Estrofe\",\"content\":\"O amor é tão imenso\\nQue tu podes ter também\\nSeu nome é Jesus Cristo\\nE está em teu coração\\nEle é um grande amigo\\nQue jamais te deixará\\nPor hoje e para sempre\\nContigo estará\"},{\"section_type\":\"Estrofe\",\"content\":\"Estaremos juntos lá no céu\"}]},{\"number\":\"2001-07\",\"collection_type\":\"Coletânea\",\"title\":\"Eu Quero Ouvir\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ouvir a tua voz\\nContigo ó Pai ficar a sós\\nMe demorar em Teu olhar\\nSeguro estar e descansar\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu sabes Pai o meu querer\\nQuero entregar tudo o que sou\\nVem transformar o meu viver\\nPra sempre Teu eu quero ser\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero a paz dos braços Teus\\nO braço forte de meu Deus\\nNos rios da graça me banhar\\nE ouvir Tua voz me sussurrar\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu sabes Pai o meu querer\\nQuero entregar tudo o que sou\\nVem transformar o meu viver\\nPra sempre Teu eu quero ser\\nPra sempre Teu eu quero ser.\"}]},{\"number\":\"2001-08\",\"collection_type\":\"Coletânea\",\"title\":\"Nisto Cremos\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cremos todos em Jesus Cristo\\nCremos todos em Deus o Pai\\nCremos todos no Santo Espírito\\nQue aonde formos conosco vai\\nCremos todos na Santa Bíblia\\n(cremos todos na Santa Bíblia)\\nE que a fé pode nos salvar\\n(e que a fé pode nos salvar)\\nCremos todos no santo Sábado\\n(cremos todos no santo Sábado)\\nE que Cristo nos vem buscar\\n(e que Cristo nos vem buscar)\"},{\"section_type\":\"Estrofe\",\"content\":\"Santo, Santo, Santo és Senhor\\nToda a terra louve ao Salvador\\nPoder, majestade e glórias\\nAo rei queremos cantar\\nPois cremos em Ti\"},{\"section_type\":\"Estrofe\",\"content\":\"Cremos todos que o cordeiro\\nE que o sangue que derramou\\nNos livrou de toda culpa\\nPara a vida nos resgatou\"},{\"section_type\":\"Estrofe\",\"content\":\"Santo, Santo, Santo és Senhor\\nSanto, Santo, Santo és Senhor\"}]},{\"number\":\"2001-09\",\"collection_type\":\"Coletânea\",\"title\":\"Medley - Canta Minh'alma, Tu É Fiel Senhor, Fixa Teus Olhos No Mestre, Porque Ele Vive\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(2X)\\nCanta minh'alma\\nCanta ao Senhor\\nRende-lhe sempre\\nHonra e louvor\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu és fiel Senhor\\nÓ Deus eterno\\nTeus filhos sabem que não falharás\\nNunca mudaste tu nunca faltaste\\nTal como eras sim sempre serás\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu és fiel Senhor\\nTu és fiel Senhor\\nDia após dia Tuas bênçãos nos dás\\nTua mercê nos sustenta e nos guarda\\nSim para sempre ó Deus fiel serás\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor meu Deus quando eu maravilhado\\nFico a pensar nas obras de Tuas mãos\\nEstrelas mil a cintilar no espaço\\nDe teu poder em manifestação\\nEntão minh'alma canta a Ti Senhor\\nQuão grande és Tu\\nQuão grande és Tu\\nEntão minh'alma canta a Ti Senhor\\nQuão grande és Tu\\nQuão grande és Tu\"},{\"section_type\":\"Estrofe\",\"content\":\"Fixa teus olhos no mestre\\nConfia no bom Salvador\\nFruirás na luta terrestre\\nMaravilhas do seu doce amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Porque Ele vive posso crer no amanhã\\nPorque Ele vive temor não há\\nEu sei que minha vida\\nNão será mais vã\\nPois meu futuro em Suas mãos\\nAgora está\"},{\"section_type\":\"Estrofe\",\"content\":\"Canta minh'alma\\nCanta ao Senhor\\nRende-lhe sempre\\nHonra e louvor\"}]},{\"number\":\"2001-10\",\"collection_type\":\"Coletânea\",\"title\":\"Foi Assim\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em tristeza eu vivia\\nO amanhã me era escuro\\nNão sabia onde meu pensamento pôr\\nMas em toda provação\\nJesus proveu consolação\\nE o meu sofrer tornou\\nMais forte o coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Foi assim foi assim,\\nQue aprendi a ter confiança\\nEm Cristo meu Senhor\\nFoi assim foi assim,\\nQue aprendi\\nA depender do amor de Deus\"},{\"section_type\":\"Estrofe\",\"content\":\"Graças dou por minhas dores\\nE tormentos que enfrentei\\nAtravés do meu sofrer\\nPude a fé compreender\\nE senti bem junto a mim\\nO amor de Cristo a me guiar\\nEm segurança no caminho rumo ao lar\"},{\"section_type\":\"Estrofe\",\"content\":\"Que aprendi a depender do amor de Deus\"}]},{\"number\":\"2001-11\",\"collection_type\":\"Coletânea\",\"title\":\"Momentos\",\"author\":\"Silmar Correa\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Momentos felizes passamos\\nMomentos tão lindos, não dá pra esquecer!\\nMomentos que em paz conversamos e\\nJuntos cantamos com tanto prazer.\\nMomentos de amor e alegria,\\nMomentos de muita emoção.\\nMomentos que compartilhamos, e agora\\nLembramos na nossa canção!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vocês deixarão saudade\\nPor momentos da nossa amizade.\\nVocês seguirão seu rumo,\\nMas algo profundo não vai se acabar:\\nNão vai se acabar\\nO amor que uniu a nossa vida,\\nO amor que nos tornou irmãos.\"},{\"section_type\":\"Estrofe\",\"content\":\"Agora somos mais que amigos\\nVocês vão comigo no meu coração!\\nSe um dia precisarem de mim,\\nDe onde eu estiver eu vou.\\nEu sempre estarei lembrando\\nDeste bom momento\\nQue você deixou.\"},{\"section_type\":\"Estrofe\",\"content\":\"(final)\\nEu sempre estarei lembrando\\nDeste bom momento que você deixou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Momentos atrás aprendemos\\nQue ter mais amigos também é sofrer,\\nMomentos que juntos choramos\\nE unidos lutamos pra sobreviver!\\nMomentos que hoje lembramos,\\nA vida não vai apagar.\\nE ao ver os seus olhos brilhando,\\nNo último instante preciso falar:\"}]},{\"number\":\"2001-12\",\"collection_type\":\"Coletânea\",\"title\":\"Meu Abrigo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Senhor é o meu abrigo\\nSeguro Rocha Eterna\\nÉ só Nele que eu confio\\nSó Ele vence a guerra\\nContra meus inimigos\\nNão preciso temer\\nO Senhor é comigo\\nMe dá poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Ele dá o poder\\nEle dá o poder\\nO Senhor\\nMe dá poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando tudo está perdido\\nEu tenho Alguém comigo\\nDou um grito de esperança\\nE ergo a minha lança\"},{\"section_type\":\"Estrofe\",\"content\":\"Contra meus inimigos\\nNão preciso temer\\nO Senhor é comigo\\nMe dá o poder\\nO Senhor é o meu abrigo\"}]},{\"number\":\"2001-13\",\"collection_type\":\"Coletânea\",\"title\":\"Vou Para o Lar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2001\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Muito em breve Cristo vai voltar\\nE eu vou para o lar\\nQuando enfim, nas nuvens regressar\"},{\"section_type\":\"Estrofe\",\"content\":\"Vou para o lar vou para o lar de glória\\nVou para o lar\\nQuando eu for aleluia eu vou cantar\\nVou para o lar\"},{\"section_type\":\"Estrofe\",\"content\":\"Logo este mundo vai findar\\nE eu vou para o lar\\nNunca mais sofrer e nem chorar\\nVou para o lar\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero então cantar alegremente:\\nVou para o lar\\nE ao mundo inteiro proclamar:\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando eu for aleluia eu vou cantar\\nVou para o lar\\nEu vou para o lar\"}]},{\"number\":\"2002-01\",\"collection_type\":\"Coletânea\",\"title\":\"Aleluia, Aleluia!\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Senhor, estamos em Tua presença\\nUnidos pelo Teu amor.\\nSomos Teu povo, remidos por Ti.\\nTeu sangue nos libertou\\nNão há Palavras para agradecer - Te\\nNem expressar o nosso louvor\\nMas ergueremos a voz\\nLouvando ao Senhor, com todo fervor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aleluia, aleluia, aleluia ao Senhor\\nAleluia, aleluia Criador e Redentor\\nTodo povo, toda raça, toda\\ntribo e nação\\nToda honra, toda glória\\nE louvores ao Cordeiro de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor em Ti fomos purificados\\nTransformados pelo Teu poder\\nSomos Teus filhos, chamados por Ti\\nPara cumprir Teu querer\\nNecessitamos do Teu Santo Espírito\\nPara ao mundo inteiro anunciar\\nQue Jesus Cristo virá\\nSeu reino fundar e ao Céu nos levar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Aleluia, aleluia, aleluia ao Senhor\\nAleluia, aleluia Criador e Redentor\\nTodo povo, toda raça, toda tribo e nação\\nToda honra, toda glória\\nE louvores ao Cordeiro de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"E louvores ao Cordeiro de Deus.\\nRei dos reis, Rei dos reis\"}]},{\"number\":\"2002-02\",\"collection_type\":\"Coletânea\",\"title\":\"Você Me Pertence\",\"author\":\"Jader Santos\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Esta vida passa depressa\\nO tempo não espera ninguém\\nNum instante tudo se acaba\\nE findam-se os sonhos também.\\nE a pergunta é: Como estaremos nós\\nQuando esse dia chegar?\\nAntes de o tempo acabar\\nOuça ainda o Mestre falar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Você me pertence, Jesus é quem diz.\\nVocê me pertence, e em mim é feliz.\\nOlhe pra cruz e receba perdão.\\nQuero lhe dar salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Siga sempre olhando em frente\\nE nunca tente olhar para trás.\\nCom certeza existe mais gente\\nQue o seu exemplo pode ajudar.\\nE a pergunta é: Quem vai à frente estar\\nQuando a jornada findar?\\nEu quero, sim, lá estar.\\nQuero ouvir meu Deus me chamar.\"}]},{\"number\":\"2002-03\",\"collection_type\":\"Coletânea\",\"title\":\"Profundo Amor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há um desejo em mim só Tu podes ver\\nMeu fraco coração podes compreender\\nMinha alma está, Senhor, sedenta por Tua luz\\nDá-me da água da fonte que é Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem encher-me do Teu profundo amor\\nCom Teus braços vem me envolver\\nPara sempre vem me aquecer com Teu calor\\nTudo o que preciso é Teu amor\\nJunto a Ti quero estar, Senhor.\\nA cada dia quero ouvir Tua voz\\nAos meus ouvidos dizendo o que fazer\"},{\"section_type\":\"Estrofe\",\"content\":\"A minha vida a Ti eu quero entregar\\nTua verdade eu quero partilhar.\"}]},{\"number\":\"2002-04\",\"collection_type\":\"Coletânea\",\"title\":\"Em Família\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em família estamos aqui\\nPartilhando o amor de Jesus\\nQue Sua cruz o motive a orar\\nE a cantar conosco esta canção\\nA alegria de vê-lo aqui,\\nPulsa forte o meu coração\\nSinta o amor que nos une então\\nNeste aperto de mão.\\n(Final 3x)\"}]},{\"number\":\"2002-05\",\"collection_type\":\"Coletânea\",\"title\":\"Unidos Pela Palavra\",\"author\":\"Marcelo Meireles\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Lâmpada para os pés\\nLuz para o caminho nós teremos\\nUnidos pela Palavra\\nEspada de poder\\nVerdade que liberta, nós teremos\\nUnidos pela Palavra\\nCom porção dobrada do Espírito\\nÓ Senhor vem nos encher\\nFaz-nos um, unidos pela Palavra\\nNós faremos grandes maravilhas\\nAo descer o Teu poder\\nFaz-nos um, unidos pela Palavra.\"},{\"section_type\":\"Estrofe\",\"content\":\"Lâmpada para os pés\\nLuz para o caminho nós teremos\\nUnidos pela Palavra\\nEspada de poder\\nVerdade que liberta, nós teremos\\nUnidos pela Palavra\\nCom porção dobrada do Espírito\\nÓ Senhor vem nos encher\\nFaz-nos um, unidos pela Palavra\\nNós faremos grandes maravilhas\\nAo descer o Teu poder\\nFaz-nos um, unidos pela Palavra.\"}]},{\"number\":\"2002-06\",\"collection_type\":\"Coletânea\",\"title\":\"Te Agradeço\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Por tudo o que Tens feito\\nPor tudo o que Vais fazer\\nPor Tuas promessas e tudo o que És\\nEu quero Te agradecer\\nCom todo o meu ser\\nHomens: Te agradeço, meu Senhor\\nMulheres: Te agradeço, meu Senhor (2 x)\\nTe agradeço por me libertar e salvar\\nPor ter morrido em meu lugar\\nTe agradeço\\nJesus, te agradeço\\nEu te agradeço\\nTe agradeço.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por tudo o que Tens feito\\nPor tudo o que Vais fazer\\nPor Tuas promessas e tudo o que És\\nEu quero Te agradecer\\nCom todo o meu ser\\nHomens: Te agradeço, meu Senhor\\nMulheres: Te agradeço, meu Senhor (2 x)\\nTe agradeço por me libertar e salvar\\nPor ter morrido em meu lugar\\nTe agradeço\\nJesus, te agradeço\\nEu te agradeço\\nTe agradeço.\"}]},{\"number\":\"2002-07\",\"collection_type\":\"Coletânea\",\"title\":\"Jesus e Eu\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Feliz estou, pois Jesus caminha sempre\\nao meu lado.\\nEu tenho paz, pois com Ele posso\\nsempre conversar.\\nJesus me dá Seu conforto,\\nproteção e segurança;\\nNão há temor, pois em Cristo posso sempre\\nconfiar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus e eu, que amizade tão bonita e sincera;\\nJesus e eu, lado a lado vamos sempre\\ncaminhar.\\nJesus e eu é certeza de vitória nesta vida;\\nJesus e eu amizade que jamais\\nacabará.\\n(Final repete)\"},{\"section_type\":\"Estrofe\",\"content\":\"Nos dias maus Jesus Cristo sempre é\\nmeu grande amigo.\\nSe falta amor, é Jesus quem me ajuda\\na entender.\\nJesus e eu para sempre estaremos\\nbem unidos;\\nFeliz serei partilhando minha vida com\\nJesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Amizade que jamais acabará.\"}]},{\"number\":\"2002-08\",\"collection_type\":\"Coletânea\",\"title\":\"Vem Senhor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem, Senhor! Vem, Senhor!\\nVem encher os corações,\\nÓ vem, Senhor!\\nAo cantar, ao orar\\nVem falar aos corações.\\nÓ vem, Senhor! Vem,Senhor!\\nVem , Senhor! Vem encher\\nos corações\\nÓ vem ,Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao cantar, ao orar\\nVem falar aos corações.\\nÓ vem, Senhor! Vem falar aos\\ncorações\\nÓ vem, Senhor! Vem falar\\naos corações.\\nÓ vem, Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem, Senhor! Vem, Senhor!\\nVem encher os corações,\\nÓ vem, Senhor!\\nAo cantar, ao orar\\nVem falar aos corações.\\nÓ vem, Senhor! Vem,Senhor!\\nVem , Senhor! Vem encher\\nos corações\\nÓ vem ,Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ao cantar, ao orar\\nVem falar aos corações.\\nÓ vem, Senhor! Vem falar aos\\ncorações\\nÓ vem, Senhor! Vem falar\\naos corações.\\nÓ vem, Senhor!\"}]},{\"number\":\"2002-09\",\"collection_type\":\"Coletânea\",\"title\":\"Louvai a Deus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vales, montanhas, planícies, louvai\\nLuas, estrelas, planetas, cantai\\nLagos e rios, ondas do mar, louvai\\nPovos, nações, toda Terra, louvai\\nBosques, Campinas, florestas, cantai\\nAves do céu, peixes do mar, louvai\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus é o regente do céu e do mar\\nDEle é a glória e todo o louvor\\nCom alegria, com fé adorai\\nLouvai a Deus com amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Com instrumentos de cordas, louvai\\nFlautas, trompetes, teclados, tocai\\nCom emoção, todos a Deus, louvai\\nDeus é o regente do céu e do mar;\\nDEle é a glória e todo o louvor.\\nCom alegria, com fé adorai;\\nLouvai a Deus com amor\\nTodos os povos na mesma emoção\\nCantai louvores em seu coração\\nDEle é a glória e todo o louvor.\\nLouvai a Deus com amor,\"},{\"section_type\":\"Estrofe\",\"content\":\"Louvai a Deus com Amor,\\nLouvai a Deus com amor.\"}]},{\"number\":\"2002-10\",\"collection_type\":\"Coletânea\",\"title\":\"Vem Brilhar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2002\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"(2 vezes)\\nPai, vem fazer com que a Tua luz\\nVenha em mim brilhar\"},{\"section_type\":\"Estrofe\",\"content\":\"Só assim eu terei salvação em Ti\\nE a Tua luz brilhando em mim\\nVai dizer que sou feliz\"},{\"section_type\":\"Estrofe\",\"content\":\"(2 vezes)\\nPai, vem trazer Tua graça e paz\\nPara o meu viver\"},{\"section_type\":\"Estrofe\",\"content\":\"Só assim eu terei salvação em Ti\\nE a Tua luz brilhando em mim\\nVai dizer que sou feliz\"},{\"section_type\":\"Estrofe\",\"content\":\"(2 vezes)\\nPai vem encher do Teu grande amor\\nEsse pobre ser\"},{\"section_type\":\"Estrofe\",\"content\":\"Só assim eu terei salvação em Ti\\nE a Tua luz brilhando em mim\\nVai dizer que sou feliz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vai dizer que sou feliz.\"}]},{\"number\":\"2003-01\",\"collection_type\":\"Coletânea\",\"title\":\"Celebrar e Cantar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Este é o momento em que vou louvar.\\nVou me alegrar em meu Salvador.\\nQuero exaltar Seu eterno amor\\nVou celebrar e cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Este é o momento em que vou louvar.\\nVou me alegrar em meu Salvador.\\nQuero exaltar Seu eterno amor.\\nVou celebrar e cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cantar da Salvação.\\nCantar do Seu perdão.\\nCantar que vai voltar.\\nVou celebrar e cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Foi pela fé que me justificou\\nPelo Espírito santificou\\nQuando voltar vai me glorificar.\\nVou celebrar, vou celebrar,\\nVou celebrar, vou celebrar e cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Todo aquele que Nele crer\\nPode em Jesus salvação obter\\nE habitar no eterno lar.\\nVou celebrar, vou celebrar,\\nVou celebrar, vou celebrar e cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"E é quando percebo, meu esforço é vão\\nE o que devo fazer é segurar Sua mão\"}]},{\"number\":\"2003-02\",\"collection_type\":\"Coletânea\",\"title\":\"Ensina-me a Servir\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O mundo quer mais atenção, pessoas pedem mais compreensão.\\nJesus morreu pra nos mostrar, que o amor tem força para nos salvar.\\nPai, Tu podes ensinar-me ao meu próximo ajudar.\\nVou a cada ser humano Tua cruz revelar.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Côro)\\nEnsina-me a servir, querido e bom Pastor;\\nQue o mundo veja em mim, Teu sorriso e Teu amor.\\nQue meus olhos mostrem vida e luz aos que não vêem.\\nE meus lábios levem esperança e paz também.\\nEnsina-me a servir Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Preciso ter mais compaixão, e dar aos pobres força água e pão;\\nPreciso ser cortês e bom, levando a todos os divinos dons.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pai, que eu tenha mais coragem para sempre estar em pé;\\nVou a cada ser humano despertar força e fé.\"},{\"section_type\":\"Estrofe\",\"content\":\"Os anjos poderiam aqui descer, servir ao mundo com seu poder,\"},{\"section_type\":\"Estrofe\",\"content\":\"Mas Deus me deu a benção de amar alguém, fazendo só o bem.\\nEnsina-me a servir, querido e bom Pastor;\"},{\"section_type\":\"Estrofe\",\"content\":\"Que o mundo veja em mim, Teu sorriso e Teu amor.\\nQue meus olhos mostrem vida e luz aos que não vêem.\"},{\"section_type\":\"Estrofe\",\"content\":\"E meus lábios levem esperança e paz também.\\nEnsina-me a servir Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"(2x)\\nEnsina-me a servir, ensina-me a servir, ensina-me a servir, Jesus.\"}]},{\"number\":\"2003-03\",\"collection_type\":\"Coletânea\",\"title\":\"Brilhar Por Ti\",\"author\":\"Versão Leonardo Gonçalves\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Às vezes parece que ser um cristão\\nNão é fácil em meio à escuridão\\nAinda mais se eu pensar que não é minha luz\\nMas a união com Deus que o brilho produz.\"},{\"section_type\":\"Estrofe\",\"content\":\"E às vezes parece difícil entender\\nQue o cristão é exemplo mesmo sem o querer\\nE por isso mesmo eu preciso orar\\nPra que Deus me ilumine e assim eu possa brilhar\"},{\"section_type\":\"Coro\",\"content\":\"Senhor eu quero brilhar por Ti\\nQuando o mundo se apagar\\nEu quero que através da minha vida\\nAlguém possa Te enxergar\\nFaze com que, mesmo sem palavras\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu fale do Teu amor\\nEu quero brilhar por Ti\\nBrilhar onde quer que for.\"},{\"section_type\":\"Estrofe\",\"content\":\"Às vezes eu temo que vou fracassar\\nPois eu sei que errei e continuo a errar\\nMas se a minha luz parece extinguir-se\\nMeu Deus me dá força pra prosseguir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não importa o quanto eu tente me esforçar\\nEu só posso vencer se Ele me ajudar\\nE é quando percebo, meu esforço é vão\\nE o que devo fazer é segurar Sua mão\"},{\"section_type\":\"Coro\",\"content\":\"Senhor eu quero brilhar por Ti\\nQuando o mundo se apagar\\nEu quero que através da minha vida\\nAlguém possa Te enxergar\\nFaze com que, mesmo sem palavras\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu fale do Teu amor\\nEu quero brilhar por Ti\\nBrilhar onde quer que for\\nEu quero brilhar por Ti\\nBrilhar onde quer que for\"}]},{\"number\":\"2003-04\",\"collection_type\":\"Coletânea\",\"title\":\"A Colheita\",\"author\":\"Jader Santos\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Os campos estão brancos, já podemos ver.\\nDesponta um novo dia, um novo amanhecer.\\nHá trabalho a ser feito, inda há muito que colher.\\nÉ Jesus que nos convida, o que vamos responder?\"},{\"section_type\":\"Coro\",\"content\":\"Eu quero ir, Senhor, à seara trabalhar.\\nQuero ser ajudador, falar de Cristo e Seu amor.\\nEu quero ser, Senhor, uma luz a iluminar.\\nQuero dar o meu melhor, quero ver Jesus voltar.\"},{\"section_type\":\"Estrofe\",\"content\":\"É nossa alegria, ir e proclamar:\\n“Jesus está voltando, Virá pra nos buscar!”\\nMuita gente não percebe, o que vai acontecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se não forem avisados, eles podem perecer!\\nCôro 2x:\\nEu quero ir, Senhor, à seara trabalhar.\\nQuero ser ajudador, falar de Cristo e Seu amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ser, Senhor, uma luz a iluminar.\\nQuero dar o meu melhor, quero ver Jesus voltar.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Final)\\nQuero ver Jesus voltar\\n(Falado) Ver Jesus voltar, Ver Jesus voltar, Ver Jesus\"}]},{\"number\":\"2003-05\",\"collection_type\":\"Coletânea\",\"title\":\"O Melhor Lugar do Mundo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"No mundo ainda existem belezas\\nQue alegram a vida e nos fazem sonhar\\nRecantos felizes da natureza\\nOnde qualquer ser humano gostaria de estar\\nMas de todos os lugares\\nO mais bonito e inspirador\\nÉ onde fico em oração\\nJunto aos pés do Salvador\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nO melhor lugar do mundo\\nÉ aos pés do Salvador\\nÉ ali onde a esperança\\nTraz alívio ao sofredor\\nÉ ali onde eu me encontro\\nCom a fonte do amor\\nO melhor lugar do mundo\\nÉ aos pés do Salvador\"},{\"section_type\":\"Estrofe\",\"content\":\"Sonhamos com casas que tenham conforto\\nTalvez numa encosta com vista pro mar\\nMas as maravilhas não fazem sentido\\nSe Cristo não está no primeiro lugar\\nAo sentir a paz de Deus\\nSeu poder e amor profundo\\nEu posso estar onde for\\nEstou feliz por me encontrar\\nNo melhor lugar do mundo\"},{\"section_type\":\"Estrofe\",\"content\":\"(Final)\\nÉ ali onde eu me encontro\\nCom a fonte do amor\\nO melhor lugar do mundo\\nÉ aos pés do Salvador\"}]},{\"number\":\"2003-06\",\"collection_type\":\"Coletânea\",\"title\":\"Em Tua Casa\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em Tua casa, Senhor,\\nOs filhos Teus reunidos\\nSe encontram felizes\\nPois fazem parte da sua Tua imensa família\"},{\"section_type\":\"Estrofe\",\"content\":\"E num sorriso feliz, repleto de afeição\\nNos cumprimentamos e nos abraçamos\\nComo amigos e irmãos\\nCristo é a videira, nós somos Seus ramos.\"},{\"section_type\":\"Estrofe\",\"content\":\"Seu sangue é que nos dá o poder\\nO amor de Jesus, em Ti faz-nos um\\nE o mal nunca irá nos vencer.\\nE agora dadas as mãos, erguemos a mesma oração:\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus fortaleça nossa amizade\\nE que ela jamais tenha fim.\\nDeus fortaleça nossa amizade\\nE que ela jamais tenha fim.\"}]},{\"number\":\"2003-07\",\"collection_type\":\"Coletânea\",\"title\":\"Perto de Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Perto de Jesus\\nSempre quero estar\\nTudo o que eu preciso ó Pai\\nSempre encontro junto a Ti\\nQuero aqui ficar\\nNunca me afastar\\nE ao me abraçar Senhor\\nSinto o Teu amor por mim\\nTu és o meu Deus\\nQuero só a Ti\"},{\"section_type\":\"Coro\",\"content\":\"Quero entregar\\nO meu viver Senhor\\nSim quero estar\\nBem junto a Ti Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"(Final)\\nBem junto a Ti Jesus\"}]},{\"number\":\"2003-08\",\"collection_type\":\"Coletânea\",\"title\":\"O Teu Poder\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Queremos te pedir Senhor Teu poder, Teu poder\\nSó há um meio de vencer Teu poder, Teu poder\"},{\"section_type\":\"Estrofe\",\"content\":\"O Teu poder que vem lá do alto\\nO Teu poder pra vencer o mal\\nEm Teu poder está nossa esperança\\nConcede o Teu poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Estamos tão cansados, Pai,\\nDá o poder, nos dá poder\\nRevive o nosso coração, dá poder, nos dá poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"(2x)\\nO Teu poder que vem lá do alto\\nO Teu poder pra vencer o mal\\nEm Teu poder está nossa esperança\\nConcede o Teu poder\"},{\"section_type\":\"Estrofe\",\"content\":\"(Final)\\nConcede o Teu poder\"}]},{\"number\":\"2003-09\",\"collection_type\":\"Coletânea\",\"title\":\"Medley: Estou Seguindo/Jesus é Melhor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Estou seguindo a Jesus Cristo.\\nDeste caminho eu não desisto.\\nEstou seguindo a Jesus Cristo\\nAtrás não volto nunca mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se me deixarem os pais e amigos.\\nSe me cercarem muitos perigos.\\nSe me deixarem os pais e amigos.\\nAtrás não volto nunca mais!\"},{\"section_type\":\"Estrofe\",\"content\":\"Atrás o mundo, Jesus na frente.\\nJesus o guia Onipotente.\\nAtrás o mundo, Jesus na frente.\\nAtrás não volto nunca mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus é melhor sim que ouro e bens.\\nJesus é melhor do que tudo que tens.\\nMelhor que riquezas e posições.\"},{\"section_type\":\"Estrofe\",\"content\":\"Melhor muito mais do que milhões.\\nJesus é melhor é melhor que qualquer valor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Amigo leal no prazer e na dor.\\nMelhor do que tudo Ele é pra mim.\\nMelhor que qualquer amigo enfim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pode ser um rei com poder nas mãos,\\nMas do mal escravo sim.\\nMil vezes prefiro o meu Jesus\\nE servi-Lo até o fim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Estou seguindo a Jesus Cristo\\nAtrás não volto nunca mais.\"}]},{\"number\":\"2003-10\",\"collection_type\":\"Coletânea\",\"title\":\"A Minha Esperança\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2003\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A minha esperança está no Senhor (2x)\\nSe a vida apresenta motivos pra desanimar\\nA minha esperança está no Senhor\\nSe as nuvens escuras não querem passar\\nA minha esperança está no Senhor\\nSe alguém que eu amo vier me ferir\\nA minha esperança está no Senhor\\nSe às vezes me esqueço de amar ou sorrir\\nA minha esperança está no Senhor\"},{\"section_type\":\"Coro\",\"content\":\"Se existem motivos pra desanimar\\nSe as nuvens escuras espalham temor\\nPreciso aprender a sorrir e cantar\\nA minha esperança está no Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"A minha esperança está no Senhor\\nEu quero erguer minha voz em louvor e cantar\\nA minha esperança está no Senhor\\nDe dia ou de noite em qualquer lugar\"},{\"section_type\":\"Estrofe\",\"content\":\"A minha esperança está no Senhor\\nEm qualquer caminho por onde eu passar\\nA minha esperança está no Senhor\\nEu quero dizer: Vale a pena confiar\\nA minha esperança está no Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, Senhor, Senhor\\nEstá no Senhor\\n(repete)\\nSe a vida apresenta motivos pra desanimar\"},{\"section_type\":\"Estrofe\",\"content\":\"A minha esperança está no Senhor\\nEu quero erguer minha voz em louvor e cantar\\nA minha esperança está no Senhor (4x)\"}]},{\"number\":\"2004-01\",\"collection_type\":\"Coletânea\",\"title\":\"Senhor, Somos tua Voz\",\"author\":\"Wanderson Paiva / Samuel Krahembüll\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Uma voz nos chama, nós devemos atender,\\nÉ a voz de Cristo nos lembrando o que fazer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Ir por todo o mundo e pregar do Seu amor\\nÉ o que faremos pelo nosso Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Senhor, usar a nossa vida,\\nÓ Senhor, dá poder a todos nós.\\nCom amor, falaremos cada dia,\\nPois, Senhor, nós somos Tua voz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mulheres\\nPara este tempo, para esta situação\\nFomos escolhidos pra cumprirmos a missão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Homens\\nVamos pelo mundo proclamando sem cessar\\nQue em breve Cristo voltará pra nos buscar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Senhor, usar a nossa vida,\\nÓ Senhor, dá poder a todos nós.\\nCom amor falaremos cada dia\\nPois, Senhor, nós somos Tua voz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Senhor, usar a nossa vida,\\nÓ Senhor, dá poder a todos nós.\\nCom amor falaremos cada dia\\nPois, Senhor, nós somos Tua voz.\\nPois, Senhor, nós somos Tua voz\"}]},{\"number\":\"2004-02\",\"collection_type\":\"Coletânea\",\"title\":\"Tu És\",\"author\":\"Joel Guimarães / Lineu Soares\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sim, Tu és poder Senhor.\\nTu és poder\\nCom Tua força\\nSempre vou vencendo o mal\\nTu és poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, Tu és amor Senhor.\\nTu és amor\\nGrande prova\\nFoi dar Teu filho em meu lugar\\nTu és amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, Tu és fiel Senhor\\nTu és fiel\\nMinha vida entrego em Tuas mãos, ó Pai.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu és fiel.\"}]},{\"number\":\"2004-03\",\"collection_type\":\"Coletânea\",\"title\":\"Em Mim\",\"author\":\"Laly de Gigliotti e Daniel Fonseca\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quero, meu Senhor, cantar em Teu Louvor\\nToma meu coração, dá-me o Teu perdão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, aviva Tua obra agora em mim\\nDá-me as palavras pra que eu fale de Ti.\\nVem habita meu ser com Tua graça e amor\\nQue eu esteja em Teus braços por onde for.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, aviva Tua obra agora em mim.\\nQue o mundo veja o meu amor por Ti\\nE que Te reconheçam como único Deus\\nE encontrem enfim salvação.\\nSenhor, aviva Tua obra em mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero, meu Senhor, falar do Teu amor\\nQuero testemunhar do que tens feito em mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, aviva Tua obra agora em mim\\nDá-me as palavras pra que eu fale de Ti.\\nVem habita meu ser com Tua graça e amor\\nQue eu esteja em Teus braços por onde for.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, aviva Tua obra agora em mim.\\nQue o mundo veja o meu amor por Ti\\nE que Te reconheçam como único Deus\\nE encontrem enfim salvação.\\nSenhor, aviva Tua obra em mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor, aviva Tua obra agora em mim.\"}]},{\"number\":\"2004-04\",\"collection_type\":\"Coletânea\",\"title\":\"Nossa Inspiração\",\"author\":\"Samuel Gravino Jr. / Silmar Correia\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Grande e lindo é o amor de Deus\\nQue um livro mui precioso nos deixou\\nSeus ensinos servem para nos lembrar\\nQue um dia lá no céu vamos morar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Bíblia é nossa inspiração\\nPalavra doce ao coração\\nÉ luz eterna de valor\\nÉ fonte de esperança e de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Curas e milagres de Jesus\\nA Bíblia tantas vezes nos mostrou\\nSempre nós devemos este livro amar\\nPois, muitas vidas pode transformar.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Bíblia é nossa inspiração\\nPalavra doce ao coração\\nÉ luz eterna de valor\\nÉ fonte de esperança e de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Bíblia é nossa inspiração\\nPalavra doce ao coração\\nÉ luz eterna de valor\\nÉ fonte de esperança e de amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"É fonte de esperança e de amor.\"}]},{\"number\":\"2004-05\",\"collection_type\":\"Coletânea\",\"title\":\"Amigos Pra Sempre\",\"author\":\"Cleiton Schaefer / Ronnye Dias\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nós estamos aqui neste mundo mas só de passagem\\nAguardando uma vida futura, uma vida melhor\\nQuando formos viver para sempre reunidos com Cristo\\nNum lugar lá no Céu onde só reinará a paz e o amor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Amigos pra sempre vamos ser\\nE o Espírito de Deus vai nos encher\\nUnidos a Jesus vamos caminhar\\nLá no Céu nós vamos juntos chegar.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Mulheres)\\nPrecisamos estar sempre juntos levando a Mensagem\\nTransmitindo essa fé às pessoas ao nosso redor\"},{\"section_type\":\"Estrofe\",\"content\":\"(Homens)\\nE usar para o bem a influência da nossa amizade\\nPra que todos unidos possamos fazer o mundo melhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Amigos pra sempre vamos ser\\nE o Espírito de Deus vai nos encher\\nUnidos a Jesus vamos caminhar\\nLá no Céu nós vamos juntos chegar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Amigos pra sempre vamos ser\\nE o Espírito de Deus vai nos encher\\nUnidos a Jesus vamos caminhar\\nLá no Céu nós vamos juntos chegar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Unidos a Jesus vamos caminhar\\nLá no céu nós vamos juntos chegar.\"}]},{\"number\":\"2004-06\",\"collection_type\":\"Coletânea\",\"title\":\"Vem Habitar em Nós\",\"author\":\"Itamir Rodrigues / Lineu Soares\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem Espírito Santo\\nHabita neste lugar\\nOnde vamos dar as mãos\\nNos unir para cantar e falar de amor\\nDo Teu imenso amor e adorar\\nSenhor, dá-nos a direção\\nSeguro estou em Tuas mãos\\nVem Senhor, vem habitar em nós\\nSenhor, contigo não temerei\\nTu és a vida, és meu Rei\\nVem Espírito Santo de Deus.\\nVem Espírito Santo\\nHabita neste lugar\\nOnde vamos dar as mãos\\nNos unir para cantar e falar de amor\\nDo Teu imenso amor e adorar\\nSenhor, dá-nos a direção\\nSeguro estou em Tuas mãos\\nVem Senhor, vem habitar em nós\\nSenhor, contigo não temerei\\nTu és a vida, és meu Rei\\nVem Espírito Santo de Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Espírito Santo de Deus.\"}]},{\"number\":\"2004-07\",\"collection_type\":\"Coletânea\",\"title\":\"Em um Só Coração\",\"author\":\"Marcelo Meireles e Udolcy Zukowski\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Um coração que está só\\nNão tem razão de existir\\nOs corações se procuram\\nSe abrem sorrindo\\nSe encontram no olhar\\nE apertos de mão.\"},{\"section_type\":\"Estrofe\",\"content\":\"É hora de dar as mãos\\nÉ tempo de união\\nNum só espírito e força\\nUnidos em Cristo, nós vamos viver\\nComo uma grande família\\nLigados pelo amor do Pai\\nEm um só Coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"É hora de dar as mãos\\nÉ tempo de união\\nNum só espírito e força\\nUnidos em Cristo, nós vamos viver\\nComo uma grande família\\nLigados pelo amor do Pai\"},{\"section_type\":\"Estrofe\",\"content\":\"Em um só Coração.\\nEm um só Coração.\\nEm um só Coração.\"}]},{\"number\":\"2004-08\",\"collection_type\":\"Coletânea\",\"title\":\"Queremos Ver Jesus Voltar\",\"author\":\"Jane Leitzke\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Um novo tempo começa a nascer\\nTempo de crer e de nada temer\\nMuitos se foram aguardando Jesus\\nMas muito em breve nós veremos Sua luz\\nPois os sinais mostram cada vez mais\\nQue triunfante vem em glória reinar\\nA esperança de então vê-Lo voltar\\nÉ o que motiva nosso caminhar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Queremos ver, queremos ver\\nCristo voltando em glória pra nos buscar.\\nQueremos ver, queremos ver\\nCristo voltando em glória pra nos buscar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mulheres\\nUm novo tempo começa a nascer\\nTempo de crer e de nada temer\\nMuitos se foram aguardando Jesus\\nMas muito em breve nós veremos Sua luz\"},{\"section_type\":\"Estrofe\",\"content\":\"Homens\\nPois os sinais mostram cada vez mais\\nQue triunfante vem em glória reinar\\nA esperança de então vê-Lo voltar\\nÉ o que motiva nosso caminhar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Queremos ver, queremos ver\\nCristo voltando em glória pra nos buscar.\\nQueremos ver, queremos ver\\nCristo voltando em glória pra nos buscar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Queremos ver, queremos ver\\nCristo voltando em glória pra nos buscar.\\nQueremos ver, queremos ver\\nCristo voltando em glória pra nos buscar.\\nCristo voltando em glória pra nos buscar.\"}]},{\"number\":\"2004-09\",\"collection_type\":\"Coletânea\",\"title\":\"Cheios do Espírito\",\"author\":\"Lineu Soares e Valdecir Lima\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Espírito de Deus nos guiará pela verdade\\nDizendo com clareza as coisas que virão\\nJesus em nossa vida vencerá a falsidade\\nNo mundo que se perde em meio à escuridão\"},{\"section_type\":\"Estrofe\",\"content\":\"Cheios do Espírito, cheios de poder\\nIremos proclamar a paz que vem da cruz\\nCheios do Espírito, cheios de poder\\nIremos anunciar a volta de Jesus\\nCheios do Espírito, cheios de poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Confiantes na riqueza da glória de Jesus\\nVivemos o poder de Seu Espírito em nós\\nAssim nós proclamamos Sua graça, eterna luz\\nAo mundo que tem fome de ouvir a Sua voz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cheios do Espírito, cheios de poder\\nIremos proclamar a paz que vem da cruz\\nCheios do Espírito, cheios de poder\\nIremos anunciar a volta de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Cheios do Espírito, cheios de poder\\nCheios do Espírito, cheios de poder.\"}]},{\"number\":\"2004-10\",\"collection_type\":\"Coletânea\",\"title\":\"Hino dos Aventureiros\",\"author\":\"Wanderson Paiva\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2004\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Somos Aventureiros alegres\\nQue confiam no amigo Jesus.\\nAprendemos que sempre devemos\\nSer pra todos um brilho da Luz.\\nDescobrimos em tudo a beleza,\\nE o amor de um Deus Criador.\\nE amando a Cristo faremos\\nMaravilhas ao nosso redor.\"}]},{\"number\":\"2005-01\",\"collection_type\":\"Coletânea\",\"title\":\"Fiel a Toda Prova\",\"author\":\"Jader Santos\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Paro pra pensar nos desafios deste meu viver.\\nParo pra ouvir o que a voz de Deus quer me dizer.\\nSão tantas as pressões que tenho que enfrentar;\\nMas bem acima delas sei que está meu Pai.\"},{\"section_type\":\"Coro\",\"content\":\"Quero ser fiel a toda prova;\\nFiel em qualquer tempo, qualquer hora.\\nQuero ser fiel no que é pouco\\nPara ser fiel no que é muito.\\nQuero ser fiel a toda prova,\\nNão por uma mera obrigação.\\nMas em resposta ao amor tão grande\\nQue um dia inundou meu coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Posso triunfar, conheço alguém que já venceu por mim.\\nPosso me apegar à forte mão de um Deus tão grande assim\\nEm meio à provação começo a louvar\\nE seu poder do alto vem me alcançar.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Final)\\nDeus Poderoso, Pai tão grandioso,\\nEnvie em meu axílio Seu anjo mais poderoso!\\nQuero ser fiel a toda prova,\\nNão por uma mera obrigação.\\nMas em resposta ao amor tão grande,\\nAo amor tão grande,\\nAo amor tão grande,\\nQue um dia inundou meu coração!\"}]},{\"number\":\"2005-02\",\"collection_type\":\"Coletânea\",\"title\":\"Fonte de Esperança\",\"author\":\"Marcelo Meireles\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu posso ver tanta gente que tem sede,\\nQuerem saber onde se encontra a Água Viva.\"},{\"section_type\":\"Coro\",\"content\":\"Oh, Senhor, pela tua graça quero ser fonte de esperança!\\nFonte de esperança quero ser,\\nSempre transbordando Teu poder\\nPra salvar do pecado,\\nPra guiar no Serviço;\\nFonte de esperança quero ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu posso ver tanta gente que tem fome,\\nQuerem saber onde se encontra o Pão da Vida.\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, Senhor, pela tua graça quero ser fonte de esperança!\\nFonte de esperança quero ser,\\nSempre transbordando Teu poder\\nPra salvar do pecado,\\nPra guiar no Serviço;\\nFonte de esperança quero ser.\"}]},{\"number\":\"2005-03\",\"collection_type\":\"Coletânea\",\"title\":\"Frágil Embarcação\",\"author\":\"Adalter Ferreira\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando a vida exige além Daquilo que eu posso dar;\\nQuando as lutas se transformam em batalhas.\\nE quando chego ao meu limite, E começo a naufragar,\\nEu logo chamo por Seu nome, Pois eu sei.\"},{\"section_type\":\"Coro\",\"content\":\"Em minha frágil embarcação Está o Senhor das ondas,\\nEstá o Senhor dos ventos, Está o Senhor do mar.\\nE quando não tiver mais forças\\nEle se levantará e, mais uma vez O mar vai se acalmar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quantas vezes já tentei Guiar sozinho a minha nau;\\nMas cada vez mais longe as ondas me levaram.\\nEm meio a cruel tormenta, Cristo estendeu sua mão\\nE logo veio a calmaria e paz.\"}]},{\"number\":\"2005-04\",\"collection_type\":\"Coletânea\",\"title\":\"Templo Vivo\",\"author\":\"Enoque Jr\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Habita oh, Senhor, em meu viver; Faz-me aprender o Teu querer.\\nEnche-me com Teu Espírito, Faz meu corpo um templo vivo\\nPra manifestar o Teu poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Moças)\\nHabita oh, Senhor, em meu viver; Faz-me aprender o Teu querer.\\n(Rapazes)\\nEnche-me com Teu Espírito, Faz meu corpo um templo vivo\\nPra manifestar o Teu poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Há um suave Espírito entre nós É do Espírito de Deus a doce voz\\nVejo em cada rosto o resplendor Da presença do Espírito do Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Habita oh, Senhor, em meu viver; Faz-me aprender o Teu querer.\\nEnche-me com Teu Espírito, Faz meu corpo um templo vivo\\nPra manifestar o Teu poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Enche-me com Teu Espírito, Faz meu corpo um templo vivo\\nPra manifestar o Teu poder. Pra manifestar o Teu poder.\"}]},{\"number\":\"2005-05\",\"collection_type\":\"Coletânea\",\"title\":\"Ser Amigo\",\"author\":\"Tarsis Iraides\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Moças)\\nQuanta coisa pra falar da gratidão que nós sentimos;\\nÉ tão forte que não há como explicar.\\nSão momentos que passamos lado a lado no viver.\\nSão momentos que não voltam nunca mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Rapazes)\\nForam tantas emoções que repartimos como amigos;\\nMas somente os bons momentos vão ficar.\\nSendo assim um novo dia, um futuro irá nascer\"},{\"section_type\":\"Estrofe\",\"content\":\"(Todos)\\nSe unirmos nossas mãos ao caminhar.\"},{\"section_type\":\"Coro\",\"content\":\"Ser amigo é repartir dos bons momentos a certeza,\\nQue existe amor em cada intenção.\\nÉ viver intensamente a chama viva da esperança;\\nÉ deixar falar a voz do coração.\\n(Final) É deixar falar a voz do coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Rapazes)\\nMuita coisa em nossa vida certamente vai mudar,\\nNos momentos que passamos no viver.\\nLindos dias doces sonhos ficarão pra compensar,\\nSe a saudade um dia em nós acontecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Moças)\\nHoje é o tempo de firmar os nossos sonhos alcançados,\\nSem contudo esquecer o que passou.\\nRenovados para a vida refletindo a paz do céu\"},{\"section_type\":\"Estrofe\",\"content\":\"(Todos)\\nVamos juntos transformados pelo amor.\"}]},{\"number\":\"2005-06\",\"collection_type\":\"Coletânea\",\"title\":\"Pés na Terra, Olhos no Céu\",\"author\":\"Jader Santos\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nós almejamos outro lar, um novo Éden pra morar,\\nPois ficaremos por aqui somente um pouco mais.\\nEsta promessa quero alcançar custe o que custar\\nE enquanto espero sigo confiando\\nNo poder que vai me salvar,\"},{\"section_type\":\"Coro\",\"content\":\"Com os pés na Terra e os olhos no céu eu vou, eu vou,\\nCom os pés na Terra e os olhos no céu\\nEu vou seguindo até encontrar meu Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Um novo dia surgirá quando Jesus aqui voltar.\\nTodo o pranto findará, só alegria haverá.\\nNão mais tristeza, não mais a dor; Lá reinará o amor.\\nFinalmente verei e adorarei o meu Rei e meu Salvador.\"}]},{\"number\":\"2005-07\",\"collection_type\":\"Coletânea\",\"title\":\"Sempre de Jesus\",\"author\":\"Wanderson Paiva\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ser sempre de Jesus. Eu levarei ao mundo Sua luz.\\nEm todo o tempo e em qualquer lugar Com meu Jesus eu quero sempre estar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ser fiel ao meu Jesus. Eu mostrarei ao mundo minha luz.\\nEm todo o tempo e em qualquer lugar Com meu Jesus eu quero sempre estar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sempre de Jesus, Sempre com meu Jesus,\\nEm todo o tempo e em qualquer lugar\\nCom meu Jesus eu quero sempre estar.\"}]},{\"number\":\"2005-08\",\"collection_type\":\"Coletânea\",\"title\":\"Encontros\",\"author\":\"Wanderson Paiva\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"É tão bom encontrar os amigos, rever os irmãos;\\nE sentir a amizade e o amor que nos traz união;\\nÉ tão bom partilhar este amor com você cada dia,\\nVamos juntos cantar demonstrando a nossa alegria.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Moças) É tão bom encontrar os amigos, rever os irmãos;\"},{\"section_type\":\"Estrofe\",\"content\":\"(Rapazes) É tão bom encontrar os amigos, rever os irmãos;\"},{\"section_type\":\"Estrofe\",\"content\":\"(Moças) E sentir a amizade e o amor que nos traz união;\"},{\"section_type\":\"Estrofe\",\"content\":\"(Rapazes) nos traz união;\"},{\"section_type\":\"Estrofe\",\"content\":\"(Todos) É tão bom partilhar este amor com você cada dia,\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos juntos cantar demonstrando a nossa alegria.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Rapazes) É tão bom encontrar os amigos, rever os irmãos;\"},{\"section_type\":\"Estrofe\",\"content\":\"(Moças) É tão bom encontrar os amigos, rever os irmãos;\"},{\"section_type\":\"Estrofe\",\"content\":\"(Rapazes) E sentir a amizade e o amor que nos traz união;\"},{\"section_type\":\"Estrofe\",\"content\":\"(Moças) nos traz união;\"},{\"section_type\":\"Estrofe\",\"content\":\"(Todos 2x) É tão bom partilhar este amor com você cada dia,\\nVamos juntos cantar demonstrando a nossa alegria\"}]},{\"number\":\"2005-09\",\"collection_type\":\"Coletânea\",\"title\":\"Vive Em Mim\",\"author\":\"Silmar Correa\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, quero agora Te pedir pra limpar Meu coração com Tua graça.\\nPai, faze dele um bom lugar Pra que possas habitar com Tua glória.\"},{\"section_type\":\"Coro\",\"content\":\"Vem usar-me cada dia para o Teu louvor; Que Tua paz viva em mim.\\nTens o trono do meu ser, minha vida, meu prazer; Pai, vive em mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"(Final) Pai, vive em mim.\\n(Moças) Pai, vem encher meu coração Com a luz do teu amor infinito.\\n(Rapazes) Sei que meus olhos vão mostrar A alegria de nós sermos amigos.\"},{\"section_type\":\"Estrofe\",\"content\":\"Teu nome quero sempre adorar; És meu Rei e eterno Senhor\\nFeliz vou Te exaltar, e ao mundo revelar Que Tu vives em mim.\"}]},{\"number\":\"2005-10\",\"collection_type\":\"Coletânea\",\"title\":\"Hino dos Desbravadores\",\"author\":\"Henry T. Bergh\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2005\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nós somos os Desbravadores Os servos do Rei dos reis\\nSempre avante assim marchamos Fiéis às Suas leis.\\nDevemos ao mundo anunciar As novas da salvação\\nQue Cristo virá em breve dar o galardão.\"}]},{\"number\":\"2006-01\",\"collection_type\":\"Coletânea\",\"title\":\"Eu te Louvarei, Senhor\",\"author\":\"Williams Costa Jr\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu te louvarei Senhor, de todo o coração.\\nCantarei a minha adoração.\\nEu te louvarei Senhor, com toda devoção.\\nCantarei em Tua adoração.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Ti toda honra, Rei do universo.\\nA Ti toda glória, Criador da Natureza.\\nA Ti todo o nosso louvor para todo o sempre\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu te louvarei, Senhor de todo o coração.\\nCantarei a minha adoração.\\nEu te louvarei, Senhor, com toda devoção.\\nCantarei em Tua adoração.\"},{\"section_type\":\"Estrofe\",\"content\":\"A Ti toda honra, Rei do universo.\\nA Ti toda glória, Criador da Natureza.\\nA Ti todo o nosso louvor para todo o sempre\\nEu te louvarei Senhor (4X)\"}]},{\"number\":\"2006-02\",\"collection_type\":\"Coletânea\",\"title\":\"Sou de Jesus\",\"author\":\"Kátia Rocha / Társis Iraídes\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dois caminhos a seguir, dois senhores a lutar.\\nQual dos dois irei servir? Há só uma decisão.\\nQuantas vezes procurei os prazeres deste mundo,\\nEncontrei mil motivos pra chorar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O inimigo sempre vem, disfarçando as intenções.\\nCom ciladas ao redor ele quer me destruir.\\nSó Jesus pode me dar a real felicidade\\nE poder para ser um vencedor.\"},{\"section_type\":\"Coro\",\"content\":\"Sou de Jesus, o Senhor da vitória,\\nO alimento a vida, Rocha Eterna da salvação.\\nSeu amor me atraiu, deu-me paz e alegria.\\nEu já fiz minha escolha: Sou de Jesus. /2x\"},{\"section_type\":\"Estrofe\",\"content\":\"Decidi testemunhar mesmo em forte provação.\\nRejeitando pela fé o pecado e seu sabor.\\nNo caminho de Jesus estarei sempre seguro,\\nE assim, eu prossigo rumo ao Céu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mais do que em qualquer outro tempo,\\nO momento é de escolher.\\nSem temer nem hesitar, eu escolho Jesus.\"}]},{\"number\":\"2006-03\",\"collection_type\":\"Coletânea\",\"title\":\"Sempre Confiante\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando a minha esperança acabar\\nQuando o sol pra mim não brilhar\\nEu só preciso a Jesus recorrer\\nPois dEle me vem o poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Deus vou sempre confiante\\nVou avante pra vencer\\nEm Deus vou sempre confiante\\nVou sem mais temer\"},{\"section_type\":\"Estrofe\",\"content\":\"O que vai no futuro eu não sei\\nO caminho que vou passar\\nMas sei que Ele sempre vai me guiar\\nE sei que seguro estarei\"},{\"section_type\":\"Estrofe\",\"content\":\"E por isso vamos cantar\\nTodos juntos nos alegrar\\nPois nosso Deus é poderoso Senhor\\nE guarda Seus filhos co’amor\"}]},{\"number\":\"2006-04\",\"collection_type\":\"Coletânea\",\"title\":\"Mensageiro\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tem dias que nem sei dizer,\\nNão tenho motivação.\\nEu sinto em mim uma dor sem fim,\\nNão sei dizer a razão.\\nConsigo ainda, Jesus buscar,\\nOs meus joelhos dobrar e orar\\nPerante Deus, me inclinar, chorar.\\nE abrir o meu coração E abrir o meu coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Já posso ver o sol brilhar, O vento a paz vem soprar.\\nSem excitar, irei sair, De meu Jesus vou falar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sou mensageiro do Rei Senhor,\\nSou testemunha do seu amor\\nAo mundo inteiro vou proclamar,\"},{\"section_type\":\"Estrofe\",\"content\":\"Que Jesus vai aqui voltar Que Jesus vai aqui voltar\\nRepete 3x a estrofe\\nQue Jesus vai aqui voltar\\nLogo vai voltar\"}]},{\"number\":\"2006-05\",\"collection_type\":\"Coletânea\",\"title\":\"É Motivo de Alegria\",\"author\":\"Williams Costa Jr\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"É motivo de alegria ter a sua companhia,\\nComo é bom lhe ver, Muito prazer em lhe conhecer,\\nPosso lhe abraçar? Porque você é a razão do meu cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"É motivo de alegria ter a sua companhia,\\nComo é bom lhe ver, Muito prazer em lhe encontrar,\\nPosso lhe abraçar? Porque você é a razão do meu cantar.\"},{\"section_type\":\"Estrofe\",\"content\":\"É motivo de alegria ter Jesus por companhia,\\nÉ muito bom saber, que agora posso Te encontrar.\\nQuero Te receber. Porque Tu és a razão do meu cantar.\"}]},{\"number\":\"2006-06\",\"collection_type\":\"Coletânea\",\"title\":\"Falar com Deus\",\"author\":\"Lineu Soares\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Na oração encontro calma\\nNa oração encontro paz\\nOrar a Deus faz bem a alma\\nFalar com Deus me satisfaz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Falar com Deus que privilégio\\nAbrir a alma ao Criador\\nSentir que os céus estão abertos\\nE ouvir a voz do Salvador.\"},{\"section_type\":\"Estrofe\",\"content\":\"Grande é o nosso Deus\\nE as obras que Ele faz\\nO Seu perdão me dá conforto\\nE em Seu amor encontro paz\"},{\"section_type\":\"Estrofe\",\"content\":\"Falar com Deus é o que mais quero\\nPois Ele é fonte de poder\\nSó nEle a vida faz sentido\\nPois me dá forças pra viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X) Grande é o nosso Deus\\nE as obras que Ele faz\\nO Seu perdão me dá conforto\\nE em Seu amor encontro paz\"},{\"section_type\":\"Estrofe\",\"content\":\"Na oração encontro calma\\nNa oração encontro paz\\n(2X) Orar a Deus faz bem a alma\\nFalar com Deus me satisfaz.\\nFalar com Deus me satisfaz.\"}]},{\"number\":\"2006-07\",\"collection_type\":\"Coletânea\",\"title\":\"Sal da Terra\",\"author\":\"Edson Romero Merques / Lineu Formighieri Soares\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Jesus nos deu esta missão:\\nO Seu amor compartilhar.\\nSomente entraremos em ação\\nSe o amor de Deus nos motivar.\"},{\"section_type\":\"Estrofe\",\"content\":\"O seu poder nos moverá,\\nE assim iremos repartir\\nO amor de Deus, a verdadeira paz\\nE a doce esperança no porvir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vós sois o sal da terra;\\nVós sois o sal da terra,\\nRestaurando o sabor\\nE a alegria de viver\\nVós sois o sal da terra.\"},{\"section_type\":\"Estrofe\",\"content\":\"A vida que Jesus viveu,\\nO exemplo que Ele nos deixou,\\nDemonstram o real sentido\\nDa missão que o Senhor nos confiou.\"},{\"section_type\":\"Estrofe\",\"content\":\"Saber a todos perdoar,\\nQuerer a todos aceitar,\\nRevela a grandeza do serviço\\nE aponta para o Salvador.\"}]},{\"number\":\"2006-08\",\"collection_type\":\"Coletânea\",\"title\":\"Real Felicidade\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando tudo está perdido\\nE os teus sonhos se ruíram\\nQuando tudo ao teu redor\\nNão te faz mais feliz\\nOlhe então para Cristo\\nPra deixá-Lo entrar em teu ser\\nE verás que suas dores e tristezas passarão\"},{\"section_type\":\"Estrofe\",\"content\":\"Pois só Cristo trás a real felicidade\\nEle quer mostrar que ao Seu lado tudo é paz\\nNão demores mais; Não demores mais\\nPra teu coração a Deus entregar\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo apenas te espera\\nPra te dar eterno amor\\nDeixa o Espírito de Deus\\nTe encher do Seu poder.\"},{\"section_type\":\"Estrofe\",\"content\":\"Logo Ele irá voltar\\nE Sua face então verás\\nPor que esperar mais tempo\\nPara alegria e paz gozar\"},{\"section_type\":\"Estrofe\",\"content\":\"(2X ) Pois só Cristo trás a real felicidade\\nEle quer mostrar que ao Seu lado tudo é paz\\nNão demores mais; Não demores mais.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pra teu coração a Deus entregar.\"}]},{\"number\":\"2006-09\",\"collection_type\":\"Coletânea\",\"title\":\"Nossa Missão\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O caminho da cruz, de amor e perdão,\\nTrouxe ao mundo uma luz de glória e salvação.\\nEsse amor que salvou, quer ao mundo anunciar\\nQue um lar preparou para com todos morar.\"},{\"section_type\":\"Estrofe\",\"content\":\"É a nossa missão ir ao mundo falar.\\nCristo está voltando Ele vem nos buscar\\nVamos em união este tempo apressar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jovens pelos jovens, jovens pela igreja,\\nJovens pelos seus semelhantes.\\nÉ a nossa missão ir ao mundo falar.\\nCristo está voltando. Ele vem nos buscar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos em união, este tempo apressar.\\nJovens pelos jovens, jovens pela igreja,\\nJovens pelos seus semelhantes.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jovens pelos jovens, jovens pela igreja,\\nJovens pelos seus semelhantes.\"}]},{\"number\":\"2006-10\",\"collection_type\":\"Coletânea\",\"title\":\"Hino do Líder\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2006\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Somos Jovens Adventistas destemidos, motivados com poder.\\nLiderando a juventude que deseja ser fiel e a Jesus seguir.\\nAnunciando a mensagem às pessoas e falando ao coração;\\nque os pecados podem ser todos vencidos, por Jesus que o céu nos dará.\"}]},{\"number\":\"2007-01\",\"collection_type\":\"Coletânea\",\"title\":\"Vem Brilhar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Como o brilho do Sol não se apaga\\nTua glória e amor nunca tem fim\\nComo a lua está iluminada\\nEu te peço Senhor vem brilhar em mim\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem brilhar no meu coração\\nVem brilhar em mim com o teu resplendor\\nÉs o Sol que traz calor\\nNasce em mim com Teu amor\\nVem Jesus brilhar em mim\"},{\"section_type\":\"Estrofe\",\"content\":\"Como a linda manhã que se renova\\nTua presença em mim eu quero ter\"},{\"section_type\":\"Estrofe\",\"content\":\"Com o meu coração peço-te agora\\nDá-me vida e luz pra alegrar meu viver\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem brilhar no meu coração\\nVem brilha em mim com o Teu resplendor\\nÉs o Sol que traz calor\\nNasce em mim com Teu amor\\nVem Jesus brilhar em mim\"},{\"section_type\":\"Estrofe\",\"content\":\"Como o brilho do Sol nunca se apaga\\nO Teu perdão não tem fim\\nO Teu poder é infinito\\nVem Jesus birlhar em mim\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem brilhar no meu coração\\nVem brilha em mim com o Teu resplendor\\nÉs o Sol que traz calor\\nNasce em mim com Teu amor\\nVem Jesus brilhar em mim\\nVem Jesus brilhar em mim\"},{\"section_type\":\"Estrofe\",\"content\":\"(mulheres)\\nComo o brilho do Sol não se apaga\\n(homens)\\nTua glória e amor nunca tem fim\"},{\"section_type\":\"Estrofe\",\"content\":\"(Todos)\\nComo a lua está iluminada eu te peço Senhor\\nVem brilhar em mim\"}]},{\"number\":\"2007-02\",\"collection_type\":\"Coletânea\",\"title\":\"Vencedor cada dia\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há caminhos que parecem ideias pra se seguir\\nHá projetos que parecem ser de Deus\\nDesde quanto me levanto até quando vou dormir\\nSou provado, tenho escolhas a fazer\"},{\"section_type\":\"Estrofe\",\"content\":\"Cada dia que eu vivo é um milagre singular,\\nmas também tenho lutas pra enfrentar\\nEu te peço Senhor que eu aprenda mais de Ti\\nPara ser cada dia vencedor\"},{\"section_type\":\"Coro\",\"content\":\"Eu me entrego a Ti, Senhor\\nEm oração aqui estou\\npra pedir que não me deixes pecar contra Ti\\nCom Teu amor em minha mente\\nque eu te obedeça humildemente\"},{\"section_type\":\"Estrofe\",\"content\":\"(moças)\\nPara todos que me ouvirem testemunha eu serei\\nVou mostrar-lhes o caminho até Jesus\\n(rapazes)\\nÉ um passo de fé entregar-se a esse Deus\\nPra ganhar liberdade pra vencer\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu nada tenho em mim mesmo\\nPreciso crer e confiar\\nAlimentar-me da Palavra\\nJamais deixar de orar\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu me entrego a Ti, Senhor\\nEm oração aqui estou\\npra pedir que não me deixes pecar contra Ti\\nCom Teu amor em minha mente\\nque eu te obedeça humildemente\"},{\"section_type\":\"Estrofe\",\"content\":\"(moças)\\nCada dia\\n(rapazes)\\nPor Tua graça\\n(todos)\\nAté Tua volta\\nVencedor eu serei\"}]},{\"number\":\"2007-03\",\"collection_type\":\"Coletânea\",\"title\":\"Deus Não Se cansa de Amar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando andamos pela vida sem destino ou direção\\nQuando faltam os amigos, auto-estima e emoção\\nDeus nos chama pelo nome\\nEle vê nosso cansaço\\nQuer nos devolver a paz\\nE quer de volta nosso abraço\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus não se cansa de amar\\nDeus não se cansa de amar\\nDeus ampara Seus filhos, paz à alma quer dar\\nPra curar as feridas que ainda estão por fechar\\nE se estamos cansados de cair e falhar\\nDeus nos toma em Seus braços, não se cansa de amar\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus não se cansa de amar\\nDeus não se cansa de amar\\nDeus não se cansa de amar\"},{\"section_type\":\"Estrofe\",\"content\":\"(moças)\\nDeus comprou-nos com Seus sangue\\nDeus conhece nossa dor\\nSe este undo nos maltrata em Seus braços há amor\\n(rapazes)\\nSua graça é infinita\\nNEle está a salvação\\n(todos)\\nSe são grandes nossas quedas\\nBem maior é o Seu perdão\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é nossa esperança\\nNuma cruz por nós morreu\\nPra ter sempre ao Seu lado\\nquem um dia se perdeu\\nEle o ama pessoalmente, é o Cordeiro de Deus\\nSe Ele tira os pecados do mundo\\nEle vai tirar os seus\"},{\"section_type\":\"Estrofe\",\"content\":\"(rapazes)\\nDeus não se cansa de amar\\n(moças)\\nDeus não se cansa de amar\\n(todos)\\nDeus ampara Seus filhos, paz à alma quer dar\\npra curar as feridas que ainda estão por fechar\\nE se estamos cansado de cair e falhar\\nDeus nos toma em Seus braços, não se cansa de amar\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus não se cansa de amar\\nDeus não se cansa de amar\\nDeus não se cansa de amar\"}]},{\"number\":\"2007-04\",\"collection_type\":\"Coletânea\",\"title\":\"Quero ver Cristo Voltar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Muitos se apressaram em pregar\\nMuitos só viveram a esperar\\nO tempo passou e Cristo não retornou\\nmas logo veremos esse dia chegar\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero ver Cristo voltar em glória\\nQuero cantar hinos de vitória\\nPoderei finalmente contemplar a Sua face\\nEu quero estar com o povo santo\\nPor esse dia espero tanto\\nSubirei como s anjos para o encontro com o meu Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"(rapazes)\\nVamos essa obra terminar\\nE em seguida Cristo voltará\\n(moças)\\nA nossa geração em um só coração\\nQuer ver o raiar de um novo dia chegar\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero ver Cristo voltar em glória\\nQuero cantar hinos de vitória\\nPoderei finalmente contemplar a Sua face\\nEu quero estar com o povo santo\\nPor esse dia espero tanto\\nSubirei como s anjos para o encontro com o meu Senhor (2x)\"}]},{\"number\":\"2007-05\",\"collection_type\":\"Coletânea\",\"title\":\"Quando Eu Olho Pra Você\",\"author\":\"Willians Costa Jr\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando eu olho pra você eu me lembro\\nQue Deus criou você e amou você,\\nÉ por isso que você se parece com Deus,\\nPor dentro e por fora, a toda hora.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando eu olho pra você eu me lembro\\nQue Deus é o Pai do Céu que nos criou,\\nÉ por isso que você se parece comigo,\\nÉ meu irmão, é meu irmão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Você vale o sangue de Cristo;\\nVocê é a glória de Deus.\\nVocê é a grande esperança\\nDe mostrar pra o Universo que o amor de Jesus valeu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando eu olho pra você eu me lembro\\nQue Deus criou você e amou você,\\nÉ por isso que você se parece com Deus,\\nPor dentro e por fora, a toda hora.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando eu olho pra você eu me lembro\\nQue Deus é o Pai do céu que nos criou,\\nÉ por isso que você se parece comigo,\\nÉ meu irmão, é meu irmão.\"},{\"section_type\":\"Estrofe\",\"content\":\"É por isso que você se parece comigo,\\nÉ meu irmão, é meu irmão.\"}]},{\"number\":\"2007-06\",\"collection_type\":\"Coletânea\",\"title\":\"Inteiramente Fiel\",\"author\":\"Evaldo Vicente\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não vou mais pensar no que passou ou deu errado.\\nAquilo que Deus começou irá crescer, pois tem o Seu cuidado.\\nQuem tanto me amou, merece de mim a entrega do meu melhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sou inteiramente de Cristo Jesus.\\nFui feito pra viver como filho do Rei.\\nSou eternamente ligado a Jesus, pra sempre serei.\\nInteiramente fiel eu quero ser.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sei de um lugar que está além do que é comum.\\nA vida que exixte lá não vai ter fim, por causa de Jesus.\\nQuem tanto me amou merece de mim\\nA entrega do meu melhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Sou inteiramente de Cristo Jesus.\\nFui feito pra viver como filho do Rei.\\nSou eternamente ligado a Jesus, pra sempre serei.\\nInteiramente fiel, inteiramente fiel,\\nInteiramente fiel eu quero ser\"}]},{\"number\":\"2007-07\",\"collection_type\":\"Coletânea\",\"title\":\"Pode cair o mundo... estou em paz\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O mundo corre em busca de sucesso, e a vida em tanta guerra se desfaz.\\nO homem sonha as glórias do progresso, mas anda velozmente para trás.\\nSó Deus concede a glória verdadeira, só nEle a vida tem real valor.\\nÉ Ele quem promete um mundo novo, sem medo, sem tristeza e sem rancor.\"},{\"section_type\":\"Coro\",\"content\":\"A glória desta terra é passageira,\\nA vida passa, e tudo que ela traz.\\nNão temo o futuro, pois tenho Deus comigo,\\nPode cair o mundo, estou em paz (Bis no final)\"},{\"section_type\":\"Estrofe\",\"content\":\"Entrega teu caminho ao Senhor, confia nEle e o mais Ele fará.\\nÉ esse o sucesso verdadeiro, estar no mundo, mais em Deus confiar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Na batalha contra o mal, Cristo é o grande vencedor.\\nEle é o nosso general, Ele é o nosso Salvador\"}]},{\"number\":\"2007-08\",\"collection_type\":\"Coletânea\",\"title\":\"Salvar do Pecado\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Moças\\nMuitos vivem sem saber que existe um Deus\\nSem saber que existe salvação\"},{\"section_type\":\"Estrofe\",\"content\":\"Rapazes\\nSe eu posso ajudar o amor de Cristo levar\\nPra que então tempo perder\"},{\"section_type\":\"Coro\",\"content\":\"Vou salvar do pecado e guiar no serviço.\\nVou buscar meu amigo e levá-lo a Cristo,\\nNão há tempo a perder, vou ao mundo dizer\\nSalvação, vida e paz só Jesus pode dar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Rapazes\\nMeu amigo quero agora te ajudar\\nTe mostrando o caminho a seguir\"},{\"section_type\":\"Estrofe\",\"content\":\"Moças\\nTua vida vai mudar quando a Cristo encontrares.\"},{\"section_type\":\"Estrofe\",\"content\":\"Todos\\nVem logo então O aceitar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não importa o preço a pagar e as lutas que vou enfrentar\\nVou buscar meu amigo e levá-lo a Cristo\\nVou mostrar que Jesus o liberta do mal\"}]},{\"number\":\"2007-09\",\"collection_type\":\"Coletânea\",\"title\":\"Descobrindo Amigos\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"É bom viver é bom sonhar\\nÉ bom ter algo pra contar\\nÉ bom sair e procurar melhor ainda é encontrar\\nUm novo endereço uma nova emoção\\nTalvez o começo de uma outra estação\\nCom sol ou chuva vamos viver\"},{\"section_type\":\"Coro\",\"content\":\"Descobrindo amigos, estendendo a mão.\\nAbrindo sem reservas as portas do coração.\\nMandando embora ao medo ou qualquer sentimento.\\nQue roube a magia desse grande momento.\\nEu quero ver sorrisos aonde quer que eu olhar.\\nEu quero receber abraços e abraçar.\\nQue tal me conceder um pouco da sua luz\\nQue tal nos espelharmos no amigo Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Moças\\nÀs vezes basta só pedir, nem é preciso insistir.\\nPra receber, pra repartir.\\nE achar alguém que queira ouvir\\nRapazes\\nSe agente coloca o amor em ação\\nDe fato aprendemos o que é ser um cristão\\nCom sol ou chuva, vamos viver\"}]},{\"number\":\"2007-10\",\"collection_type\":\"Coletânea\",\"title\":\"Volta\",\"author\":\"Letra: Leonardo Gosalves\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2007\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Desde quando eu era criança, ouvir falar de um Deus\\nQue abriu o Mar Vermelho, lutava pelos Seus,\\nCotra feras e gigantes, reinos e nações.\\nE, eu me encantava cantando Suas conções.\"},{\"section_type\":\"Estrofe\",\"content\":\"Mas o tempo foi passando e não quis ouvir,\\nPreferi seguir meus rumos, tentei de Deus fugir.\\nMas, no final do meu caminho, não conseguia mais andar\\nEu senti Sua prensensa convidando-me a voltar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor quero me entregar.\\nNos Teus cminhos quero andar,\\nE segurar a Tua mão, e receber o Teu perdão.\\nE quero ser a voz que ouvia em minha infância.\\nE vou cantar que não a distâcia\\nQue Te possa afastar.\"},{\"section_type\":\"Estrofe\",\"content\":\"E pra quem estiver cansado, sofre de solidão,\\nPra tua vida fracassada, meu Deus é solução.\\nPois deixou as Suas ovelhas para vir te procurar.\\nE, se sentes Sua presença, por que hoje não cantar?\"},{\"section_type\":\"Estrofe\",\"content\":\"Senhor quero me entregar.\\nNos Teus caminhos quero andar,\\nE segurar a Tua mão, e receber o Teu perdão.\\nE quero ser a voz que ouvia em minha infância.\\nE vou cantar que não a distâcia\\nQue Te possa afastar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Que não importa a distância, Ele vai te alcançar.\"}]},{\"number\":\"2008-01\",\"collection_type\":\"Coletânea\",\"title\":\"Cada Dia Mais Perto\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando o mundo chega ao fim de sua história\\nJá sem brilho, sem beleza e sem luz\\nNossa vida já aguarda a nova glória,\\nA esperança está na volta de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"A tristeza se transforma em alegria,\\nAo sentir que vem do céu a eterna luz\\nCada dia bem mais perto desse dia,\\nCada dia bem mais perto de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Quanto almejo ver Jesus naquele dia,\\nPai querido, Rei eterno, Salvador\\nToda luz que sua face irradia,\\nMostra ao mundo o poder do seu amor\"},{\"section_type\":\"Estrofe\",\"content\":\"A tristeza se transforma em alegria,\\nao sentir que vem do céu a eterna luz\\nCada dia bem mais perto desse dia,\\nCada dia bem mais perto de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"A tristeza se transforma em alegria,\\nAo sentir que vem do céu a eterna luz\\nCada dia bem mais perto desse dia,\\nCada dia bem mais perto de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"A esperança está na volta de Jesus\"}]},{\"number\":\"2008-02\",\"collection_type\":\"Coletânea\",\"title\":\"Vivo Por Jesus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quero falar de esperança e paz em seu coração\\nQuero cantar com alegria esta canção\\nQuero contigo poder repartir a luz que ilumina meu ser\\nA alegria de estar com Jesus com Ele viver\"},{\"section_type\":\"Estrofe\",\"content\":\"Vou sorrir vou cantar hoje eu Vivo por Jesus\\nVou falar de amor, hoje eu vivo por Jesus\\nMinha vida, é Jesus,\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero falar da amizade da benção que é ser um irmão\\nDa comunhão de orar e buscar em adoração\\nQuero contigo poder repartir a luz que ilumina meu ser\\nA alegria de estar com Jesus com Ele Viver\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro 2 vezes)\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu Vivo por Jesus\"}]},{\"number\":\"2008-03\",\"collection_type\":\"Coletânea\",\"title\":\"Vinde às Águas\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Todos vós que tendes sede, vinde às Águas\\nE quem já se sente perdido, vindo tomar e bebei\\nE inclinem seus ouvidos, e vossa alma viverá\\nA quem estiver com sede, vinde ás Águas\"},{\"section_type\":\"Estrofe\",\"content\":\"Buscai ao Senhor, enquanto se pode achar\\nInvocai-o o seu nome, enquanto perto Ele está\\nDeixe o ímpio o seu caminho\\nDeixe o homem seus pensamentos maus\\nE volte pro Senhor\"}]},{\"number\":\"2008-04\",\"collection_type\":\"Coletânea\",\"title\":\"Coragem Pra Vencer\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"É preciso coragem é preciso coragem\\nO inimigo vira me tentar\\nÉ preciso coragem é preciso coragem\\nCom Jesus eu vou ficar\"},{\"section_type\":\"Estrofe\",\"content\":\"Coragem pra vencer, enfrentar o mal\\nCoragem pra vencer ir ate o final\\nCoragem pra vencer, Com Jesus eu vou\\nOrar lutar, vencer\"},{\"section_type\":\"Estrofe\",\"content\":\"Vou andando com Ele, vou andando com ele\\nHá vitória para quem persistir\\nVou andando com Ele, vou andando com Ele,\\nPara o céu eu quero ir\"},{\"section_type\":\"Estrofe\",\"content\":\"(Coro 3 x )\"},{\"section_type\":\"Estrofe\",\"content\":\"Coragem pra vencer\"}]},{\"number\":\"2008-05\",\"collection_type\":\"Coletânea\",\"title\":\"Descansar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu não quero viver pensando no amanhã\\neu quero ser feliz\\nDias vem e vão não irei temer,\\nposso confiar em Ti\\nSe o futuro incerto é, basta olhar com os olhos da fé\\nE descansar nos braços do Pai\"},{\"section_type\":\"Estrofe\",\"content\":\"Descansar, confiando em Tua proteção\\nDescansar, vou me entregar em tuas mãos\\nDescansar sei que cuidará de mim Senhor,\\nEnsina-me a descansar\"},{\"section_type\":\"Estrofe\",\"content\":\"Cada passo que eu der seja aonde estiver\\nQuero entregar a Ti\\nCada decisão vou depor em Tuas mãos e esperar\\nSe das aves Deus cuida\\nSei que tenho muito mais valor\\nPosso esperar e descansar nos braços do Pai\"},{\"section_type\":\"Estrofe\",\"content\":\"Descansar, confiando em Tua proteção\\nDescansar, vou me entregar em tuas mãos\\nDescansar sei que cuidará de mim Senhor,\\nEnsina-me a descansar\"},{\"section_type\":\"Estrofe\",\"content\":\"Só em Teus braços encontro paz pra repousar\\nMesmo que os temores me vençam, vou descansar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Confiando em Tua proteção\\nVou me entregar em tuas mãos\\nSei que cuidará de mim Senhor\\nEnsina-me a descansar\"}]},{\"number\":\"2008-06\",\"collection_type\":\"Coletânea\",\"title\":\"Tua Palavra\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Escondi a tua palavra no meu coração\\nPra não pecar contra Ti\\nEscondi as Tuas preciosas verdades dentro de mim\\nEu não quero falhar,\\nEu não quero jamais entristecer meu Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Tua palavra é luz, Tua palavra é paz\\nTua palavra e vida ao meu coração\\nPor isso em meu viver eu quero compreender,\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero aceitar em mim o Teu querer\\nVem ajudar-me ó Deus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Decidi obedecer Senhor em qualquer situação\\nSe Tu vais ser comigo\\nDecidi que quero de hoje em diante ser sempre Teu\\nEu não quero falhar, eu não quero jamais entristecer meu Jesus\"}]},{\"number\":\"2008-07\",\"collection_type\":\"Coletânea\",\"title\":\"Está na Hora\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Está na hora, a minha redenção já não demora\\nO mal que fere a alma vai sumir\\nEstá na hora, quero ver o céu se abrir\"},{\"section_type\":\"Estrofe\",\"content\":\"Está na hora, sinais do fim, me avisam é agora,\\nA minha fé vai se concretizar\\nEstá na hora quero ver Jesus voltar\"},{\"section_type\":\"Estrofe\",\"content\":\"Está na hora, de aquecer o coração e amar o meu irmão.\\nComo eu amo a mim mesmo\\nEstá na hora, de viver a pregação e sair da mornidão\\nPor Jesus intensamente me apaixonar\\nEstar pronto para quando Ele voltar\"},{\"section_type\":\"Estrofe\",\"content\":\"Está na Hora\"}]},{\"number\":\"2008-08\",\"collection_type\":\"Coletânea\",\"title\":\"Você Pode Ter Amigos\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Você pode ter amigos, se quiser,\\nBasta dar o seu sorriso se quiser\\nBasta abrir seu coração\\nE assim sem mais aviso eles virão\"},{\"section_type\":\"Estrofe\",\"content\":\"Você pode ter amigos como irmãos,\\nBasta apenas um sorriso e atenção,\\nPra buscá-los onde estão\\nE assim sem mais aviso eles virão\"},{\"section_type\":\"Estrofe\",\"content\":\"Se você quer ter amigos,\\nNão se esqueça de cantar,\\nNão se esqueça do abraço de abrir seu coração,\\nNão esqueça de amar\"},{\"section_type\":\"Estrofe\",\"content\":\"Você pode ter amigos como irmãos,\\nBasta apenas um sorriso e atenção,\\nPra buscá-los onde estão e assim,\\nSem mais aviso eles virão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se você quer ter amigos,\\nE deixar de ser comum\\nVocê pode ter amigos e deixar de ser comum,\\nMuito simples seja um\"},{\"section_type\":\"Estrofe\",\"content\":\"Você pode ter amigos como irmãos,\\nBasta apenas um sorriso e atenção,\\nPra buscá-los onde estão e assim,\\nSem mais aviso eles virão.\"},{\"section_type\":\"Estrofe\",\"content\":\"Você pode ter amigos, muito simples seja um.\"}]},{\"number\":\"2008-09\",\"collection_type\":\"Coletânea\",\"title\":\"Ninguém Perdoa Assim\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Recebe o meu coração te entrego a vida Jesus\\nMe aceita agora Senhor, pois quero habitar em Tua luz\\nEu quero mostrar Teu amor, que um dia alcançou o meu viver\\nErguer minha voz em louvor, pra ti adorar com todo meu ser\"},{\"section_type\":\"Estrofe\",\"content\":\"Não há outro igual, (não há outro igual)\\nNinguém perdoa assim (perdoa assim)\\nO amor do meu Jesus demonstrado lá na cruz,\\nPelo novo começo, Vida nova enfim.\"}]},{\"number\":\"2008-10\",\"collection_type\":\"Coletânea\",\"title\":\"Jesus Meu Porto\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2008\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Depois de navegar por mares tão distantes\\nDepois de enfrentar as ondas tão gigantes\\nEu só desejo a calma, chão firme aos meus pés\\nE toda segurança que puder.\"},{\"section_type\":\"Estrofe\",\"content\":\"É bom poder dizer, bem forte, terra á vista\\nÉ bom poder voltar pra gente tão querida\\nE então poder rever amigos e irmãos\\nSentir bater mais forte o coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"Jesus é quem faz o meu porto mais alegre\\nSem eles os dias são tristes e sombrios\\nJesus é o sol que brilha que aquece\\nSó Ele devolve a alegria que fulgiu\"},{\"section_type\":\"Estrofe\",\"content\":\"Inútil é pensar que agora estou seguro\\nQue aqui ao meu redor existe um grande muro\\nPois mesmo em terra firme, balançam alicerces\\nE lá que terremotos acontecem\\nPreciso me apegar à rocha inabalável\\nAo Grande Deus que faz milagres incontáveis\\nAqui está o segredo a chave do sucesso\\nE sempre estar ligado ao Forte Elo\"}]},{\"number\":\"2009-01\",\"collection_type\":\"Coletânea\",\"title\":\"Brilha Em Mim I\",\"author\":\"Fernando Rochael\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Como o sol no céu eu quero brilhar como o farol que guia os barcos no mar.\\nSer portador de luz e compartilhar\\nComo a vela divide a chama com outros e um grande clarão se produz\\nQuero cumprir a missão vencer a escuridão\\nResplandecer a luz do amor de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"[refrão]\\nBrilha em mim Senhor das Luzes Cristo meu,\\nQuero ser um contigo assim como tu és ligado a Deus\\nBrilha em mim vem habitar em meu coração\\nPois eu so vou brilhar por ti se o Senhor brilhar em mim\\nSenhor, brilha em mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Repete tudo.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero glorificar ao Pai com a luz que Jesus me dá\\nVou morrer para o mundo mas que ele viva em meu lugar\"},{\"section_type\":\"Estrofe\",\"content\":\"[refrão]\\nBrilha em mim Senhor das luzes Cristo meu,\\nQuero ser um contigo assim como tu és ligado a Deus\\nBrilha em mim vem habitar em meu coração\\nPois eu so vou brilhar por ti se o Senhor brilhar em mim\\nSenhor, brilha em mim.\"}]},{\"number\":\"2009-02\",\"collection_type\":\"Coletânea\",\"title\":\"Brilha Em Mim II\",\"author\":\"Felipe Tonasso\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu fui criado por uma razão fui escolhido pra amar e servir\\nAo mundo que padece em escuridão eu fui chamado pra brilhar.\\nEu fui comprado por sangue real fui transformado em um filho teu\\nHoje sou testemunha de um único Deus sou mensageiro da cruz\"},{\"section_type\":\"Estrofe\",\"content\":\"[refrão]\\nPor onde quer que eu vá, eu irei falar\\nPor onde quer que eu vá, eu serei tua luz\\nBrilha em mim com a tua gloria\\nBrilha em mim quero testemunhar\\nBrilha em mim pra que o mundo te conheça\\nBrilha em meu coração brilha em mim\\nEu levarei a esperança em todo lugar\\nSe o Senhor habitar em mim\\nPor onde quer que eu vá, eu irei falar\\nPor onde quer que eu vá, eu serei tua luz\\nBrilha em mim com a tua gloria\\nBrilha em mim quero testemunhar\\nBrilha em mim pra que o mundo te conheça\\nBrilha em meu coração brilha em mim\\nBrilha em mim com a tua gloria\\nBrilha em mim quero testemunhar\\nBrilha em mim pra que o mundo te conheça\\nBrilha em meu coração brilha em mim\\nBrilha em meu coração brilha em mim\"}]},{\"number\":\"2009-03\",\"collection_type\":\"Coletânea\",\"title\":\"Cada Novo Dia\",\"author\":\"Denisso Reis, Delmar Reis\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"É tão bom acordar e sentir o calor\\nComo é bom levantar, ter na voz o louvor\\nÉ tão bom perceber que o sol já brilhou\\nSou feliz com Jesus, minha vida mudou\"},{\"section_type\":\"Estrofe\",\"content\":\"Deus ama cantar, Ele ama compor\\nCada nota um som, todas têm seu valor\\nO compasso da fé só existe canção\\nSe Jesus estiver dentro do coração\"},{\"section_type\":\"Estrofe\",\"content\":\"[Refrão]\\nCada novo dia, cada nova manhã\\nCom minha vida vou louvar ao Senhor\\nCada novo dia, sinto Seu amor\\nO Autor da existência,\\nPoeta da história,\\nEle é meu Criador.\"},{\"section_type\":\"Estrofe\",\"content\":\"A pausa é um espaço, uma ausência de som\\nSe sua voz silencia, não perca o tom\\nA canção de sua vida não é sem valor\\nTenha fé no Maestro, erga a voz em louvor\"},{\"section_type\":\"Estrofe\",\"content\":\"Se te falta harmonia na canção do viver\\nO Autor de sua vida quer reger o seu ser\\nE nas horas de dor não precisa chorar\\nÉ Jesus que nos guia, é só confiar\"}]},{\"number\":\"2009-04\",\"collection_type\":\"Coletânea\",\"title\":\"De hoje em diante\",\"author\":\"Evaldo Vicente\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"De hoje em diante escolho viver com Jesus\\nComo um barco alcança o porto eu encontrei Sua Luz\\nDe hoje em diante escolho amar\\nPois eu tenho paz\\nQue Jesus pode dar\\nDe hoje em diante...\"},{\"section_type\":\"Estrofe\",\"content\":\"[refrão]\\nSenhor do Universo, és minha esperança\\nSantifica os propósitos do meu coração\\nContigo ao meu lado não tenho mais o que temer\\nPois Tu és a razão do meu viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Acima de tudo escolho viver com Jesus\\nEm resposta ao grande preço que já foi pago na cruz\\nEu sigo Teus passos pra não me perder\\nDescobri que és minha razão de viver\\nDe hoje em diante...\"},{\"section_type\":\"Estrofe\",\"content\":\"[refrão]\\nSenhor do Universo, és minha esperança\\nSantifica os propósitos do meu coração\\nContigo ao meu lado não tenho mais o que temer\\nPois Tu és a razão do meu viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"[refrão]\\nSenhor do Universo, és minha esperança\\nSantifica os propósitos do meu coração\\nContigo ao meu lado não tenho mais o que temer\\nPois Tu és a razão do meu viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pois Tu és a razão do meu viver.\\nTu és a razão do meu viver.\"}]},{\"number\":\"2009-05\",\"collection_type\":\"Coletânea\",\"title\":\"Além\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Além do que vejo, há um Deus que me ama,\\nMuito além do que eu possa imaginar.\\nAlém dos meus fracassos, existe o perdão.\\nAlém dos meus pecados, uma cruz.\"},{\"section_type\":\"Estrofe\",\"content\":\"Além do que penso, sei que está Seu querer,\\nQue me leva além do que eu posso imaginar.\\nAlém das fraquezas, há graça e poder.\\nPra seguir nessa estrada, sem nada a temer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ir além, pra falar de Jesus.\\nQuero Ir além, ser um servo fiel.\\nEu quero ir além, quero dar meu melhor,\\nPois Deus foi além por mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Além desse mundo, Ele foi preparar\\nUm lugar feliz, onde eu possa morar.\\nAlém das circunstâncias eu posso confiar,\\nPois quem prometeu jamais falhará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu quero ir além, pra falar de Jesus.\\nQuero ir além, ser um servo fiel.\\nEu quero ir além, quero dar meu melhor,\\nPois Deus foi além por mim.\"},{\"section_type\":\"Estrofe\",\"content\":\"Contigo, Senhor, quero andar.\\nEm Teu amor vou além.\\n(2x)\\nEu quero ir além, pra falar de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero ir além, ser um servo fiel.\\nEu quero ir além, quero dar meu melhor,\\nPois Deus foi além por mim.\\nPois Deus foi Além por Mim\"}]},{\"number\":\"2009-06\",\"collection_type\":\"Coletânea\",\"title\":\"Meu Senhor Minha vida\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Senhor, Tu és o que eu preciso.\\nÉs o meu constante abrigo,\\nA razão da minha alegria.\\nMeu Senhor, Tu és minha vida.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Senhor, Tu és o que eu preciso.\\nÉs o meu constante abrigo,\\nA razão da minha alegria.\\nMeu Senhor, Tu és minha vida.\"},{\"section_type\":\"Estrofe\",\"content\":\"És o Bom Pastor,\\nE ovelha Tua sou.\\nEm Teus braços me sinto bem.\\nQuando em perigo Tu vens em meu auxílio,\"},{\"section_type\":\"Estrofe\",\"content\":\"És meu maior protetor.\\nMeu Senhor, Tu és o que eu preciso.\\nÉs o meu constante abrigo,\\nA razão da minha alegria.\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Senhor, Tu és minha vida\\nSei que és um Pai,\\nE eu sou filho Teu.\\nTeu carinho me faz tão bem,\\nNunca estou sozinho, Tu és o meu caminho,\"}]},{\"number\":\"2009-07\",\"collection_type\":\"Coletânea\",\"title\":\"Vaso e oleiro\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O vaso e o oleiro são obra e autor\\nsão dois que mais pareçe que são um,\\nUm elo de amor que nunca chega ao fim.\\nO barro ganha forma, beleza,brilho e cor\\nCom toque especial do Criador,\\nAos olhos do Senhor sou vaso de valor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Como vaso e oleiro estou em suas mãos\\nRenovado a cada dia quero ser,\\nsó lhe peço uma vida nova, novo coração\\nSenhor, estou em taus mãos, Senhor estou em tuas mãos.\"},{\"section_type\":\"Estrofe\",\"content\":\"Às vezes no caminho eu posso me ferir a Ele até mesmo me quebrar\\nMas sei que ao meu lado estão aquelas mãos\\nJuntando os meus pedaços pelo chão\\nAos olhos do Senhor sou vaso de valor.\"}]},{\"number\":\"2009-08\",\"collection_type\":\"Coletânea\",\"title\":\"Enquanto eu viver\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Enquanto eu viver,Teu Nome louvarei\\nNada me impedirá de sempre o adorar Senhor.\\nOs lábios dirão que tu és Senhor\\nO mundo virá teu poder,\\nCéus e terra irão te adorar meu Deus Teu Nome exaltará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sejas louvado Senhor e meu Deus\\nTu és a glória e Teu é o poder\\nNão haverá outro rei,outro Deus\\nCom tanto amor, Deus vencedor\\nMeu Senhor e meu Rei\\nO Deus que sempre me salvará\\nO Deus que sabe quem sou\\nEle sempre me amará.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu és o Salvador,teu sempre é o louvor\\nMeus lábios cantarão em teu louvor Salvador\\nAs vitórias que eu alcançar aqui irão me lembrar quem tu és\\nPois vitória sem ti não existiram,és o Deus que jamais perderá.\"}]},{\"number\":\"2009-09\",\"collection_type\":\"Coletânea\",\"title\":\"A Tua Lei\",\"author\":\"Milton Andrade, Valdecir Lima e Silmar Correia\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Oh! Quanto amo a Tua Lei\\nEla é o meu prazer, Senhor\\nSim, verdadeiros são seus passos\\nÉ a verdade dos Teus lábios\\nÉ motivo do meu louvor\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem-aventurados os que andam na Lei\\nNela tenho vida, não me esquecerei\\nSão os Teus ensinos luz p'ro meu caminho\\nNela seguro estarei\"},{\"section_type\":\"Estrofe\",\"content\":\"A Tua Lei é perfeita\\nComo Tu És, perfeito, meu Deus\\nA Tua Lei é santa e justa\\nPois santo e justo Tu És\\nÉ a mais bela expressão do Teu coração\\nÉ Teu próprio caráter, Senhor\\nReflete a grandeza e a Tua beleza\\nRevela por mim Teu amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh! Quanto amo a Tua Lei\\nNela vida e paz achei, Senhor\\nSim, tenho a luz dos seus ensinos\\nQue ilumina o meu caminho\\nE me leva ao Salvador\"},{\"section_type\":\"Estrofe\",\"content\":\"Bem aventurados os que guardam a Lei\\nNos seus mandamentos eu me alegrarei\\nTua Lei tem a verdade, os princípios do amor\\nSua autoridade, vem de Ti, meu Criador\\nPalavras eternas, fontes de luz\\nSão reveladas em Cristo Jesus\"}]},{\"number\":\"2009-10\",\"collection_type\":\"Coletânea\",\"title\":\"Diga ao Mundo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2009\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Em seus olhos posso ver uma lágrima\\nDe tristeza por viver em solidão\\nCaminhando esperando e sonhado\\nCom o dia que não sabe quando chegará\\nQuando vira a paz\"},{\"section_type\":\"Estrofe\",\"content\":\"Hoje o mundo inteiro assiste\\nA violencia, a morte, a dor\\nE o Engano a verdade apagou\"},{\"section_type\":\"Estrofe\",\"content\":\"Avancemos proclamando\\nO amor do Salvador\\nQue sua vida fale\\nAos outros desse amor\\nE nossa voz de\\nCoração vai proclamar\"},{\"section_type\":\"Estrofe\",\"content\":\"Diga ao mundo: há esperança\\nQue Jesus em glória voltará\\nPra salvar a todos\\nQue aceitarem seu perdão\\nTrazendo a paz, a liberdade, a salvação\"},{\"section_type\":\"Estrofe\",\"content\":\"Diga ao mundo: há esperança\\nQue Jesus em glória voltará\\nViva cada dia partilhando sua luz\\nSeja uma fonte de esperança e de paz\"},{\"section_type\":\"Estrofe\",\"content\":\"Hoje o mundo inteiro assiste\\nA violencia, a morte, a dor\\nE o Engano a verdade apagou\"},{\"section_type\":\"Estrofe\",\"content\":\"Avancemos proclamando\\nO amor do Salvador\\nQue sua vida fale\\nAos outros desse amor\\nE nossa voz de\\nCoração vai proclamar\"},{\"section_type\":\"Estrofe\",\"content\":\"Diga ao mundo: há esperança\\nQue Jesus em glória voltará\\nPra salvar a todos\\nQue aceitarem seu perdão\\nTrazendo a paz, a liberdade, a salvação\"},{\"section_type\":\"Estrofe\",\"content\":\"Diga ao mundo: há esperança\\nQue Jesus em glória voltará\\nViva cada dia partilhando sua luz\\nSeja uma fonte de esperança e de paz\"}]},{\"number\":\"2010-01\",\"collection_type\":\"Coletânea\",\"title\":\"Sua Glória\",\"author\":\"Jairo Prado\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quando ouvimos do amor que Deus nos tem,\\ne as promessas tão preciosas que nos fez,\\nas histórias incontáveis de um amor incomparável,\\nnós sentimos que esse amor vai mais além.\"},{\"section_type\":\"Estrofe\",\"content\":\"Nosso Deus é fonte sempre a jorrar\\nde bondade, esperança e de paz.\\nSeu olhar de compaixão alivia e trás perdão.\\nNós pedimos que nos venha confortar.\"},{\"section_type\":\"Estrofe\",\"content\":\"[Coro]\\nSua Glória encherá este lugar.\\nSua Luz inundará os corações.\\nSeu poder inabalável, seu amor incomparável\\nSua Luz preencherá nosso viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"[Final]\\nSua Luz preencherá nosso viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"Hoje é dia de louvar o Criador.\\nDe lembrar das maravilhas que Ele fez.\\nDe rogar por sua Glória, pela Luz e por Vitória.\\nNós louvamos este Deus que é nosso Rei.\"}]},{\"number\":\"2010-02\",\"collection_type\":\"Coletânea\",\"title\":\"Geração Esperança\",\"author\":\"Letra: Valdecir Lima / Música: Lineu Soares\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nossos pais já proclamavam A breve volta de Jesus\\nE esperaram tanto tempo pelo brilho de Sua luz\\nA promessa é verdadeira Jesus Cristo iremos ver\\nMas se a noite já está longa, logo vem o amanhecer\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós somos a Geração Esperança,\\nNós pregamos o evangelho da justiça e da cruz\\nBreve Jesus voltará, breve Jesus voltará\\nNós pregamos, esperamos o retorno de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Não cansemos de falar sobre a volta de Jesus\\nE Ele vem enfim buscar os que comprou com sua cruz\\nJesus Cristo é nossa herança ele inspira nossa voz\\nÉ a razão da Esperança e da vida que há nós\\nÉ a razão da Esperança e da vida que há nós\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós somos a Geração Esperança,\\nNós pregamos o evangelho da justiça e da cruz\\nBreve Jesus voltará, breve Jesus voltará\\nNós pregamos, esperamos o retorno de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós somos a Geração Esperança,\\nNós pregamos o evangelho da justiça e da cruz\\nBreve Jesus voltará, breve Jesus voltará\\nNós pregamos, esperamos o retorno de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós pregamos, esperamos o retorno de Jesus\"}]},{\"number\":\"2010-03\",\"collection_type\":\"Coletânea\",\"title\":\"Um Dia de Esperança\",\"author\":\"Jader Santos\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus nos deu um dia da semana\\nPra pensarmos no que Ele fez\\nSeparado, abençoado,\\nSantificado, dia de louvor\\nDia lindo, escolhido como verdadeiro memorial\\nPra lembramos constantemente que o grande Deus é o Criador!\"},{\"section_type\":\"Estrofe\",\"content\":\"O Sábado é um dia de esperança!\\nDe lembrança\\nDe descanso pleno do labor\\nÉ dia de esperança, de aliança\\nEntre o povo e o seu Senhor\\nÉ dia de alegria, de harmonia\\nÉ dia de canção e poesia\\nTempo abençoado\\nSanto dia do Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Livres de cuidados dessa vida\\nNos voltamos para o Salvador\\nEstudamos a palavra\\nAprendemos mais do Seu amor\\nNesse dia tão precioso dedicamos tempo pra servir\\nAos que tanto necessitam de atençao e um pouco de amor\"},{\"section_type\":\"Estrofe\",\"content\":\"O Sábado é um dia de esperança!\\nDe lembrança\\nDe descanso pleno do labor\\nÉ dia de esperança, de aliança\\nEntre o povo e o seu Senhor\\nÉ dia de alegria, de harmonia\\nÉ dia de canção e poesia\\nTempo abençoado\\nSanto dia do Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"De um Sábado a outro Sábado\\nAdoraremos juntos ao Senhor\\nNa terra renovada por toda a eternidade exaltaremos seu amor!\"},{\"section_type\":\"Estrofe\",\"content\":\"O Sábado é um dia de esperança!\\nDe lembrança\\nDe descanso pleno do labor\\nÉ dia de esperança, de aliança\\nEntre o povo e o seu Senhor\\nÉ dia de alegria, de harmonia\\nÉ dia de canção e poesia\\nTempo abençoado, tempo consagrado\\nTempo incomparável\\nSanto dia do Senhor!\"}]},{\"number\":\"2010-04\",\"collection_type\":\"Coletânea\",\"title\":\"Nasce em Mim\",\"author\":\"Ariney Oliveira\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus, ouve a minha oração\\nNasce em mim e me salva\\nDeus, ouve a minha oração\\nNasce em mim e me salva\"},{\"section_type\":\"Estrofe\",\"content\":\"Nasce em mim, nasce em mim\\nNasce em mim, apaga o meu pecar\\nNasce em mim, nasce em mim\\nNasce em mim e salva minha vida\"}]},{\"number\":\"2010-05\",\"collection_type\":\"Coletânea\",\"title\":\"Nossa Esperança\",\"author\":\"Letra: Denilson Reis e Ricardo Ortolan / Música: Delmar Reis\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus nos chama para ser luz em meio a escuridao\\nFomos feitos para amar e servir é a missão\"},{\"section_type\":\"Estrofe\",\"content\":\"Para ver o grande dia, receber a salvação\\nVou levar a esperança, quero ser a geração\\nQue vai cantar, espalhar o amor nossa esperança está no Senhor\\nVamos louvar com grande fervor temos fé em sua vinda,\\nE esperança em seu amor\"},{\"section_type\":\"Estrofe\",\"content\":\"No passado Deus chamou pioneiros pra pregar\\nE em sua geração foram luzes a brilhar\"},{\"section_type\":\"Estrofe\",\"content\":\"Para ver o grande dia, receber a salvação\\nVou levar a esperança, quero ser a geração\\nQue vai cantar, espalhar o amor\\nNossa esperança está no Senhor\\nVamos louvar com grande fervor\\nTemos fé em sua vinda, e esperança em seu amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos cantar, espalhar o amor nossa esperança está no Senhor\\nVamos louvar com grande fervor temos fé em sua vinda,\\nE esperança em seu amor temos fé em sua vinda\\nEsperança em seu amor\"}]},{\"number\":\"2010-06\",\"collection_type\":\"Coletânea\",\"title\":\"Entrega\",\"author\":\"Suzanne Hirle\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Preciso me entregar Senhor\\nPreciso a Ti me entregar\\nPreciso ouvir Tua voz a me falar\\nNão tenho nada a te oferecer\\nSomente um coração Impuro e pecador\\nMas, aqui estou Me aceita Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Toma os meus pensamentos meus dons e meus bens\\nToma o meu coração e tudo que ele tem\\nRenova Senhor meu viver\\nDerrama em mim Teu amor\\nQuero pra sempre servir Por onde for\"}]},{\"number\":\"2010-07\",\"collection_type\":\"Coletânea\",\"title\":\"Eu Posso Todas As Coisas\",\"author\":\"Sonete Costa\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu posso todas, todas as coisas\\nNaquele que me fortalece,\\nEu posso todas, todas as coisas\\nNaquele que me fortalece.\"},{\"section_type\":\"Estrofe\",\"content\":\"[Coro]\\nEu posso todas, todas as coisas\\nNaquele que me fortalece,\\nEu posso todas, todas as coisas\\nNaquele que me fortalece.\"},{\"section_type\":\"Estrofe\",\"content\":\"As lutas da vida me fazem chorar\\nE até sou tentado a desanimar,\\nMas em Cristo encontro a força e o poder\\nQue está disponível a todo o que crer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Por isso, é possível sempre eu me alegrar\\nE por toda a vida orar sem cessar\\nEm tudo dar graças, que é a vontade de Deus\\nQue, por Jesus Cristo, cumpre o que prometeu.\"},{\"section_type\":\"Estrofe\",\"content\":\"[Moças] Por isso eu quero louvar\\n[Rapazes] Aquele que me fortalece\\n[Rapazes] Pra sempre vou me alegrar\\n[Moças] Naquele que me fortalece\\n[Moças] Por isso eu quero louvar\\n[Rapazes] Aquele que me fortalece\\n[Rapazes] Pra sempre vou me alegrar\\n[Moças] Naquele que me fortalece\"},{\"section_type\":\"Estrofe\",\"content\":\"[Final]\\nEu posso todas as coisas\\nNaquele que me fortalece,\\nEu posso todas, todas as coisas\\nNaquele que me fortalece.\\nNaquele que me fortalece.\"}]},{\"number\":\"2010-08\",\"collection_type\":\"Coletânea\",\"title\":\"Unidos\",\"author\":\"Juliana Sanches\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não importa a cor, não importa o jeito de ser,\\nNão importa a raça, o que importa é que somos irmãos.\\nJuntos faremos brotar asemente do amor.\\nJuntos iremos mudar o mundo pra melhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Unidos pra sempre iremos estar.\\nNão importa o dia, não importa o lugar.\\nEm, breve estaremos pra sempre unidos.\\nE então todos juntos iremos morar naquele lar.\\nJamais nossa história irá terminar,\\nPorque este dia já vai chegar\\nUnidos iremos,unidos iremos estar.\"},{\"section_type\":\"Estrofe\",\"content\":\"É unindo as forças que encontraremos poder.\\nSó unidos iremos ajudar um amigo a vencer.\\nJuntos poderemos levar a paz a quem sente dor.\\nJuntos iremos mudar o mundo pra melhor\"}]},{\"number\":\"2010-09\",\"collection_type\":\"Coletânea\",\"title\":\"Não Desistir\",\"author\":\"Chuck Fulmore\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Dias há bem sei, em que triste te sentes Sem ter esperança e prazer.\\nMas existe alguém que promete ajudar-te E forças à alma trazer\"},{\"section_type\":\"Estrofe\",\"content\":\"Não desistir Cristo vem logo, Breve a Aurora há de raiar!\\nNão desistir Cristo vem logo, Não desistir, Ele virá.\"},{\"section_type\":\"Estrofe\",\"content\":\"Este mundo eu sei, já não vai muito longe, E o mal vai em breve findar.\\nMinha fé em Deus sim está bem firmada, Jesus logo vai regressar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Não desistir Cristo vem logo, Breve a Aurora há de raiar!\\nNão desistir Cristo vem logo, Não desistir, Ele virá.\"}]},{\"number\":\"2010-10\",\"collection_type\":\"Coletânea\",\"title\":\"Jovem Com Poder\",\"author\":\"Jader Santos\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cante e louve a todo instante\\nDe forma incessante adore o Criador\\nLeia a Bíblia a cada dia\\nÉ luz que ilumina a vida do cristão\\nLembre: amar é importante\\nServir ao semelhante faz bem ao coração\\nConte as bençãos recebidas\\nPartilhe as maravilhas que Deus fez por você\\nE peça poder!\"},{\"section_type\":\"Estrofe\",\"content\":\"Poder pra vencer as lutas,\\nPoder pra vencer o mal,\\nPoder pra viver a vida plena que só Jesus lhe dá,\\nPoder pra levar avante a obra de anunciar\\nQue Cristo está voltando,\\nVirá logo nos buscar\"},{\"section_type\":\"Estrofe\",\"content\":\"Ore, converse com O Eterno\\nPois Ele está bem perto\\nE quer ouvir você\\nFale com toda autoridade\\nDe Deus e da Verdade que um dia o alcançou\\nMostre que vive por princípios\\nQue não cultiva vícios\\nPois ama o Salvador\\nSaiba que em todo o momento\\nSeu corpo é um Templo,\\nMorada do Senhor\\nE peça poder!\"},{\"section_type\":\"Estrofe\",\"content\":\"Poder pra vencer as lutas,\\nPoder pra vencer o mal,\\nPoder pra viver a vida plena que só Jesus lhe dá\\nPoder pra levar avante a obra de anunciar\\nQue Cristo está voltando,\\nVirá logo nos buscar\"}]},{\"number\":\"2010-11\",\"collection_type\":\"Coletânea\",\"title\":\"Com Jejum e Oração\",\"author\":\"Cleiton Schaefer\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Com jejum e oração\\nMe entreguei de corpo e alma,\\nPra cumprir essa missão.\\nCom jejum e oração\\nSegurei na mão do Mestre,\\nEncontrei a direção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com jejum e oração,\\nCom jejum e oração,\\nMe encontrei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com jejum e oração\\nO poder que vem do alto\\nMe transforma o coração.\\nCom jejum e oração\\nEu renovo as minhas forças,\\nPartilhando a salvação.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com jejum e oração,\\nCom jejum e oração,\\nEu me encontrei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com jejum e oração\\nVou vivendo, co’alegria,\\nEsperança e emoção.\\nCom jejum e oração\\nEu espero aquele dia\\nCom os santos, em canção.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com jejum e oração,\\nCom jejum e oração,\\nAo orar, em comunhão\\nEu vencerei.\"},{\"section_type\":\"Estrofe\",\"content\":\"Com jejum e oração\\nEu vencerei.\"}]},{\"number\":\"2010-12\",\"collection_type\":\"Coletânea\",\"title\":\"Vou Abraçar\",\"author\":\"Fernando Rochael\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Cada vez que eu venho aqui pra louvar a Deus\\nSinto a glória do Santo Espírito inundar-me de emoção\\nA alegria se faz mais forte quando sinto junto a mim\"},{\"section_type\":\"Estrofe\",\"content\":\"[Repete]\\nE essa força faz nascer uma canção\\nE envolve, faz crescer a união\\nPor isso vou abraçar o meu irmão\\nDizer-lhe como é bom sentir a sua presença.\\nAgora quero abraçar o meu irmão,\\nPois o amor do Pai está em nosso coração.\"},{\"section_type\":\"Estrofe\",\"content\":\"[Final]\\nO amor está no coração.\\nO amor está no coração.\"}]},{\"number\":\"2010-13\",\"collection_type\":\"Coletânea\",\"title\":\"Em paz eu vou\",\"author\":\"Marcelo Martins\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"[Repete]\\nOuvi a voz de Deus.\\nEm paz eu vou, estou feliz.\\nAchei abrigo em Sua casa.\\nEm paz estou com meu Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"[Final]\\nAchei abrigo em Sua casa.\\nEm paz estou com meu Jesus.\"}]},{\"number\":\"2010-14\",\"collection_type\":\"Coletânea\",\"title\":\"Tua Graça Cantarei\",\"author\":\"Letra e Música: Bruce Ashton / Versão em português: Gesson A. Magalhães\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2010\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Graça que me salva e vem do meu Senhor,\\nGraça que me ama e me faz vencedor.\\nGraça tão sublime, proteção total\\nGraça tão profunda, ampla e eternal.\"},{\"section_type\":\"Estrofe\",\"content\":\"Tua graça me perdoa e livra de cair\\nTua graça me transforma, me faz prosseguir;\\nPor graça, ó Deus, triunfante um dia Te verei\\nPra sempre de Tua graça cantarei.\"}]},{\"number\":\"2011-01\",\"collection_type\":\"Coletânea\",\"title\":\"Plantando Igrejas\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nosso tempo, nessa terra é tão curto e sem valor\\nO espírito está pronto é preciso força e vigor\\nHá um trabalho que nos chama há uma terra a preparar\\nE até que Cristo volte, nós devemos estar:\"},{\"section_type\":\"Estrofe\",\"content\":\"Plantando igrejas, colhendo salvação\\nAgindo em massa pra cumprir a missão\\nA nossa meta é não parar\\nEstar no campo até Jesus regressar\"},{\"section_type\":\"Estrofe\",\"content\":\"O Evangelho nos liberta desse mundo e suas paixões\\nSomos livres do pecado, somos salvos desses grilhões\\nE andamos nessa graça, motivados pelo amor\\nTrabalhando incansáveis pelo Nosso Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Estar no campo até Cristo voltar\\nVoltar\"}]},{\"number\":\"2011-02\",\"collection_type\":\"Coletânea\",\"title\":\"Incomum\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deus um dia me chamou pra falar de salvação\\nIr ao mundo anunciar que que voltará\\nE parece incomum a razão da minha fé,\\nComo pode alguém ainda ser fiel?\"},{\"section_type\":\"Estrofe\",\"content\":\"Muitos correm por aí, o sucesso querem ter,\\nMas prefiro continuar na contramão\\nVou mostrar de quem eu sou, quem um dia me salvou,\\nDecidi seguir o que Deus tem pra mim\"},{\"section_type\":\"Estrofe\",\"content\":\"Se Jesus no coração for incomum, incomum eu quero ser até o fim\\nEu não posso resistir ao Seu amor que me abraça com a força do perdão\\nSe ouvir a Sua voz é incomum, incomum então eu sou de coração\\nEu entrego tudo aquilo que eu sou,\\nVem fazer, ó Pai, Tua obra incomum em mim\"},{\"section_type\":\"Estrofe\",\"content\":\"(Mulheres)\\nCom a fé que vem de Ti verdadeiro quero ser\\nPra que outros possam ver Tua face em mim\"},{\"section_type\":\"Estrofe\",\"content\":\"(Homens)\\nEu me rendo ao Teu poder, vem usar o meu viver\\nSe mandares, Tua voz irei seguir\"}]},{\"number\":\"2011-03\",\"collection_type\":\"Coletânea\",\"title\":\"Se não for Eu\",\"author\":\"Edson Romero e Silmar Correia\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Se não for eu quem vai estender a mão para o próximo ajudar?\\nSe não for eu quem vai ensinar de Deus para o pecador salvar?\\nSe não for eu quem vai ser o sal da terra para o sofrimento aliviar?\\nSe não for eu... Quem vai servir? Quem vai sorrir? Quem vai amar?\"},{\"section_type\":\"Estrofe\",\"content\":\"Num mundo de tanta miséria, injustiça, morte e dor.\\nPosso levar a esperança a palavra do Senhor\\nVou aceitar a missão de Cristo Testemunhar\\nSe não for Eu, Quem irá se Levantar?\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim vai ser eu minha mão vou estender\\nSim vai ser eu que por Cristo vou viver\\nSim vai ser eu de sua volta vou pregar\\nSim vai ser eu.\"},{\"section_type\":\"Estrofe\",\"content\":\"Se não for eu... Quem vai servir? Quem vai sorrir? Quem vai amar?\\nEu decidi, vou servir, vou amar\\nSim vai ser eu\"}]},{\"number\":\"2011-04\",\"collection_type\":\"Coletânea\",\"title\":\"Confiarei\",\"author\":\"Sullivan Dutra\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"As Tuas veredas Senhor, eu quero sempre andar\\nAs Tuas palavras, Senhor eu quero sempre escutar\\nAs Tuas verdades Senhor, quero levar comigo onde for.\\nA Tua Lei, o Teu querer, são preciosidades que eu quero viver.\"},{\"section_type\":\"Estrofe\",\"content\":\"(coro)\\nTu és a força se fraco estou\\nSó em teus braços encontro calor\\nQuando vier a tristeza e a dor, confiarei em Teu amor\\nConfiarei em Ti Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Teus passos desejo seguir deixando o mal para trás\\nSe busco tua face, Senhor, ali eu sei que estás\\nEu quero viver plenamente, quero esquecer o que já passou\\nUsa meus pés, as minhas mãos e faz morada em meu coração\"},{\"section_type\":\"Estrofe\",\"content\":\"(CORO)\"},{\"section_type\":\"Estrofe\",\"content\":\"Confiarei\\nConfiarei\\nConfiarei\"},{\"section_type\":\"Estrofe\",\"content\":\"(CORO)\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando vier a tristeza e a dor, confiarei em Teu amor\\nConfiarei em Ti Senhor\"}]},{\"number\":\"2011-05\",\"collection_type\":\"Coletânea\",\"title\":\"Amigos da Esperança\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Há sempre mais força quando unimos nossas mãos\\nQuando é genuíno, o amor produz ação\\nSomos conclamados a seguir um ideal\\nUma causa nobre, essa luta contra o mal\"},{\"section_type\":\"Estrofe\",\"content\":\"(refrão)\\nAmigos da esperança e promessas do Senhor\\nNão se calam, não se cansam, são movidos por amor\\nAmigos da esperança vão além do que é comum\\nEsperam e trabalham pela volta de Jesus.\"},{\"section_type\":\"Estrofe\",\"content\":\"‘stá perto o dia de encontrarmos o Senhor\\nLogo deixaremos para trás o mal e a dor\\nVai ser realidade, as trombetas vão soar\\nAnjos, aos milhares, vão trazer o Rei da Paz\"}]},{\"number\":\"2011-06\",\"collection_type\":\"Coletânea\",\"title\":\"Até o Fim\",\"author\":\"Deise Jacinto\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus eu sei que logo virá\\nTodo Céu ansioso está a esperar\\nQuando Cristo se erguer do\\nSeu trono e disser; “vou trazer os meus queridos ao lar”\"},{\"section_type\":\"Estrofe\",\"content\":\"Minha vida eu vou entregar\\nMinha voz será sempre pra te louvar\\nNeste mundo de dor quero sempre, Senhor\\nSer um instrumento em teu favor\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero louvar teu nome até o fim\\nQuero te agradecer por cuidar de mim\\nO Criador da terra, céus e mar\\nVeio ao mundo morrer em meu lugar\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero hoje pedir teu perdão\\nPor às vezes seguir só o meu coração\\nPor eu tanto falhar e não te escutar\\nQuero segurar de novo tua mão\"},{\"section_type\":\"Estrofe\",\"content\":\"Cada dia preciso de ti\\nMe mostrando o caminho que devo seguir\\nCada passo que eu der seja\\nOnde estiver quero sempre escolher te servir\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero louvar teu nome\\nQuero te agradecer\"},{\"section_type\":\"Estrofe\",\"content\":\"O Criador da terra, céus e mar\\nVeio ao mundo morrer em meu lugar\"},{\"section_type\":\"Estrofe\",\"content\":\"Veio ao mundo morrer em meu lugar\"}]},{\"number\":\"2011-07\",\"collection_type\":\"Coletânea\",\"title\":\"Medley Missionário\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Novo canto há em meu ser\\nDes’ que Cristo me salvou\\nÉ um canto de prazer\\nPois Jesus me resgatou\"},{\"section_type\":\"Estrofe\",\"content\":\"Toda culpa e todo mal\\nEm seu sangue assim lavou\\nQue prazer que paz, tanto amor me traz!\\nNovo canto há em meu ser!\"},{\"section_type\":\"Estrofe\",\"content\":\"Há um dever que Deus nos confiou\\nIr e anunciar Jesus ao pecador\\nIr proclamar que já o resgatou\\nSim expandir a fé no Salvador\"},{\"section_type\":\"Estrofe\",\"content\":\"Grande alegria inundou meu coração\\nAo descobrir que Cristo logo vai voltar\\nGrande alegria explodiu a emoção\\nPelo que Cristo fez e faz pra me salvar\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó que esperança vibra em nosso ser\\nPois aguardamos o Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Pois aguardamos o Senhor\"}]},{\"number\":\"2011-08\",\"collection_type\":\"Coletânea\",\"title\":\"Como Poderei Fugir?\",\"author\":\"Gabriel Iglesias e Sullivan Dutra\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Como poderei fugir dos teus olhos de amor?\\nSua mão me alcançará não importa onde eu for\\nTu conheces meu viver mesmo antes de eu nascer\\nMeu deitar e levantar sei que está a observar\"},{\"section_type\":\"Estrofe\",\"content\":\"Precioso é o teu amor\\nExaltado, coroado\\nEm teu nome há poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu és digno de louvor e glória,\\nMeu desejo é viver por ti\"},{\"section_type\":\"Estrofe\",\"content\":\"(mulheres)\\nDeixe-me beber, Senhor, da tua fonte que é sem fim\\nPra que os outros possam ver teu poder agindo em mim\"},{\"section_type\":\"Estrofe\",\"content\":\"(todos)\\nA sombra de tuas asas eu encontro proteção\\nQuando estou perdido me estendes tua mão\"},{\"section_type\":\"Estrofe\",\"content\":\"Exaltado, coroado\\nEm teu nome há poder\\nTu és digno de louvor e glória,\\nMeu desejo é viver por ti\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu desejo é viver por ti\"}]},{\"number\":\"2011-09\",\"collection_type\":\"Coletânea\",\"title\":\"Não Há Nada Comparado\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não há nada comparado ao teu poder\\nNão há nada comparado ao teu amor\\nMe transforma, me restaura, faz de mim um vaso novo\\nEsse amor incondicional é a razão do meu viver\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu te amo, meu Senhor\\nTu és o meu, meu querido e bom pastor\\nNunca mais te deixarei, não importa o que acontecer\\nEu te amo, meu Senhor\"}]},{\"number\":\"2011-10\",\"collection_type\":\"Coletânea\",\"title\":\"Tu És meu Deus\",\"author\":\"Lucas Pimentel\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"A tua Graça me satisfaz\\nTua presença restaura a paz\\nA tua graça me satisfaz\\nTua presença restaura a paz\"},{\"section_type\":\"Estrofe\",\"content\":\"A tua força me sustenta\\nÉs meu refúgio na tormenta\\nPor isso eu te louvo\\nTu és meu Deus\"},{\"section_type\":\"Estrofe\",\"content\":\"Rei dos reis, meu Senhor\\nPai eterno, Deus de amor\\nEu te exalto, eu me entrego em Tuas mãos\"},{\"section_type\":\"Estrofe\",\"content\":\"Rei dos reis, Criador, não há outro igual a Ti\\nPor isso eu Te louvo, Tu és o meu Deus\"},{\"section_type\":\"Estrofe\",\"content\":\"Tu és o meu Deus\"}]},{\"number\":\"2011-11\",\"collection_type\":\"Coletânea\",\"title\":\"O Espírito de Deus\",\"author\":\"Valdecir Lima / Lineu Soares\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O Espírito de Deus caminha sempre ao nosso lado\\nEle é o dom do céu p’ra convencermos do pecado\\nSó Ele nos ajuda e nos orienta nos conflitos\\nSua voz nos fala à alma e nos alerta dos perigos\"},{\"section_type\":\"Estrofe\",\"content\":\"O Espírito é a luz que ilumina o caminho\\nEle é a voz de Deus, nosso amparo, nosso amigo\\nEle é o fogo que transforma, é a paz que nos acalma\\nO Espírito é a água que sacia, sacia nossa alma\"},{\"section_type\":\"Estrofe\",\"content\":\"O Espírito de Deus quer nos levar até Jesus\\nCom Sua doce voz nos faz pensar em Sua cruz\\nQualquer que a Ele ouvir terá alívio sem demora\\nO Espírito de Deus está disposto a qualquer hora\"},{\"section_type\":\"Estrofe\",\"content\":\"O Espírito é a água que sacia, sacia nossa alma\"}]},{\"number\":\"2011-12\",\"collection_type\":\"Coletânea\",\"title\":\"Quando Eu Amar\",\"author\":\"Mylher Lira\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O amor é a força maior do universo\\nQue faz até deserto em água se tornar\\nÉ um sentimento mais lindo e mais profundo\\nE que a este mundo Jesus quis demonstrar e provar\\nQue também posso amar\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando eu amar ao meu irmão\\nAmarei as pessoas do jeito que são\\nQuando eu amar ao meu irmão, só então amarei a Deus\\nBuscarei quem precisa de auxilio e atenção\\nPra que veja o amor em ação\\nQuando eu amar\"},{\"section_type\":\"Estrofe\",\"content\":\"O amor tem mil formas de amar quem mais precisa\\nE deu a própria vida pra gente viver\\nMostrou a todos o amor mais verdadeiro\\nE revelou segredos de como deve ser o amor que eu devo mostrar\"},{\"section_type\":\"Estrofe\",\"content\":\"(mulheres)\\nQuando eu amar\"},{\"section_type\":\"Estrofe\",\"content\":\"(homens)\\nQuando eu amar\"},{\"section_type\":\"Estrofe\",\"content\":\"(todos)\\nQuando eu amar\"}]},{\"number\":\"2011-13\",\"collection_type\":\"Coletânea\",\"title\":\"Vitória em Cristo\",\"author\":\"Eugene Barlett\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Ouvi da bela história que Jesus desceu da glória\\nE no Gólgota enfim morreu por quantos como eu\"},{\"section_type\":\"Estrofe\",\"content\":\"Ouvi de Seus gemidos, de Seu sangue e dos remidos;\\nE ao fim, contrito me prostrei, vitoria nEle achei\"},{\"section_type\":\"Estrofe\",\"content\":\"Vitória em Cristo eterna vitória\\nBuscou-me, salvou-me, na cruz por mim morreu\\nQue paz e que alegria! Raiou um novo dia!\\nVitória Jesus me deu, no sangue que verteu!\"},{\"section_type\":\"Estrofe\",\"content\":\"(Mulheres)\\nOuvi que Ele cura, sim, a todos que O procura;\\nQue o coxo fez andar, então e ao cego deu visão\"},{\"section_type\":\"Estrofe\",\"content\":\"(Todos)\\nOrei, clamei: “Meu Mestre, vem restaura minha vida\\nE logo Cristo me atendeu e, a mim vitória deu\"},{\"section_type\":\"Estrofe\",\"content\":\"Ouvi falar da glória que virá após vitória,\\nPara os redimidos por Jesus, na resplendente luz;\\nDe anjos lá cantando, e mansões já me aguardando;\\nSerá glorioso ali chegar, e, então poder cantar.\"}]},{\"number\":\"2011-14\",\"collection_type\":\"Coletânea\",\"title\":\"Amigo de Verdade\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2011\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Quero encontrar, um amigo especial\\nQuero abrir meu coração\\nEntregar o que eu sou a um amigo de verdade\"},{\"section_type\":\"Estrofe\",\"content\":\"Um amigo que não falhe, um amigo que me apóie\\nUm amigo mui sincero, um amigo especial\\nQue entenda meus temores, que alivie as minhas dores\\nUm amigo especial\"},{\"section_type\":\"Estrofe\",\"content\":\"2x\\nSeu nome é Jesus\\n(Jesus, Jesus)\\nAmigo especial\\n(meu Jesus, Jesus)\\nÉ verdadeiro e fiel\\nAmigo especial\"},{\"section_type\":\"Estrofe\",\"content\":\"É lindo ver um amigo que é fiel\\nConsagrado ao Senhor, um cristão, um servidor\\nQue ao mundo mostre amor\\nEsse mundo tão violento, onde há guerras e tormento\\nOnde morrem inocentes, onde impera a dor e o mal\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero já gritar sem medo: meu amigo é a resposta\\nAbre já, teu coração\"}]},{\"number\":\"2012-01\",\"collection_type\":\"Coletânea\",\"title\":\"Somos Teus\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Está nascendo um novo tempo,\\nUma nova geração\\nPra espalhar Tua glória em toda a Terra\"},{\"section_type\":\"Estrofe\",\"content\":\"Um tempo de consagração,\\nRestauração da Tua verdade\\nPra levantar Teu nome em toda a Terra\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu vejo os jovens se prostrando\\nEm reverência e adoração\\nEu vejo o Espírito movendo os corações\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu vejo a igreja se erguendo\\nE terminando a missão\\nEu vejo um povo declarando em uma canção\"},{\"section_type\":\"Coro\",\"content\":\"Somos Teus, Senhor!\\nSomos Teus, Senhor!\\nQuer vivamos ou morramos,\\nSomos Teus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Está nascendo um novo tempo,\\nUma nova geração\\nPra espalhar Tua glória em toda a Terra\"},{\"section_type\":\"Estrofe\",\"content\":\"Um tempo de consagração,\\nRestauração da Tua verdade\\nPra levantar Teu nome em toda a Terra\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu vejo os jovens se prostrando\\nEm reverência e adoração\\nEu vejo o Espírito movendo os corações\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu vejo a igreja se erguendo\\nE terminando a missão\\nEu vejo um povo declarando em uma canção\"},{\"section_type\":\"Coro\",\"content\":\"Somos Teus, Senhor!\\nSomos Teus, Senhor!\\nQuer vivamos ou morramos,\\nSomos Teus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Viveremos só por Ti\\nE morreremos só por Ti\\nQuer vivamos ou morramos,\\nSomos Teus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Viveremos só por Ti\\nE morreremos só por Ti\\nQuer vivamos ou morramos,\\nSomos Teus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Somos Teus, Senhor!\\nSomos Teus, Senhor!\\nQuer vivamos ou morramos,\\nSomos Teus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Somos Teus, Senhor! ( VIVEREMOS SÓ POR TI )\\nSomos Teus, Senhor! ( MORREREMOS SÓ POR TI )\\nQuer vivamos ou morramos,\\nSomos Teus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Somos Teus, Senhor!\\nSomos Teus, Senhor!\\nQuer vivamos ou morramos,\\nSomos Teus!\"},{\"section_type\":\"Estrofe\",\"content\":\"Somos Teus, Senhor!\\nSomos Teus, Senhor!\\nQuer vivamos ou morramos,\\nSomos Teus!\"}]},{\"number\":\"2012-02\",\"collection_type\":\"Coletânea\",\"title\":\"Meu Tudo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu era um perdido, Jesus me encontrou\\nEu era escravo e me libertou\\nEu sou tão indigno, tão vil pecador\\nJesus me cobriu com Seu manto de Amor\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu sou tão pequeno, Tu és o Senhor\\nEu sou criatura Tu és Criador\\nTua mão me ampara, Me livra do mal\\nTeu toque restaura, Traz cura real\"},{\"section_type\":\"Coro\",\"content\":\"Aleluia! Aleluia!\\nGlória Te dou pelo que Tu és\\nE por tudo que Tu farás em mim\\nTu és tão forte, eu forte serei\\nTu és tão manso, eu manso serei\\nÉs compassivo, tão cheio de Amor,\\nE eu, em resposta, te amo, Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu era sozinho, Jesus me acolheu\\nEu não era nada, Jesus me escolheu\\nSua graça alcançou-me na hora fatal\\nSeu braço arrancou-me das garras do mal\"},{\"section_type\":\"Estrofe\",\"content\":\"Não mereço nada e tudo me deu\\nA paz que faltava já me concedeu\\nSe apenas confiar nesse dom sem igual\\nTerei vida eterna com Ele afinal\"},{\"section_type\":\"Coro\",\"content\":\"Aleluia! Aleluia!\\nGlória Te dou pelo que Tu és\\nE por tudo que Tu farás em mim\\nTu és tão forte, eu forte serei\\nTu és tão manso, eu manso serei\\nÉs compassivo, tão cheio de Amor,\\nE eu, em resposta, te amo, Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Te amo Senhor\\nTe amo, Senhor\"}]},{\"number\":\"2012-03\",\"collection_type\":\"Coletânea\",\"title\":\"Eu vou para o Céu\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Podemos ver sinais do fim\\nna terra e no mar\\nDoenças, fome guerra e dor,\\nangústia entre as nações\\nMas em meio a tanta aflição,\\ncomeço a me alegrar,\\nPois eu sei que se aproxima\\nNossa redenção\"},{\"section_type\":\"Coro\",\"content\":\"Eu vou para o céu e já não demora,\\nMinha espera logo vai terminar\\nDecidi que sou de Jesus\\npra sempre e nada poderá me abalar,\\nNada!\\nLogo Cristo virá,\\ne eu vou para o Céu\"},{\"section_type\":\"Estrofe\",\"content\":\"É reino contra reino,\\nnação contra nação\\nAumento de maldade,\\nde ódio e traição\\nPois agora é o tempo de guardar\\nbem firme a nossa fé\\nNa bendita esperança\\nda promessa de Jesus!\"},{\"section_type\":\"Coro\",\"content\":\"Eu vou para o Céu e já não demora,\\nMinha espera logo vai terminar\\nDecidi que sou de Jesus\\npra sempre e nada poderá me abalar\\nNada!\\nLogo Cristo virá,\\ne eu vou para o Céu\"},{\"section_type\":\"Estrofe\",\"content\":\"Logo veremos numa nuvem\\nCristo retornar\\nCheio de glória, honra e poder\\nVirá buscar quem for fiel!\"},{\"section_type\":\"Coro\",\"content\":\"Eu vou para o Céu e já não demora,\\nMinha espera logo vai terminar\\nDecidi que sou de Jesus\\npra sempre e nada poderá me abalar\\nNada!\\nLogo Cristo virá,\\ne eu vou para o Céu\\npois Cristo virá\\nMinha espera vai terminar!\\nLogo Cristo virá\\nE eu vou para o Céu!\"}]},{\"number\":\"2012-04\",\"collection_type\":\"Coletânea\",\"title\":\"Renascer\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tanto tempo na escuridão\\nEu vivi bem longe de Ti\\nSem nenhuma esperança,\\nSem amor tão só eu vivi,\"},{\"section_type\":\"Estrofe\",\"content\":\"O pecado assolava minh'alma,\\nForam noites sem fim\\nSubmergido em profundas águas\\nMe sentia infeliz\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu coração tremeu ao escutar Sua voz\\nMinha cabeça suavemente levantou\\nMeu coração tremeu ao escutar Sua voz\\nMinha cabeça suavemente levantou\"},{\"section_type\":\"Estrofe\",\"content\":\"A esperança hoje renasceu em mim,\\nA antiga vida deixei\\nO velho homem que fui não existe mais.\\nQuão belo é renascer\"},{\"section_type\":\"Estrofe\",\"content\":\"Se sofrendo estas, clama sem vacilar,\\nTeu Deus te responderá\\nO que fez no passado fará outra vez\\nQuão grande é seu poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu coração tremeu ao escutar Sua voz\\nMinha cabeça suavemente levantou\\nMeu coração tremeu ao escutar Sua voz\\nMinha cabeça suavemente levantou\"},{\"section_type\":\"Estrofe\",\"content\":\"A esperança hoje renasceu em mim,\\nA antiga vida deixei\\nO velho homem que fui não existe mais.\\nQuão belo é renascer\"},{\"section_type\":\"Estrofe\",\"content\":\"Se sofrendo estas, clama sem vacilar,\\nTeu Deus te responderá\\nO que fez no passado fará outra vez\\nQuão grande é seu poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Quão belo é renascer\\nQuão belo é renascer\\nBelo é renascer\"}]},{\"number\":\"2012-05\",\"collection_type\":\"Coletânea\",\"title\":\"A Grande Esperança\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Os heróis do passado deixaram um grande legado\\nAo erguerem com santa ousadia\\nA bandeira da cruz\\nCom coragem venceram gigantes\\nSuperando os limites com fé\\nInspirados no exemplo maior\\nque é Cristo Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Viva a Grande Esperança\\nTestemunhando de Cristo e da salvação\\nViva a Grande Esperança\\nDeixe Jesus habitar hoje em seu coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Hoje o meu compromisso\\nÉ viver e falar de esperança\\nMesmo se for preciso sofrer\\nEu não vou desistir\\nVou lutar pela causa do Mestre\\nVou levar os perdidos à luz\\nPois o que me motiva\\nÉ a volta de Cristo Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Viva a Grande Esperança\\nTestemunhando de Cristo e da salvação\\nViva a Grande Esperança\\nDeixe Jesus habitar hoje em seu coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Viva a grande Esperança\\nTestemunhando de Cristo e da salvação\\nViva a grande Esperança\\nDeixe Jesus habitar hoje em seu coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo é nossa Esperança\\nCristo é a grande Esperança\\nDeixe Ele ser a esperança do seu coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Viva essa esperança\\nCristo, a Grande Esperança\"}]},{\"number\":\"2012-06\",\"collection_type\":\"Coletânea\",\"title\":\"Quero Recomeçar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Pai, estou aqui,\\nCansado de lutar.\\nQuero cumprir Teu querer,\\nQuero sentir Teu calor.\\nPai, errei outra vez,\\nNão esperei em Ti.\\nPreciso tanto do Teu amor,\\nTua misericórdia alcançar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dá-me um novo coração,\\nVem transformar o meu viver\\nEnsina-me olhar com os olhos da fé,\\nE em Teus braços descansar.\\nOuve ó Deus meu clamor,\\nQuero recomeçar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Pai, errei outra vez,\\nNão esperei em Ti.\\nPreciso tanto do Teu amor,\\nTua misericórdia alcançar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Dá-me um novo coração,\\nVem transformar o meu viver\\nEnsina-me olhar com os olhos da fé,\\nE em Teus braços descansar.\\nOuve ó Deus meu clamor...\"},{\"section_type\":\"Estrofe\",\"content\":\"Dá-me um novo coração,\\nVem transformar o meu viver\\nEnsina-me olhar com os olhos da fé,\\nE em Teus braços descansar.\\nOuve ó Deus meu clamor...\"},{\"section_type\":\"Estrofe\",\"content\":\"Dá-me um novo coração,\\nVem transformar o meu viver\\nEnsina-me olhar com os olhos da fé,\\nE em Teus braços descansar.\\nOuve, Senhor, meu clamor...\\nOuve, Senhor, meu clamor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero recomeçar.\\nQuero recomeçar.\\nQuero recomeçar.\"}]},{\"number\":\"2012-07\",\"collection_type\":\"Coletânea\",\"title\":\"Esperança e Poder\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Reunidos em Teu Santo Nome\\nRepartindo a mensagem de amor\\nEntregamos a Deus nossos sonhos\\norando com fervor\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Senhor quero ser instrumento,\\nAo perdido levar salvação\\nEntregando meus dons e talentos,\\nCumprindo a missão\"},{\"section_type\":\"Estrofe\",\"content\":\"Sou um servo, trabalho por Cristo!\\nMe alegro em falar do Salvador\\nAlmas mil ganharei e no Céu eu coroas terei\\nCoroas terei\"},{\"section_type\":\"Estrofe\",\"content\":\"Ó Senhor quero ser instrumento,\\nAo perdido levar salvação\\nEntregando meus dons e talentos,\\nCumprindo a missão\"},{\"section_type\":\"Estrofe\",\"content\":\"Sou um servo, trabalho por Cristo!\\nMe alegro em falar do Salvador\\nAlmas mil ganharei e no Céu eu coroas terei\"},{\"section_type\":\"Estrofe\",\"content\":\"Sou um servo, trabalho por Cristo!\\nMe alegro em falar do Salvador\\nAlmas mil ganharei e no Céu eu coroas terei\\nCoroas terei\"}]},{\"number\":\"2012-08\",\"collection_type\":\"Coletânea\",\"title\":\"Restaura\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Restaura meu ser\\nRestaura meu viver\\nRestaura minha desilusão\\nRestaura meu quebrantado coração\"},{\"section_type\":\"Estrofe\",\"content\":\"Restaura meus sonhos\\nRestaura os meus planos, Senhor\\nRestaura minha vida por completo\\nPra que todos saibam que Tu és meu Deus\\nPorque Teu é o poder e o louvor\\nPorque Tu és a paz e o amor\\nA Ti toda honra e glória rendemos Senhor\\nGrandioso é o Teu agir em nossas vidas\"},{\"section_type\":\"Estrofe\",\"content\":\"Restaura\"},{\"section_type\":\"Estrofe\",\"content\":\"Restaura meus sonhos\\nRestaura os meus planos, Senhor\\nRestaura minha vida por completo\\nPra que todos saibam que Tu és meu Deus\\nPorque Teu é o poder e o louvor\\nPorque Tu és a paz e o amor\\nA Ti toda honra e glória rendemos Senhor\\nGrandioso é o Teu agir em nossas vidas\"},{\"section_type\":\"Estrofe\",\"content\":\"Porque Teu é o poder e o louvor\\nPorque Tu és a paz e o amor\\nA Ti toda honra e glória rendemos Senhor\\nGrandioso é o Teu agir em nossas vidas\"},{\"section_type\":\"Estrofe\",\"content\":\"Restaura\\nRestaura\\nRestaura\"}]},{\"number\":\"2012-09\",\"collection_type\":\"Coletânea\",\"title\":\"O Poder Pra Vencer\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu preciso de poder pra vencer\\nAs batalhas que a vida traz\\nEu preciso de coragem lá do Céu\\nPra viver no espírito e na paz\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando sinto o amor de Deus\\nNão consigo compreender\\nTudo o que Ele fez por mim,\\nMas eu posso receber\"},{\"section_type\":\"Estrofe\",\"content\":\"O poder para vencer\\nQuero ser o que Deus desejar\\nSó a Cruz me dá forças contra o mal,\\nEm Jesus há poder real\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu preciso de poder pra alcançar\\nO que Deus sonhou pro meu viver\\nVou ao mundo sua imagem espelhar.\\nSua luz aqui resplandecer\"},{\"section_type\":\"Estrofe\",\"content\":\"Quando eu olho para mim\\nVejo que eu nada sou,\\nMas Jesus sorrindo diz:\\nTodo o meu poder Te dou\"},{\"section_type\":\"Estrofe\",\"content\":\"Pela fé vitorioso sou!\\nMe tornei templo do Senhor\\nCom o poder, para Vencer\\nQuero ser o que Deus desejar\"},{\"section_type\":\"Estrofe\",\"content\":\"Só a Cruz Me dá forças contra o mal\\nEm Jesus há poder real\\nSó a Cruz Me dá forças contra o mal\\nEm Jesus há poder real\"},{\"section_type\":\"Estrofe\",\"content\":\"Em Jesus há poder real\"}]},{\"number\":\"2012-10\",\"collection_type\":\"Coletânea\",\"title\":\"A Esperança\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"O fim dos tempos se aproxima\\nJá estamos vendo os sinais\\nUm novo tempo está chegando\\nE vida nova ele traz\\nPodemos ver em cada instante\\nQue o mundo não aguenta mais\\nOs homens clamam por justiça\\nE a natureza pede paz\"},{\"section_type\":\"Estrofe\",\"content\":\"A Grande Esperança\\nNos aquece o coração\\nAgita a nossa alma\\nE traz paz na provação\\nA Grande Esperança\\nÉ um sol que nos conduz\\nNa busca da verdade\\nQue nos leva até Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Enquanto o mundo em desespero\\nEstá buscando alguma luz\\nA liberdade que procura\\nSe encontra ao pé de uma Cruz\\nEsta é a fonte da Esperança\\nÉ a verdade que reluz\\nÉ nossa Grande Esperança\\nÉ o retorno de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"A Grande Esperança\\nNos aquece o coração\\nAgita a nossa alma\\nE traz paz na provação\\nA Grande Esperança\\nÉ um sol que nos conduz\\nNa busca da verdade\\nQue nos leva até Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"A Grande Esperança\\nNos aquece o coração\\nAgita a nossa alma\\nE traz paz na provação\\nA Grande Esperança\\nÉ um sol que nos conduz\\nNa busca da verdade\\nQue nos leva até Jesus\"}]},{\"number\":\"2012-11\",\"collection_type\":\"Coletânea\",\"title\":\"Que Prazer é Ser de Cristo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Que prazer é ser de Cristo,\\nNEle crer e confiar,\\nAceitar os Seus ensinos,\\nSua paz e amor gozar!\"},{\"section_type\":\"Estrofe\",\"content\":\"Oh, que bênção crer em Cristo,\\nCrer no sangue que verteu!\\nPois os meus pecados todos\\nSepultou e os esqueceu!\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo! Cristo! Já confio\\nEm Teu nome, em Teu poder.\\nCristo! Cristo! bem-amado,\\nFaze em mim a fé crescer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sim, feliz eu sou em Cristo,\\nDEle aqui desejo ser;\\nQuero, pois, humildemente,\\nAo Senhor obedecer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo! Cristo! Já confio\\nEm Teu nome, em Teu poder.\\nCristo! Cristo! Bem-amado,\\nFaze em mim a fé crescer.\"},{\"section_type\":\"Estrofe\",\"content\":\"Crescer\\nFaze em mim a fé crescer.\\nCrescer\"}]},{\"number\":\"2012-12\",\"collection_type\":\"Coletânea\",\"title\":\"Santo És Senhor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2012\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Santo és, Senhor nosso Deus Criador\\nTu és digno de todo louvor\\nGrande és Senhor Teu amor sem igual\\nNos livrou do pecado e do mal\\nEm uma voz vamos todos cantar\\nTeu poder sempre nos unirá\\nAleluia, Santo és Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Santo és, Senhor nosso Deus Criador\\nTu és digno de todo louvor\\nGrande és Senhor Teu amor sem igual\\nNos livrou do pecado e do mal\\nEm uma voz vamos todos cantar\\nTeu poder sempre nos unirá\\nAleluia, Santo és Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Tua presença imploramos Senhor\\nNossa vida está em Tuas Mãos\\nVem aceita ó Deus nossa adoração\"},{\"section_type\":\"Estrofe\",\"content\":\"Amém\\nAmém\"}]},{\"number\":\"2013-01\",\"collection_type\":\"Coletânea\",\"title\":\"Som de Chuva\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Sopra Teu vento sobre o deserto sem vida\\nMinh'alma sedenta procura Teu Rio de Água Viva\\nSom de chuvas abundantes eu já posso ouvir\\nEssas nuvens carregadas de poder\"},{\"section_type\":\"Estrofe\",\"content\":\"Como chuva vem\\nComo chuva vem\"},{\"section_type\":\"Estrofe\",\"content\":\"Como Chuva Serôdia caindo do Céu\\nO Espírito Santo virá\\nPois quem fez a promessa é Justo e Fiel\\nÉ certo que não falhará\\nVem sacia minha sede de viver\\nTransbordando minha vida de poder\\nNessa chuva do Espírito Santo vou me molhar\\nNesse rio de avivamento vou mergulhar\"},{\"section_type\":\"Estrofe\",\"content\":\"O que tenho visto é ação de gotas do Teu poder\\nEstou bem seguro Tu tens muito mais para oferecer\\nA promessa não demora para se cumprir\\nNão se cansa Tua igreja de pedir\"},{\"section_type\":\"Estrofe\",\"content\":\"Como chuva vem\\nComo chuva vem\"},{\"section_type\":\"Estrofe\",\"content\":\"Como Chuva Serôdia caindo do Céu\\nO Espírito Santo virá\\nPois quem fez a promessa é Justo e Fiel\\nÉ certo que não falhará\\nVem sacia minha sede de viver\\nTransbordando minha vida de poder\\nNessa chuva do Espírito Santo vou me molhar\\nNesse rio de avivamento vou mergulhar\"},{\"section_type\":\"Estrofe\",\"content\":\"Como chuva vem\\nComo chuva vem\\nComo chuva vem\"}]},{\"number\":\"2013-02\",\"collection_type\":\"Coletânea\",\"title\":\"Eu Sou Calebe\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Nasce um novo dia, eu escolho viver.\\nPara o Teu reino, para o Teu reino.\\nEm tudo o que sou, o meu tempo e dons.\\nA Tí entrego, a Tí entrego.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vou deixar minha marca na história.\\nVou viver meus dias pra Tua Glória, pra Tua Glória\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu soooou Calebe! Eu soooou Calebe!\\nPor tudo o que fizeste, por quem Tu és pra mim.\\nMinha vida eu entrego pra servir, sou Calebe!\"},{\"section_type\":\"Estrofe\",\"content\":\"Ando pelo mundo, como Cristo andou.\\nPara salvar, para salvar.\\nEm todos os lugares, como o Mestre mandou,\\nEu vou testemunhar, eu vou testemunhar.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vou deixar minha marca na história.\\nVou viver meus dias pra Tua glótia, pra Tua Glória\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu soooou Calebe! Eu soooou Calebe!\\nPor tudo o que fizeste, por quem Tu és pra mim.\\nMinha vida eu entrego pra servir, sou Calebe!\"},{\"section_type\":\"Estrofe\",\"content\":\"Por tudo o que fizeste, por tudo que és pra mim.\\nMinha vida eu entrego pra servir.\\nPor tudo o que fizeste, por tudo que és pra mim.\\nMinha vida eu entrego pra servir.\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu soooou Calebe! Eu soooou Calebe!\\nPor tudo o que fizeste, por quem Tu és pra mim.\\nMinha vida eu entrego pra servir, sou Calebe!\\nMinha vida eu entrego pra servir, sou Calebe!\"}]},{\"number\":\"2013-03\",\"collection_type\":\"Coletânea\",\"title\":\"Fortes\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Não teremos temor\\nAo enfrentar o mal\\nAo passarmos por lutas,\\nSim, Deus é refúgio\\nContra o mal\\nNão queremos falhar\\nFrente à provação\\nMesmo que nos ataquem\\nOu que nos persigam\\nTemos Deus\"},{\"section_type\":\"Estrofe\",\"content\":\"Fortes, corajosos\\nNós seremos,\\nPois Deus conosco está\\nFortes, corajosos\\nNós seremos,\\nSe estivermos\\nSempre ao Seu lado\"},{\"section_type\":\"Estrofe\",\"content\":\"Mesmo na escuridão\\nNos toma pela mão\\nQuem irá derrotar-nos\\nSe nós estivermos\\nCom o Senhor!\"},{\"section_type\":\"Estrofe\",\"content\":\"Fortes, corajosos\\nNós seremos,\\nPois Deus conosco está\\nFortes, corajosos\\nNós seremos,\\nSe estivermos\\nSempre ao Seu lado\"},{\"section_type\":\"Estrofe\",\"content\":\"Em meio à escuridão\\nNão há o que temer\\nNos toma pela mão\\nNinguem nos vencerá\\nLigados ao Senhor\\nVitória haverá\"},{\"section_type\":\"Estrofe\",\"content\":\"Não há ninguem\\nCapaz de separar-nos\\nO Seu amor\\nEstá ao nosso lado\"},{\"section_type\":\"Estrofe\",\"content\":\"Fortes, corajosos\\nNós seremos,\\nPois Deus conosco está\\nFortes, corajosos\\nNós seremos,\\nSe estivermos\\nA cada instante,\\nBem seguros,\\nSempre ao Seu lado\"}]},{\"number\":\"2013-04\",\"collection_type\":\"Coletânea\",\"title\":\"Vem Espírito Santo\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Vem Espírito Santo, com Teu poder renovar.\\nEu quero ter a vitória, vem me purificar.\\nVem guiar o Teu povo e convencer corações\\nPra consolar os cansados e libertar das prisões.\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Espírito Santo, faz morada em mim\\nTraz mais vida pra vida e me batiza, enfim\\nPara testemunhar, para usar os Teus dons\\nE Teus frutos fruírem de mim\\nPlenitude de Ti é o que eu busco ter\\nOutra vez vou rogar para Ti: Vem Espírito!\\nVem Espírito!\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Espírito Santo, com Teu poder renovar\\nEu quero ter a vitória, vem me purificar\\nVem guiar o Teu povo e convencer corações\\nPra consolar os cansados e libertar das prisões\"},{\"section_type\":\"Estrofe\",\"content\":\"Vem Espírito Santo, faz morada em mim\\nTraz mais vida pra vida e me batiza, enfim\\nPara testemunhar, para usar os Teus dons\\nE Teus frutos fruírem de mim\\nPlenitude de Ti é o que eu busco ter\\nOutra vez vou rogar para Ti: Vem Espírito!\\nVem Espírito! Vem Espírito!\\nVem Espírito!\"}]},{\"number\":\"2013-05\",\"collection_type\":\"Coletânea\",\"title\":\"A Espera do Melhor\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu tenho certeza que dias melhores virão\\nÉ esse o desejo sincero do meu coração\\nColoco meus olhos em Cristo e na vida eternal\\nVislumbro um futuro de glória e paz sem igual\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu vivo meus dias à espera de um mundo melhor\\nSem ódio, sem dor, sem lembrança do mal tão atroz\\nAlmejo herdar a morada dos filhos da Luz\\nE estar para sempre ao lado de Cristo Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu vivo sonhando acordado com meu Salvador\\nE toco Suas mãos perfuradas por causa do amor\\nMe lanço a Seus pés comovido por tudo que fez\\nE Ele me diz com ternura és meu outra vez\"},{\"section_type\":\"Estrofe\",\"content\":\"Eu vivo meus dias à espera de um mundo melhor\\nSem ódio, sem dor, sem lembrança do mal tão atroz\\nAlmejo herdar a morada dos filhos da Luz\\nE estar para sempre ao lado de Cristo Jesus\"}]},{\"number\":\"2013-06\",\"collection_type\":\"Coletânea\",\"title\":\"Estamos Juntos\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Temos que aprender a ser humildes, tolerar\\nBaixar a guarda em nome do amor\\nOh, tanto a perder quando esquecemos de amar\\nAfinal, todos somos filhos de Deus\\nSe um de nós está ferido, todos vão sentir\\nSomos parte de um corpo devemos nos unir\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós vamos dar as mãos, unidos como irmãos,\\nNós precisamos uns dos outros pra ter força\\nEu conto com você, você confia em mim\\nE assim ninguém está sozinho no mundo\\nEstamos juntos\"},{\"section_type\":\"Estrofe\",\"content\":\"Cristo nos pediu pra vivermos em amor\\nPorque então fazer separação\\nPodemos construir, um lugar acolhedor\\nAceitar a quem necessitar\\nSe um de nós está ferido, todos vão sentir\\nSomos parte de um corpo devemos nos unir\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós vamos dar as mãos, unidos como irmãos,\\nNós precisamos uns dos outros pra ter força\\nEu conto com você, você confia em mim\\nE assim ninguém está sozinho no mundo\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós vamos dar as mãos, unidos como irmãos,\\nNós precisamos uns dos outros pra ter força\\nEu conto com você, você confia em mim\\nE assim ninguém está sozinho no mundo\"},{\"section_type\":\"Estrofe\",\"content\":\"Vamos levar a nossa luz\\nVamos mostrar o amor de Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós vamos dar as mãos, unidos como irmãos,\\nNós precisamos uns dos outros pra ter força\\nEu conto com você, você confia em mim\\nE assim ninguem está sozinho no mundo\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós temos força\\nNós temos força\"},{\"section_type\":\"Estrofe\",\"content\":\"Nós temos força\"}]},{\"number\":\"2013-07\",\"collection_type\":\"Coletânea\",\"title\":\"Estou Aqui Para Adorar\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Eu estou aqui para adorar\\nCom alegria minha vida dar\\nPra buscar a perfeição que nasce\\nDia a dia ao contemplar a Tua face\"},{\"section_type\":\"Estrofe\",\"content\":\"Em espírito e em verdade eu quero louvar\\nE a minha vida vou Te entregar\\nQuero ser um verdadeiro adorador\\nDo meu Senhor do meu Grande Criador\"},{\"section_type\":\"Estrofe\",\"content\":\"Quero ser obediente em meu viver\\nNo Seu amor eu quero crescer\\nGrato a Cristo que Sua vida deu\\nNuma cruz em meu lugar Ele morreu\"},{\"section_type\":\"Estrofe\",\"content\":\"Em espírito e em verdade eu quero louvar\\nE a minha vida vou Te entregar\\nQuero ser um verdadeiro adorador\\nDo meu Senhor do meu Grande Criador\"},{\"section_type\":\"Estrofe\",\"content\":\"Em espírito e em verdade eu quero louvar\\nE a minha vida vou Te entregar\\nQuero ser um verdadeiro adorador\\nDo meu Senhor do meu Grande Criador\"},{\"section_type\":\"Estrofe\",\"content\":\"Do meu Senhor,\\nDo meu Grande Criador\"}]},{\"number\":\"2013-08\",\"collection_type\":\"Coletânea\",\"title\":\"Maravilhas\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Meu coração se alegra no Senhor\\nProclama a Sua grandeza\\nO Seu perdão alcança todos nós\\nSua graça nos cobre de bênçãos\\nSeu nome Santo é,\\nSanto é o Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Maravilhas Ele fez, nos mostrou o Seu poder\\nEle é o nosso Rei dos reis, Jesus\\nMaravilhas Ele fez, Ele operou em mim\\nSeu poder me resgatou, Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu coração se alegra no Senhor\\nProclama a Sua grandeza\\nO Seu perdão alcança todos nós\\nSua graça nos cobre de bênçãos\\nSeu Nome Santo é,\\nSanto é o Senhor\"},{\"section_type\":\"Estrofe\",\"content\":\"Maravilhas Ele fez, nos mostrou o Seu poder\\nEle é o nosso Rei dos reis, Jesus\\nMaravilhas Ele fez, Ele operou em mim\\nSeu poder me resgatou, Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"O Seu nome eu vou louvar e vou cantar\\nSeu nome eu vou louvar e vou cantar\\nO Seu nome eu vou louvar e vou cantar\\nSeu nome eu vou louvar e vou cantar\"},{\"section_type\":\"Estrofe\",\"content\":\"O Seu nome eu vou louvar e vou cantar\\nSeu nome eu vou louvar e vou cantar\\nSeu nome eu vou louvar e vou cantar\\nSeu nome eu vou louvar, vou cantar\"},{\"section_type\":\"Estrofe\",\"content\":\"Maravilhas Ele fez, nos mostrou o Seu poder\\nEle é o nosso Rei dos reis, Jesus\\nMaravilhas Ele fez, Ele operou em mim\\nSeu poder me resgatou, Jesus\"},{\"section_type\":\"Estrofe\",\"content\":\"O Seu nome eu vou louvar e vou cantar\\nSeu nome eu vou louvar e vou cantar\\nSeu nome eu vou louvar e vou cantar\\nSeu nome eu vou louvar\\nVou cantar\"}]},{\"number\":\"2013-09\",\"collection_type\":\"Coletânea\",\"title\":\"Discípulos de Esperança\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Deixamos já as trevas desse mundo\\nPois temos esperança em Teu amor\\nOuvimos Teu chamado e respondemos:\\nSeremos servos fiéis do Bom Senhor.\"},{\"section_type\":\"Estrofe\",\"content\":\"Sabemos do sublime compromisso\\nDe ser embaixadores de Jesus\\nQueremos proclamar e a Cristo imitar\\nDizer ao mundo que Ele voltará!\"},{\"section_type\":\"Estrofe\",\"content\":\"Faz de mim um discípulo\\nFaz de mim um discípulo\\nFaz de mim um discípulo\\nPra cumprir o Teu querer\"},{\"section_type\":\"Estrofe\",\"content\":\"Faz de mim um discípulo\\nFaz de mim um discípulo\\nFaz de mim um discípulo\\nPra cumprir o Teu querer\"},{\"section_type\":\"Estrofe\",\"content\":\"Queremos bênção nos Pequenos Grupos\\nQue muitos possam conhecer Jesus\\nDesperta o Teu povo em toda parte\\nE que ao voltares possam ver Tua Luz\"},{\"section_type\":\"Estrofe\",\"content\":\"Sabemos do sublime compromisso\\nDe ser embaixadores de Jesus\\nQueremos proclamar e a Cristo imitar\\nDizer ao mundo que Ele voltará!\"},{\"section_type\":\"Estrofe\",\"content\":\"Faz de mim um discípulo\\nFaz de mim um discípulo\\nFaz de mim um discípulo\\nPra cumprir o Teu querer\"},{\"section_type\":\"Estrofe\",\"content\":\"Faz de mim um discípulo\\nFaz de mim um discípulo\\nFaz de mim um discípulo\\nPra cumprir o Teu querer\"},{\"section_type\":\"Estrofe\",\"content\":\"Meu Jesus\"}]},{\"number\":\"2013-10\",\"collection_type\":\"Coletânea\",\"title\":\"Tal Qual Estou\",\"author\":\"Ministério Jovem\",\"folder_id\":\"\",\"folder_name\":\"Coletânea 2013\",\"sections\":[{\"section_type\":\"Estrofe\",\"content\":\"Tal qual estou, eu venho a Ti,\\nAceita-me, ó Salvador!\\nConfiante sou em Teu amor\\nÓ Salvador, me achego a Ti!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tal qual estou, eu venho a Ti,\\nPerdão me podes conceder\\nE minhas faltas esquecer\\nÓ Salvador, me achego a Ti!\"},{\"section_type\":\"Estrofe\",\"content\":\"Tal qual estou eu venho a Ti\\nE Tu minh'alma limparás,\\nCom Teu amor me envolverás\\nÓ Salvador, me achego a Ti.\"}]}]}";

